package main

// This file is the CANDIDATE SLOT for evolved routing algorithms. During
// optimization, the entire file is replaced (via go build -overlay) with a
// generated implementation. The contract is a single constructor:
//
//	newCandidateRouter(view, source, localBalances, spec)
//
// returning a routing.SimRouter. The router sees only the public gossip
// graph, its own channel balances and per-attempt feedback — the same
// information a real Lightning sender has. The in-tree implementation below
// is the seed algorithm: a deliberately simple fee-optimizing Dijkstra with
// failure blacklisting and halving-based MPP splitting.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

// candidateEdge is one directed edge of the public graph: a channel from
// one node to another, with the policy the sending node announced.
type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

// fee returns the fee the sending node charges to forward amt over this
// edge.
func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

// usable reports whether the edge can carry the given amount per its
// announced policy.
func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	// The public capacity is a hard upper bound on what can flow.
	return amt <= e.capacity
}

// candidateRouter is the seed algorithm: cheapest-path routing with a
// failure blacklist and amount halving when no route is found.
type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// incomingEdges maps a node to the directed edges arriving at it,
	// the natural shape for backward Dijkstra.
	incomingEdges map[route.Vertex][]*candidateEdge

	// localBalances is the exact outbound liquidity of our own channels.
	localBalances map[uint64]lnwire.MilliSatoshi

	// failedAmt records, per directed channel, the lowest amount that
	// failed with a liquidity error; routes are built to stay below it.
	failedAmt map[uint64]lnwire.MilliSatoshi

	// shardAmt is the current shard size for MPP splitting.
	shardAmt lnwire.MilliSatoshi

	// partsUsed counts the successful shards so far.
	partsUsed uint32

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route
}

// newCandidateRouter builds the router for one payment. This signature is
// the stable contract between the harness and generated candidates.
func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	router := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		failedAmt:     make(map[uint64]lnwire.MilliSatoshi),
		shardAmt:      spec.Amount,
		pending:       make(map[uint64]*route.Route),
	}

	// Build the adjacency list from gossip. Iterating a node's channels
	// yields, per channel, the policy the OTHER node announced toward us
	// (InPolicy). That is exactly the policy governing the directed edge
	// other -> node, so we record the reversed edge at each visit.
	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				router.incomingEdges[edge.to] = append(
					router.incomingEdges[edge.to], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

// dijkstraItem is a priority queue entry.
type dijkstraItem struct {
	node route.Vertex
	cost lnwire.MilliSatoshi
	idx  int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int           { return len(q) }
func (q dijkstraQueue) Less(i, j int) bool { return q[i].cost < q[j].cost }
func (q dijkstraQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}
func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

// findRoute computes the cheapest usable path delivering amt to the target,
// walking backward from the target so fees accumulate correctly.
func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (*route.Route,
	error) {

	// dist[node] = amount that must arrive at node to deliver amt.
	dist := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = amt
	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{node: r.spec.Target, cost: amt})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node, arriving := item.node, item.cost

		if arriving > dist[node] {
			continue
		}
		if node == r.source {
			break
		}

		// Consider all edges INTO node: for edge u->node, u must
		// send arriving plus u's fee.
		for _, edge := range r.incomingEdges[node] {
			amtOver := arriving

			if !edge.usable(amtOver) {
				continue
			}

			// Skip channels whose liquidity failure bound says
			// this amount cannot pass.
			if bound, ok := r.failedAmt[edge.chanID]; ok &&
				amtOver >= bound {

				continue
			}

			// Our own channels: check exact local balance.
			if edge.from == r.source {
				if r.localBalances[edge.chanID] < amtOver {
					continue
				}
			}

			var sending lnwire.MilliSatoshi
			if edge.from == r.source {
				// We pay no fee to ourselves.
				sending = amtOver
			} else {
				sending = amtOver + edge.fee(amtOver)
			}

			best, ok := dist[edge.from]
			if !ok || sending < best {
				dist[edge.from] = sending
				next[edge.from] = edge
				heap.Push(pq, &dijkstraItem{
					node: edge.from,
					cost: sending,
				})
			}
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

// buildRoute walks the next-pointers from source to target and constructs a
// route with correctly accumulated fees and cltv deltas.
func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	const finalCltvDelta = 40

	// Collect the path edges source -> target.
	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	// Amounts and expiries per channel, computed backward.
	numHops := len(path)
	amtOver := make([]lnwire.MilliSatoshi, numHops)
	expiryOver := make([]uint32, numHops)

	amtOver[numHops-1] = amt
	expiryOver[numHops-1] = finalCltvDelta

	for i := numHops - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(fwd.timeLockDelta)
	}

	hops := make([]*route.Hop, numHops)
	for i, edge := range path {
		amtToFwd := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < numHops-1 {
			amtToFwd = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToFwd,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// RequestRoute returns the next route to try: the cheapest path for the
// current shard size, halving the shard when no route exists.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if r.shardAmt > amt {
		r.shardAmt = amt
	}

	for {
		rt, err := r.findRoute(r.shardAmt)
		if err == nil {
			return rt, nil
		}

		// No route at this shard size: split if we're allowed more
		// parts and the shard is still meaningfully large.
		partsLeft := r.spec.MaxParts - inFlightHtlcs
		if partsLeft <= 1 || r.shardAmt < 10_000_000 {
			return nil, err
		}
		r.shardAmt /= 2
	}
}

// ReportAttempt learns from an attempt: liquidity failures set an upper
// bound on the failing channel.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		return nil
	}

	// Locate the failing hop and record the amount bound on its
	// outgoing channel.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			failIdx = i + 1
		}
	}

	// The failing node could not forward over its outgoing channel,
	// which is rt.Hops[failIdx].
	if failIdx >= 0 && failIdx < len(rt.Hops) {
		hop := rt.Hops[failIdx]
		amtOver := rt.TotalAmount
		if failIdx > 0 {
			amtOver = rt.Hops[failIdx-1].AmtToForward
		}

		bound, ok := r.failedAmt[hop.ChannelID]
		if !ok || amtOver < bound {
			r.failedAmt[hop.ChannelID] = amtOver
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskPriceMsat  = 420000.0
	maxRouteHops   = 30
	maxNodeLabels  = 4
	maxAttempts    = 48
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	successes uint16
	failures  uint16
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.035)
	highMode := 0.5 / (1 + math.Exp((x-0.92)*30))
	p := lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func edgeProbability(e *candidateEdge, load lnwire.MilliSatoshi) float64 {
	prior := bimodalPrior(load, e.capacity)

	sharedBeliefs.Lock()
	b := sharedBeliefs.m[e.key]
	sharedBeliefs.Unlock()

	if b.lowerOK == 0 && b.upperFail == 0 {
		return prior
	}
	if b.lowerOK > 0 && load <= b.lowerOK {
		return 0.985
	}
	if b.upperFail > 0 && load >= b.upperFail {
		return 0.012
	}

	var evidence float64
	switch {
	case b.lowerOK > 0 && b.upperFail > b.lowerOK:
		x := float64(load-b.lowerOK) /
			float64(b.upperFail-b.lowerOK)
		evidence = 0.985 - x*(0.985-0.012)

	case b.upperFail > 0:
		x := float64(load) / float64(b.upperFail)
		evidence = 0.012 + 0.973*math.Exp(-x/0.20)

	case b.lowerOK > 0:
		excess := float64(load-b.lowerOK) / float64(e.capacity)
		evidence = 0.985 * math.Exp(-5*excess)

	default:
		evidence = prior
	}

	confidence := float64(b.successes+b.failures) * 0.18
	if confidence > 0.82 {
		confidence = 0.82
	}
	p := prior*(1-confidence) + evidence*confidence
	if p < 0.012 {
		return 0.012
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func recordSuccess(key edgeKey, load lnwire.MilliSatoshi) {
	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if load > b.lowerOK {
		b.lowerOK = load
	}
	if b.upperFail != 0 && load >= b.upperFail {
		b.upperFail = 0
	}
	if b.successes < 100 {
		b.successes++
	}
	sharedBeliefs.m[key] = b
}

func recordFailure(key edgeKey, load lnwire.MilliSatoshi) {
	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if b.lowerOK >= load {
		b.lowerOK = load * 3 / 4
	}
	if b.upperFail == 0 || load < b.upperFail {
		b.upperFail = load
	}
	if b.failures < 100 {
		b.failures++
	}
	sharedBeliefs.m[key] = b
}

type searchLabel struct {
	node   route.Vertex
	edge   *candidateEdge
	amt    lnwire.MilliSatoshi
	suffix *searchLabel

	fee   lnwire.MilliSatoshi
	score float64
	hops  int
	index int
}

type labelQueue []*searchLabel

func (q labelQueue) Len() int {
	return len(q)
}

func (q labelQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q labelQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *labelQueue) Push(x any) {
	item := x.(*searchLabel)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *labelQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	*q = old[:n-1]
	return item
}

type candidatePath struct {
	rt      *route.Route
	deliver lnwire.MilliSatoshi
	edges   []*candidateEdge
	amounts []lnwire.MilliSatoshi
	loads   []lnwire.MilliSatoshi
	score   float64
}

type plannedRoute struct {
	path *candidatePath
}

type attemptMeta struct {
	deliver lnwire.MilliSatoshi
	edges   []*candidateEdge
	amounts []lnwire.MilliSatoshi
	loads   []lnwire.MilliSatoshi
	fee     lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeIndex     map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	activeLoads map[edgeKey]lnwire.MilliSatoshi
	tempPenalty map[edgeKey]float64
	policyBad   map[edgeKey]bool

	planned []*plannedRoute
	pending map[*route.Route]*attemptMeta

	committedFees lnwire.MilliSatoshi
	partsUsed     uint32
	retryCap      lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeIndex:     make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		activeLoads:   make(map[edgeKey]lnwire.MilliSatoshi),
		tempPenalty:   make(map[edgeKey]float64),
		policyBad:     make(map[edgeKey]bool),
		pending:       make(map[*route.Route]*attemptMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				e := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:    ch.InboundFee.BaseFee,
					inboundRate:    ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], e,
				)
				r.edgeIndex[key] = e
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func combinedForwardingFee(incoming, outgoing *candidateEdge,
	outAmt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outFee := outgoing.fee(outAmt)
	feeBase := int64(outAmt + outFee)
	inFee := int64(incoming.inboundBase) +
		feeBase*int64(incoming.inboundRate)/1_000_000

	total := int64(outFee) + inFee
	if total < 0 {
		total = 0
	}
	return lnwire.MilliSatoshi(total)
}

func labelContains(label *searchLabel, node route.Vertex) bool {
	for l := label; l != nil; l = l.suffix {
		if l.node == node {
			return true
		}
	}
	return false
}

func acceptLabel(best map[route.Vertex][]float64, node route.Vertex,
	score float64) bool {

	scores := best[node]
	if len(scores) < maxNodeLabels {
		best[node] = append(scores, score)
		return true
	}

	worst := 0
	for i := 1; i < len(scores); i++ {
		if scores[i] > scores[worst] {
			worst = i
		}
	}
	if score >= scores[worst] {
		return false
	}
	scores[worst] = score
	best[node] = scores
	return true
}

func (r *candidateRouter) remainingBudget() lnwire.MilliSatoshi {
	limit := r.spec.FeeLimitMsat
	if limit == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= limit {
		return 0
	}
	return limit - r.committedFees
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	reserved map[edgeKey]lnwire.MilliSatoshi,
	used map[edgeKey]int,
	maxFee lnwire.MilliSatoshi) (*candidatePath, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid shard amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	start := &searchLabel{
		node:  r.spec.Target,
		amt:   deliver,
		score: 0,
	}
	pq := &labelQueue{}
	heap.Push(pq, start)
	best := map[route.Vertex][]float64{
		r.spec.Target: {0},
	}

	for pq.Len() != 0 {
		cur := heap.Pop(pq).(*searchLabel)
		if cur.node == r.source {
			return r.buildPath(deliver, cur, reserved)
		}
		if cur.hops >= maxRouteHops {
			continue
		}

		for _, e := range r.incomingEdges[cur.node] {
			if r.policyBad[e.key] || labelContains(cur, e.key.from) {
				continue
			}

			edgeAmt := cur.amt
			addedFee := lnwire.MilliSatoshi(0)
			if cur.edge != nil {
				addedFee = combinedForwardingFee(
					e, cur.edge, cur.amt,
				)
				edgeAmt += addedFee
			}
			if !e.usable(edgeAmt) {
				continue
			}

			load := edgeAmt + reserved[e.key]
			if load > e.capacity {
				continue
			}

			prob := edgeProbability(e, load)
			if e.key.from == r.source {
				balance, ok := r.localBalances[e.key.chanID]
				if !ok || load > balance {
					continue
				}
				prob = 0.999
			}

			newFee := cur.fee + addedFee
			if maxFee != lnwire.MaxMilliSatoshi &&
				newFee > maxFee {

				continue
			}

			increment := float64(addedFee) -
				riskPriceMsat*math.Log(prob)
			increment += r.tempPenalty[e.key]
			if n := used[e.key]; n > 0 {
				increment += float64(n) * 300000
			}

			next := &searchLabel{
				node:   e.key.from,
				edge:   e,
				amt:    edgeAmt,
				suffix: cur,
				fee:    newFee,
				score:  cur.score + increment,
				hops:   cur.hops + 1,
			}
			if !acceptLabel(best, next.node, next.score) {
				continue
			}
			heap.Push(pq, next)
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) buildPath(deliver lnwire.MilliSatoshi,
	sourceLabel *searchLabel,
	reserved map[edgeKey]lnwire.MilliSatoshi) (*candidatePath, error) {

	var edges []*candidateEdge
	var amounts []lnwire.MilliSatoshi

	for label := sourceLabel; label != nil && label.edge != nil;
		label = label.suffix {

		edges = append(edges, label.edge)
		amounts = append(amounts, label.amt)
	}
	if len(edges) == 0 {
		return nil, errors.New("empty route")
	}
	if edges[len(edges)-1].key.to != r.spec.Target {
		return nil, errors.New("route does not reach target")
	}

	expiry := make([]uint32, len(edges))
	expiry[len(expiry)-1] = finalCltvDelta
	for i := len(edges) - 2; i >= 0; i-- {
		expiry[i] = expiry[i+1] +
			uint32(edges[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(edges))
	loads := make([]lnwire.MilliSatoshi, len(edges))
	for i, e := range edges {
		forward := deliver
		outgoingExpiry := uint32(finalCltvDelta)
		if i+1 < len(edges) {
			forward = amounts[i+1]
			outgoingExpiry = expiry[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      e.key.to,
			ChannelID:        e.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: outgoingExpiry,
		}
		loads[i] = amounts[i] + reserved[e.key]
	}

	rt := &route.Route{
		TotalTimeLock: expiry[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}
	return &candidatePath{
		rt:      rt,
		deliver: deliver,
		edges:   edges,
		amounts: amounts,
		loads:   loads,
		score:   sourceLabel.score,
	}, nil
}

func copyLoads(src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {
	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for k, v := range src {
		dst[k] = v
	}
	return dst
}

func copyUsage(src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]int {
	dst := make(map[edgeKey]int, len(src))
	for k, v := range src {
		if v > 0 {
			dst[k] = 1
		}
	}
	return dst
}

func ceilDiv(a lnwire.MilliSatoshi, b int) lnwire.MilliSatoshi {
	return (a + lnwire.MilliSatoshi(b) - 1) /
		lnwire.MilliSatoshi(b)
}

func (r *candidateRouter) buildPlanVariant(total lnwire.MilliSatoshi,
	parts int, bias int, maxShard lnwire.MilliSatoshi,
	budget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reserved := copyLoads(r.activeLoads)
	used := copyUsage(r.activeLoads)
	remaining := total
	remainingBudget := budget
	plan := make([]*plannedRoute, 0, parts)
	totalScore := 0.0

	for i := 0; i < parts; i++ {
		left := parts - i
		shard := remaining
		if left > 1 {
			base := ceilDiv(remaining, left)
			shard = base * lnwire.MilliSatoshi(bias) / 100
			if shard < 1 {
				shard = 1
			}

			minRemainder := lnwire.MilliSatoshi(left - 1)
			if shard > remaining-minRemainder {
				shard = remaining - minRemainder
			}
		}
		if maxShard > 0 && shard > maxShard {
			shard = maxShard
		}
		if shard <= 0 {
			return nil, 0, false
		}

		path, err := r.findRoute(
			shard, reserved, used, remainingBudget,
		)
		if err != nil {
			return nil, 0, false
		}

		fee := path.rt.TotalAmount - path.deliver
		if remainingBudget != lnwire.MaxMilliSatoshi {
			if fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= fee
		}

		plan = append(plan, &plannedRoute{path: path})
		totalScore += path.score
		for j, e := range path.edges {
			reserved[e.key] += path.amounts[j]
			used[e.key]++
		}
		remaining -= shard
	}

	if remaining != 0 {
		return nil, 0, false
	}

	totalScore += float64(parts-1) * 150000
	return plan, totalScore, true
}

func (r *candidateRouter) createPlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts reached")
	}

	budget := r.remainingBudget()
	var best []*plannedRoute
	bestScore := math.Inf(1)
	biases := []int{125, 100, 80}

	for parts := 1; parts <= int(slots); parts++ {
		if r.retryCap > 0 &&
			ceilDiv(total, parts) > r.retryCap {

			continue
		}

		for _, bias := range biases {
			if parts == 1 && bias != 100 {
				continue
			}
			plan, score, ok := r.buildPlanVariant(
				total, parts, bias, r.retryCap, budget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) == 0 {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func (r *candidateRouter) issuePlanned(pr *plannedRoute) *route.Route {
	path := pr.path
	fee := path.rt.TotalAmount - path.deliver
	r.pending[path.rt] = &attemptMeta{
		deliver: path.deliver,
		edges:   path.edges,
		amounts: path.amounts,
		loads:   path.loads,
		fee:     fee,
	}
	return path.rt
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment complete")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt limit reached")
	}

	for len(r.planned) > 0 {
		pr := r.planned[0]
		if pr.path.deliver > amt {
			r.planned = nil
			break
		}
		fee := pr.path.rt.TotalAmount - pr.path.deliver
		budget := r.remainingBudget()
		if budget != lnwire.MaxMilliSatoshi && fee > budget {
			r.planned = nil
			break
		}

		r.planned = r.planned[1:]
		return r.issuePlanned(pr), nil
	}

	usedParts := r.partsUsed
	if inFlightHtlcs > usedParts {
		usedParts = inFlightHtlcs
	}
	if usedParts >= r.spec.MaxParts {
		return nil, errors.New("maximum parts reached")
	}
	slots := r.spec.MaxParts - usedParts

	plan, err := r.createPlan(amt, slots)
	if err == nil {
		r.planned = plan[1:]
		return r.issuePlanned(plan[0]), nil
	}

	if slots > 1 {
		candidates := []lnwire.MilliSatoshi{
			ceilDiv(amt, int(slots)),
			amt / 2,
			amt / 3,
			amt / 4,
		}
		budget := r.remainingBudget()
		for _, shard := range candidates {
			if shard <= 0 || shard >= amt {
				continue
			}
			if r.retryCap > 0 && shard > r.retryCap {
				shard = r.retryCap
			}
			path, findErr := r.findRoute(
				shard, r.activeLoads,
				copyUsage(r.activeLoads), budget,
			)
			if findErr == nil {
				return r.issuePlanned(
					&plannedRoute{path: path},
				), nil
			}
		}
	}

	return nil, err
}

func classifyFailure(f any) (liquidity, policy bool) {
	switch f.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true, false

	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:
		return false, true

	default:
		return false, false
	}
}

func (r *candidateRouter) fallbackMeta(rt *route.Route) *attemptMeta {
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	meta := &attemptMeta{
		deliver: rt.Hops[len(rt.Hops)-1].AmtToForward,
		fee: rt.TotalAmount -
			rt.Hops[len(rt.Hops)-1].AmtToForward,
	}
	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		e := r.edgeIndex[key]
		if e == nil {
			return nil
		}

		amtOver := rt.TotalAmount
		if i > 0 {
			amtOver = rt.Hops[i-1].AmtToForward
		}
		meta.edges = append(meta.edges, e)
		meta.amounts = append(meta.amounts, amtOver)
		meta.loads = append(
			meta.loads, amtOver+r.activeLoads[key],
		)
		from = hop.PubKeyBytes
	}
	return meta
}

func failureEdgeIndex(rt *route.Route, source route.Vertex) int {
	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	r.attempts++

	meta := r.pending[rt]
	delete(r.pending, rt)
	if meta == nil {
		meta = r.fallbackMeta(rt)
	}
	if meta == nil {
		r.planned = nil
		return nil
	}

	if result.Failure == nil {
		for i, e := range meta.edges {
			recordSuccess(e.key, meta.loads[i])
			r.activeLoads[e.key] += meta.amounts[i]
			if r.tempPenalty[e.key] > 0 {
				r.tempPenalty[e.key] *= 0.35
			}
		}
		r.committedFees += meta.fee
		r.partsUsed++
		r.retryCap = 0
		return nil
	}

	r.planned = nil
	liquidity, policy := classifyFailure(result.Failure)
	failIdx := failureEdgeIndex(rt, result.FailureSource)
	if failIdx < 0 && liquidity && len(meta.edges) == 1 {
		failIdx = 0
	}

	if failIdx >= 0 && failIdx < len(meta.edges) {
		for i := 0; i < failIdx; i++ {
			recordSuccess(meta.edges[i].key, meta.loads[i])
		}

		failed := meta.edges[failIdx]
		if liquidity {
			recordFailure(failed.key, meta.loads[failIdx])
			r.tempPenalty[failed.key] += 650000

			nextCap := meta.deliver * 45 / 100
			if nextCap < 1 {
				nextCap = 1
			}
			if r.retryCap == 0 || nextCap < r.retryCap {
				r.retryCap = nextCap
			}
		}
		if policy {
			r.policyBad[failed.key] = true
		}
	}

	return nil
}

var _ routing.SimRouter = (*candidateRouter)(nil)

func (r *candidateRouter) String() string {
	return fmt.Sprintf("candidate-router(%v->%v)",
		r.source, r.spec.Target)
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta       = uint32(40)
	probabilityPriceMsat = 420000.0
	reservationPenalty   = 650000.0
	policyPenalty        = 2000000.0
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	okCount  uint32
	badCount uint32
}

var candidateSharedBeliefs = struct {
	sync.RWMutex
	m map[candidateEdgeKey]candidateBelief
}{
	m: make(map[candidateEdgeKey]candidateBelief),
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	fee := int64(e.baseFeeMsat) +
		int64(amt)*int64(e.feeRatePPM)/1_000_000
	if fee < 0 {
		return 0
	}
	return lnwire.MilliSatoshi(fee)
}

func (e *candidateEdge) inboundFee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	fee := int64(e.inboundBase) +
		int64(amt)*int64(e.inboundRate)/1_000_000

	return lnwire.MilliSatoshi(fee)
}

func (e *candidateEdge) usable(shardAmt,
	totalLoad lnwire.MilliSatoshi) bool {

	if shardAmt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && shardAmt > e.maxHTLC {
		return false
	}
	return totalLoad <= e.capacity
}

type candidatePlanRoute struct {
	rt          *route.Route
	probability float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	policyBad map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	plan     []candidatePlanRoute

	committedFees lnwire.MilliSatoshi
	lastFailedAmt lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		policyBad:     make(map[candidateEdgeKey]uint32),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

type candidateQueueItem struct {
	node     route.Vertex
	score    float64
	fee      lnwire.MilliSatoshi
	outAmt   lnwire.MilliSatoshi
	outEdge  *candidateEdge
	riskNats float64
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(x any) {
	*q = append(*q, x.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidateClampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidatePrior(amt,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.04)
	highMode := 0.5 / (1 + math.Exp((x-0.90)*18))

	return candidateClampProbability(lowMode + highMode)
}

func candidateReadBelief(key candidateEdgeKey) candidateBelief {
	candidateSharedBeliefs.RLock()
	belief := candidateSharedBeliefs.m[key]
	candidateSharedBeliefs.RUnlock()
	return belief
}

func candidateRecordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	belief := candidateSharedBeliefs.m[key]

	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	belief.okCount++
	candidateSharedBeliefs.m[key] = belief
	candidateSharedBeliefs.Unlock()
}

func candidateRecordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	belief := candidateSharedBeliefs.m[key]

	// A failure below a previously successful total load is likely
	// transient contention. Do not turn it into a contradictory bound.
	if amt > belief.lowerOK &&
		(belief.upperBad == 0 || amt < belief.upperBad) {

		belief.upperBad = amt
	}
	belief.badCount++
	candidateSharedBeliefs.m[key] = belief
	candidateSharedBeliefs.Unlock()
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		balance, ok := r.localBalances[edge.chanID]
		if !ok || load > balance {
			return 0.005
		}
		return 0.995
	}

	prior := candidatePrior(load, edge.capacity)
	belief := candidateReadBelief(edge.key)

	if belief.lowerOK != 0 && load <= belief.lowerOK {
		return 0.995
	}
	if belief.upperBad != 0 && load >= belief.upperBad {
		return 0.012
	}

	if belief.lowerOK != 0 && belief.upperBad > belief.lowerOK {
		width := float64(belief.upperBad - belief.lowerOK)
		pos := float64(load-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		empirical := 0.995*(1-pos) + 0.012*pos
		confidence := float64(belief.okCount+belief.badCount) / 5
		if confidence > 0.8 {
			confidence = 0.8
		}
		return candidateClampProbability(
			prior*(1-confidence) + empirical*confidence,
		)
	}

	if belief.upperBad != 0 {
		x := float64(load) / float64(belief.upperBad)
		if x > 0.5 {
			softener := 1 - 0.75*(x-0.5)/0.5
			if softener < 0.25 {
				softener = 0.25
			}
			prior *= softener
		}
	}

	return candidateClampProbability(prior)
}

func candidateNodeFee(outEdge, incoming *candidateEdge,
	outAmt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if outEdge == nil {
		return 0
	}

	outbound := outEdge.fee(outAmt)
	inbound := incoming.inboundFee(outAmt + outbound)
	total := int64(outbound) + int64(inbound)
	if total < 0 {
		total = 0
	}

	return lnwire.MilliSatoshi(total)
}

func candidateRiskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return probabilityPriceMsat
	}

	price := float64(feeCap) / 3
	if price < 15000 {
		price = 15000
	}
	if price > probabilityPriceMsat {
		price = probabilityPriceMsat
	}
	return price
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*route.Route, float64, float64, error) {

	if amt <= 0 {
		return nil, 0, 0, errors.New("invalid route amount")
	}

	riskPrice := candidateRiskPrice(feeCap)
	dist := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = 0
	pq := &candidateQueue{}
	heap.Push(pq, &candidateQueueItem{
		node:   r.spec.Target,
		outAmt: amt,
	})

	var sourceItem *candidateQueueItem

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*candidateQueueItem)
		best, ok := dist[item.node]
		if !ok || item.score > best+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceItem = item
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			nodeFee := candidateNodeFee(
				item.outEdge, edge, item.outAmt,
			)
			channelAmt := item.outAmt + nodeFee
			load := channelAmt + reservations[edge.key]

			if !edge.usable(channelAmt, load) {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || load > balance {
					continue
				}
			}

			newFee := item.fee + nodeFee
			if feeCap != lnwire.MaxMilliSatoshi &&
				newFee > feeCap {

				continue
			}

			probability := r.edgeProbability(edge, load)
			risk := -math.Log(probability)
			score := item.score + float64(nodeFee) +
				riskPrice*risk + 1500

			if reservations[edge.key] != 0 {
				score += reservationPenalty *
					(1 + float64(reservations[edge.key])/
						float64(edge.capacity+1))
			}
			if count := r.policyBad[edge.key]; count != 0 {
				score += policyPenalty * float64(count)
			}

			old, exists := dist[edge.from]
			if exists && old <= score {
				continue
			}

			dist[edge.from] = score
			next[edge.from] = edge
			heap.Push(pq, &candidateQueueItem{
				node:     edge.from,
				score:    score,
				fee:      newFee,
				outAmt:   channelAmt,
				outEdge:  edge,
				riskNats: item.riskNats + risk,
			})
		}
	}

	if sourceItem == nil {
		return nil, 0, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, 0, err
	}

	fee := rt.TotalAmount - amt
	if feeCap != lnwire.MaxMilliSatoshi && fee > feeCap {
		return nil, 0, 0, errors.New("no route within fee budget")
	}

	probability := math.Exp(-sourceItem.riskNats)
	if probability < 1e-12 {
		probability = 1e-12
	}

	return rt, probability, sourceItem.score, nil
}

func (r *candidateRouter) buildRoute(
	amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, errors.New("cycle in route")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		fee := candidateNodeFee(
			path[i+1], path[i], amounts[i+1],
		)
		amounts[i] = amounts[i+1] + fee
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmt := amt
		outgoingExpiry := finalCltvDelta
		if i < last {
			forwardAmt = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forwardAmt,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteFee(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	if rt.TotalAmount <= delivered {
		return 0
	}
	return rt.TotalAmount - delivered
}

func candidateRouteDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateForEachRouteEdge(rt *route.Route,
	fn func(candidateEdgeKey, lnwire.MilliSatoshi)) {

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		fn(key, amt)
		from = hop.PubKeyBytes
	}
}

func candidateAddReservation(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	candidateForEachRouteEdge(
		rt, func(key candidateEdgeKey, amt lnwire.MilliSatoshi) {
			reservations[key] += amt
		},
	)
}

func (r *candidateRouter) remainingBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFees
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	divisor int) lnwire.MilliSatoshi {

	return (amt + lnwire.MilliSatoshi(divisor) - 1) /
		lnwire.MilliSatoshi(divisor)
}

func candidateUniqueAmounts(
	values []lnwire.MilliSatoshi,
	minimum, maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	result := make([]lnwire.MilliSatoshi, 0, len(values))

	for _, value := range values {
		if value < minimum || value > maximum || seen[value] {
			continue
		}
		seen[value] = true
		result = append(result, value)
	}

	return result
}

func (r *candidateRouter) buildPlan(
	total lnwire.MilliSatoshi, parts int,
	budget lnwire.MilliSatoshi, sizeBias float64,
) ([]candidatePlanRoute, bool) {

	reservations := candidateCopyReservations(r.reserved)
	remaining := total
	feeLeft := budget
	plan := make([]candidatePlanRoute, 0, parts)

	for part := 0; part < parts; part++ {
		partsLeft := parts - part
		if partsLeft == 1 {
			rt, probability, _, err := r.findRoute(
				remaining, reservations, feeLeft,
			)
			if err != nil {
				return nil, false
			}

			plan = append(plan, candidatePlanRoute{
				rt:          rt,
				probability: probability,
			})
			remaining = 0
			break
		}

		equal := candidateCeilDiv(remaining, partsLeft)
		maximum := remaining - lnwire.MilliSatoshi(partsLeft-1)

		values := []lnwire.MilliSatoshi{
			equal * 135 / 100,
			equal * 115 / 100,
			equal,
			equal * 85 / 100,
			equal * 70 / 100,
		}
		if r.lastFailedAmt > 0 {
			values = append(
				values, r.lastFailedAmt*65/100,
			)
		}

		amounts := candidateUniqueAmounts(
			values, 1, maximum,
		)

		var chosen *candidatePlanRoute
		var chosenMetric float64

		for _, shardAmt := range amounts {
			rt, probability, score, err := r.findRoute(
				shardAmt, reservations, feeLeft,
			)
			if err != nil {
				continue
			}

			ratio := float64(shardAmt) / float64(equal)
			metric := score/probabilityPriceMsat -
				sizeBias*math.Log(ratio)

			if chosen == nil || metric < chosenMetric {
				chosen = &candidatePlanRoute{
					rt:          rt,
					probability: probability,
				}
				chosenMetric = metric
			}
		}

		if chosen == nil {
			return nil, false
		}

		plan = append(plan, *chosen)
		shardAmt := candidateRouteDelivered(chosen.rt)
		remaining -= shardAmt

		fee := candidateRouteFee(chosen.rt)
		if feeLeft != lnwire.MaxMilliSatoshi {
			if fee > feeLeft {
				return nil, false
			}
			feeLeft -= fee
		}

		candidateAddReservation(reservations, chosen.rt)
	}

	return plan, remaining == 0
}

func candidatePlanUtility(
	plan []candidatePlanRoute,
	budget lnwire.MilliSatoshi) float64 {

	riskPrice := candidateRiskPrice(budget)
	utility := 0.18 * float64(len(plan)-1)

	for _, planned := range plan {
		p := planned.probability
		if p < 1e-12 {
			p = 1e-12
		}
		utility += -math.Log(p)
		utility += float64(candidateRouteFee(planned.rt)) / riskPrice
		utility += 0.025 * float64(len(planned.rt.Hops))
	}

	return utility
}

func (r *candidateRouter) makePlan(
	amt lnwire.MilliSatoshi, slots int,
) []candidatePlanRoute {

	if slots < 1 {
		return nil
	}

	budget := r.remainingBudget()
	bestUtility := math.Inf(1)
	var best []candidatePlanRoute

	biases := []float64{0, 0.55, -0.35}
	for parts := 1; parts <= slots; parts++ {
		tries := biases
		if parts == 1 {
			tries = biases[:1]
		}

		for _, bias := range tries {
			plan, ok := r.buildPlan(
				amt, parts, budget, bias,
			)
			if !ok {
				continue
			}

			utility := candidatePlanUtility(plan, budget)
			if utility < bestUtility {
				bestUtility = utility
				best = plan
			}
		}
	}

	return best
}

func (r *candidateRouter) rebuildReservations() {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	for _, rt := range r.held {
		candidateAddReservation(r.reserved, rt)
	}
}

func (r *candidateRouter) syncHeld(inFlightHtlcs uint32) {
	if int(inFlightHtlcs) >= len(r.held) {
		return
	}

	r.held = r.held[:int(inFlightHtlcs)]
	r.rebuildReservations()
	r.plan = nil
}

func (r *candidateRouter) fallbackRoute(
	amt lnwire.MilliSatoshi, slots int,
) (*route.Route, error) {

	minimum := candidateCeilDiv(amt, slots)
	values := candidateUniqueAmounts(
		[]lnwire.MilliSatoshi{
			amt,
			amt * 3 / 4,
			amt * 2 / 3,
			amt / 2,
			minimum,
		},
		minimum, amt,
	)

	var best *candidatePlanRoute
	bestMetric := math.Inf(1)
	budget := r.remainingBudget()

	for _, shardAmt := range values {
		rt, probability, score, err := r.findRoute(
			shardAmt, r.reserved, budget,
		)
		if err != nil {
			continue
		}

		metric := score/probabilityPriceMsat -
			0.25*math.Log(float64(shardAmt)/float64(minimum))
		metric += -math.Log(probability) * 0.15

		if metric < bestMetric {
			bestMetric = metric
			best = &candidatePlanRoute{
				rt:          rt,
				probability: probability,
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best.rt, nil
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment complete")
	}

	r.syncHeld(inFlightHtlcs)

	if r.spec.MaxParts <= inFlightHtlcs {
		return nil, errors.New("maximum parts reached")
	}
	slots := int(r.spec.MaxParts - inFlightHtlcs)

	for len(r.plan) != 0 {
		next := r.plan[0]
		r.plan = r.plan[1:]

		delivered := candidateRouteDelivered(next.rt)
		fee := candidateRouteFee(next.rt)
		budget := r.remainingBudget()

		if delivered <= amt &&
			(budget == lnwire.MaxMilliSatoshi || fee <= budget) {

			return next.rt, nil
		}

		r.plan = nil
	}

	r.plan = r.makePlan(amt, slots)
	if len(r.plan) != 0 {
		next := r.plan[0]
		r.plan = r.plan[1:]
		return next.rt, nil
	}

	return r.fallbackRoute(amt, slots)
}

func (r *candidateRouter) routeLoads(
	rt *route.Route) map[candidateEdgeKey]lnwire.MilliSatoshi {

	loads := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	candidateForEachRouteEdge(
		rt, func(key candidateEdgeKey, amt lnwire.MilliSatoshi) {
			loads[key] = amt + r.reserved[key]
		},
	)
	return loads
}

func (r *candidateRouter) ReportAttempt(
	attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	loads := r.routeLoads(rt)

	if result.Failure == nil {
		candidateForEachRouteEdge(
			rt, func(key candidateEdgeKey, _ lnwire.MilliSatoshi) {
				candidateRecordSuccess(key, loads[key])
			},
		)

		r.committedFees += candidateRouteFee(rt)
		r.held = append(r.held, rt)
		candidateAddReservation(r.reserved, rt)
		r.lastFailedAmt = 0
		return nil
	}

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	edgeKeys := make([]candidateEdgeKey, 0, len(rt.Hops))
	edgeAmts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	candidateForEachRouteEdge(
		rt, func(key candidateEdgeKey, amt lnwire.MilliSatoshi) {
			edgeKeys = append(edgeKeys, key)
			edgeAmts = append(edgeAmts, amt)
		},
	)

	if failIdx > len(edgeKeys) {
		failIdx = len(edgeKeys)
	}

	if failIdx >= 0 {
		for i := 0; i < failIdx && i < len(edgeKeys); i++ {
			candidateRecordSuccess(
				edgeKeys[i], loads[edgeKeys[i]],
			)
		}
	}

	code := result.Failure.Code()
	if failIdx >= 0 && failIdx < len(edgeKeys) {
		key := edgeKeys[failIdx]
		load := loads[key]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(key, load)
			r.lastFailedAmt = edgeAmts[failIdx]

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.policyBad[key]++
		}
	}

	r.plan = nil
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskPriceMsat  = 420000.0
	partCostMsat   = 12000.0
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFee int64
	feeRate int64
	delta   uint16
	minHTLC lnwire.MilliSatoshi
	maxHTLC lnwire.MilliSatoshi

	// This fee belongs to the receiving node and applies when an HTLC
	// arrives over this edge.
	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) outboundFee(amt lnwire.MilliSatoshi) int64 {
	fee := e.baseFee + int64(amt)*e.feeRate/1_000_000
	if fee < 0 {
		return 0
	}
	return fee
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

// nodeFee returns the total fee charged by the node between in and out.
// The inbound component is charged on the forwarded amount plus the
// ordinary outbound fee, and the combined fee is floored at zero.
func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if out == nil {
		return 0
	}

	outFee := out.outboundFee(amt)
	inFee := in.inboundBase +
		(int64(amt)+outFee)*in.inboundRate/1_000_000

	total := outFee + inFee
	if total < 0 {
		total = 0
	}

	return lnwire.MilliSatoshi(total)
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func edgeProbability(key edgeKey, amt,
	capacity lnwire.MilliSatoshi) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()

	if !ok || b.conf == 0 {
		return prior
	}

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return 0.992
	}
	if b.upperBad > 0 && amt >= b.upperBad {
		return 0.012
	}

	evidence := prior
	switch {
	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(amt-b.lowerOK) / width
		evidence = 0.985 - 0.973*pos

	case b.lowerOK > 0:
		headroom := capacity - b.lowerOK
		if headroom > 0 {
			pos := float64(amt-b.lowerOK) / float64(headroom)
			evidence = 0.985*(1-pos) + 0.012*pos
		}

	case b.upperBad > 0:
		pos := float64(amt) / float64(b.upperBad)
		evidence = 0.985*(1-pos) + 0.012*pos
	}

	if evidence < 0.012 {
		evidence = 0.012
	}
	if evidence > 0.992 {
		evidence = 0.992
	}

	weight := b.conf / (b.conf + 2)
	if weight > 0.85 {
		weight = 0.85
	}

	p := prior*(1-weight) + evidence*weight
	if p < 0.012 {
		return 0.012
	}
	if p > 0.992 {
		return 0.992
	}
	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool) {
	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad > 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}

		// Contradictions can arise from drift or temporarily held
		// liquidity. Retain useful history without creating impossible
		// hard bounds.
		if b.lowerOK >= amt {
			b.lowerOK = amt * 3 / 4
		}
	}

	b.conf++
	if b.conf > 8 {
		b.conf = 8
	}
	sharedBeliefs.m[key] = b
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[edgeKey]*candidateEdge
	local    map[uint64]lnwire.MilliSatoshi

	committedFees lnwire.MilliSatoshi

	planned []*route.Route

	outstanding map[*route.Route]bool
	held        []*route.Route
	attemptLoad map[*route.Route]map[edgeKey]lnwire.MilliSatoshi

	avoid    map[edgeKey]float64
	failedAt map[edgeKey]lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:      source,
		spec:        spec,
		incoming:    make(map[route.Vertex][]*candidateEdge),
		edges:       make(map[edgeKey]*candidateEdge),
		local:       localBalances,
		outstanding: make(map[*route.Route]bool),
		attemptLoad: make(map[*route.Route]map[edgeKey]lnwire.MilliSatoshi),
		avoid:       make(map[edgeKey]float64),
		failedAt:    make(map[edgeKey]lnwire.MilliSatoshi),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
				}
				edge := &candidateEdge{
					key:      key,
					chanID:   ch.ChannelID,
					from:     ch.OtherNode,
					to:       node,
					capacity: lnwire.NewMSatFromSatoshis(ch.Capacity),

					baseFee: int64(pol.FeeBaseMSat),
					feeRate: int64(
						pol.FeeProportionalMillionths,
					),
					delta:   pol.TimeLockDelta,
					minHTLC: pol.MinHTLC,

					inboundBase: int64(ch.InboundFee.BaseFee),
					inboundRate: int64(ch.InboundFee.FeeRate),
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incoming[node] = append(r.incoming[node], edge)
				r.edges[key] = edge
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

type searchItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	path   []*candidateEdge
	index  int
}

type searchQueue []*searchItem

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *searchQueue) Push(x any) {
	item := x.(*searchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type foundRoute struct {
	rt    *route.Route
	score float64
}

func pathContains(path []*candidateEdge, node route.Vertex) bool {
	for _, edge := range path {
		if edge.from == node || edge.to == node {
			return true
		}
	}
	return false
}

func (r *candidateRouter) reservationLedger() map[edgeKey]lnwire.MilliSatoshi {
	res := make(map[edgeKey]lnwire.MilliSatoshi)

	for _, rt := range r.held {
		r.addRouteReservation(res, rt)
	}
	for rt := range r.outstanding {
		r.addRouteReservation(res, rt)
	}

	return res
}

func routeAmounts(rt *route.Route) map[edgeKey]lnwire.MilliSatoshi {
	amounts := make(map[edgeKey]lnwire.MilliSatoshi)
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
		}
		amounts[key] += amt
		from = hop.PubKeyBytes
	}

	return amounts
}

func (r *candidateRouter) addRouteReservation(
	res map[edgeKey]lnwire.MilliSatoshi, rt *route.Route) {

	for key, amt := range routeAmounts(rt) {
		res[key] += amt
	}
}

func routeFee(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}

	received := rt.Hops[len(rt.Hops)-1].AmtToForward
	if rt.TotalAmount <= received {
		return 0
	}
	return rt.TotalAmount - received
}

func routeReceiverAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) feeLeft() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	used := r.committedFees
	for rt := range r.outstanding {
		used += routeFee(rt)
	}

	if used >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - used
}

func (r *candidateRouter) findRoute(
	deliver, maxFee lnwire.MilliSatoshi,
	reserved map[edgeKey]lnwire.MilliSatoshi) (*foundRoute, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	best := make(map[route.Vertex]float64)
	best[r.spec.Target] = 0

	pq := &searchQueue{}
	heap.Push(pq, &searchItem{
		node:   r.spec.Target,
		amount: deliver,
		path:   nil,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*searchItem)
		if known, ok := best[item.node]; ok && item.score > known {
			continue
		}

		if item.node == r.source {
			rt, err := r.buildRoute(deliver, item.path)
			if err != nil {
				return nil, err
			}
			if routeFee(rt) > maxFee {
				continue
			}
			return &foundRoute{rt: rt, score: item.score}, nil
		}

		var out *candidateEdge
		if len(item.path) > 0 {
			out = item.path[0]
		}

		for _, in := range r.incoming[item.node] {
			if pathContains(item.path, in.from) {
				continue
			}

			fee := nodeFee(in, out, item.amount)
			if int64(item.amount) > math.MaxInt64-int64(fee) {
				continue
			}
			crossing := item.amount + fee

			if !in.usableHTLC(crossing) {
				continue
			}

			load := crossing + reserved[in.key]
			if load > in.capacity {
				continue
			}

			if in.from == r.source {
				balance, ok := r.local[in.chanID]
				if !ok || load > balance {
					continue
				}
			}

			accruedFee := crossing - deliver
			if accruedFee > maxFee {
				continue
			}

			p := edgeProbability(in.key, load, in.capacity)
			risk := -math.Log(p)

			if penalty := r.avoid[in.key]; penalty > 0 {
				scale := 1.0
				if failed := r.failedAt[in.key]; failed > 0 &&
					load < failed {

					scale = 0.2 + 0.8*
						float64(load)/float64(failed)
				}
				risk += penalty * scale
			}

			// Reusing an already reserved corridor is legal, but it is
			// deliberately expensive so an MPP set fans out when the
			// graph offers alternatives.
			reuseCost := 0.0
			if reserved[in.key] > 0 {
				ratio := float64(reserved[in.key]) /
					float64(in.capacity)
				reuseCost = 250000 + 350000*ratio
			}

			score := item.score + float64(fee) +
				riskPriceMsat*risk + reuseCost

			if old, ok := best[in.from]; ok && score >= old {
				continue
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = in
			copy(path[1:], item.path)

			best[in.from] = score
			heap.Push(pq, &searchItem{
				node:   in.from,
				amount: crossing,
				score:  score,
				path:   path,
			})
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = deliver
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fee := nodeFee(path[i], path[i+1], amounts[i+1])
		amounts[i] = amounts[i+1] + fee
		expiries[i] = expiries[i+1] + uint32(path[i+1].delta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

type routePlan struct {
	routes []*route.Route
	score  float64
}

func (r *candidateRouter) constructPlan(
	total lnwire.MilliSatoshi, parts int, skew bool,
	baseReserved map[edgeKey]lnwire.MilliSatoshi,
	budget lnwire.MilliSatoshi) (*routePlan, error) {

	reserved := make(map[edgeKey]lnwire.MilliSatoshi, len(baseReserved))
	for key, amt := range baseReserved {
		reserved[key] = amt
	}

	leftAmt := total
	leftBudget := budget
	plan := &routePlan{}

	for i := 0; i < parts; i++ {
		leftParts := parts - i
		shard := (leftAmt + lnwire.MilliSatoshi(leftParts) - 1) /
			lnwire.MilliSatoshi(leftParts)

		// A second family of candidate plans gives earlier, stronger
		// corridors a larger share. Equal plans remain available when
		// asymmetric allocation is not beneficial.
		if skew && leftParts > 1 {
			larger := shard * 3 / 2
			minRemainder := lnwire.MilliSatoshi(leftParts - 1)
			if larger < leftAmt-minRemainder {
				shard = larger
			}
		}

		found, err := r.findRoute(shard, leftBudget, reserved)
		if err != nil {
			return nil, err
		}

		fee := routeFee(found.rt)
		if fee > leftBudget {
			return nil, errors.New("route plan exceeds fee budget")
		}

		plan.routes = append(plan.routes, found.rt)
		plan.score += found.score + partCostMsat
		r.addRouteReservation(reserved, found.rt)

		leftAmt -= shard
		if leftBudget != lnwire.MaxMilliSatoshi {
			leftBudget -= fee
		}
	}

	if leftAmt != 0 {
		return nil, errors.New("incomplete route plan")
	}
	return plan, nil
}

func (r *candidateRouter) makePlan(
	amt lnwire.MilliSatoshi, slots uint32) error {

	if slots == 0 {
		return errors.New("maximum parts already in flight")
	}

	budget := r.feeLeft()
	if budget == 0 && r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
		return errors.New("fee budget exhausted")
	}

	reserved := r.reservationLedger()
	var best *routePlan

	for parts := 1; parts <= int(slots); parts++ {
		equal, err := r.constructPlan(
			amt, parts, false, reserved, budget,
		)
		if err == nil && (best == nil || equal.score < best.score) {
			best = equal
		}

		if parts > 1 {
			skewed, err := r.constructPlan(
				amt, parts, true, reserved, budget,
			)
			if err == nil &&
				(best == nil || skewed.score < best.score) {

				best = skewed
			}
		}
	}

	if best == nil {
		return errors.New("no route found")
	}

	r.planned = best.routes
	return nil
}

func (r *candidateRouter) reconcileHeld(inFlight uint32) {
	outstanding := len(r.outstanding)
	wantedHeld := int(inFlight) - outstanding
	if wantedHeld < 0 {
		wantedHeld = 0
	}

	if len(r.held) > wantedHeld {
		drop := len(r.held) - wantedHeld
		r.held = append([]*route.Route(nil), r.held[drop:]...)
	}
}

func (r *candidateRouter) markOutstanding(rt *route.Route) {
	shardAmounts := routeAmounts(rt)
	reserved := r.reservationLedger()
	loads := make(map[edgeKey]lnwire.MilliSatoshi, len(shardAmounts))

	for key, shard := range shardAmounts {
		loads[key] = reserved[key] + shard

		// If attempts are launched before earlier attempts resolve,
		// their observations concern their aggregate concurrent load.
		for other := range r.outstanding {
			otherAmounts := routeAmounts(other)
			if _, shared := otherAmounts[key]; !shared {
				continue
			}
			if prior := r.attemptLoad[other]; prior != nil {
				prior[key] += shard
			}
		}
	}

	r.attemptLoad[rt] = loads
	r.outstanding[rt] = true
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	r.reconcileHeld(inFlightHtlcs)

	for len(r.planned) > 0 {
		rt := r.planned[0]
		r.planned = r.planned[1:]

		if routeReceiverAmount(rt) > amt || routeFee(rt) > r.feeLeft() {
			r.planned = nil
			break
		}

		r.markOutstanding(rt)
		return rt, nil
	}

	slots := uint32(0)
	if r.spec.MaxParts > inFlightHtlcs {
		slots = r.spec.MaxParts - inFlightHtlcs
	}
	if slots == 0 {
		return nil, errors.New("maximum parts already in flight")
	}

	if err := r.makePlan(amt, slots); err != nil {
		return nil, err
	}
	if len(r.planned) == 0 {
		return nil, errors.New("no route found")
	}

	rt := r.planned[0]
	r.planned = r.planned[1:]
	r.markOutstanding(rt)
	return rt, nil
}

func failureIndex(rt *route.Route, source route.Vertex) int {
	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func routeEdgeKeys(rt *route.Route) []edgeKey {
	keys := make([]edgeKey, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
		}
		from = hop.PubKeyBytes
	}

	return keys
}

func (r *candidateRouter) ReportAttempt(
	attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	loads := r.attemptLoad[rt]
	if loads == nil {
		loads = make(map[edgeKey]lnwire.MilliSatoshi)
		reserved := r.reservationLedger()
		for key, shard := range routeAmounts(rt) {
			loads[key] = reserved[key] + shard
		}
	}

	delete(r.attemptLoad, rt)
	delete(r.outstanding, rt)

	keys := routeEdgeKeys(rt)

	if result.Failure == nil {
		for _, key := range keys {
			updateBelief(key, loads[key], true)
			r.avoid[key] *= 0.25
		}

		r.committedFees += routeFee(rt)
		r.held = append(r.held, rt)
		return nil
	}

	// Any failure invalidates the unsent remainder of the route-set plan.
	// Already dispatched siblings remain accounted for separately.
	r.planned = nil

	failIdx := failureIndex(rt, result.FailureSource)
	if failIdx < 0 {
		return nil
	}

	// Every channel before the failing node carried the aggregate load.
	for i := 0; i < failIdx && i < len(keys); i++ {
		key := keys[i]
		updateBelief(key, loads[key], true)
		r.avoid[key] *= 0.5
	}

	if failIdx >= len(keys) {
		return nil
	}

	failedKey := keys[failIdx]
	code := result.Failure.Code()

	if code == lnwire.CodeTemporaryChannelFailure {
		updateBelief(failedKey, loads[failedKey], false)
		r.failedAt[failedKey] = loads[failedKey]
		r.avoid[failedKey] += 1.2
		if r.avoid[failedKey] > 7 {
			r.avoid[failedKey] = 7
		}
	} else {
		// Fee and CLTV failures indicate that this exact advertised
		// corridor should not immediately be selected again. They do not
		// establish a liquidity upper bound.
		r.avoid[failedKey] += 5
		if r.avoid[failedKey] > 12 {
			r.avoid[failedKey] = 12
		}
	}

	return nil
}

func (r *candidateRouter) String() string {
	return fmt.Sprintf("bimodal-budget-router(%v)", r.source)
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)
	riskPriceMsat  = 420000.0
	hopCostMsat    = 2500.0
	reuseCostMsat  = 350000.0
	maxPathHops    = 30
	maxLabels      = 4
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	fee := e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
	if fee < 0 {
		return 0
	}
	return fee
}

func (e *candidateEdge) inboundFee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return lnwire.MilliSatoshi(
		int64(e.inboundBase) +
			int64(amt)*int64(e.inboundRate)/1_000_000,
	)
}

func (e *candidateEdge) shardUsable(
	amt lnwire.MilliSatoshi) bool {

	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

// nodeFee is the fee charged by the node reached over incoming. It combines
// that node's outgoing policy with the inbound fee attached to incoming.
func nodeFee(outgoing, incoming *candidateEdge,
	amtToForward lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outFee := outgoing.fee(amtToForward)
	inFee := incoming.inboundFee(amtToForward + outFee)
	total := outFee + inFee
	if total < 0 {
		return 0
	}
	return total
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
}

type knowledgeKey struct {
	source   route.Vertex
	chanID   uint64
	from     route.Vertex
	capacity lnwire.MilliSatoshi
}

var sharedKnowledge = struct {
	sync.Mutex
	beliefs map[knowledgeKey]liquidityBelief
}{
	beliefs: make(map[knowledgeKey]liquidityBelief),
}

type heldShard struct {
	rt *route.Route
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved map[edgeKey]lnwire.MilliSatoshi
	useCount map[edgeKey]int
	held     []heldShard

	badPolicy map[edgeKey]bool
	penalty   map[edgeKey]float64

	committedFees lnwire.MilliSatoshi

	plan       []*route.Route
	plannedAmt lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incoming:      make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		useCount:      make(map[edgeKey]int),
		badPolicy:     make(map[edgeKey]bool),
		penalty:       make(map[edgeKey]float64),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &candidateEdge{
					key: edgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
					},
					from: ch.OtherNode,
					to:   node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.incoming[e.to] = append(r.incoming[e.to], e)
				r.edges[e.key] = e
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedKnowledge.Lock()
	for key, edge := range r.edges {
		k := r.knowledgeKey(edge)
		if belief, ok := sharedKnowledge.beliefs[k]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedKnowledge.Unlock()

	return r, nil
}

func (r *candidateRouter) knowledgeKey(e *candidateEdge) knowledgeKey {
	return knowledgeKey{
		source:   r.source,
		chanID:   e.key.chanID,
		from:     e.key.from,
		capacity: e.capacity,
	}
}

func priorProbability(amt,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.035)
	highMode := 0.5 / (1 + math.Exp((x-0.88)/0.055))
	p := lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	if e.from == r.source {
		return 0.997
	}

	prior := priorProbability(load, e.capacity)
	b, ok := r.beliefs[e.key]
	if !ok {
		return prior
	}

	if b.lowerOK > 0 && load <= b.lowerOK {
		return 0.995
	}

	estimate := b.estimate
	if estimate <= 0 {
		estimate = e.capacity / 2
	}

	scale := float64(e.capacity) * 0.055
	if scale < 1 {
		scale = 1
	}
	z := (float64(load) - float64(estimate)) / scale
	if z > 30 {
		z = 30
	} else if z < -30 {
		z = -30
	}
	model := 1 / (1 + math.Exp(z))

	weight := b.conf / (b.conf + 2)
	p := prior*(1-weight) + model*weight

	if b.upperFail > 0 {
		if load >= b.upperFail {
			if p > 0.04 {
				p = 0.04
			}
			if p < 0.012 {
				p = 0.012
			}
		} else if load > b.lowerOK &&
			b.upperFail > b.lowerOK {

			span := float64(b.upperFail - b.lowerOK)
			left := float64(b.upperFail-load) / span
			p *= 0.25 + 0.75*left
		}
	}

	if p < 0.012 {
		return 0.012
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func updateBelief(b liquidityBelief, capacity,
	load lnwire.MilliSatoshi, success bool) liquidityBelief {

	if b.estimate <= 0 {
		b.estimate = capacity / 2
	}

	if success {
		if load > b.lowerOK {
			b.lowerOK = load
		}
		if b.upperFail > 0 && load >= b.upperFail {
			b.upperFail = 0
		}

		target := load + (capacity-load)*4/5
		if target > b.estimate {
			b.estimate = target
		}
		b.conf += 1.4
	} else {
		if b.lowerOK > 0 && load <= b.lowerOK {
			b.lowerOK = load * 3 / 4
		}
		if b.upperFail == 0 || load < b.upperFail {
			b.upperFail = load
		}

		target := load / 8
		if target < b.estimate {
			b.estimate = (b.estimate + target) / 2
		}
		b.conf += 1
	}

	if b.conf > 12 {
		b.conf = 12
	}
	if b.estimate < 0 {
		b.estimate = 0
	}
	if b.estimate > capacity {
		b.estimate = capacity
	}
	return b
}

func (r *candidateRouter) observe(e *candidateEdge,
	load lnwire.MilliSatoshi, success bool) {

	local := r.beliefs[e.key]
	local = updateBelief(local, e.capacity, load, success)
	r.beliefs[e.key] = local

	k := r.knowledgeKey(e)
	sharedKnowledge.Lock()
	global := sharedKnowledge.beliefs[k]
	global = updateBelief(global, e.capacity, load, success)
	sharedKnowledge.beliefs[k] = global
	sharedKnowledge.Unlock()
}

type pathLabel struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	fee    lnwire.MilliSatoshi
	score  float64
	hops   int
	path   []*candidateEdge
	active bool
	index  int
}

type labelQueue []*pathLabel

func (q labelQueue) Len() int {
	return len(q)
}

func (q labelQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q labelQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *labelQueue) Push(x any) {
	item := x.(*pathLabel)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *labelQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func pathContains(path []*candidateEdge, vertex route.Vertex) bool {
	for _, edge := range path {
		if edge.from == vertex || edge.to == vertex {
			return true
		}
	}
	return false
}

func insertLabel(labels map[route.Vertex][]*pathLabel,
	label *pathLabel) bool {

	current := labels[label.node]
	filtered := current[:0]

	for _, old := range current {
		if !old.active {
			continue
		}
		if old.score <= label.score &&
			old.amount <= label.amount {

			return false
		}
		if label.score <= old.score &&
			label.amount <= old.amount {

			old.active = false
			continue
		}
		filtered = append(filtered, old)
	}

	filtered = append(filtered, label)
	if len(filtered) > maxLabels {
		minAmount := 0
		for i := 1; i < len(filtered); i++ {
			if filtered[i].amount < filtered[minAmount].amount {
				minAmount = i
			}
		}

		worst := -1
		for i := range filtered {
			if i == minAmount {
				continue
			}
			if worst < 0 ||
				filtered[i].score > filtered[worst].score {

				worst = i
			}
		}
		if worst < 0 {
			worst = len(filtered) - 1
		}

		evicted := filtered[worst]
		evicted.active = false
		filtered = append(
			filtered[:worst], filtered[worst+1:]...,
		)
		if evicted == label {
			labels[label.node] = filtered
			return false
		}
	}

	labels[label.node] = filtered
	label.active = true
	return true
}

func copyReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func copyUses(src map[edgeKey]int) map[edgeKey]int {
	dst := make(map[edgeKey]int, len(src))
	for key, count := range src {
		dst[key] = count
	}
	return dst
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reserved map[edgeKey]lnwire.MilliSatoshi,
	uses map[edgeKey]int,
	feeCap lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid shard amount")
	}

	price := riskPriceMsat
	if feeCap != lnwire.MaxMilliSatoshi {
		budgetPrice := float64(feeCap) * 2
		if budgetPrice < price {
			price = budgetPrice
		}
		if price < 30000 {
			price = 30000
		}
	}

	start := &pathLabel{
		node:   r.spec.Target,
		amount: amt,
		score:  0,
		active: true,
	}

	labels := map[route.Vertex][]*pathLabel{
		r.spec.Target: {start},
	}
	pq := &labelQueue{}
	heap.Push(pq, start)

	for pq.Len() != 0 {
		current := heap.Pop(pq).(*pathLabel)
		if !current.active {
			continue
		}
		if current.node == r.source {
			rt, err := r.buildRoute(amt, current.path)
			return rt, current.score, err
		}
		if current.hops >= maxPathHops {
			continue
		}

		for _, incoming := range r.incoming[current.node] {
			if r.badPolicy[incoming.key] {
				continue
			}
			if pathContains(current.path, incoming.from) {
				continue
			}

			over := amt
			addedFee := lnwire.MilliSatoshi(0)
			if len(current.path) != 0 {
				outgoing := current.path[0]
				addedFee = nodeFee(
					outgoing, incoming, current.amount,
				)
				over = current.amount + addedFee
			}

			if !incoming.shardUsable(over) {
				continue
			}

			load := over + reserved[incoming.key]
			if load > incoming.capacity {
				continue
			}

			if incoming.from == r.source {
				balance := r.localBalances[incoming.key.chanID]
				if load > balance {
					continue
				}
			}

			totalFee := over - amt
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			probability := r.edgeProbability(incoming, load)
			addedScore := float64(addedFee) +
				price*(-math.Log(probability)) +
				hopCostMsat +
				float64(uses[incoming.key])*reuseCostMsat +
				r.penalty[incoming.key]

			path := make([]*candidateEdge, len(current.path)+1)
			path[0] = incoming
			copy(path[1:], current.path)

			next := &pathLabel{
				node:   incoming.from,
				amount: over,
				fee:    totalFee,
				score:  current.score + addedScore,
				hops:   current.hops + 1,
				path:   path,
			}
			if insertLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = deliver
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		amounts[i] = amounts[i+1] +
			nodeFee(path[i+1], path[i], amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := deliver
		expiry := finalCltvDelta
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func routeDelivery(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeAmount(rt *route.Route, index int) lnwire.MilliSatoshi {
	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func routeEdge(rt *route.Route, index int) edgeKey {
	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}
	return edgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
	}
}

func addRouteReservations(rt *route.Route,
	reserved map[edgeKey]lnwire.MilliSatoshi,
	uses map[edgeKey]int) {

	for i := range rt.Hops {
		key := routeEdge(rt, i)
		reserved[key] += routeAmount(rt, i)
		uses[key]++
	}
}

func (r *candidateRouter) rebuildReservations() {
	r.reserved = make(map[edgeKey]lnwire.MilliSatoshi)
	r.useCount = make(map[edgeKey]int)
	for _, held := range r.held {
		addRouteReservations(
			held.rt, r.reserved, r.useCount,
		)
	}
}

func (r *candidateRouter) reconcileHeld(inFlight uint32) bool {
	if int(inFlight) >= len(r.held) {
		return false
	}

	r.held = r.held[:int(inFlight)]
	r.rebuildReservations()
	return true
}

func weightedShard(remaining lnwire.MilliSatoshi,
	parts int, bias float64) lnwire.MilliSatoshi {

	if parts <= 1 {
		return remaining
	}

	totalWeight := 0.0
	for i := 0; i < parts; i++ {
		totalWeight += math.Pow(bias, float64(parts-1-i))
	}
	firstWeight := math.Pow(bias, float64(parts-1))
	shard := lnwire.MilliSatoshi(
		float64(remaining) * firstWeight / totalWeight,
	)

	if shard < 1 {
		shard = 1
	}
	maximum := remaining - lnwire.MilliSatoshi(parts-1)
	if shard > maximum {
		shard = maximum
	}
	return shard
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts int, bias float64,
	feeBudget lnwire.MilliSatoshi) ([]*route.Route, float64, bool) {

	reserved := copyReservations(r.reserved)
	uses := copyUses(r.useCount)
	remaining := total
	feeRemaining := feeBudget

	plan := make([]*route.Route, 0, parts)
	score := float64(parts-1) * 20000

	for i := 0; i < parts; i++ {
		left := parts - i
		shard := weightedShard(remaining, left, bias)

		rt, routeScore, err := r.findRoute(
			shard, reserved, uses, feeRemaining,
		)
		if err != nil {
			return nil, 0, false
		}

		fee := rt.TotalAmount - shard
		if feeRemaining != lnwire.MaxMilliSatoshi {
			if fee > feeRemaining {
				return nil, 0, false
			}
			feeRemaining -= fee
		}

		plan = append(plan, rt)
		score += routeScore
		addRouteReservations(rt, reserved, uses)
		remaining -= shard
	}

	if remaining != 0 {
		return nil, 0, false
	}
	return plan, score, true
}

func candidatePartCounts(maxParts int) []int {
	if maxParts < 1 {
		return nil
	}

	counts := make([]int, 0, 11)
	add := func(value int) {
		if value < 1 || value > maxParts {
			return
		}
		for _, existing := range counts {
			if existing == value {
				return
			}
		}
		counts = append(counts, value)
	}

	limit := maxParts
	if limit > 8 {
		limit = 8
	}
	for i := 1; i <= limit; i++ {
		add(i)
	}
	add(10)
	add(12)
	add(maxParts)

	return counts
}

func (r *candidateRouter) remainingFeeBudget() (
	lnwire.MilliSatoshi, error) {

	limit := r.spec.FeeLimitMsat
	if limit == lnwire.MaxMilliSatoshi {
		return limit, nil
	}
	if r.committedFees > limit {
		return 0, errors.New("fee budget exhausted")
	}
	return limit - r.committedFees, nil
}

func (r *candidateRouter) createPlan(amt lnwire.MilliSatoshi,
	inFlight uint32) error {

	maxParts := int(r.spec.MaxParts)
	if maxParts < 1 {
		maxParts = 1
	}
	available := maxParts - int(inFlight)
	if available < 1 {
		return errors.New("maximum parts in flight")
	}

	feeBudget, err := r.remainingFeeBudget()
	if err != nil {
		return err
	}

	var best []*route.Route
	bestScore := math.Inf(1)
	biases := []float64{1, 1.35, 0.74}

	for _, parts := range candidatePartCounts(available) {
		for _, bias := range biases {
			plan, score, ok := r.makePlan(
				amt, parts, bias, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) == 0 {
		return errors.New("no route found")
	}

	r.plan = best
	r.plannedAmt = amt
	return nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment complete")
	}

	if r.reconcileHeld(inFlightHtlcs) {
		r.plan = nil
		r.plannedAmt = 0
	}

	if len(r.plan) == 0 || r.plannedAmt != amt {
		r.plan = nil
		r.plannedAmt = 0
		if err := r.createPlan(amt, inFlightHtlcs); err != nil {
			return nil, err
		}
	}

	rt := r.plan[0]
	r.plan = r.plan[1:]
	deliver := routeDelivery(rt)
	if deliver <= 0 || deliver > r.plannedAmt {
		r.plan = nil
		r.plannedAmt = 0
		return nil, errors.New("invalid planned shard")
	}
	r.plannedAmt -= deliver

	return rt, nil
}

func failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key := routeEdge(rt, i)
			edge := r.edges[key]
			if edge == nil {
				continue
			}
			load := routeAmount(rt, i) + r.reserved[key]
			r.observe(edge, load, true)
		}

		deliver := routeDelivery(rt)
		if rt.TotalAmount >= deliver {
			r.committedFees += rt.TotalAmount - deliver
		}
		r.held = append(r.held, heldShard{rt: rt})
		r.rebuildReservations()
		return nil
	}

	r.plan = nil
	r.plannedAmt = 0

	failIdx := failureIndex(rt, result.FailureSource)
	if failIdx >= 0 {
		for i := 0; i < failIdx && i < len(rt.Hops); i++ {
			key := routeEdge(rt, i)
			edge := r.edges[key]
			if edge == nil {
				continue
			}
			load := routeAmount(rt, i) + r.reserved[key]
			r.observe(edge, load, true)
		}
	}

	code := result.Failure.Code()
	if failIdx >= 0 && failIdx < len(rt.Hops) {
		key := routeEdge(rt, failIdx)
		edge := r.edges[key]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			if edge != nil {
				load := routeAmount(rt, failIdx) +
					r.reserved[key]
				r.observe(edge, load, false)
			}

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.badPolicy[key] = true

		default:
			r.penalty[key] += 175000
		}
	} else {
		for i := range rt.Hops {
			key := routeEdge(rt, i)
			r.penalty[key] += 25000
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskPriceMsat  = 420000.0
	hopCostMsat    = 8000.0
	minShardMsat   = lnwire.MilliSatoshi(1000)
)

type edgeKey struct {
	chanID   uint64
	from     route.Vertex
	to       route.Vertex
	capacity lnwire.MilliSatoshi
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	observed uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) outboundFee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	fee := int64(e.baseFeeMsat) +
		int64(amt)*int64(e.feeRatePPM)/1_000_000
	if fee < 0 {
		return 0
	}

	return lnwire.MilliSatoshi(fee)
}

func (e *candidateEdge) inboundFee(amt lnwire.MilliSatoshi) int64 {
	return e.inboundBase + int64(amt)*e.inboundRate/1_000_000
}

func forwardingFee(incoming, outgoing *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outFee := outgoing.outboundFee(amt)
	inBase := amt + outFee
	combined := int64(outFee) + incoming.inboundFee(inBase)
	if combined < 0 {
		return 0
	}

	return lnwire.MilliSatoshi(combined)
}

func priorProbability(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.035)
	highMode := 0.49 / (1 + math.Exp((x-0.82)/0.08))
	p := lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	prior := priorProbability(load, e.capacity)

	sharedBeliefs.Lock()
	belief, ok := sharedBeliefs.values[e.key]
	sharedBeliefs.Unlock()

	if !ok || belief.observed == 0 {
		return prior
	}

	if belief.lowerOK > 0 && load <= belief.lowerOK {
		return 0.993
	}
	if belief.upperBad > 0 && load >= belief.upperBad {
		return 0.012
	}

	var estimate lnwire.MilliSatoshi
	switch {
	case belief.lowerOK > 0 && belief.upperBad > belief.lowerOK:
		estimate = belief.lowerOK +
			(belief.upperBad-belief.lowerOK)*35/100

	case belief.upperBad > 0:
		estimate = belief.upperBad * 30 / 100

	case belief.lowerOK > 0:
		estimate = belief.lowerOK * 5 / 4
		fallback := e.capacity * 3 / 4
		if estimate < fallback {
			estimate = fallback
		}
		if estimate > e.capacity {
			estimate = e.capacity
		}

	default:
		return prior
	}

	scale := float64(e.capacity) * 0.06
	if scale < 1000 {
		scale = 1000
	}
	evidence := 1 / (1 + math.Exp(
		(float64(load)-float64(estimate))/scale,
	))

	confidence := 1 - math.Exp(-float64(belief.observed)/2.5)
	if confidence > 0.90 {
		confidence = 0.90
	}

	p := prior*(1-confidence) + evidence*confidence
	if p < 0.012 {
		return 0.012
	}
	if p > 0.993 {
		return 0.993
	}

	return p
}

func recordSuccess(key edgeKey, amt lnwire.MilliSatoshi) {
	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	belief := sharedBeliefs.values[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperBad > 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if belief.observed < 1000 {
		belief.observed++
	}
	sharedBeliefs.values[key] = belief
}

func recordFailure(key edgeKey, amt lnwire.MilliSatoshi) {
	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	belief := sharedBeliefs.values[key]
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.observed < 1000 {
		belief.observed++
	}
	sharedBeliefs.values[key] = belief
}

type recentFailure struct {
	amount lnwire.MilliSatoshi
	count  uint32
}

type routeReservation struct {
	edges  []edgeKey
	amount []lnwire.MilliSatoshi
}

type attemptRecord struct {
	edges  []edgeKey
	loads  []lnwire.MilliSatoshi
	amount []lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	recent map[edgeKey]recentFailure
	extra  map[edgeKey]float64

	held     []routeReservation
	plan     []*route.Route
	attempts map[*route.Route]attemptRecord

	spentFee lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		recent:        make(map[edgeKey]recentFailure),
		extra:         make(map[edgeKey]float64),
		attempts:      make(map[*route.Route]attemptRecord),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				capacity := lnwire.NewMSatFromSatoshis(
					ch.Capacity,
				)
				key := edgeKey{
					chanID:   ch.ChannelID,
					from:     ch.OtherNode,
					to:       node,
					capacity: capacity,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      capacity,
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   int64(ch.InboundFee.BaseFee),
					inboundRate:   int64(ch.InboundFee.FeeRate),
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeByKey[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

type searchItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	path   []*candidateEdge
	index  int
}

type searchQueue []*searchItem

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *searchQueue) Push(value any) {
	item := value.(*searchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *searchQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	old[last] = nil
	*q = old[:last]
	return item
}

func copyReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) currentReservations() map[edgeKey]lnwire.MilliSatoshi {
	reserved := make(map[edgeKey]lnwire.MilliSatoshi)
	for _, hold := range r.held {
		for i, key := range hold.edges {
			reserved[key] += hold.amount[i]
		}
	}

	return reserved
}

func (r *candidateRouter) canUse(edge *candidateEdge,
	amount, load lnwire.MilliSatoshi) bool {

	if amount < edge.minHTLC {
		return false
	}
	if edge.maxHTLC != 0 && amount > edge.maxHTLC {
		return false
	}
	if amount > edge.capacity || load > edge.capacity {
		return false
	}

	if edge.from == r.source {
		balance := r.localBalances[edge.chanID]
		if load > balance {
			return false
		}
	}

	return true
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		return 0.998
	}

	p := beliefProbability(edge, load)
	if failure, ok := r.recent[edge.key]; ok && failure.amount > 0 {
		ratio := float64(load) / float64(failure.amount)
		if ratio > 1 {
			ratio = 1
		}
		if ratio < 0 {
			ratio = 0
		}

		penalty := math.Exp(
			-0.85 * float64(failure.count) * ratio,
		)
		p *= penalty
	}

	if p < 0.006 {
		return 0.006
	}
	if p > 0.998 {
		return 0.998
	}

	return p
}

func (r *candidateRouter) edgeScore(edge *candidateEdge,
	load, reserved lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(edge, load)
	score := -math.Log(p)*riskPriceMsat + hopCostMsat
	score += r.extra[edge.key]

	if reserved > 0 && edge.capacity > 0 {
		fraction := float64(reserved) / float64(edge.capacity)
		score += 100000 + 700000*fraction
	}

	return score
}

func (r *candidateRouter) searchRoute(deliver lnwire.MilliSatoshi,
	reserved map[edgeKey]lnwire.MilliSatoshi,
	feeWeight float64) (*route.Route, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	best := make(map[route.Vertex]float64)
	best[r.spec.Target] = 0

	pq := &searchQueue{}
	heap.Push(pq, &searchItem{
		node:   r.spec.Target,
		amount: deliver,
		score:  0,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*searchItem)
		bestScore, ok := best[item.node]
		if !ok || item.score > bestScore+0.0001 {
			continue
		}
		if item.node == r.source {
			return r.buildRoute(item.path, deliver)
		}

		for _, incoming := range r.incomingEdges[item.node] {
			edgeAmount := deliver
			feeDelta := lnwire.MilliSatoshi(0)

			if item.node != r.spec.Target {
				if len(item.path) == 0 {
					continue
				}

				outgoing := item.path[0]
				feeDelta = forwardingFee(
					incoming, outgoing, item.amount,
				)
				edgeAmount = item.amount + feeDelta
			}

			already := reserved[incoming.key]
			load := edgeAmount + already
			if !r.canUse(incoming, edgeAmount, load) {
				continue
			}

			score := item.score +
				float64(feeDelta)*feeWeight +
				r.edgeScore(incoming, load, already)

			old, exists := best[incoming.from]
			if exists && score >= old {
				continue
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = incoming
			copy(path[1:], item.path)

			best[incoming.from] = score
			heap.Push(pq, &searchItem{
				node:   incoming.from,
				amount: edgeAmount,
				score:  score,
				path:   path,
			})
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = deliver
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fee := forwardingFee(path[i], path[i+1], amounts[i+1])
		amounts[i] = amounts[i+1] + fee
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	for i, edge := range path {
		if amounts[i] < edge.minHTLC {
			return nil, errors.New("route below htlc minimum")
		}
		if edge.maxHTLC != 0 && amounts[i] > edge.maxHTLC {
			return nil, errors.New("route above htlc maximum")
		}
		if amounts[i] > edge.capacity {
			return nil, errors.New("route above channel capacity")
		}
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func routeDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeFee(rt *route.Route) lnwire.MilliSatoshi {
	deliver := routeDelivered(rt)
	if rt == nil || rt.TotalAmount < deliver {
		return 0
	}

	return rt.TotalAmount - deliver
}

func (r *candidateRouter) routeReservation(
	rt *route.Route) (routeReservation, bool) {

	if rt == nil || len(rt.Hops) == 0 {
		return routeReservation{}, false
	}

	result := routeReservation{
		edges:  make([]edgeKey, 0, len(rt.Hops)),
		amount: make([]lnwire.MilliSatoshi, 0, len(rt.Hops)),
	}

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		var edge *candidateEdge
		for key, candidate := range r.edgeByKey {
			if key.chanID == hop.ChannelID &&
				key.from == from && key.to == hop.PubKeyBytes {

				edge = candidate
				break
			}
		}
		if edge == nil {
			return routeReservation{}, false
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		result.edges = append(result.edges, edge.key)
		result.amount = append(result.amount, amount)
		from = hop.PubKeyBytes
	}

	return result, true
}

func addReservation(dst map[edgeKey]lnwire.MilliSatoshi,
	reservation routeReservation) {

	for i, key := range reservation.edges {
		dst[key] += reservation.amount[i]
	}
}

func (r *candidateRouter) evaluateRoute(rt *route.Route,
	reserved map[edgeKey]lnwire.MilliSatoshi) float64 {

	reservation, ok := r.routeReservation(rt)
	if !ok {
		return math.Inf(1)
	}

	score := float64(routeFee(rt))
	for i, key := range reservation.edges {
		edge := r.edgeByKey[key]
		already := reserved[key]
		load := reservation.amount[i] + already
		score += r.edgeScore(edge, load, already)
	}

	return score
}

func (r *candidateRouter) remainingBudget() (
	lnwire.MilliSatoshi, bool) {

	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi, false
	}
	if r.spentFee >= r.spec.FeeLimitMsat {
		return 0, true
	}

	return r.spec.FeeLimitMsat - r.spentFee, true
}

func (r *candidateRouter) findBudgetedRoute(
	deliver lnwire.MilliSatoshi,
	reserved map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi, limited bool) (*route.Route, error) {

	weights := [...]float64{1, 4, 16, 64, 256, 4096, 1000000000}

	var bestRoute *route.Route
	bestScore := math.Inf(1)

	for _, weight := range weights {
		rt, err := r.searchRoute(deliver, reserved, weight)
		if err != nil {
			continue
		}

		if limited && routeFee(rt) > feeCap {
			continue
		}

		score := r.evaluateRoute(rt, reserved)
		if score < bestScore {
			bestScore = score
			bestRoute = rt
		}

		if weight == 1 {
			break
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route within fee budget")
	}

	return bestRoute, nil
}

func shardFeeCap(budget, shard, remaining lnwire.MilliSatoshi,
	slots int) lnwire.MilliSatoshi {

	if slots <= 1 || shard >= remaining {
		return budget
	}

	cap := budget * shard / remaining
	cap += budget / lnwire.MilliSatoshi(slots*5)
	if cap > budget {
		cap = budget
	}

	return cap
}

func (r *candidateRouter) constructPlan(amount lnwire.MilliSatoshi,
	parts int, grow bool, baseReserved map[edgeKey]lnwire.MilliSatoshi,
	budget lnwire.MilliSatoshi, limited bool) ([]*route.Route,
	float64, error) {

	reserved := copyReservations(baseReserved)
	remaining := amount
	budgetLeft := budget
	plan := make([]*route.Route, 0, parts)
	score := 0.0

	for i := 0; i < parts; i++ {
		slots := parts - i
		shard := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)
		if shard < minShardMsat {
			return nil, 0, errors.New("shard too small")
		}

		cap := budgetLeft
		if limited {
			cap = shardFeeCap(
				budgetLeft, shard, remaining, slots,
			)
		}

		rt, err := r.findBudgetedRoute(
			shard, reserved, cap, limited,
		)
		if err != nil {
			return nil, 0, err
		}

		if grow && slots > 1 {
			minFuture := shard / 2
			if minFuture < minShardMsat {
				minFuture = minShardMsat
			}

			upper := shard * 3 / 2
			leave := minFuture * lnwire.MilliSatoshi(slots-1)
			if remaining > leave && upper > remaining-leave {
				upper = remaining - leave
			}

			low := shard
			best := rt
			for step := 0; step < 5 && upper > low; step++ {
				trial := low + (upper-low+1)/2
				trialCap := budgetLeft
				if limited {
					trialCap = shardFeeCap(
						budgetLeft, trial,
						remaining, slots,
					)
				}

				candidate, findErr := r.findBudgetedRoute(
					trial, reserved, trialCap, limited,
				)
				if findErr != nil {
					upper = trial - 1
					continue
				}

				best = candidate
				low = trial
			}
			rt = best
			shard = routeDelivered(rt)
		}

		fee := routeFee(rt)
		if limited && fee > budgetLeft {
			return nil, 0, errors.New("plan exceeds fee budget")
		}

		score += r.evaluateRoute(rt, reserved)
		reservation, ok := r.routeReservation(rt)
		if !ok {
			return nil, 0, errors.New("invalid planned route")
		}
		addReservation(reserved, reservation)

		plan = append(plan, rt)
		remaining -= shard
		if limited {
			budgetLeft -= fee
		}
	}

	if remaining != 0 {
		return nil, 0, errors.New("incomplete shard plan")
	}

	score += float64(parts-1) * 20000
	return plan, score, nil
}

func (r *candidateRouter) makePlan(amount lnwire.MilliSatoshi,
	partsLeft uint32) ([]*route.Route, error) {

	if partsLeft == 0 {
		return nil, errors.New("maximum parts reached")
	}

	baseReserved := r.currentReservations()
	budget, limited := r.remainingBudget()

	var best []*route.Route
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(partsLeft); parts++ {
		if amount/lnwire.MilliSatoshi(parts) < minShardMsat {
			break
		}

		for _, grow := range []bool{false, true} {
			if parts == 1 && grow {
				continue
			}

			plan, score, err := r.constructPlan(
				amount, parts, grow, baseReserved,
				budget, limited,
			)
			if err != nil {
				continue
			}
			if score < bestScore {
				bestScore = score
				best = plan
			}
		}
	}

	if len(best) == 0 {
		return nil, errors.New("no route found")
	}

	return best, nil
}

func (r *candidateRouter) reconcileHeld(inFlight uint32) {
	if uint32(len(r.held)) <= inFlight {
		return
	}

	if inFlight == 0 {
		r.held = nil
		return
	}

	start := len(r.held) - int(inFlight)
	remaining := make([]routeReservation, int(inFlight))
	copy(remaining, r.held[start:])
	r.held = remaining
}

func (r *candidateRouter) prepareAttempt(rt *route.Route) {
	reservation, ok := r.routeReservation(rt)
	if !ok {
		return
	}

	reserved := r.currentReservations()
	record := attemptRecord{
		edges:  append([]edgeKey(nil), reservation.edges...),
		amount: append([]lnwire.MilliSatoshi(nil), reservation.amount...),
		loads:  make([]lnwire.MilliSatoshi, len(reservation.edges)),
	}
	for i, key := range reservation.edges {
		record.loads[i] = reservation.amount[i] + reserved[key]
	}

	r.attempts[rt] = record
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}

	r.reconcileHeld(inFlightHtlcs)

	for len(r.plan) > 0 {
		rt := r.plan[0]
		r.plan = r.plan[1:]

		if routeDelivered(rt) > amt {
			r.plan = nil
			break
		}

		budget, limited := r.remainingBudget()
		if limited && routeFee(rt) > budget {
			r.plan = nil
			break
		}

		r.prepareAttempt(rt)
		return rt, nil
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts reached")
	}

	plan, err := r.makePlan(amt, maxParts-inFlightHtlcs)
	if err != nil {
		return nil, err
	}
	r.plan = plan

	rt := r.plan[0]
	r.plan = r.plan[1:]
	r.prepareAttempt(rt)

	return rt, nil
}

func failureOutgoingIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) fallbackAttemptRecord(
	rt *route.Route) attemptRecord {

	reservation, ok := r.routeReservation(rt)
	if !ok {
		return attemptRecord{}
	}

	reserved := r.currentReservations()
	record := attemptRecord{
		edges:  reservation.edges,
		amount: reservation.amount,
		loads:  make([]lnwire.MilliSatoshi, len(reservation.edges)),
	}
	for i, key := range reservation.edges {
		record.loads[i] = reservation.amount[i] + reserved[key]
	}

	return record
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	record, ok := r.attempts[rt]
	if ok {
		delete(r.attempts, rt)
	} else {
		record = r.fallbackAttemptRecord(rt)
	}

	if result.Failure == nil {
		for i, key := range record.edges {
			recordSuccess(key, record.loads[i])
			delete(r.recent, key)
			r.extra[key] *= 0.25
		}

		r.spentFee += routeFee(rt)
		if reservation, valid := r.routeReservation(rt); valid {
			r.held = append(r.held, reservation)
		}

		return nil
	}

	r.plan = nil

	failIdx := failureOutgoingIndex(rt, result.FailureSource)
	for i := 0; i < failIdx && i < len(record.edges); i++ {
		recordSuccess(record.edges[i], record.loads[i])
	}

	liquidityFailure :=
		result.Failure.Code() == lnwire.CodeTemporaryChannelFailure

	if failIdx >= 0 && failIdx < len(record.edges) {
		key := record.edges[failIdx]

		if liquidityFailure {
			recordFailure(key, record.loads[failIdx])

			recent := r.recent[key]
			recent.amount = record.loads[failIdx]
			if recent.count < 20 {
				recent.count++
			}
			r.recent[key] = recent
		} else {
			r.extra[key] += 2_000_000
		}
	} else {
		for _, key := range record.edges {
			r.extra[key] += 150_000
		}
	}

	return nil
}

var _ routing.SimRouter = (*candidateRouter)(nil)

func (r *candidateRouter) String() string {
	return fmt.Sprintf("candidate-router(%x)", r.source[:4])
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)
	riskPriceMsat  = 420000.0
	hopCostMsat    = 12000.0
	reuseCostMsat  = 180000.0
	maxSearchHops  = 32
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat int64
	feeRatePPM  int64

	inboundBase int64
	inboundRate int64

	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	fee := e.baseFeeMsat + int64(amt)*e.feeRatePPM/1_000_000
	if fee <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(fee)
}

func (e *candidateEdge) inboundFee(amt lnwire.MilliSatoshi) int64 {
	return e.inboundBase + int64(amt)*e.inboundRate/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type searchState struct {
	edge  *candidateEdge
	amt   lnwire.MilliSatoshi
	score float64
	depth int
	next  *searchState
}

type searchItem struct {
	state *searchState
	index int
}

type searchQueue []*searchItem

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].state.score < q[j].state.score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *searchQueue) Push(value any) {
	item := value.(*searchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	*q = old[:n-1]
	return item
}

type searchLabel struct {
	amt   lnwire.MilliSatoshi
	score float64
}

type plannedRoute struct {
	route *route.Route
	score float64
	fee   lnwire.MilliSatoshi
}

type attemptInfo struct {
	loads map[edgeKey]lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs      map[edgeKey]liquidityBelief
	reserved     map[edgeKey]lnwire.MilliSatoshi
	policyBad    map[edgeKey]uint32
	failureCount map[edgeKey]uint32

	committedFee lnwire.MilliSatoshi
	partsUsed   uint32
	attempts    uint32

	plan    []*plannedRoute
	offered map[*route.Route]*attemptInfo
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		policyBad:     make(map[edgeKey]uint32),
		failureCount:  make(map[edgeKey]uint32),
		offered:       make(map[*route.Route]*attemptInfo),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   int64(policy.FeeBaseMSat),
					feeRatePPM:    int64(policy.FeeProportionalMillionths),
					inboundBase:   int64(ch.InboundFee.BaseFee),
					inboundRate:   int64(ch.InboundFee.FeeRate),
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key := range r.edges {
		if belief, ok := sharedBeliefs.values[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func addMSat(a, b lnwire.MilliSatoshi) (lnwire.MilliSatoshi, bool) {
	if b > lnwire.MaxMilliSatoshi-a {
		return 0, false
	}
	return a + b, true
}

func forwardingFee(inEdge, outEdge *candidateEdge,
	outAmt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outFee := outEdge.fee(outAmt)
	inboundBasis, ok := addMSat(outAmt, outFee)
	if !ok {
		return lnwire.MaxMilliSatoshi
	}

	total := int64(outFee) + inEdge.inboundFee(inboundBasis)
	if total <= 0 {
		return 0
	}
	if total > int64(lnwire.MaxMilliSatoshi) {
		return lnwire.MaxMilliSatoshi
	}
	return lnwire.MilliSatoshi(total)
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.035)
	highMode := 0.48 / (1 + math.Exp(17*(x-0.79)))
	p := lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	if load > edge.capacity {
		return 0
	}
	if edge.from == r.source {
		return 0.999
	}

	prior := bimodalPrior(load, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return prior
	}

	if belief.lowerOK > 0 && load <= belief.lowerOK {
		return 0.995
	}

	if belief.upperBad > 0 && load >= belief.upperBad {
		return 0.012
	}

	switch {
	case belief.lowerOK > 0 && belief.upperBad > belief.lowerOK:
		width := float64(belief.upperBad - belief.lowerOK)
		position := float64(load-belief.lowerOK) / width
		evidence := 0.995*(1-position) + 0.012*position
		return 0.82*evidence + 0.18*prior

	case belief.upperBad > 0:
		position := float64(load) / float64(belief.upperBad)
		if position > 1 {
			position = 1
		}
		evidence := 0.985*(1-position) + 0.012*position
		return 0.70*evidence + 0.30*prior

	case belief.lowerOK > 0:
		ratio := float64(belief.lowerOK) / float64(load)
		if ratio > 1 {
			ratio = 1
		}
		return prior + (0.995-prior)*0.70*ratio
	}

	return prior
}

func (r *candidateRouter) edgeCost(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi) (float64, bool) {

	if !edge.usableHTLC(amt) {
		return 0, false
	}

	reserved := reservations[edge.key]
	load, ok := addMSat(amt, reserved)
	if !ok || load > edge.capacity {
		return 0, false
	}

	if edge.from == r.source {
		balance := r.localBalances[edge.chanID]
		if reserved > balance || amt > balance-reserved {
			return 0, false
		}
	}

	p := r.probability(edge, load)
	if p <= 0 {
		return 0, false
	}

	cost := -math.Log(p)*riskPriceMsat + hopCostMsat
	if reserved > 0 {
		fraction := float64(reserved) / float64(edge.capacity)
		cost += reuseCostMsat * (1 + 2*fraction)
	}
	if failures := r.failureCount[edge.key]; failures > 0 {
		cost += float64(failures) * 65000
	}
	if bad := r.policyBad[edge.key]; bad > 0 {
		cost += float64(bad) * 900000
	}

	return cost, true
}

func stateContains(state *searchState, node route.Vertex) bool {
	for current := state; current != nil; current = current.next {
		if current.edge.from == node || current.edge.to == node {
			return true
		}
	}
	return false
}

func acceptLabel(labels map[edgeKey][]searchLabel, key edgeKey,
	amt lnwire.MilliSatoshi, score float64) bool {

	current := labels[key]
	for _, label := range current {
		if label.amt <= amt && label.score <= score {
			return false
		}
	}

	filtered := current[:0]
	for _, label := range current {
		if amt <= label.amt && score <= label.score {
			continue
		}
		filtered = append(filtered, label)
	}

	filtered = append(filtered, searchLabel{amt: amt, score: score})
	if len(filtered) > 5 {
		worst := 0
		for i := 1; i < len(filtered); i++ {
			if filtered[i].score > filtered[worst].score {
				worst = i
			}
		}
		filtered[worst] = filtered[len(filtered)-1]
		filtered = filtered[:len(filtered)-1]
	}
	labels[key] = filtered
	return true
}

func (r *candidateRouter) findRoute(deliver,
	feeBudget lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi) (*plannedRoute, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid shard amount")
	}

	pq := &searchQueue{}
	heap.Init(pq)
	labels := make(map[edgeKey][]searchLabel)

	for _, edge := range r.incomingEdges[r.spec.Target] {
		cost, ok := r.edgeCost(edge, deliver, reservations)
		if !ok {
			continue
		}

		state := &searchState{
			edge:  edge,
			amt:   deliver,
			score: cost,
			depth: 1,
		}
		if acceptLabel(labels, edge.key, deliver, cost) {
			heap.Push(pq, &searchItem{state: state})
		}
	}

	for pq.Len() > 0 {
		state := heap.Pop(pq).(*searchItem).state

		if state.edge.from == r.source {
			fee := state.amt - deliver
			if fee <= feeBudget {
				rt, err := r.buildRoute(deliver, state)
				if err != nil {
					continue
				}
				return &plannedRoute{
					route: rt,
					score: state.score,
					fee:   fee,
				}, nil
			}
			continue
		}

		if state.depth >= maxSearchHops {
			continue
		}

		node := state.edge.from
		for _, inEdge := range r.incomingEdges[node] {
			if stateContains(state, inEdge.from) {
				continue
			}

			nodeFee := forwardingFee(inEdge, state.edge, state.amt)
			if nodeFee == lnwire.MaxMilliSatoshi {
				continue
			}
			inAmt, ok := addMSat(state.amt, nodeFee)
			if !ok {
				continue
			}

			edgeCost, ok := r.edgeCost(inEdge, inAmt, reservations)
			if !ok {
				continue
			}

			score := state.score + float64(nodeFee) + edgeCost
			if !acceptLabel(labels, inEdge.key, inAmt, score) {
				continue
			}

			next := &searchState{
				edge:  inEdge,
				amt:   inAmt,
				score: score,
				depth: state.depth + 1,
				next:  state,
			}
			heap.Push(pq, &searchItem{state: next})
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	first *searchState) (*route.Route, error) {

	var path []*candidateEdge
	for state := first; state != nil; state = state.next {
		path = append(path, state.edge)
	}
	if len(path) == 0 || path[0].from != r.source ||
		path[len(path)-1].to != r.spec.Target {

		return nil, errors.New("broken route path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)
	amounts[n-1] = deliver
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fee := forwardingFee(path[i], path[i+1], amounts[i+1])
		var ok bool
		amounts[i], ok = addMSat(amounts[i+1], fee)
		if !ok {
			return nil, errors.New("route amount overflow")
		}
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		amtToForward := deliver
		outgoingExpiry := finalCltvDelta
		if i+1 < n {
			amtToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func copyReservations(source map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {
	result := make(map[edgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		result[key] = amount
	}
	return result
}

func channelAmount(rt *route.Route, index int) lnwire.MilliSatoshi {
	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func reserveRoute(reservations map[edgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		amount := channelAmount(rt, i)
		reservations[key], _ = addMSat(reservations[key], amount)
		from = hop.PubKeyBytes
	}
}

func remainingPlanAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, item := range plan {
		last := item.route.Hops[len(item.route.Hops)-1]
		total, _ = addMSat(total, last.AmtToForward)
	}
	return total
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFee >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFee
}

func (r *candidateRouter) constructPlan(total lnwire.MilliSatoshi,
	partCount int, unequal bool) ([]*plannedRoute, float64, bool) {

	reservations := copyReservations(r.reserved)
	feeLeft := r.remainingFeeBudget()
	remaining := total
	plan := make([]*plannedRoute, 0, partCount)
	score := 0.0

	for i := 0; i < partCount; i++ {
		slots := partCount - i
		shard := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		if unequal && slots > 1 {
			minTail := shard / 3
			if minTail < 1000 {
				minTail = 1000
			}

			tailNeed := minTail * lnwire.MilliSatoshi(slots-1)
			if tailNeed < remaining {
				high := remaining - tailNeed
				if high > shard {
					candidates := []lnwire.MilliSatoshi{
						high,
						shard + (high-shard)*2/3,
						shard + (high-shard)/3,
					}
					for _, candidate := range candidates {
						test, err := r.findRoute(
							candidate, feeLeft, reservations,
						)
						if err == nil {
							shard = candidate
							test = nil
							break
						}
					}
				}
			}
		}

		if slots == 1 {
			shard = remaining
		}

		item, err := r.findRoute(shard, feeLeft, reservations)
		if err != nil {
			return nil, 0, false
		}

		plan = append(plan, item)
		reserveRoute(reservations, item.route)
		remaining -= shard
		if feeLeft != lnwire.MaxMilliSatoshi {
			if item.fee > feeLeft {
				return nil, 0, false
			}
			feeLeft -= item.fee
		}

		score += item.score
		if i > 0 {
			score += 35000
		}
	}

	if remaining != 0 {
		return nil, 0, false
	}
	return plan, score, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	partsAvailable uint32) error {

	if partsAvailable == 0 {
		return errors.New("maximum parts reached")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for count := 1; count <= int(partsAvailable); count++ {
		equal, score, ok := r.constructPlan(total, count, false)
		if ok && score < bestScore {
			best = equal
			bestScore = score
		}

		if count > 1 {
			unequal, unequalScore, ok := r.constructPlan(
				total, count, true,
			)
			if ok && unequalScore < bestScore {
				best = unequal
				bestScore = unequalScore
			}
		}

		if count >= 8 && best != nil {
			break
		}
	}

	if best == nil {
		return errors.New("no route found")
	}

	r.plan = best
	return nil
}

func (r *candidateRouter) attemptInfo(rt *route.Route) *attemptInfo {
	info := &attemptInfo{
		loads: make(map[edgeKey]lnwire.MilliSatoshi),
	}

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		amount := channelAmount(rt, i)
		load, ok := addMSat(amount, r.reserved[key])
		if !ok {
			load = lnwire.MaxMilliSatoshi
		}
		info.loads[key] = load
		from = hop.PubKeyBytes
	}

	return info
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment complete")
	}

	maxAttempts := uint32(48) + 8*r.spec.MaxParts
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt limit reached")
	}

	if len(r.plan) > 0 && remainingPlanAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		used := r.partsUsed
		if inFlightHtlcs > used {
			used = inFlightHtlcs
		}
		if used >= r.spec.MaxParts {
			return nil, errors.New("maximum parts reached")
		}

		if err := r.makePlan(amt, r.spec.MaxParts-used); err != nil {
			return nil, err
		}
	}

	item := r.plan[0]
	r.plan = r.plan[1:]
	r.offered[item.route] = r.attemptInfo(item.route)
	return item.route, nil
}

func routeEdgeKeys(rt *route.Route) []edgeKey {
	keys := make([]edgeKey, len(rt.Hops))
	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		from = hop.PubKeyBytes
	}
	return keys
}

func failureOutgoingIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func failureCode(failure any) (lnwire.FailCode, bool) {
	coded, ok := failure.(interface {
		Code() lnwire.FailCode
	})
	if !ok {
		return 0, false
	}
	return coded.Code(), true
}

func (r *candidateRouter) storeBelief(key edgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief
	sharedBeliefs.Lock()
	shared := sharedBeliefs.values[key]
	if belief.lowerOK > shared.lowerOK {
		shared.lowerOK = belief.lowerOK
	}
	if belief.upperBad > 0 &&
		(shared.upperBad == 0 || belief.upperBad < shared.upperBad) {

		shared.upperBad = belief.upperBad
	}
	if shared.upperBad > 0 && shared.lowerOK >= shared.upperBad {
		shared.upperBad = 0
	}
	sharedBeliefs.values[key] = shared
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key edgeKey,
	load lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if load > belief.lowerOK {
		belief.lowerOK = load
	}
	if belief.upperBad > 0 && belief.lowerOK >= belief.upperBad {
		belief.upperBad = 0
	}
	r.storeBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperBad == 0 || load < belief.upperBad {
		belief.upperBad = load
	}
	if belief.lowerOK >= belief.upperBad {
		belief.lowerOK = 0
	}
	r.failureCount[key]++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	r.attempts++

	info := r.offered[rt]
	delete(r.offered, rt)
	if info == nil {
		info = r.attemptInfo(rt)
	}

	keys := routeEdgeKeys(rt)

	if result.Failure == nil {
		for _, key := range keys {
			r.recordSuccess(key, info.loads[key])
		}

		reserveRoute(r.reserved, rt)
		r.partsUsed++

		if len(rt.Hops) == 0 {
			return fmt.Errorf("successful route has no hops")
		}
		delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
		if rt.TotalAmount >= delivered {
			fee := rt.TotalAmount - delivered
			r.committedFee, _ = addMSat(r.committedFee, fee)
		}
		return nil
	}

	r.plan = nil
	failIndex := failureOutgoingIndex(rt, result.FailureSource)
	code, hasCode := failureCode(result.Failure)

	if failIndex >= 0 {
		for i := 0; i < failIndex && i < len(keys); i++ {
			r.recordSuccess(keys[i], info.loads[keys[i]])
		}
	}

	if !hasCode || failIndex < 0 || failIndex >= len(keys) {
		return nil
	}

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		r.recordFailure(
			keys[failIndex], info.loads[keys[failIndex]],
		)

	case lnwire.CodeFeeInsufficient, lnwire.CodeIncorrectCltvExpiry:
		r.policyBad[keys[failIndex]]++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta     = uint32(40)
	baseRiskPriceMsat  = float64(420_000)
	minRiskPriceMsat   = float64(30_000)
	hopCostMsat        = float64(2_000)
	reusedEdgeCostMsat = float64(650_000)
	maxSearchHops      = 60
	maxLabelsPerNode   = 8
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inbound := int64(in.inboundBase) +
		int64(amt)*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved       map[edgeKey]lnwire.MilliSatoshi
	edgePenalty    map[edgeKey]float64
	issued         map[*route.Route]*routeMeta
	plan           []*plannedRoute
	planRemaining  lnwire.MilliSatoshi
	committedFees  lnwire.MilliSatoshi
	budgetGuard    lnwire.MilliSatoshi
	successfulParts uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:          view,
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeLookup:    make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[edgeKey]float64),
		issued:        make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() {
		return 0
	}
	if now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	// Evidence softens over roughly half an hour of virtual time. Bounds
	// remain strong within a payment but do not permanently retire a
	// corridor when traffic is moving.
	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		// A failure may have been caused by a sibling reservation, so an
		// upper bound is deliberately soft rather than a permanent ban.
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees + r.budgetGuard
	if spent >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}
	return price
}

func cloneReservations(src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {
	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)
			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}
				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				// Our balance is known exactly, but retain a little
				// uncertainty for concurrent sibling payments.
				p = 0.985
			}

			score := cur.score + float64(nodeCharge) +
				price*(-math.Log(p)) + hopCostMsat +
				r.edgePenalty[edge.key]

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.45
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)
	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}
		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			int64(total) * weight / sum,
		)
		if part <= 0 {
			part = 1
		}
		result[i] = part
		remaining -= part
	}
	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	switch parts {
	case 2:
		for _, weights := range [][]int64{
			{45, 55}, {55, 45},
			{35, 65}, {65, 35},
			{25, 75}, {75, 25},
		} {
			patterns = append(patterns,
				weightedAllocation(total, weights))
		}

	case 3:
		for _, weights := range [][]int64{
			{20, 30, 50}, {50, 30, 20},
			{25, 35, 40}, {40, 35, 25},
		} {
			patterns = append(patterns,
				weightedAllocation(total, weights))
		}

	case 4:
		for _, weights := range [][]int64{
			{15, 20, 25, 40}, {40, 25, 20, 15},
		} {
			patterns = append(patterns,
				weightedAllocation(total, weights))
		}

	default:
		if parts > 4 {
			ascending := make([]int64, parts)
			descending := make([]int64, parts)
			for i := 0; i < parts; i++ {
				ascending[i] = int64(i + 1)
				descending[i] = int64(parts - i)
			}
			patterns = append(patterns,
				weightedAllocation(total, ascending),
				weightedAllocation(total, descending),
			)
		}
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}

		pr, err := r.findRoute(shard, reservations, remainingBudget)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
	}

	// Repeated base fees and the larger failure surface make unnecessary
	// parts undesirable, while reliability can still justify splitting.
	totalScore += float64(len(plan)-1) * 40_000

	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) != 0 {
		return best, nil
	}

	// If joint planning cannot cover the full remainder, retain a bounded
	// reactive fallback. It retries at a smaller amount, but only when
	// enough part slots remain to make such a shard useful.
	if slots > 1 {
		shard := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		for shard >= 10_000 {
			cap := feeBudget
			if feeBudget != lnwire.MaxMilliSatoshi {
				cap = feeBudget * shard / total
			}

			pr, err := r.findRoute(shard, r.reserved, cap)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}
			shard /= 2
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	used := r.successfulParts
	if inFlightHtlcs > used {
		used = inFlightHtlcs
	}
	if used >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - used

	if len(r.plan) != 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
		r.planRemaining = 0
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
		r.planRemaining = queuedAmount(plan)
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.planRemaining -= next.meta.delivered
	r.issued[next.rt] = next.meta

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		r.planRemaining = 0
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.35
		}

		r.committedFees += meta.fee
		r.successfulParts++
		return nil
	}

	// Any failed route invalidates the remainder of the joint plan because
	// its tentative reservations assumed that this shard succeeded.
	r.plan = nil
	r.planRemaining = 0

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// Every edge before the failing node's outgoing edge demonstrably
	// carried the total load that included our existing reservations.
	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}
	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
	}

	code := result.Failure.Code()

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.edgePenalty[edge.key] += 350_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			// These indicate a policy mismatch rather than hidden
			// liquidity. Avoid the edge without poisoning its balance.
			r.edgePenalty[edge.key] += 5_000_000

		default:
			r.edgePenalty[edge.key] += 1_500_000
		}
	} else {
		// A dispatch refusal has no failure source and teaches nothing
		// about liquidity. Add a small budget guard and path penalty so
		// an accounting discrepancy cannot burn the attempt budget.
		if r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
			guard := meta.fee / 20
			if guard < 1_000 {
				guard = 1_000
			}
			r.budgetGuard += guard
		}
		for _, edge := range meta.path {
			r.edgePenalty[edge.key] += 100_000
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = 40
	riskPriceMsat    = 420000.0
	hopPriceMsat     = 20000.0
	partPriceMsat    = 80000.0
	reusePriceMsat   = 850000.0
	failurePriceMsat = 400000.0
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	base := int64(e.baseFeeMsat)
	rate := int64(e.feeRatePPM)
	fee := base + int64(amt)*rate/1_000_000
	if fee <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(fee)
}

func (e *candidateEdge) policyUsable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return amt <= e.capacity
}

// forwardingFee computes the fee charged by the node between incoming and
// outgoing. The inbound fee is attached to the incoming channel, and is
// applied to the forwarded amount plus the ordinary outbound fee.
func forwardingFee(incoming, outgoing *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outFee := outgoing.fee(amt)
	inBase := int64(incoming.inboundBase)
	inRate := int64(incoming.inboundRate)
	inFee := inBase +
		int64(amt+outFee)*inRate/1_000_000

	total := int64(outFee) + inFee
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.RWMutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

func readBelief(key edgeKey) liquidityBelief {
	sharedBeliefs.RLock()
	b := sharedBeliefs.m[key]
	sharedBeliefs.RUnlock()

	return b
}

func recordSuccess(edge *candidateEdge, amt lnwire.MilliSatoshi) {
	sharedBeliefs.Lock()
	b := sharedBeliefs.m[edge.key]

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	optimistic := edge.capacity * 92 / 100
	if optimistic < amt {
		optimistic = amt
	}
	if optimistic > b.estimate {
		b.estimate = optimistic
	}

	if b.samples < 1000 {
		b.samples++
	}
	sharedBeliefs.m[edge.key] = b
	sharedBeliefs.Unlock()
}

func recordFailure(edge *candidateEdge, amt lnwire.MilliSatoshi) {
	sharedBeliefs.Lock()
	b := sharedBeliefs.m[edge.key]

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= b.upperFail {
		b.lowerOK = b.upperFail * 3 / 4
	}

	depleted := amt / 5
	floor := edge.capacity / 200
	if depleted < floor {
		depleted = floor
	}
	if b.estimate == 0 || depleted < b.estimate {
		b.estimate = depleted
	}

	if b.samples < 1000 {
		b.samples++
	}
	sharedBeliefs.m[edge.key] = b
	sharedBeliefs.Unlock()
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

// bimodalPrior models a channel as usually being close to empty or close to
// full in a particular direction. Tiny transfers can use either mode, while
// transfers near capacity require the full mode and encounter a sharp cliff.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity == 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	fullMode := 1.0 / (1.0 + math.Exp((x-0.93)/0.035))

	return clampProbability(0.48*lowMode + 0.52*fullMode)
}

func edgeProbability(edge *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	prior := bimodalPrior(load, edge.capacity)
	b := readBelief(edge.key)
	if b.samples == 0 {
		return prior
	}

	if b.lowerOK != 0 && load <= b.lowerOK {
		return 0.985
	}
	if b.upperFail != 0 && load >= b.upperFail {
		// A failure may have been caused by a temporarily held sibling
		// shard, so never permanently retire the direction.
		return 0.012
	}

	evidence := prior
	if b.estimate != 0 && edge.capacity != 0 {
		width := 0.055 * float64(edge.capacity)
		if width < 1 {
			width = 1
		}
		evidence = 1.0 / (1.0 +
			math.Exp((float64(load)-float64(b.estimate))/width))
	}

	confidence := 0.18 * float64(b.samples)
	if confidence > 0.85 {
		confidence = 0.85
	}
	p := prior*(1-confidence) + evidence*confidence

	if b.lowerOK != 0 && b.upperFail != 0 &&
		b.lowerOK < load && load < b.upperFail {

		span := float64(b.upperFail - b.lowerOK)
		position := float64(load-b.lowerOK) / span
		bounded := 0.985*(1-position) + 0.012*position
		p = 0.45*p + 0.55*bounded
	}

	return clampProbability(p)
}

type failurePenalty struct {
	amt   lnwire.MilliSatoshi
	count uint32
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	committedFee lnwire.MilliSatoshi

	// held is the aggregate load of this payment's successful atomic
	// shards. heldRoutes lets it be reconciled with inFlightHtlcs.
	held       map[edgeKey]lnwire.MilliSatoshi
	heldRoutes []*route.Route

	// plan contains the rest of an up-front route set. A failed shard
	// invalidates the set and triggers a new joint plan.
	plan []*route.Route

	// issued records the reservations that existed when a route was sent,
	// so feedback is learned at total load rather than shard load.
	issued map[*route.Route]map[edgeKey]lnwire.MilliSatoshi

	penalties map[edgeKey]failurePenalty
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		held:          make(map[edgeKey]lnwire.MilliSatoshi),
		issued:        make(map[*route.Route]map[edgeKey]lnwire.MilliSatoshi),
		penalties:     make(map[edgeKey]failurePenalty),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: edgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
					},
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

type pathItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
	idx   int
}

type pathQueue []*pathItem

func (q pathQueue) Len() int {
	return len(q)
}

func (q pathQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q pathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *pathQueue) Push(x any) {
	item := x.(*pathItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *pathQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]

	return item
}

func copyReservations(src map[edgeKey]lnwire.MilliSatoshi) map[
	edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingBudget() lnwire.MilliSatoshi {
	limit := r.spec.FeeLimitMsat
	if limit == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFee >= limit {
		return 0
	}

	return limit - r.committedFee
}

func addWithinLimit(a, b, limit lnwire.MilliSatoshi) bool {
	if limit == lnwire.MaxMilliSatoshi {
		return true
	}
	if a > limit {
		return false
	}

	return b <= limit-a
}

func (r *candidateRouter) penaltyFor(key edgeKey,
	load lnwire.MilliSatoshi) float64 {

	p, ok := r.penalties[key]
	if !ok || p.amt == 0 {
		return 0
	}

	ratio := float64(load) / float64(p.amt)
	if ratio > 1 {
		ratio = 1
	}
	if ratio < 0 {
		ratio = 0
	}

	return failurePriceMsat * float64(p.count) *
		ratio * ratio * ratio
}

// findRoute performs a reliability-aware backward search. Its score is
// denominated in millisatoshis: actual fees plus a fixed msat price for
// negative log success probability.
func (r *candidateRouter) findRoute(
	amt, maxFee lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi) (*route.Route,
	float64, error) {

	if amt == 0 {
		return nil, 0, errors.New("zero shard")
	}

	bestScore := make(map[route.Vertex]float64)
	bestAmt := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	bestAmt[r.spec.Target] = amt

	pq := &pathQueue{}
	heap.Push(pq, &pathItem{
		node: r.spec.Target,
		amt:  amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*pathItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			sendAmt := item.amt
			nodeFee := lnwire.MilliSatoshi(0)

			if item.node != r.spec.Target {
				outgoing, ok := next[item.node]
				if !ok {
					continue
				}
				nodeFee = forwardingFee(
					edge, outgoing, item.amt,
				)
				sendAmt += nodeFee
			}

			if !edge.policyUsable(sendAmt) {
				continue
			}

			reserved := reservations[edge.key]
			if reserved > edge.capacity ||
				sendAmt > edge.capacity-reserved {

				continue
			}
			load := sendAmt + reserved

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || reserved > balance ||
					sendAmt > balance-reserved {

					continue
				}
			}

			partialFee := sendAmt - amt
			if maxFee != lnwire.MaxMilliSatoshi &&
				partialFee > maxFee {

				continue
			}

			probability := edgeProbability(edge, load)
			if edge.from == r.source {
				// The local balance is known exactly for this
				// payment's snapshot.
				probability = 0.999
			}

			increment := float64(nodeFee) +
				riskPriceMsat*(-math.Log(probability)) +
				hopPriceMsat +
				r.penaltyFor(edge.key, load)

			if reserved != 0 {
				fraction := float64(reserved) /
					float64(edge.capacity)
				increment += reusePriceMsat *
					(0.35 + fraction)
			}

			score := item.score + increment
			old, exists := bestScore[edge.from]
			if exists && score >= old {
				continue
			}

			bestScore[edge.from] = score
			bestAmt[edge.from] = sendAmt
			next[edge.from] = edge
			heap.Push(pq, &pathItem{
				node:  edge.from,
				score: score,
				amt:   sendAmt,
			})
		}
	}

	score, ok := bestScore[r.source]
	if !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	fee := routeFee(rt)
	if maxFee != lnwire.MaxMilliSatoshi && fee > maxFee {
		return nil, 0, errors.New("no route within fee budget")
	}

	return rt, score, nil
}

func (r *candidateRouter) buildRoute(
	amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		fee := forwardingFee(
			path[i], path[i+1], amtOver[i+1],
		)
		amtOver[i] = amtOver[i+1] + fee
		expiryOver[i] = expiryOver[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmt := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			forwardAmt = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forwardAmt,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeFee(rt *route.Route) lnwire.MilliSatoshi {
	delivered := deliveredAmount(rt)
	if rt == nil || rt.TotalAmount < delivered {
		return 0
	}

	return rt.TotalAmount - delivered
}

func routeEdgeAmount(rt *route.Route, idx int) lnwire.MilliSatoshi {
	if idx == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[idx-1].AmtToForward
}

func routeEdgeKey(rt *route.Route, idx int) edgeKey {
	from := rt.SourcePubKey
	if idx > 0 {
		from = rt.Hops[idx-1].PubKeyBytes
	}

	return edgeKey{
		chanID: rt.Hops[idx].ChannelID,
		from:   from,
	}
}

func reserveRoute(
	reservations map[edgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key := routeEdgeKey(rt, i)
		reservations[key] += routeEdgeAmount(rt, i)
	}
}

func allocation(
	total lnwire.MilliSatoshi, parts, mode int) []lnwire.MilliSatoshi {

	weights := make([]uint64, parts)
	var weightTotal uint64

	for i := 0; i < parts; i++ {
		left := uint64(parts - i)
		switch mode {
		case 1:
			weights[i] = left
		case 2:
			weights[i] = left * left
		default:
			weights[i] = 1
		}
		weightTotal += weights[i]
	}

	result := make([]lnwire.MilliSatoshi, parts)
	remainingAmt := total
	remainingWeight := weightTotal

	for i := 0; i < parts; i++ {
		if i == parts-1 {
			result[i] = remainingAmt
			break
		}

		value := lnwire.MilliSatoshi(
			uint64(remainingAmt) * weights[i] /
				remainingWeight,
		)
		if value == 0 {
			value = 1
		}
		result[i] = value
		remainingAmt -= value
		remainingWeight -= weights[i]
	}

	return result
}

// buildPlan compares complete route sets with equal, moderately unequal and
// strongly unequal allocations. Each route is priced against the shards
// already placed in the same hypothetical set.
func (r *candidateRouter) buildPlan(
	remaining lnwire.MilliSatoshi, slots uint32) ([]*route.Route, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts reached")
	}

	maxParts := int(slots)
	if maxParts > 20 {
		maxParts = 20
	}

	budget := r.remainingBudget()
	var bestPlan []*route.Route
	bestPlanScore := math.Inf(1)

	for parts := 1; parts <= maxParts; parts++ {
		for mode := 0; mode < 3; mode++ {
			amounts := allocation(remaining, parts, mode)
			reservations := copyReservations(r.held)
			budgetLeft := budget
			plan := make([]*route.Route, 0, parts)
			totalScore := partPriceMsat * float64(parts)
			valid := true

			for _, shard := range amounts {
				rt, score, err := r.findRoute(
					shard, budgetLeft, reservations,
				)
				if err != nil {
					valid = false
					break
				}

				fee := routeFee(rt)
				if !addWithinLimit(
					fee, 0, budgetLeft,
				) {
					valid = false
					break
				}
				if budgetLeft != lnwire.MaxMilliSatoshi {
					budgetLeft -= fee
				}

				plan = append(plan, rt)
				totalScore += score
				reserveRoute(reservations, rt)
			}

			if valid && totalScore < bestPlanScore {
				bestPlanScore = totalScore
				bestPlan = plan
			}
		}
	}

	if len(bestPlan) != 0 {
		return bestPlan, nil
	}

	// A complete greedy set can occasionally fail because its first path
	// consumed a corridor needed later. Preserve a lower-amount retry
	// escape hatch rather than terminally abandoning the payment.
	minimum := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)
	candidates := []lnwire.MilliSatoshi{
		remaining,
		remaining * 3 / 4,
		remaining * 2 / 3,
		remaining / 2,
		minimum,
	}

	var fallback *route.Route
	fallbackScore := math.Inf(1)
	seen := make(map[lnwire.MilliSatoshi]bool)
	for _, shard := range candidates {
		if shard < minimum {
			shard = minimum
		}
		if shard == 0 || shard > remaining || seen[shard] {
			continue
		}
		seen[shard] = true

		rt, score, err := r.findRoute(
			shard, budget, r.held,
		)
		if err == nil && score < fallbackScore {
			fallback = rt
			fallbackScore = score
		}
	}

	if fallback == nil {
		return nil, errors.New("no route found")
	}

	return []*route.Route{fallback}, nil
}

func (r *candidateRouter) rebuildHeld(count uint32) {
	if int(count) >= len(r.heldRoutes) {
		return
	}

	if count == 0 {
		r.heldRoutes = nil
		r.held = make(map[edgeKey]lnwire.MilliSatoshi)
		r.plan = nil
		return
	}

	r.heldRoutes = r.heldRoutes[:count]
	r.held = make(map[edgeKey]lnwire.MilliSatoshi)
	for _, rt := range r.heldRoutes {
		reserveRoute(r.held, rt)
	}
	r.plan = nil
}

func (r *candidateRouter) issue(rt *route.Route) *route.Route {
	r.issued[rt] = copyReservations(r.held)
	return rt
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt == 0 {
		return nil, errors.New("payment complete")
	}

	r.rebuildHeld(inFlightHtlcs)

	for len(r.plan) != 0 {
		rt := r.plan[0]
		r.plan = r.plan[1:]

		if deliveredAmount(rt) > amt {
			r.plan = nil
			break
		}
		if routeFee(rt) > r.remainingBudget() {
			r.plan = nil
			break
		}

		return r.issue(rt), nil
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts reached")
	}

	plan, err := r.buildPlan(amt, maxParts-inFlightHtlcs)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.plan = plan[1:]
	}

	return r.issue(rt), nil
}

func (r *candidateRouter) failureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(
	attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	snapshot, ok := r.issued[rt]
	if !ok {
		snapshot = copyReservations(r.held)
	}
	delete(r.issued, rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			edge := r.edges[key]
			if edge == nil {
				continue
			}

			load := routeEdgeAmount(rt, i) + snapshot[key]
			recordSuccess(edge, load)

			if penalty, exists := r.penalties[key]; exists {
				if penalty.count <= 1 {
					delete(r.penalties, key)
				} else {
					penalty.count--
					r.penalties[key] = penalty
				}
			}
		}

		r.committedFee += routeFee(rt)
		r.heldRoutes = append(r.heldRoutes, rt)
		reserveRoute(r.held, rt)

		return nil
	}

	// A planned sibling may depend on the route that just failed.
	r.plan = nil

	failIdx := r.failureIndex(rt, result.FailureSource)
	if failIdx < 0 {
		// Dispatcher-side refusals provide no network evidence.
		return nil
	}

	// Every edge before the failing node's outgoing channel carried the
	// HTLC successfully and therefore supplies a lower liquidity bound.
	passCount := failIdx
	if passCount > len(rt.Hops) {
		passCount = len(rt.Hops)
	}
	for i := 0; i < passCount; i++ {
		key := routeEdgeKey(rt, i)
		edge := r.edges[key]
		if edge == nil {
			continue
		}

		load := routeEdgeAmount(rt, i) + snapshot[key]
		recordSuccess(edge, load)
	}

	if failIdx >= len(rt.Hops) {
		return nil
	}

	key := routeEdgeKey(rt, failIdx)
	edge := r.edges[key]
	if edge == nil {
		return nil
	}

	load := routeEdgeAmount(rt, failIdx) + snapshot[key]
	penalty := r.penalties[key]
	if penalty.amt == 0 || load < penalty.amt {
		penalty.amt = load
	}
	if penalty.count < 12 {
		penalty.count++
	}
	r.penalties[key] = penalty

	if result.Failure.Code() == lnwire.CodeTemporaryChannelFailure {
		recordFailure(edge, load)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxSearchHops  = 20
	maxNodeLabels  = 6
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type edgeRef struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	capacity  lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	fee := int64(e.baseFeeMsat) +
		int64(amt)*int64(e.feeRatePPM)/1_000_000
	if fee < 0 {
		return 0
	}
	return lnwire.MilliSatoshi(fee)
}

func (e *candidateEdge) inboundFee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	fee := e.inboundBase + int64(amt)*e.inboundRate/1_000_000
	return lnwire.MilliSatoshi(fee)
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type plannedRoute struct {
	rt    *route.Route
	prior map[edgeKey]lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByRef     map[edgeRef]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi
	issued   map[*route.Route]map[edgeKey]lnwire.MilliSatoshi
	plans    []plannedRoute

	failedHere map[edgeKey]lnwire.MilliSatoshi
	policyBad  map[edgeKey]bool

	committedFee lnwire.MilliSatoshi
	accounted    map[*route.Route]bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	balances := make(map[uint64]lnwire.MilliSatoshi, len(localBalances))
	for id, balance := range localBalances {
		balances[id] = balance
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByRef:     make(map[edgeRef]*candidateEdge),
		localBalances: balances,
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		issued:        make(map[*route.Route]map[edgeKey]lnwire.MilliSatoshi),
		failedHere:    make(map[edgeKey]lnwire.MilliSatoshi),
		policyBad:     make(map[edgeKey]bool),
		accounted:     make(map[*route.Route]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				capacity := lnwire.NewMSatFromSatoshis(ch.Capacity)
				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      capacity,
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   int64(ch.InboundFee.BaseFee),
					inboundRate:   int64(ch.InboundFee.FeeRate),
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeByRef[edgeRef{
					chanID: edge.chanID,
					from:   edge.from,
					to:     edge.to,
				}] = edge

				sharedBeliefs.Lock()
				b := sharedBeliefs.m[key]
				if b.capacity == 0 {
					b.capacity = capacity
					b.estimate = capacity / 2
					sharedBeliefs.m[key] = b
				}
				sharedBeliefs.Unlock()

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func forwardingFee(incoming, outgoing *candidateEdge,
	outAmt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outFee := outgoing.fee(outAmt)
	inFee := incoming.inboundFee(outAmt + outFee)
	total := int64(outFee) + int64(inFee)
	if total < 0 {
		total = 0
	}
	return lnwire.MilliSatoshi(total)
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.55 * math.Exp(-8*x)
	highMode := 0.43 / (1 + math.Exp(18*(x-0.82)))
	p := lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefProbability(key edgeKey, amt,
	capacity lnwire.MilliSatoshi) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok || b.conf == 0 {
		return prior
	}

	var learned float64
	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		learned = 0.995

	case b.upperFail > 0 && amt >= b.upperFail:
		learned = 0.012

	default:
		estimate := b.estimate
		if estimate <= 0 {
			estimate = capacity / 2
		}
		scale := float64(capacity) * 0.08
		if scale < 1 {
			scale = 1
		}
		learned = 1 / (1 + math.Exp(
			(float64(amt)-float64(estimate))/scale,
		))
		if learned < 0.012 {
			learned = 0.012
		}
		if learned > 0.995 {
			learned = 0.995
		}
	}

	weight := b.conf / (b.conf + 1.5)
	if weight > 0.88 {
		weight = 0.88
	}
	p := prior*(1-weight) + learned*weight
	if p < 0.012 {
		return 0.012
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func recordSuccess(key edgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	b.capacity = capacity
	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail > 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	highEstimate := capacity * 85 / 100
	if highEstimate < amt {
		highEstimate = amt
	}
	if highEstimate > b.estimate {
		b.estimate = highEstimate
	}
	b.conf += 1
	if b.conf > 6 {
		b.conf = 6
	}
	sharedBeliefs.m[key] = b
}

func recordFailure(key edgeKey, amt,
	capacity lnwire.MilliSatoshi) {

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	b.capacity = capacity
	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt * 3 / 4
	}

	lowEstimate := amt / 4
	if b.estimate == 0 || lowEstimate < b.estimate {
		b.estimate = lowEstimate
	}
	b.conf += 1.25
	if b.conf > 6 {
		b.conf = 6
	}
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node   route.Vertex
	outAmt lnwire.MilliSatoshi
	fees   lnwire.MilliSatoshi
	score  float64
	hops   int

	edge  *candidateEdge
	child *searchState
	live  bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func stateContains(s *searchState, node route.Vertex) bool {
	for s != nil {
		if s.node == node {
			return true
		}
		s = s.child
	}
	return false
}

func cloneReservations(src map[edgeKey]lnwire.MilliSatoshi,
) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) remainingBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFee >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFee
}

func riskPrice(budget lnwire.MilliSatoshi) float64 {
	if budget == lnwire.MaxMilliSatoshi {
		return 420_000
	}
	price := float64(budget) / 3
	if price < 5_000 {
		price = 5_000
	}
	if price > 420_000 {
		price = 420_000
	}
	return price
}

func dominated(labels []*searchState, candidate *searchState) bool {
	for _, old := range labels {
		if !old.live {
			continue
		}
		if old.score <= candidate.score &&
			old.fees <= candidate.fees &&
			old.outAmt <= candidate.outAmt {

			return true
		}
	}
	return false
}

func trimLabels(labels []*searchState) []*searchState {
	live := labels[:0]
	for _, label := range labels {
		if label.live {
			live = append(live, label)
		}
	}
	if len(live) <= maxNodeLabels {
		return live
	}

	minFee := 0
	minAmt := 0
	for i := 1; i < len(live); i++ {
		if live[i].fees < live[minFee].fees {
			minFee = i
		}
		if live[i].outAmt < live[minAmt].outAmt {
			minAmt = i
		}
	}

	worst := -1
	for i := range live {
		if i == minFee || i == minAmt {
			continue
		}
		if worst < 0 || live[i].score > live[worst].score {
			worst = i
		}
	}
	if worst < 0 {
		worst = len(live) - 1
	}
	live[worst].live = false
	return append(live[:worst], live[worst+1:]...)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi) float64 {

	load := amt + reservations[edge.key]
	if load > edge.capacity {
		return 0
	}

	if edge.from == r.source {
		balance, ok := r.localBalances[edge.chanID]
		if !ok || load > balance {
			return 0
		}
		return 0.995
	}

	if failed, ok := r.failedHere[edge.key]; ok {
		threshold := failed * 85 / 100
		if threshold == 0 {
			threshold = failed
		}
		if load >= threshold {
			return 0
		}
	}

	p := beliefProbability(edge.key, load, edge.capacity)
	if reservations[edge.key] > 0 {
		ratio := float64(reservations[edge.key]) /
			float64(edge.capacity)
		p *= math.Exp(-0.8 * ratio)
	}
	if p < 0.003 {
		p = 0.003
	}
	return p
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 || r.source == r.spec.Target {
		return nil, errors.New("invalid route amount")
	}

	price := riskPrice(feeBudget)
	root := &searchState{
		node:   r.spec.Target,
		outAmt: amt,
		live:   true,
	}
	labels := map[route.Vertex][]*searchState{
		r.spec.Target: {root},
	}
	pq := &searchQueue{}
	heap.Push(pq, root)

	for pq.Len() != 0 {
		state := heap.Pop(pq).(*searchState)
		if !state.live {
			continue
		}
		if state.node == r.source {
			return r.buildRoute(state)
		}
		if state.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[state.node] {
			if r.policyBad[edge.key] ||
				stateContains(state, edge.from) {

				continue
			}

			edgeAmt := state.outAmt
			nodeFee := lnwire.MilliSatoshi(0)
			if state.node != r.spec.Target {
				nodeFee = forwardingFee(
					edge, state.edge, state.outAmt,
				)
				edgeAmt += nodeFee
			}

			if !edge.usable(edgeAmt) {
				continue
			}

			fees := state.fees + nodeFee
			if feeBudget != lnwire.MaxMilliSatoshi &&
				fees > feeBudget {

				continue
			}

			p := r.edgeProbability(edge, edgeAmt, reservations)
			if p <= 0 {
				continue
			}

			reusePenalty := 0.0
			if reservations[edge.key] > 0 {
				reusePenalty = price * 0.70
			}
			candidate := &searchState{
				node:   edge.from,
				outAmt: edgeAmt,
				fees:   fees,
				score: state.score + float64(nodeFee) +
					price*(-math.Log(p)) +
					reusePenalty + 1_200,
				hops:  state.hops + 1,
				edge:  edge,
				child: state,
				live:  true,
			}

			nodeLabels := labels[candidate.node]
			if dominated(nodeLabels, candidate) {
				continue
			}
			for _, old := range nodeLabels {
				if candidate.score <= old.score &&
					candidate.fees <= old.fees &&
					candidate.outAmt <= old.outAmt {

					old.live = false
				}
			}

			nodeLabels = append(nodeLabels, candidate)
			nodeLabels = trimLabels(nodeLabels)
			labels[candidate.node] = nodeLabels
			if candidate.live {
				heap.Push(pq, candidate)
			}
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(
	sourceState *searchState) (*route.Route, error) {

	var edges []*candidateEdge
	var amounts []lnwire.MilliSatoshi
	state := sourceState
	for state != nil && state.edge != nil {
		edges = append(edges, state.edge)
		amounts = append(amounts, state.outAmt)
		state = state.child
	}
	if len(edges) == 0 || state == nil ||
		state.node != r.spec.Target {

		return nil, errors.New("broken route")
	}

	expiries := make([]uint32, len(edges))
	expiries[len(edges)-1] = finalCltvDelta
	for i := len(edges) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(edges[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(edges))
	for i, edge := range edges {
		forward := amounts[len(amounts)-1]
		outgoingExpiry := uint32(finalCltvDelta)
		if i+1 < len(edges) {
			forward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func routeDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeChannelAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func (r *candidateRouter) routeEdges(
	rt *route.Route) []*candidateEdge {

	edges := make([]*candidateEdge, 0, len(rt.Hops))
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		edge := r.edgeByRef[edgeRef{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}]
		edges = append(edges, edge)
		from = hop.PubKeyBytes
	}
	return edges
}

func (r *candidateRouter) addRouteReservations(
	reservations map[edgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i, edge := range r.routeEdges(rt) {
		if edge == nil {
			continue
		}
		reservations[edge.key] += routeChannelAmount(rt, i)
	}
}

func routeFee(rt *route.Route) lnwire.MilliSatoshi {
	delivered := routeDelivered(rt)
	if rt.TotalAmount <= delivered {
		return 0
	}
	return rt.TotalAmount - delivered
}

func (r *candidateRouter) findLargestRoute(
	limit lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	budget lnwire.MilliSatoshi) (*route.Route,
	lnwire.MilliSatoshi, error) {

	if rt, err := r.findRoute(limit, reservations, budget); err == nil {
		return rt, limit, nil
	}

	high := limit
	probe := limit * 3 / 4
	var best *route.Route
	var low lnwire.MilliSatoshi

	for i := 0; i < 26 && probe >= 1_000; i++ {
		rt, err := r.findRoute(probe, reservations, budget)
		if err == nil {
			best = rt
			low = probe
			break
		}
		high = probe
		next := probe * 3 / 4
		if next == probe {
			next--
		}
		probe = next
	}
	if best == nil {
		return nil, 0, errors.New("no shard route found")
	}

	for i := 0; i < 14 && high > low+1; i++ {
		mid := low + (high-low)/2
		rt, err := r.findRoute(mid, reservations, budget)
		if err == nil {
			low = mid
			best = rt
		} else {
			high = mid
		}
	}

	return best, low, nil
}

func (r *candidateRouter) greedyPlan(total lnwire.MilliSatoshi,
	slots uint32) ([]plannedRoute, bool) {

	reservations := cloneReservations(r.reserved)
	budget := r.remainingBudget()
	remaining := total
	plans := make([]plannedRoute, 0, slots)

	for uint32(len(plans)) < slots && remaining > 0 {
		prior := cloneReservations(reservations)
		rt, shard, err := r.findLargestRoute(
			remaining, reservations, budget,
		)
		if err != nil || shard <= 0 {
			return plans, false
		}

		plans = append(plans, plannedRoute{
			rt:    rt,
			prior: prior,
		})
		r.addRouteReservations(reservations, rt)

		fee := routeFee(rt)
		if budget != lnwire.MaxMilliSatoshi {
			if fee > budget {
				return nil, false
			}
			budget -= fee
		}
		remaining -= shard
	}

	return plans, remaining == 0
}

func (r *candidateRouter) equalPlan(total lnwire.MilliSatoshi,
	parts uint32) ([]plannedRoute, bool) {

	reservations := cloneReservations(r.reserved)
	budget := r.remainingBudget()
	remaining := total
	plans := make([]plannedRoute, 0, parts)

	for i := uint32(0); i < parts; i++ {
		left := parts - i
		shard := remaining / lnwire.MilliSatoshi(left)
		if remaining%lnwire.MilliSatoshi(left) != 0 {
			shard++
		}
		if shard <= 0 {
			return nil, false
		}

		prior := cloneReservations(reservations)
		rt, err := r.findRoute(shard, reservations, budget)
		if err != nil {
			return nil, false
		}

		plans = append(plans, plannedRoute{
			rt:    rt,
			prior: prior,
		})
		r.addRouteReservations(reservations, rt)

		fee := routeFee(rt)
		if budget != lnwire.MaxMilliSatoshi {
			if fee > budget {
				return nil, false
			}
			budget -= fee
		}
		remaining -= shard
	}

	return plans, remaining == 0
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) error {

	if slots == 0 {
		return errors.New("maximum parts reached")
	}

	if plans, ok := r.greedyPlan(total, slots); ok {
		r.plans = plans
		return nil
	}

	for parts := uint32(2); parts <= slots; parts++ {
		if plans, ok := r.equalPlan(total, parts); ok {
			r.plans = plans
			return nil
		}
	}

	return errors.New("no route set found")
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	for len(r.plans) > 0 {
		plan := r.plans[0]
		r.plans = r.plans[1:]
		if routeDelivered(plan.rt) > amt {
			r.plans = nil
			break
		}
		r.issued[plan.rt] = plan.prior
		return plan.rt, nil
	}

	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts reached")
	}
	slots := r.spec.MaxParts - inFlightHtlcs
	if err := r.makePlan(amt, slots); err != nil {
		return nil, err
	}
	if len(r.plans) == 0 {
		return nil, errors.New("empty route plan")
	}

	plan := r.plans[0]
	r.plans = r.plans[1:]
	r.issued[plan.rt] = plan.prior
	return plan.rt, nil
}

func failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) observationLoad(
	rt *route.Route, index int, edge *candidateEdge,
	prior map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	load := routeChannelAmount(rt, index)
	if prior != nil {
		load += prior[edge.key]
	}
	return load
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	prior := r.issued[rt]
	delete(r.issued, rt)
	edges := r.routeEdges(rt)

	if result.Failure == nil {
		if r.accounted[rt] {
			return nil
		}
		r.accounted[rt] = true

		for i, edge := range edges {
			if edge == nil {
				continue
			}
			load := r.observationLoad(rt, i, edge, prior)
			recordSuccess(edge.key, load, edge.capacity)
			if failed, ok := r.failedHere[edge.key];
				ok && load >= failed {

				delete(r.failedHere, edge.key)
			}
		}

		r.addRouteReservations(r.reserved, rt)
		r.committedFee += routeFee(rt)
		return nil
	}

	r.plans = nil
	failIdx := failureIndex(rt, result.FailureSource)

	for i := 0; i < failIdx && i < len(edges); i++ {
		edge := edges[i]
		if edge == nil {
			continue
		}
		load := r.observationLoad(rt, i, edge, prior)
		recordSuccess(edge.key, load, edge.capacity)
	}

	liquidityFailure := false
	policyFailure := false
	switch result.Failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		liquidityFailure = true

	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		policyFailure = true
	}

	if failIdx >= 0 && failIdx < len(edges) {
		edge := edges[failIdx]
		if edge != nil {
			if liquidityFailure {
				load := r.observationLoad(
					rt, failIdx, edge, prior,
				)
				old, ok := r.failedHere[edge.key]
				if !ok || load < old {
					r.failedHere[edge.key] = load
				}
				recordFailure(edge.key, load, edge.capacity)
			} else if policyFailure {
				r.policyBad[edge.key] = true
			}
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta     = uint32(40)
	baseRiskPriceMsat  = float64(420_000)
	minRiskPriceMsat   = float64(25_000)
	hopCostMsat        = float64(2_500)
	reusedEdgeCostMsat = float64(700_000)
	maxSearchHops      = 60
	maxLabelsPerNode   = 10
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type beliefKey struct {
	network string
	edge    edgeKey
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[beliefKey]liquidityBelief
}{
	m: make(map[beliefKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inbound := int64(in.inboundBase) +
		int64(amt)*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view      routing.SimNetworkView
	source    route.Vertex
	spec      *routing.SimPaymentSpec
	networkID string

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	heldReservations    map[edgeKey]lnwire.MilliSatoshi
	pendingReservations map[edgeKey]lnwire.MilliSatoshi
	localUpperBad       map[edgeKey]lnwire.MilliSatoshi
	blockedEdges        map[edgeKey]bool
	edgePenalty         map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi
	pendingFees   lnwire.MilliSatoshi
	budgetGuard   lnwire.MilliSatoshi
	successParts  uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:                view,
		source:              source,
		spec:                spec,
		networkID:           fmt.Sprintf("%T:%p", view, view),
		incomingEdges:       make(map[route.Vertex][]*candidateEdge),
		edgeLookup:          make(map[edgeKey]*candidateEdge),
		localBalances:       localBalances,
		heldReservations:    make(map[edgeKey]lnwire.MilliSatoshi),
		pendingReservations: make(map[edgeKey]lnwire.MilliSatoshi),
		localUpperBad:       make(map[edgeKey]lnwire.MilliSatoshi),
		blockedEdges:        make(map[edgeKey]bool),
		edgePenalty:         make(map[edgeKey]float64),
		issued:              make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key beliefKey, amt,
	capacity lnwire.MilliSatoshi, now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		position := float64(b.upperBad-amt) /
			float64(b.upperBad-b.lowerOK)
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}
		evidence = 0.012 + 0.983*position
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func updateBelief(key beliefKey, amt lnwire.MilliSatoshi,
	success bool, now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int           { return len(q) }
func (q searchQueue) Less(i, j int) bool { return q[i].score < q[j].score }
func (q searchQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i] }

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for current := s; current != nil; current = current.child {
		if current.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFee := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFee].fee {
				minFee = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFee {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amount := range src {
		dst[key] = amount
	}
	return dst
}

func addAmount(dst map[edgeKey]lnwire.MilliSatoshi,
	key edgeKey, amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}
	dst[key] += amount
}

func subtractAmount(dst map[edgeKey]lnwire.MilliSatoshi,
	key edgeKey, amount lnwire.MilliSatoshi) {

	current := dst[key]
	if amount >= current {
		delete(dst, key)
		return
	}
	dst[key] = current - amount
}

func (r *candidateRouter) reservationSnapshot(
) map[edgeKey]lnwire.MilliSatoshi {

	result := cloneReservations(r.heldReservations)
	for key, amount := range r.pendingReservations {
		result[key] += amount
	}
	return result
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		addAmount(dst, edge.key, meta.amounts[i])
	}
}

func subtractReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		subtractAmount(dst, edge.key, meta.amounts[i])
	}
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees + r.pendingFees + r.budgetGuard
	if spent >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}
	return price
}

func (r *candidateRouter) beliefKey(edge edgeKey) beliefKey {
	return beliefKey{
		network: r.networkID,
		edge:    edge,
	}
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		current := heap.Pop(pq).(*searchState)
		if !current.active {
			continue
		}
		if current.node == r.source {
			result = current
			break
		}
		if current.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[current.node] {
			if r.blockedEdges[edge.key] ||
				containsNode(current, edge.from) {

				continue
			}

			over := current.amount
			nodeCharge := lnwire.MilliSatoshi(0)
			if current.node != r.spec.Target {
				if current.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(
					edge, current.nextEdge, current.amount,
				)
				if nodeCharge >
					lnwire.MaxMilliSatoshi-current.amount {

					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			if failedAt := r.localUpperBad[edge.key]; failedAt > 0 &&
				totalLoad >= failedAt {

				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := current.fee + nodeCharge
			if totalFee < current.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				r.beliefKey(edge.key), totalLoad,
				edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.985
			}

			score := current.score + float64(nodeCharge) +
				price*(-math.Log(p)) + hopCostMsat +
				r.edgePenalty[edge.key]

			if reservations[edge.key] > 0 {
				reuseCost := reusedEdgeCostMsat
				if edge.from == r.source {
					reuseCost *= 0.45
				}
				score += reuseCost
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     current.hops + 1,
				nextEdge: edge,
				child:    current,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for current := result; current.node != r.spec.Target;
		current = current.child {

		if current.nextEdge == nil || current.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, current.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}
	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route,
	[]lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	count := len(path)
	amounts := make([]lnwire.MilliSatoshi, count)
	expiries := make([]uint32, count)
	amounts[count-1] = amt
	expiries[count-1] = finalCltvDelta

	for i := count - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, count)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < count-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var weightSum int64
	for _, weight := range weights {
		weightSum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	whole := int64(total) / weightSum
	remainder := int64(total) % weightSum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			whole*weight + remainder*weight/weightSum,
		)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}

		result[i] = part
		remaining -= part
	}

	return result
}

func allocationKey(allocation []lnwire.MilliSatoshi) string {
	return fmt.Sprint(allocation)
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	seen := make(map[string]bool)
	patterns := make([][]lnwire.MilliSatoshi, 0)

	add := func(weights []int64) {
		allocation := weightedAllocation(total, weights)
		for _, amount := range allocation {
			if amount <= 0 {
				return
			}
		}

		key := allocationKey(allocation)
		if seen[key] {
			return
		}
		seen[key] = true
		patterns = append(patterns, allocation)
	}

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}
	add(equal)

	if parts == 1 {
		return patterns
	}

	for _, heavy := range []int64{35, 45, 55, 65, 75, 82} {
		lightTotal := int64(100) - heavy
		light := lightTotal / int64(parts-1)
		if light <= 0 {
			continue
		}

		for position := 0; position < parts; position++ {
			weights := make([]int64, parts)
			for i := range weights {
				weights[i] = light
			}
			weights[position] = heavy
			add(weights)
		}
	}

	ascending := make([]int64, parts)
	descending := make([]int64, parts)
	for i := 0; i < parts; i++ {
		ascending[i] = int64(i + 1)
		descending[i] = int64(parts - i)
	}
	add(ascending)
	add(descending)

	for rotation := 1; rotation < parts; rotation++ {
		weights := make([]int64, parts)
		for i := range weights {
			weights[i] = ascending[(i+rotation)%parts]
		}
		add(weights)
	}

	return patterns
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := r.reservationSnapshot()
	remainingBudget := feeBudget
	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}

		pr, err := r.findRoute(shard, reservations, remainingBudget)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
	}

	totalScore += float64(len(plan)-1) * 45_000
	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	var best []*plannedRoute
	bestScore := math.Inf(1)

	maxParts := int(slots)
	if total < lnwire.MilliSatoshi(maxParts) {
		maxParts = int(total)
	}

	for parts := 1; parts <= maxParts; parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	if slots > 1 {
		ratios := [][2]int64{
			{3, 4},
			{2, 3},
			{3, 5},
			{1, 2},
		}

		minUseful := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)
		reservations := r.reservationSnapshot()

		for _, ratio := range ratios {
			shard := total * lnwire.MilliSatoshi(ratio[0]) /
				lnwire.MilliSatoshi(ratio[1])
			if shard < minUseful || shard >= total {
				continue
			}

			feeCap := feeBudget
			if feeBudget != lnwire.MaxMilliSatoshi {
				feeCap = feeBudget * shard / total
				extra := feeBudget / 10
				if feeCap <= lnwire.MaxMilliSatoshi-extra {
					feeCap += extra
				}
				if feeCap > feeBudget {
					feeCap = feeBudget
				}
			}

			pr, err := r.findRoute(shard, reservations, feeCap)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}
		}

		shard := minUseful
		for shard >= 10_000 {
			feeCap := feeBudget
			if feeBudget != lnwire.MaxMilliSatoshi {
				feeCap = feeBudget * shard / total
			}

			pr, err := r.findRoute(shard, reservations, feeCap)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}
			shard /= 2
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, planned := range plan {
		total += planned.meta.delivered
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	used := r.successParts + uint32(len(r.issued))
	if inFlightHtlcs > used {
		used = inFlightHtlcs
	}
	if used >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - used

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	addReservationSet(r.pendingReservations, next.meta)
	r.pendingFees += next.meta.fee

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) observationLoads(
	meta *routeMeta) []lnwire.MilliSatoshi {

	reservations := r.reservationSnapshot()
	loads := make([]lnwire.MilliSatoshi, len(meta.path))

	for i, edge := range meta.path {
		load := meta.amounts[i] + reservations[edge.key]
		if load < meta.amounts[i] {
			load = lnwire.MaxMilliSatoshi
		}
		loads[i] = load
	}

	return loads
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	if issuedMeta, ok := r.issued[rt]; ok {
		subtractReservationSet(r.pendingReservations, issuedMeta)
		if issuedMeta.fee >= r.pendingFees {
			r.pendingFees = 0
		} else {
			r.pendingFees -= issuedMeta.fee
		}
	}
	delete(r.issued, rt)

	if meta == nil {
		r.plan = nil
		return nil
	}

	loads := r.observationLoads(meta)
	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(
				r.beliefKey(edge.key), loads[i], true, now,
			)
			addAmount(
				r.heldReservations, edge.key, meta.amounts[i],
			)
			r.edgePenalty[edge.key] *= 0.3

			if failedAt := r.localUpperBad[edge.key];
				failedAt > 0 && loads[i] >= failedAt {

				delete(r.localUpperBad, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.successParts++
		return nil
	}

	r.plan = nil
	failIdx := r.failureIndex(rt, result.FailureSource)

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		updateBelief(
			r.beliefKey(meta.path[i].key),
			loads[i], true, now,
		)
	}

	code := result.Failure.Code()
	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(
				r.beliefKey(edge.key),
				loads[failIdx], false, now,
			)

			current := r.localUpperBad[edge.key]
			if current == 0 || loads[failIdx] < current {
				r.localUpperBad[edge.key] = loads[failIdx]
			}
			r.edgePenalty[edge.key] += 450_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.blockedEdges[edge.key] = true
			r.edgePenalty[edge.key] += 8_000_000

		default:
			r.blockedEdges[edge.key] = true
			r.edgePenalty[edge.key] += 3_000_000
		}

		return nil
	}

	if r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
		guard := meta.fee / 8
		if guard < 1_000 {
			guard = 1_000
		}
		if guard > r.remainingFeeBudget() {
			guard = r.remainingFeeBudget()
		}
		r.budgetGuard += guard
	}

	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 500_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta  = uint32(40)
	riskPriceMsat   = 420000.0
	hopPriceMsat    = 12000.0
	reusePriceMsat  = 650000.0
	partPriceMsat   = 25000.0
	largeShardMsat  = lnwire.MilliSatoshi(750000000)
	beliefLifetime  = int64(3600)
	beliefHalfLife  = 900.0
	probabilityFloor = 0.012
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) outboundFee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	fee := int64(e.baseFeeMsat) +
		int64(amt)*int64(e.feeRatePPM)/1_000_000
	if fee < 0 {
		return 0
	}

	return lnwire.MilliSatoshi(fee)
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

// forwardingFee returns the total fee charged by the forwarding node.
// out is that node's outgoing channel and in is its incoming channel.
func forwardingFee(out, in *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outFee := int64(out.outboundFee(amt))
	inboundBase := int64(amt) + outFee
	inFee := int64(in.inboundBase) +
		inboundBase*int64(in.inboundRate)/1_000_000

	total := outFee + inFee
	if total < 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	updated   int64
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type routeMeta struct {
	rt       *route.Route
	path     []*candidateEdge
	amounts  []lnwire.MilliSatoshi
	loads    []lnwire.MilliSatoshi
	deliver  lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	status   uint8
}

const (
	metaPlanned uint8 = iota
	metaPending
	metaHeld
	metaReleased
)

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs    map[edgeKey]liquidityBelief
	edgeFails  map[edgeKey]uint32
	policyBad  map[edgeKey]bool
	reserved   map[edgeKey]lnwire.MilliSatoshi
	records    map[*route.Route]*routeMeta
	held       []*routeMeta
	plan       []*routeMeta

	committedFee lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[edgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[edgeKey]liquidityBelief),
		edgeFails:      make(map[edgeKey]uint32),
		policyBad:      make(map[edgeKey]bool),
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		records:        make(map[*route.Route]*routeMeta),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	now := r.now()
	sharedBeliefs.Lock()
	for key := range r.edges {
		belief, ok := sharedBeliefs.m[key]
		if !ok {
			continue
		}

		age := (now - belief.updated) / 1_000_000_000
		if age >= 0 && age <= beliefLifetime {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func (r *candidateRouter) now() int64 {
	return r.view.Now().UnixNano()
}

func clampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	highMode := 1.0 / (1.0 + math.Exp((x-0.88)/0.045))

	return clampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	if load > edge.capacity {
		return 0.005
	}

	if edge.from == r.source {
		if load > r.localBalances[edge.chanID] {
			return 0.005
		}
		return 0.985
	}

	prior := bimodalPrior(load, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return prior
	}

	age := float64(r.now()-belief.updated) / 1e9
	if age < 0 || age > float64(beliefLifetime) {
		return prior
	}

	confidence := math.Exp(-math.Ln2 * age / beliefHalfLife)
	evidence := prior

	switch {
	case belief.lowerOK > 0 && load <= belief.lowerOK:
		evidence = 0.995

	case belief.upperFail > 0 && load >= belief.upperFail:
		evidence = probabilityFloor

	case belief.lowerOK > 0 && belief.upperFail > belief.lowerOK:
		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(load-belief.lowerOK) / width
		evidence = 0.995 -
			position*(0.995-probabilityFloor)

	case belief.upperFail > 0:
		distance := float64(belief.upperFail-load) /
			math.Max(1, float64(belief.upperFail))
		evidence = probabilityFloor +
			(0.90-probabilityFloor)*math.Min(1, 4*distance)

	case belief.lowerOK > 0:
		distance := float64(load-belief.lowerOK) /
			math.Max(1, float64(edge.capacity-belief.lowerOK))
		evidence = 0.995 - 0.55*math.Max(0, distance)
	}

	p := confidence*evidence + (1-confidence)*prior
	if p < probabilityFloor {
		p = probabilityFloor
	}
	if p > 0.995 {
		p = 0.995
	}

	return p
}

func (r *candidateRouter) updateBelief(key edgeKey,
	load lnwire.MilliSatoshi, success bool) {

	belief := r.beliefs[key]
	if success {
		if load > belief.lowerOK {
			belief.lowerOK = load
		}
		if belief.upperFail != 0 &&
			belief.lowerOK >= belief.upperFail {

			belief.upperFail = 0
		}
	} else {
		if belief.upperFail == 0 || load < belief.upperFail {
			belief.upperFail = load
		}
		if belief.lowerOK >= belief.upperFail {
			belief.lowerOK = 0
		}
	}

	belief.updated = r.now()
	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.m[key] = belief
	sharedBeliefs.Unlock()
}

type searchItem struct {
	node       route.Vertex
	out        *candidateEdge
	forwardAmt lnwire.MilliSatoshi
	cost       float64
	risk       float64
	path       []*candidateEdge
	index      int
}

type searchQueue []*searchItem

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].cost < q[j].cost
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *searchQueue) Push(value any) {
	item := value.(*searchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func prependEdge(edge *candidateEdge,
	path []*candidateEdge) []*candidateEdge {

	result := make([]*candidateEdge, len(path)+1)
	result[0] = edge
	copy(result[1:], path)
	return result
}

func cloneReservations(
	source map[edgeKey]lnwire.MilliSatoshi,
) map[edgeKey]lnwire.MilliSatoshi {

	result := make(map[edgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		result[key] = amount
	}
	return result
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	reserved map[edgeKey]lnwire.MilliSatoshi,
	maxFee lnwire.MilliSatoshi, limited bool) (*routeMeta, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid shard amount")
	}

	if r.source == r.spec.Target {
		rt := &route.Route{
			TotalTimeLock: finalCltvDelta,
			TotalAmount:   deliver,
			SourcePubKey:  r.source,
		}
		return &routeMeta{
			rt:      rt,
			deliver: deliver,
		}, nil
	}

	pq := &searchQueue{}
	heap.Push(pq, &searchItem{
		node: r.spec.Target,
		path: nil,
	})

	best := make(map[*candidateEdge]float64)
	var winning *searchItem

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*searchItem)

		if winning != nil && item.cost >= winning.cost {
			break
		}

		if item.out != nil {
			if known, ok := best[item.out]; ok &&
				item.cost > known {

				continue
			}
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] {
				continue
			}

			amountOver := deliver
			incrementalFee := lnwire.MilliSatoshi(0)
			if item.out != nil {
				incrementalFee = forwardingFee(
					item.out, edge, item.forwardAmt,
				)
				amountOver = item.forwardAmt + incrementalFee
			}

			if !edge.usableHTLC(amountOver) {
				continue
			}

			load := amountOver + reserved[edge.key]
			if load > edge.capacity {
				continue
			}

			if edge.from == r.source &&
				load > r.localBalances[edge.chanID] {

				continue
			}

			feesSoFar := amountOver - deliver
			if limited && feesSoFar > maxFee {
				continue
			}

			probability := r.edgeProbability(edge, load)
			edgeRisk := -math.Log(probability)
			cost := item.cost + float64(incrementalFee) +
				riskPriceMsat*edgeRisk + hopPriceMsat

			if reserved[edge.key] > 0 {
				cost += reusePriceMsat
			}
			if failures := r.edgeFails[edge.key]; failures != 0 {
				cost += float64(failures) * 350000
			}

			path := prependEdge(edge, item.path)
			next := &searchItem{
				node:       edge.from,
				out:        edge,
				forwardAmt: amountOver,
				cost:       cost,
				risk:       item.risk + edgeRisk,
				path:       path,
			}

			if edge.from == r.source {
				if winning == nil || next.cost < winning.cost {
					winning = next
				}
				continue
			}

			if old, ok := best[edge]; ok && old <= cost {
				continue
			}
			best[edge] = cost
			heap.Push(pq, next)
		}
	}

	if winning == nil {
		return nil, errors.New("no route found")
	}

	rt, amounts, err := r.buildRoute(deliver, winning.path)
	if err != nil {
		return nil, err
	}

	fee := rt.TotalAmount - deliver
	if limited && fee > maxFee {
		return nil, errors.New("route exceeds fee budget")
	}

	loads := make([]lnwire.MilliSatoshi, len(amounts))
	for i, edge := range winning.path {
		loads[i] = amounts[i] + reserved[edge.key]
	}

	return &routeMeta{
		rt:      rt,
		path:    winning.path,
		amounts: amounts,
		loads:   loads,
		deliver: deliver,
		fee:     fee,
		score:   winning.cost,
		status:  metaPlanned,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route,
	[]lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		fee := forwardingFee(path[i+1], path[i], amounts[i+1])
		amounts[i] = amounts[i+1] + fee
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := finalCltvDelta
		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return rt, amounts, nil
}

func shardAmounts(total lnwire.MilliSatoshi, parts int,
	unequal bool) []lnwire.MilliSatoshi {

	result := make([]lnwire.MilliSatoshi, parts)
	if parts == 1 {
		result[0] = total
		return result
	}

	remaining := total
	if !unequal {
		for i := 0; i < parts; i++ {
			left := parts - i
			amount := remaining / lnwire.MilliSatoshi(left)
			if remaining%lnwire.MilliSatoshi(left) != 0 {
				amount++
			}
			result[i] = amount
			remaining -= amount
		}
		return result
	}

	totalWeight := int64(2 * parts * parts)
	usedWeight := int64(0)
	for i := 0; i < parts; i++ {
		if i == parts-1 {
			result[i] = remaining
			break
		}

		weight := int64(3*parts - 1 - 2*i)
		amount := lnwire.MilliSatoshi(
			float64(total) * float64(weight) /
				float64(totalWeight),
		)
		if amount <= 0 {
			amount = 1
		}
		result[i] = amount
		remaining -= amount
		usedWeight += weight
		_ = usedWeight
	}

	return result
}

func (r *candidateRouter) remainingBudget() (
	lnwire.MilliSatoshi, bool) {

	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return 0, false
	}
	if r.committedFee >= r.spec.FeeLimitMsat {
		return 0, true
	}

	return r.spec.FeeLimitMsat - r.committedFee, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	partsLeft uint32) ([]*routeMeta, error) {

	if partsLeft == 0 {
		return nil, errors.New("maximum parts reached")
	}

	remainingBudget, limited := r.remainingBudget()
	maxParts := int(partsLeft)
	if maxParts < 1 {
		maxParts = 1
	}

	preferred := int(
		(total + largeShardMsat - 1) / largeShardMsat,
	)
	if preferred < 1 {
		preferred = 1
	}
	if preferred > maxParts {
		preferred = maxParts
	}

	var bestPlan []*routeMeta
	bestScore := math.Inf(1)

	for parts := 1; parts <= maxParts; parts++ {
		shapeCount := 1
		if parts > 1 {
			shapeCount = 2
		}

		for shape := 0; shape < shapeCount; shape++ {
			amounts := shardAmounts(total, parts, shape == 1)
			tempReservations := cloneReservations(r.reserved)
			plan := make([]*routeMeta, 0, parts)
			planFee := lnwire.MilliSatoshi(0)
			planScore := float64(parts) * partPriceMsat
			remainingAmount := total
			valid := true

			for _, shard := range amounts {
				if shard <= 0 || shard > remainingAmount {
					valid = false
					break
				}

				maxShardFee := lnwire.MilliSatoshi(0)
				if limited {
					if planFee >= remainingBudget {
						maxShardFee = 0
					} else {
						budgetLeft := remainingBudget - planFee
						maxShardFee = lnwire.MilliSatoshi(
							float64(budgetLeft) *
								float64(shard) /
								float64(remainingAmount),
						)
					}
				}

				meta, err := r.findRoute(
					shard, tempReservations,
					maxShardFee, limited,
				)
				if err != nil {
					valid = false
					break
				}

				plan = append(plan, meta)
				planFee += meta.fee
				planScore += meta.score
				remainingAmount -= shard

				for i, edge := range meta.path {
					tempReservations[edge.key] +=
						meta.amounts[i]
				}
			}

			if !valid || remainingAmount != 0 {
				continue
			}
			if limited && planFee > remainingBudget {
				continue
			}

			if parts < preferred {
				planScore += float64(preferred-parts) * 900000
			}

			if planScore < bestScore {
				bestScore = planScore
				bestPlan = plan
			}
		}
	}

	if len(bestPlan) == 0 {
		return nil, errors.New("no route set found")
	}

	return bestPlan, nil
}

func (r *candidateRouter) addReservation(meta *routeMeta) {
	for i, edge := range meta.path {
		r.reserved[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) releaseReservation(meta *routeMeta) {
	if meta == nil || meta.status == metaReleased {
		return
	}

	for i, edge := range meta.path {
		amount := meta.amounts[i]
		current := r.reserved[edge.key]
		if current <= amount {
			delete(r.reserved, edge.key)
		} else {
			r.reserved[edge.key] = current - amount
		}
	}
	meta.status = metaReleased
}

func (r *candidateRouter) discardPlan() {
	for _, meta := range r.plan {
		r.releaseReservation(meta)
	}
	r.plan = nil
}

func (r *candidateRouter) syncHeld(inFlight uint32) {
	for len(r.held) > int(inFlight) {
		meta := r.held[0]
		r.held = r.held[1:]

		r.releaseReservation(meta)
		delete(r.records, meta.rt)

		if len(meta.path) != 0 {
			first := meta.path[0]
			spent := meta.amounts[0]
			balance := r.localBalances[first.chanID]
			if spent >= balance {
				r.localBalances[first.chanID] = 0
			} else {
				r.localBalances[first.chanID] =
					balance - spent
			}
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	r.syncHeld(inFlightHtlcs)

	if amt <= 0 {
		return nil, errors.New("payment complete")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts reached")
	}

	if len(r.plan) != 0 && r.plan[0].deliver > amt {
		r.discardPlan()
	}

	if len(r.plan) == 0 {
		partsLeft := r.spec.MaxParts - inFlightHtlcs
		plan, err := r.makePlan(amt, partsLeft)
		if err != nil {
			return nil, err
		}

		for _, meta := range plan {
			r.addReservation(meta)
		}
		r.plan = plan
	}

	meta := r.plan[0]
	r.plan = r.plan[1:]
	meta.status = metaPending
	r.records[meta.rt] = meta

	return meta.rt, nil
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.records[rt]
	if meta == nil {
		return nil
	}

	if result.Failure == nil {
		for i, edge := range meta.path {
			r.updateBelief(edge.key, meta.loads[i], true)
		}

		r.committedFee += meta.fee
		meta.status = metaHeld
		r.held = append(r.held, meta)
		return nil
	}

	r.releaseReservation(meta)
	delete(r.records, rt)
	r.discardPlan()

	failIdx := r.failureIndex(rt, result.FailureSource)
	if failIdx >= 0 {
		for i := 0; i < failIdx && i < len(meta.path); i++ {
			r.updateBelief(
				meta.path[i].key, meta.loads[i], true,
			)
		}
	}

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		if failIdx >= 0 && failIdx < len(meta.path) {
			edge := meta.path[failIdx]
			r.updateBelief(
				edge.key, meta.loads[failIdx], false,
			)
			r.edgeFails[edge.key]++
		} else {
			for _, edge := range meta.path {
				r.edgeFails[edge.key]++
			}
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		if failIdx >= 0 && failIdx < len(meta.path) {
			edge := meta.path[failIdx]
			r.policyBad[edge.key] = true
		} else {
			for _, edge := range meta.path {
				r.edgeFails[edge.key]++
			}
		}

	default:
		if failIdx >= 0 && failIdx < len(meta.path) {
			r.edgeFails[meta.path[failIdx].key]++
		} else {
			for _, edge := range meta.path {
				r.edgeFails[edge.key]++
			}
		}
	}

	return nil
}

var _ routing.SimRouter = (*candidateRouter)(nil)

func brokenPathError(node route.Vertex) error {
	return fmt.Errorf("broken path at %v", node)
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta       = uint32(40)
	baseRiskPriceMsat    = float64(420_000)
	minRiskPriceMsat     = float64(25_000)
	hopCostMsat          = float64(28_000)
	reusedEdgeCostMsat   = float64(1_800_000)
	extraPartCostMsat    = float64(80_000)
	maxSearchHops        = 40
	maxLabelsPerNode     = 14
	maxRouterAttempts    = uint32(96)
	minFallbackShardMsat = lnwire.MilliSatoshi(5_000)
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inboundBasis := int64(amt)
	if outbound > 0 && inboundBasis <= math.MaxInt64-outbound {
		inboundBasis += outbound
	}

	inbound := int64(in.inboundBase) +
		inboundBasis*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
	pathHash  uint64
	busy      bool
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type amountPenalty struct {
	threshold lnwire.MilliSatoshi
	cost      float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved         map[edgeKey]lnwire.MilliSatoshi
	liquidityPenalty map[edgeKey]amountPenalty
	policyPenalty    map[edgeKey]float64
	pathPenalty      map[uint64]float64
	issued           map[*route.Route]*routeMeta
	plan             []*plannedRoute

	committedFees  lnwire.MilliSatoshi
	budgetGuard    lnwire.MilliSatoshi
	successfulParts uint32
	attempts        uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:               view,
		source:             source,
		spec:               spec,
		incomingEdges:      make(map[route.Vertex][]*candidateEdge),
		edgeLookup:         make(map[edgeKey]*candidateEdge),
		localBalances:      localBalances,
		reserved:           make(map[edgeKey]lnwire.MilliSatoshi),
		liquidityPenalty:   make(map[edgeKey]amountPenalty),
		policyPenalty:      make(map[edgeKey]float64),
		pathPenalty:        make(map[uint64]float64),
		issued:             make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.015
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence = 0.015 + 0.98*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	gain float64, now time.Time) {

	if amt <= 0 || gain <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+gain)
	b.updated = now
	sharedBeliefs.m[key] = b
}

func mixPathHash(h, chanID uint64, from route.Vertex) uint64 {
	h ^= chanID
	h *= 1099511628211
	h ^= uint64(from[0])<<8 | uint64(from[1])
	h *= 1099511628211
	return h
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	pathHash uint64
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		protected := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[protected].fee {
				protected = i
			}
		}

		worst := -1
		for i := range kept {
			if i == protected {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		old := dst[edge.key]
		if meta.amounts[i] > lnwire.MaxMilliSatoshi-old {
			dst[edge.key] = lnwire.MaxMilliSatoshi
			continue
		}
		dst[edge.key] = old + meta.amounts[i]
	}
}

func (r *candidateRouter) activeReservations(
) map[edgeKey]lnwire.MilliSatoshi {

	result := cloneReservations(r.reserved)
	for _, meta := range r.issued {
		addReservationSet(result, meta)
	}
	return result
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees + r.budgetGuard
	for _, meta := range r.issued {
		if meta.fee > lnwire.MaxMilliSatoshi-spent {
			return 0
		}
		spent += meta.fee
	}

	if spent >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) * 0.55
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}
	return price
}

func (r *candidateRouter) liquidityCost(key edgeKey,
	load lnwire.MilliSatoshi) float64 {

	penalty, ok := r.liquidityPenalty[key]
	if !ok || penalty.cost <= 0 {
		return 0
	}
	if penalty.threshold <= 0 || load >= penalty.threshold {
		return penalty.cost
	}

	ratio := float64(load) / float64(penalty.threshold)
	return penalty.cost * (0.05 + 0.95*ratio*ratio)
}

func (r *candidateRouter) bumpLiquidityPenalty(key edgeKey,
	amount lnwire.MilliSatoshi, increment float64) {

	p := r.liquidityPenalty[key]
	if p.threshold == 0 || amount < p.threshold {
		p.threshold = amount
	}
	p.cost += increment
	if p.cost > 4_000_000 {
		p.cost = 4_000_000
	}
	r.liquidityPenalty[key] = p
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi, busy bool) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:     r.spec.Target,
		amount:   amt,
		pathHash: 1469598103934665603,
		active:   true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)
			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			if reserved > lnwire.MaxMilliSatoshi-over {
				continue
			}
			totalLoad := over + reserved
			if totalLoad > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			if nodeCharge > lnwire.MaxMilliSatoshi-cur.fee {
				continue
			}
			totalFee := cur.fee + nodeCharge
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.985
				if busy {
					p = 0.97
				}
			}

			score := cur.score + float64(nodeCharge) +
				price*(-math.Log(p)) + hopCostMsat +
				r.policyPenalty[edge.key] +
				r.liquidityCost(edge.key, totalLoad)

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.45
				}
				score += reuse
			}

			pathHash := mixPathHash(
				cur.pathHash, edge.chanID, edge.from,
			)
			if edge.from == r.source {
				score += r.pathPenalty[pathHash]
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				pathHash: pathHash,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		if reservations[edge.key] >
			lnwire.MaxMilliSatoshi-amounts[i] {

			return nil, errors.New("route load overflow")
		}
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
		pathHash:  result.pathHash,
		busy:      busy,
	}
	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)
	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	base := int64(total) / sum
	remainder := int64(total) % sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			base*weight + remainder*weight/sum,
		)
		if part <= 0 {
			part = 1
		}
		result[i] = part
		remaining -= part
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	ascending := make([]int64, parts)
	descending := make([]int64, parts)
	geometricUp := make([]int64, parts)
	geometricDown := make([]int64, parts)
	dominantFirst := make([]int64, parts)
	dominantLast := make([]int64, parts)

	for i := 0; i < parts; i++ {
		equal[i] = 1
		ascending[i] = int64(i + 1)
		descending[i] = int64(parts - i)

		shift := i
		if shift > 6 {
			shift = 6
		}
		geometricUp[i] = int64(1) << shift

		shift = parts - i - 1
		if shift > 6 {
			shift = 6
		}
		geometricDown[i] = int64(1) << shift

		dominantFirst[i] = 1
		dominantLast[i] = 1
	}
	if parts > 1 {
		dominantFirst[0] = int64(parts + 2)
		dominantLast[parts-1] = int64(parts + 2)
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}
	if parts > 1 {
		patterns = append(
			patterns,
			weightedAllocation(total, ascending),
			weightedAllocation(total, descending),
			weightedAllocation(total, geometricUp),
			weightedAllocation(total, geometricDown),
			weightedAllocation(total, dominantFirst),
			weightedAllocation(total, dominantLast),
		)
	}

	if parts == 2 {
		for _, weights := range [][]int64{
			{45, 55}, {55, 45},
			{35, 65}, {65, 35},
			{25, 75}, {75, 25},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}
	}

	return patterns
}

func proportionalBudget(totalBudget, shard,
	remaining lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if totalBudget == lnwire.MaxMilliSatoshi ||
		shard >= remaining {

		return totalBudget
	}

	cap := lnwire.MilliSatoshi(
		float64(totalBudget) * float64(shard) /
			float64(remaining),
	)
	if cap < 0 {
		return 0
	}
	if cap > totalBudget {
		return totalBudget
	}
	return cap
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi,
	baseReservations map[edgeKey]lnwire.MilliSatoshi,
	proportional bool, busy bool) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(baseReservations)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)
	for _, shard := range allocation {
		if shard <= 0 ||
			shard > lnwire.MaxMilliSatoshi-remainingAmount {

			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		feeCap := remainingBudget
		if proportional &&
			remainingBudget != lnwire.MaxMilliSatoshi {

			feeCap = proportionalBudget(
				remainingBudget, shard, remainingAmount,
			)
		}

		pr, err := r.findRoute(
			shard, reservations, feeCap, busy,
		)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat
	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32, busy bool) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	baseReservations := r.activeReservations()
	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		if lnwire.MilliSatoshi(parts) > total {
			break
		}

		for _, allocation := range allocationPatterns(total, parts) {
			for _, proportional := range []bool{true, false} {
				plan, score, ok := r.tryAllocation(
					allocation, feeBudget,
					baseReservations, proportional, busy,
				)
				if ok && score < bestScore {
					best = plan
					bestScore = score
				}
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	if slots > 1 {
		shard := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		for shard >= minFallbackShardMsat {
			feeCap := feeBudget
			if feeBudget != lnwire.MaxMilliSatoshi {
				feeCap = proportionalBudget(
					feeBudget, shard, total,
				)
			}

			pr, err := r.findRoute(
				shard, baseReservations, feeCap, busy,
			)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}

			next := shard * 2 / 3
			if next >= shard {
				break
			}
			shard = next
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	used := r.successfulParts
	if inFlightHtlcs > used {
		used = inFlightHtlcs
	}
	if used >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - used

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	busy := inFlightHtlcs > 0 || len(r.issued) > 0
	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots, busy)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	next.meta.busy = busy
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	reservations := r.activeReservations()
	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey
	pathHash := uint64(1469598103934665603)

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}
		if reservations[key] >
			lnwire.MaxMilliSatoshi-amount {

			return nil
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+reservations[key])
		pathHash = mixPathHash(pathHash, edge.chanID, edge.from)
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
		pathHash:  pathHash,
		busy:      len(r.issued) > 0,
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(
				edge.key, meta.loads[i], true, 0.5, now,
			)
			r.reserved[edge.key] += meta.amounts[i]

			if penalty, ok := r.liquidityPenalty[edge.key]; ok {
				penalty.cost *= 0.25
				if penalty.cost < 10_000 {
					delete(r.liquidityPenalty, edge.key)
				} else {
					r.liquidityPenalty[edge.key] = penalty
				}
			}
			r.policyPenalty[edge.key] *= 0.8
		}

		r.pathPenalty[meta.pathHash] *= 0.2
		r.committedFees += meta.fee
		r.successfulParts++
		return nil
	}

	r.plan = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		updateBelief(
			meta.path[i].key, meta.loads[i], true, 0.3, now,
		)
	}

	code := result.Failure.Code()
	r.pathPenalty[meta.pathHash] += 300_000

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			gain := 0.55
			if meta.busy {
				gain = 0.25
			}
			updateBelief(
				edge.key, meta.loads[failIdx],
				false, gain, now,
			)
			r.bumpLiquidityPenalty(
				edge.key, meta.loads[failIdx], 650_000,
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.policyPenalty[edge.key] += 6_000_000

		default:
			r.policyPenalty[edge.key] += 1_500_000
		}

		return nil
	}

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		r.pathPenalty[meta.pathHash] += 2_500_000
		for i, edge := range meta.path {
			r.bumpLiquidityPenalty(
				edge.key, meta.loads[i], 120_000,
			)
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.pathPenalty[meta.pathHash] += 5_000_000
		for _, edge := range meta.path {
			r.policyPenalty[edge.key] += 300_000
		}

		if r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
			guard := meta.fee / 10
			if guard < 1_000 {
				guard = 1_000
			}
			if guard <= lnwire.MaxMilliSatoshi-r.budgetGuard {
				r.budgetGuard += guard
			}
		}

	default:
		r.pathPenalty[meta.pathHash] += 1_500_000
		for _, edge := range meta.path {
			r.policyPenalty[edge.key] += 100_000
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCLTV   = uint32(40)
	candidateRiskPrice   = 420000.0
	candidateHopPrice    = 8000.0
	candidateReuseNats   = 1.15
	candidateMinShard    = lnwire.MilliSatoshi(10000)
	candidateProbFloor   = 0.012
	candidateProbCeiling = 0.995
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat int64
	feeRatePPM  int64
	cltvDelta   uint16
	minHTLC     lnwire.MilliSatoshi
	maxHTLC     lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func (e *candidateEdge) outgoingFee(amt lnwire.MilliSatoshi) int64 {
	fee := e.baseFeeMsat + int64(amt)*e.feeRatePPM/1_000_000
	if fee < 0 {
		return 0
	}
	return fee
}

// forwardingFee is the fee charged by the node between incoming and
// outgoing. The inbound component belongs to the incoming channel and is
// assessed on the forwarded amount plus the ordinary outbound fee.
func forwardingFee(incoming, outgoing *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if incoming == nil || outgoing == nil {
		return 0
	}

	outFee := outgoing.outgoingFee(amt)
	inBasis := int64(amt) + outFee
	inFee := incoming.inboundBase +
		inBasis*incoming.inboundRate/1_000_000

	total := outFee + inFee
	if total < 0 {
		total = 0
	}
	return lnwire.MilliSatoshi(total)
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	success  uint32
	failure  uint32
}

var candidateSharedBeliefs = struct {
	sync.Mutex
	m map[candidateEdgeKey]candidateBelief
}{
	m: make(map[candidateEdgeKey]candidateBelief),
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return candidateProbFloor
	}

	x := float64(amt) / float64(capacity)

	// A bimodal survival prior: one component represents channels whose
	// directional balance is near zero, the other channels whose balance
	// is near full capacity.
	lowMode := 0.5 * math.Exp(-x/0.045)
	highMode := 0.5 / (1 + math.Exp((x-0.94)/0.035))
	p := lowMode + highMode

	if p < candidateProbFloor {
		return candidateProbFloor
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	prior := candidatePrior(load, e.capacity)

	candidateSharedBeliefs.Lock()
	belief, ok := candidateSharedBeliefs.m[e.key]
	candidateSharedBeliefs.Unlock()

	if !ok {
		return prior
	}

	if belief.lowerOK > 0 && load <= belief.lowerOK {
		return candidateProbCeiling
	}

	if belief.upperBad > 0 && load >= belief.upperBad {
		p := prior * 0.08
		if p < candidateProbFloor {
			p = candidateProbFloor
		}
		return p
	}

	var learned float64
	var confidence float64

	switch {
	case belief.lowerOK > 0 && belief.upperBad > belief.lowerOK:
		mid := 0.5 * float64(belief.lowerOK+belief.upperBad)
		width := math.Max(
			float64(belief.upperBad-belief.lowerOK)*0.18,
			float64(e.capacity)*0.012,
		)
		learned = 1 / (1 + math.Exp((float64(load)-mid)/width))
		confidence = 0.88

	case belief.upperBad > 0:
		width := math.Max(
			float64(belief.upperBad)*0.14,
			float64(e.capacity)*0.015,
		)
		learned = 1 / (1 + math.Exp(
			(float64(load)-float64(belief.upperBad))/width,
		))
		confidence = 0.72

	case belief.lowerOK > 0:
		if load <= belief.lowerOK {
			learned = candidateProbCeiling
		} else {
			excess := float64(load-belief.lowerOK) /
				math.Max(float64(e.capacity), 1)
			learned = candidateProbCeiling *
				math.Exp(-excess/0.12)
		}
		confidence = 0.62

	default:
		return prior
	}

	p := confidence*learned + (1-confidence)*prior
	if p < candidateProbFloor {
		return candidateProbFloor
	}
	if p > candidateProbCeiling {
		return candidateProbCeiling
	}
	return p
}

func candidateRecordSuccess(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	b := candidateSharedBeliefs.m[key]
	if load > b.lowerOK {
		b.lowerOK = load
	}
	b.success++

	// Contradictory observations can occur when concurrent holds are
	// released. Preserve both observations as a soft interval instead of
	// permanently retiring the channel.
	if b.upperBad > 0 && b.lowerOK >= b.upperBad {
		b.upperBad = b.lowerOK + 1
	}
	candidateSharedBeliefs.m[key] = b
}

func candidateRecordFailure(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	b := candidateSharedBeliefs.m[key]
	if b.upperBad == 0 || load < b.upperBad {
		b.upperBad = load
	}
	b.failure++
	candidateSharedBeliefs.m[key] = b
}

type candidateSearchItem struct {
	node    route.Vertex
	amount  lnwire.MilliSatoshi
	score   float64
	risk    float64
	hops    int
	path    []*candidateEdge
	index   int
}

type candidateSearchQueue []*candidateSearchItem

func (q candidateSearchQueue) Len() int {
	return len(q)
}

func (q candidateSearchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateSearchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateSearchQueue) Push(x any) {
	item := x.(*candidateSearchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateSearchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	*q = old[:n-1]
	return item
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[candidateEdgeKey]*candidateEdge
	local    map[uint64]lnwire.MilliSatoshi

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	issued   map[*route.Route]bool
	penalty  map[candidateEdgeKey]float64
	banned   map[candidateEdgeKey]bool

	plan          []*route.Route
	committedFees lnwire.MilliSatoshi
	failures      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:   source,
		spec:     spec,
		incoming: make(map[route.Vertex][]*candidateEdge),
		edges:    make(map[candidateEdgeKey]*candidateEdge),
		local:    localBalances,
		reserved: make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		issued:   make(map[*route.Route]bool),
		penalty:  make(map[candidateEdgeKey]float64),
		banned:   make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:      key,
					capacity: lnwire.NewMSatFromSatoshis(ch.Capacity),

					baseFeeMsat: int64(policy.FeeBaseMSat),
					feeRatePPM: int64(
						policy.FeeProportionalMillionths,
					),
					cltvDelta: policy.TimeLockDelta,
					minHTLC:   policy.MinHTLC,

					inboundBase: int64(ch.InboundFee.BaseFee),
					inboundRate: int64(ch.InboundFee.FeeRate),
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incoming[node] = append(r.incoming[node], edge)
				r.edges[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) budgetLeft() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) routeFee(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	if rt.TotalAmount <= delivered {
		return 0
	}
	return rt.TotalAmount - delivered
}

func (r *candidateRouter) routeAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateAdd(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b > 0 && a > lnwire.MaxMilliSatoshi-b {
		return lnwire.MaxMilliSatoshi
	}
	return a + b
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi,
	maxFee lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("invalid shard amount")
	}

	dist := make(map[route.Vertex]float64)
	dist[r.spec.Target] = 0

	pq := &candidateSearchQueue{}
	heap.Push(pq, &candidateSearchItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateSearchItem)

		best, ok := dist[item.node]
		if !ok || item.score > best+0.0001 {
			continue
		}

		if item.node == r.source {
			rt, err := r.buildRoute(item.path, deliver)
			if err != nil {
				return nil, 0, err
			}
			if r.routeFee(rt) > maxFee {
				continue
			}

			quality := 1.0
			if item.hops > 0 {
				quality = math.Exp(-item.risk / float64(item.hops))
			}
			return rt, quality, nil
		}

		var outgoing *candidateEdge
		if len(item.path) > 0 {
			outgoing = item.path[0]
		}

		for _, incoming := range r.incoming[item.node] {
			if r.banned[incoming.key] {
				continue
			}

			amountOver := item.amount
			if item.node != r.spec.Target {
				amountOver = candidateAdd(
					amountOver,
					forwardingFee(incoming, outgoing, item.amount),
				)
			}

			if !incoming.usable(amountOver) {
				continue
			}

			if maxFee != lnwire.MaxMilliSatoshi &&
				amountOver-deliver > maxFee {

				continue
			}

			load := amountOver
			load = candidateAdd(load, r.reserved[incoming.key])
			if extra != nil {
				load = candidateAdd(load, extra[incoming.key])
			}
			if load > incoming.capacity {
				continue
			}

			var probability float64
			if incoming.key.from == r.source {
				balance, ok := r.local[incoming.key.chanID]
				if !ok || load > balance {
					continue
				}
				probability = 0.999
			} else {
				probability = candidateProbability(incoming, load)
			}

			risk := -math.Log(probability)
			edgePenalty := r.penalty[incoming.key]
			reuse := 0.0
			if r.reserved[incoming.key] > 0 ||
				(extra != nil && extra[incoming.key] > 0) {

				reuse = candidateReuseNats
			}

			feeIncrement := float64(amountOver - item.amount)
			newScore := item.score + feeIncrement +
				candidateRiskPrice*(risk+edgePenalty+reuse) +
				candidateHopPrice

			oldScore, exists := dist[incoming.key.from]
			if exists && oldScore <= newScore {
				continue
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = incoming
			copy(path[1:], item.path)

			dist[incoming.key.from] = newScore
			heap.Push(pq, &candidateSearchItem{
				node:   incoming.key.from,
				amount: amountOver,
				score:  newScore,
				risk:   item.risk + risk,
				hops:   item.hops + 1,
				path:   path,
			})
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = deliver
	expiries[n-1] = candidateFinalCLTV

	for i := n - 2; i >= 0; i-- {
		fee := forwardingFee(path[i], path[i+1], amounts[i+1])
		amounts[i] = candidateAdd(amounts[i+1], fee)
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].cltvDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := deliver
		expiry := candidateFinalCLTV
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) forEachRouteEdge(rt *route.Route,
	fn func(candidateEdgeKey, lnwire.MilliSatoshi, int)) {

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		fn(key, amount, i)
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) addVirtualReservation(
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		reserved[key] = candidateAdd(reserved[key], amount)
	})
}

func (r *candidateRouter) reserveIssued(rt *route.Route) {
	if r.issued[rt] {
		return
	}
	r.issued[rt] = true
	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		r.reserved[key] = candidateAdd(r.reserved[key], amount)
	})
}

func (r *candidateRouter) releaseIssued(rt *route.Route) {
	if !r.issued[rt] {
		return
	}
	delete(r.issued, rt)

	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		current := r.reserved[key]
		if current <= amount {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = current - amount
		}
	})
}

func (r *candidateRouter) maxFeeForPlan(
	already lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	left := r.budgetLeft()
	if left == lnwire.MaxMilliSatoshi {
		return left
	}
	if already >= left {
		return 0
	}
	return left - already
}

func (r *candidateRouter) tryPlan(amount lnwire.MilliSatoshi,
	parts int) ([]*route.Route, bool) {

	if parts < 1 {
		return nil, false
	}

	remaining := amount
	virtual := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	plannedFees := lnwire.MilliSatoshi(0)
	plan := make([]*route.Route, 0, parts)

	for i := 0; i < parts; i++ {
		left := parts - i
		if remaining < candidateMinShard*lnwire.MilliSatoshi(left) {
			return nil, false
		}

		shard := remaining / lnwire.MilliSatoshi(left)

		// Let early corridors take a modestly larger unequal share when
		// they can carry it, while reserving enough for all later parts.
		var candidates []lnwire.MilliSatoshi
		if left > 1 {
			maximum := remaining -
				candidateMinShard*lnwire.MilliSatoshi(left-1)
			boosted := shard + shard/4
			if boosted > maximum {
				boosted = maximum
			}
			if boosted > shard {
				candidates = append(candidates, boosted)
			}
		}
		candidates = append(candidates, shard)

		var selected *route.Route
		for _, candidate := range candidates {
			maxFee := r.maxFeeForPlan(plannedFees)
			rt, _, err := r.findRoute(candidate, virtual, maxFee)
			if err == nil {
				selected = rt
				break
			}
		}
		if selected == nil {
			return nil, false
		}

		fee := r.routeFee(selected)
		if r.budgetLeft() != lnwire.MaxMilliSatoshi &&
			plannedFees+fee > r.budgetLeft() {

			return nil, false
		}

		plan = append(plan, selected)
		plannedFees += fee
		r.addVirtualReservation(virtual, selected)
		remaining -= r.routeAmount(selected)
	}

	return plan, remaining == 0
}

func (r *candidateRouter) makePlan(amount lnwire.MilliSatoshi,
	slots uint32) ([]*route.Route, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts already in flight")
	}

	maxFee := r.budgetLeft()
	full, quality, fullErr := r.findRoute(amount, nil, maxFee)

	if slots == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	preferred := 1
	switch {
	case fullErr != nil:
		preferred = 2
	case quality < 0.43:
		preferred = 3
	case quality < 0.62 && amount >= 50_000_000:
		preferred = 2
	}

	if r.failures > 0 && preferred < 2 {
		preferred = 2
	}
	if r.failures >= 2 && preferred < 3 {
		preferred = 3
	}
	if preferred > int(slots) {
		preferred = int(slots)
	}

	if preferred == 1 && fullErr == nil {
		return []*route.Route{full}, nil
	}

	for parts := preferred; parts <= int(slots); parts++ {
		plan, ok := r.tryPlan(amount, parts)
		if ok {
			return plan, nil
		}
	}

	if fullErr == nil {
		return []*route.Route{full}, nil
	}

	// Last-resort lower retry. This preserves the useful evidence-driven
	// retry behavior without an unbounded halving ladder.
	shard := amount / lnwire.MilliSatoshi(slots)
	if shard < candidateMinShard {
		shard = candidateMinShard
	}
	for shard >= candidateMinShard {
		rt, _, err := r.findRoute(shard, nil, r.budgetLeft())
		if err == nil {
			return []*route.Route{rt}, nil
		}
		if shard == candidateMinShard {
			break
		}
		shard = shard * 2 / 3
		if shard < candidateMinShard {
			shard = candidateMinShard
		}
	}

	return nil, fullErr
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	for {
		if len(r.plan) == 0 {
			maxParts := r.spec.MaxParts
			if maxParts == 0 {
				maxParts = 1
			}
			if inFlightHtlcs >= maxParts {
				return nil, errors.New("maximum parts already in flight")
			}

			plan, err := r.makePlan(amt, maxParts-inFlightHtlcs)
			if err != nil {
				return nil, err
			}
			r.plan = plan
		}

		rt := r.plan[0]
		r.plan = r.plan[1:]

		if r.routeAmount(rt) > amt {
			r.plan = nil
			continue
		}

		fee := r.routeFee(rt)
		budget := r.budgetLeft()
		if budget != lnwire.MaxMilliSatoshi && fee > budget {
			r.plan = nil
			r.failures++
			continue
		}

		r.reserveIssued(rt)
		return rt, nil
	}
}

func (r *candidateRouter) routeFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) routeEdgeAt(rt *route.Route,
	index int) (candidateEdgeKey, lnwire.MilliSatoshi, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, 0, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	amount := rt.TotalAmount
	if index > 0 {
		amount = rt.Hops[index-1].AmtToForward
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, amount, true
}

func (r *candidateRouter) observedLoad(key candidateEdgeKey,
	fallback lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if load := r.reserved[key]; load > 0 {
		return load
	}
	return fallback
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		r.forEachRouteEdge(rt, func(key candidateEdgeKey,
			amount lnwire.MilliSatoshi, _ int) {

			candidateRecordSuccess(
				key, r.observedLoad(key, amount),
			)
			if r.penalty[key] > 0.25 {
				r.penalty[key] -= 0.25
			}
		})

		r.committedFees = candidateAdd(
			r.committedFees, r.routeFee(rt),
		)
		return nil
	}

	r.failures++
	r.plan = nil

	failIndex := r.routeFailureIndex(rt, result.FailureSource)

	// Every channel before the failing outgoing channel demonstrably
	// carried the total load imposed by this payment's concurrent holds.
	for i := 0; i < failIndex && i < len(rt.Hops); i++ {
		key, amount, ok := r.routeEdgeAt(rt, i)
		if ok {
			candidateRecordSuccess(
				key, r.observedLoad(key, amount),
			)
		}
	}

	code := result.Failure.Code()
	if key, amount, ok := r.routeEdgeAt(rt, failIndex); ok {
		load := r.observedLoad(key, amount)

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(key, load)
			r.penalty[key] += 1.65

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			// These indicate that this direction cannot be encoded from
			// the advertised policy as currently observed.
			r.banned[key] = true

		default:
			r.penalty[key] += 0.75
		}
	} else {
		// Sender-side refusals or unattributed failures should not poison
		// liquidity bounds, but avoiding the identical route is useful.
		r.forEachRouteEdge(rt, func(key candidateEdgeKey,
			_ lnwire.MilliSatoshi, _ int) {

			r.penalty[key] += 0.18
		})
	}

	r.releaseIssued(rt)
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"strings"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskPriceMsat  = 420000.0
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	forward lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if out == nil {
		return 0
	}

	outFee := int64(out.fee(forward))
	basis := int64(forward) + outFee
	inFee := in.inboundBase + basis*in.inboundRate/1_000_000
	total := outFee + inFee
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	epoch     uint64
}

var sharedKnowledge = struct {
	sync.Mutex
	epoch   uint64
	beliefs map[edgeKey]liquidityBelief
}{
	beliefs: make(map[edgeKey]liquidityBelief),
}

type localEdgeState struct {
	belief  liquidityBelief
	failures int
	lastFail lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	state        map[edgeKey]*localEdgeState
	reserved     map[edgeKey]lnwire.MilliSatoshi
	committedFee lnwire.MilliSatoshi
	reported     map[*route.Route]bool

	failureStreak int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	sharedKnowledge.Lock()
	sharedKnowledge.epoch++
	epoch := sharedKnowledge.epoch
	sharedKnowledge.Unlock()

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		epoch:         epoch,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		state:         make(map[edgeKey]*localEdgeState),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		reported:      make(map[*route.Route]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				e := &candidateEdge{
					key:      key,
					chanID:   ch.ChannelID,
					from:     ch.OtherNode,
					to:       node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase: int64(
						ch.InboundFee.BaseFee,
					),
					inboundRate: int64(
						ch.InboundFee.FeeRate,
					),
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.edgeByKey[key] = e
				r.incomingEdges[e.to] = append(
					r.incomingEdges[e.to], e,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedKnowledge.Lock()
	for key, e := range r.edgeByKey {
		b, ok := sharedKnowledge.beliefs[key]
		if !ok {
			b.estimate = e.capacity / 2
		}
		r.state[key] = &localEdgeState{belief: b}
	}
	sharedKnowledge.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.025)
	highMode := 0.5 / (1 + math.Exp((x-0.90)/0.035))
	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	if load > e.capacity {
		return 0.005
	}
	if e.from == r.source {
		balance := r.localBalances[e.chanID]
		if load <= balance {
			return 0.999
		}
		return 0.001
	}

	prior := bimodalPrior(load, e.capacity)
	st := r.state[e.key]
	if st == nil || st.belief.conf <= 0 {
		return prior
	}

	b := st.belief
	age := uint64(0)
	if r.epoch > b.epoch {
		age = r.epoch - b.epoch
	}

	conf := b.conf * math.Exp(-float64(age)/12)
	if conf < 0.03 {
		return prior
	}

	activeBounds := age <= 8
	var learned float64

	switch {
	case activeBounds && b.lowerOK > 0 && load <= b.lowerOK:
		learned = 0.995

	case activeBounds && b.upperFail > 0 && load >= b.upperFail:
		// A failure may have been caused by transient reservations.
		learned = 0.012

	default:
		estimate := b.estimate
		if estimate <= 0 {
			estimate = e.capacity / 2
		}
		width := float64(e.capacity) * 0.075
		if width < 1_000_000 {
			width = 1_000_000
		}
		z := (float64(load) - float64(estimate)) / width
		learned = 1 / (1 + math.Exp(z))
		learned = clampProbability(learned)
	}

	return clampProbability(conf*learned + (1-conf)*prior)
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFee >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFee
}

func (r *candidateRouter) shardFeeBudget(shard,
	remaining lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	budget := r.remainingFeeBudget()
	if budget == lnwire.MaxMilliSatoshi || shard >= remaining {
		return budget
	}
	if remaining <= 0 {
		return 0
	}

	share := float64(budget) * float64(shard) / float64(remaining)
	if share >= float64(budget) {
		return budget
	}
	if share <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(share)
}

type searchItem struct {
	node route.Vertex
	cost float64
	amt  lnwire.MilliSatoshi
}

type searchQueue []*searchItem

func (q searchQueue) Len() int      { return len(q) }
func (q searchQueue) Less(i, j int) bool { return q[i].cost < q[j].cost }
func (q searchQueue) Swap(i, j int) { q[i], q[j] = q[j], q[i] }
func (q *searchQueue) Push(x any)   { *q = append(*q, x.(*searchItem)) }
func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type routeMeta struct {
	path    []*candidateEdge
	fee     lnwire.MilliSatoshi
	logProb float64
	score   float64
}

func (r *candidateRouter) edgePenalty(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	penalty := 0.0
	reserved := r.reserved[e.key]
	if reserved > 0 {
		// Strongly prefer independent corridors for atomic shard sets.
		penalty += 900000
		if e.capacity > 0 {
			penalty += 600000 *
				float64(reserved) / float64(e.capacity)
		}
	}

	st := r.state[e.key]
	if st == nil || st.failures == 0 {
		return penalty
	}

	unit := 650000.0
	if st.lastFail > 0 && load*2 < st.lastFail {
		// Preserve lower-amount retries on a failed channel.
		unit = 90000
	}
	return penalty + float64(st.failures)*unit
}

func (r *candidateRouter) search(amt lnwire.MilliSatoshi,
	riskScale float64) (*route.Route, *routeMeta, error) {

	best := make(map[route.Vertex]float64)
	amount := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	best[r.spec.Target] = 0
	amount[r.spec.Target] = amt

	pq := &searchQueue{}
	heap.Push(pq, &searchItem{
		node: r.spec.Target,
		cost: 0,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*searchItem)
		currentBest, ok := best[item.node]
		if !ok || item.cost > currentBest+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		out := next[item.node]
		for _, in := range r.incomingEdges[item.node] {
			fee := lnwire.MilliSatoshi(0)
			if item.node != r.spec.Target {
				fee = nodeFee(in, out, item.amt)
			}
			if fee > lnwire.MaxMilliSatoshi-item.amt {
				continue
			}

			over := item.amt + fee
			if !in.usable(over) {
				continue
			}

			reserved := r.reserved[in.key]
			if reserved > in.capacity ||
				over > in.capacity-reserved {

				continue
			}

			load := over + reserved
			if in.from == r.source {
				balance := r.localBalances[in.chanID]
				if reserved > balance ||
					over > balance-reserved {

					continue
				}
			}

			p := r.edgeProbability(in, load)
			step := float64(fee) -
				riskScale*math.Log(p) + 1800
			step += r.edgePenalty(in, load)
			newCost := item.cost + step

			old, seen := best[in.from]
			if seen && newCost >= old {
				continue
			}

			best[in.from] = newCost
			amount[in.from] = over
			next[in.from] = in
			heap.Push(pq, &searchItem{
				node: in.from,
				cost: newCost,
				amt:  over,
			})
		}
	}

	if _, ok := best[r.source]; !ok {
		return nil, nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, nil, err
	}

	fee := rt.TotalAmount - amt
	logProb := 0.0
	for i, e := range path {
		over := rt.TotalAmount
		if i > 0 {
			over = rt.Hops[i-1].AmtToForward
		}
		load := over + r.reserved[e.key]
		logProb += math.Log(r.edgeProbability(e, load))
	}

	return rt, &routeMeta{
		path:    path,
		fee:     fee,
		logProb: logProb,
	}, nil
}

func (r *candidateRouter) findRoute(amt,
	feeCap lnwire.MilliSatoshi) (*route.Route, *routeMeta, error) {

	baseScale := riskPriceMsat
	if feeCap != lnwire.MaxMilliSatoshi {
		budgetScale := float64(feeCap) * 0.35
		if budgetScale < 4000 {
			budgetScale = 4000
		}
		if budgetScale < baseScale {
			baseScale = budgetScale
		}
	}

	scales := []float64{
		baseScale,
		baseScale / 4,
		0,
		riskPriceMsat,
	}

	var bestRoute *route.Route
	var bestMeta *routeMeta

	for _, scale := range scales {
		rt, meta, err := r.search(amt, scale)
		if err != nil {
			continue
		}
		if feeCap != lnwire.MaxMilliSatoshi &&
			meta.fee > feeCap {

			continue
		}

		meta.score = float64(meta.fee) -
			baseScale*meta.logProb +
			float64(len(meta.path))*1800

		if bestMeta == nil || meta.score < bestMeta.score {
			bestRoute = rt
			bestMeta = meta
		}
	}

	if bestRoute == nil {
		return nil, nil, errors.New("no route found")
	}
	return bestRoute, bestMeta, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	path := make([]*candidateEdge, 0, 12)
	visited := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, nil, errors.New("routing cycle")
		}
		visited[node] = true

		e, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, e)
		node = e.to
	}

	n := len(path)
	if n == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, n)
	expiryOver := make([]uint32, n)
	amtOver[n-1] = deliver
	expiryOver[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fee := nodeFee(path[i], path[i+1], amtOver[i+1])
		amtOver[i] = amtOver[i+1] + fee
		expiryOver[i] = expiryOver[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i < n-1 {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func ceilDiv(a lnwire.MilliSatoshi, b int) lnwire.MilliSatoshi {
	if b <= 1 {
		return a
	}
	d := lnwire.MilliSatoshi(b)
	return (a + d - 1) / d
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment complete")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts reached")
	}

	partsLeft := int(r.spec.MaxParts - inFlightHtlcs)
	factors := []float64{1}
	if partsLeft > 1 && r.failureStreak > 0 {
		ladder := []float64{0.55, 0.32, 0.78, 1.0}
		f := ladder[(r.failureStreak-1)%len(ladder)]
		factors = []float64{f, 1.0}
	}

	var lastErr error
	for _, factor := range factors {
		for plannedParts := partsLeft; plannedParts >= 1;
			plannedParts-- {

			shard := ceilDiv(amt, plannedParts)
			if plannedParts > 1 && factor < 1 {
				scaled := lnwire.MilliSatoshi(
					float64(shard) * factor,
				)
				if scaled > 0 {
					shard = scaled
				}
			}
			if plannedParts == 1 {
				shard = amt
			}
			if shard > amt {
				shard = amt
			}

			feeCap := r.shardFeeBudget(shard, amt)
			rt, meta, err := r.findRoute(shard, feeCap)
			if err != nil {
				lastErr = err
				continue
			}

			// Once a corridor is strongly evidenced, allow it to
			// deliberately take an unequal, larger share.
			if plannedParts > 1 && factor == 1 &&
				meta.logProb > math.Log(0.25) {

				grown := shard + shard/2
				if grown > amt {
					grown = amt
				}
				grownCap := r.shardFeeBudget(grown, amt)
				grt, gmeta, growErr := r.findRoute(
					grown, grownCap,
				)
				if growErr == nil &&
					gmeta.logProb >= meta.logProb+
						math.Log(0.65) {

					rt = grt
				}
			}

			return rt, nil
		}
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}
	return nil, lastErr
}

func routeAmountAt(rt *route.Route, index int) lnwire.MilliSatoshi {
	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func routeEdgeKey(rt *route.Route, index int) edgeKey {
	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}
	return edgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
	}
}

func (r *candidateRouter) saveBelief(key edgeKey,
	b liquidityBelief) {

	if st := r.state[key]; st != nil {
		st.belief = b
	}

	sharedKnowledge.Lock()
	sharedKnowledge.beliefs[key] = b
	sharedKnowledge.Unlock()
}

func (r *candidateRouter) recordSuccess(key edgeKey,
	load lnwire.MilliSatoshi) {

	e := r.edgeByKey[key]
	st := r.state[key]
	if e == nil || st == nil {
		return
	}

	b := st.belief
	if load > b.lowerOK {
		b.lowerOK = load
	}
	highEstimate := e.capacity * 88 / 100
	if load > highEstimate {
		highEstimate = load
	}
	if highEstimate > b.estimate {
		b.estimate = highEstimate
	}
	if b.upperFail > 0 && load >= b.upperFail {
		b.upperFail = 0
	}
	b.conf = 0.92
	b.epoch = r.epoch
	r.saveBelief(key, b)
}

func (r *candidateRouter) recordFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	e := r.edgeByKey[key]
	st := r.state[key]
	if e == nil || st == nil {
		return
	}

	st.failures++
	st.lastFail = load

	b := st.belief
	if b.upperFail == 0 || load < b.upperFail {
		b.upperFail = load
	}

	depletedEstimate := load * 22 / 100
	if b.estimate == 0 || depletedEstimate < b.estimate {
		b.estimate = depletedEstimate
	}

	if b.lowerOK >= load {
		// Contradictory evidence is likely reservation or drift.
		b.lowerOK = load * 3 / 4
		b.conf = 0.68
	} else {
		b.conf = 0.90
	}
	if e.from == r.source {
		b.conf *= 0.8
	}
	b.epoch = r.epoch
	r.saveBelief(key, b)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if rt == nil || r.reported[rt] {
		return nil
	}
	r.reported[rt] = true

	if result.Failure == nil {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			over := routeAmountAt(rt, i)
			load := over + r.reserved[key]
			r.recordSuccess(key, load)
			r.reserved[key] += over
		}

		delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
		if rt.TotalAmount > delivered {
			r.committedFee += rt.TotalAmount - delivered
		}
		r.failureStreak = 0
		return nil
	}

	kind := fmt.Sprintf("%T", result.Failure)
	isLiquidity := strings.Contains(
		kind, "TemporaryChannelFailure",
	)
	isPolicy := strings.Contains(kind, "FeeInsufficient") ||
		strings.Contains(kind, "IncorrectCltvExpiry")

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex >= 0 && failIndex < len(rt.Hops) {
		key := routeEdgeKey(rt, failIndex)
		over := routeAmountAt(rt, failIndex)
		load := over + r.reserved[key]

		if isLiquidity {
			r.recordFailure(key, load)
			r.failureStreak++
		} else if isPolicy {
			if st := r.state[key]; st != nil {
				st.failures += 2
				st.lastFail = load
			}
		}
		return nil
	}

	// Unknown-source liquidity failures should diversify the next route
	// without inventing a hard bound for every channel on the path.
	if isLiquidity {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			if st := r.state[key]; st != nil {
				st.failures++
				st.lastFail = routeAmountAt(rt, i) +
					r.reserved[key]
			}
		}
		r.failureStreak++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(30_000)

	hopCostMsat        = float64(5_000)
	reusedEdgeCostMsat = float64(1_100_000)
	extraPartCostMsat  = float64(45_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 8
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 40
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inbound := int64(in.inboundBase) +
		int64(amt)*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	// reserved is cumulative load contributed by successful shards in this
	// payment. It models both held atomic shards and liquidity consumed by
	// already-settled non-atomic shards.
	reserved map[edgeKey]lnwire.MilliSatoshi

	// localUpper is deliberately payment-local and stricter than the shared
	// belief. A failed load must be retried substantially lower, rather than
	// being sent repeatedly at nearly the same amount.
	localUpper map[edgeKey]lnwire.MilliSatoshi
	localFails map[edgeKey]int
	blocked    map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi
	budgetGuard   lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		// Shared failures remain soft because another payment or held shard
		// may have caused a transient depletion.
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees + r.budgetGuard
	if spent >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 3 / 4
	if r.localFails[key] >= 3 {
		cutoff = upper / 2
	}
	if cutoff <= 0 {
		cutoff = 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				// The snapshot makes the first hop nearly certain until an
				// observed local or concurrent reservation failure says
				// otherwise.
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.80
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			int64(total) * weight / sum,
		)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	switch parts {
	case 2:
		for _, weights := range [][]int64{
			{40, 60}, {60, 40},
			{25, 75}, {75, 25},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 3:
		for _, weights := range [][]int64{
			{20, 30, 50},
			{50, 30, 20},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 4:
		for _, weights := range [][]int64{
			{15, 20, 25, 40},
			{40, 25, 20, 15},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	default:
		if parts > 4 {
			ascending := make([]int64, parts)
			descending := make([]int64, parts)

			for i := 0; i < parts; i++ {
				ascending[i] = int64(i + 1)
				descending[i] = int64(parts - i)
			}

			patterns = append(
				patterns,
				weightedAllocation(total, ascending),
				weightedAllocation(total, descending),
			)
		}
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := remainingBudget

		// Reserve a proportional share of a finite budget for later
		// shards. A small allowance avoids rejecting a shard merely due
		// to base-fee rounding.
		if remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			shardCap = remainingBudget * shard / remainingAmount
			allowance := remainingBudget / 20
			if allowance > 25_000 {
				allowance = 25_000
			}
			if shardCap <= remainingBudget-allowance {
				shardCap += allowance
			} else {
				shardCap = remainingBudget
			}
		}

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	// When the whole route set cannot be formed, make one useful shard.
	// Each failure bound forces the next attempt onto another corridor or
	// onto a materially smaller amount.
	if slots > 1 {
		shard := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		for shard > 0 {
			cap := feeBudget
			if feeBudget != lnwire.MaxMilliSatoshi {
				cap = feeBudget * shard / total
				if cap < 1_000 {
					cap = 1_000
				}
			}

			pr, err := r.findRoute(shard, r.reserved, cap)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}

			if shard <= 10_000 {
				break
			}

			next := shard * 2 / 3
			if next >= shard {
				next = shard - 1
			}
			shard = next
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	// MaxParts limits concurrent shards, not the lifetime number of
	// successful shards. Atomic held shards appear in inFlightHtlcs,
	// while settled non-atomic shards release their slots.
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			// A forwarding node reports failure of its outgoing edge.
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.30

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	// A source-side liquidity failure may be represented without a public
	// failure source. It is safe and useful to attribute that case to the
	// first channel; treating it as an uninformative dispatch refusal causes
	// an otherwise identical route to be retried until the runner times out.
	if failIdx < 0 &&
		code == lnwire.CodeTemporaryChannelFailure &&
		len(meta.path) > 0 {

		failIdx = 0
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.recordLocalFailure(edge.key, meta.loads[failIdx])

			count := r.localFails[edge.key]
			r.edgePenalty[edge.key] +=
				300_000 + float64(count)*175_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			// Gossip-policy mismatches are deterministic within this
			// payment and should never poison liquidity estimates.
			r.blocked[edge.key] = true
			r.edgePenalty[edge.key] += 8_000_000

		default:
			r.edgePenalty[edge.key] += 2_000_000
		}

		return nil
	}

	// An unidentified non-liquidity failure provides no trustworthy
	// channel bound. Penalize the whole route to obtain diversity. If a
	// finite budget was involved, retain a small guard against dispatch
	// accounting or rounding differences.
	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 500_000
	}

	if r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
		guard := meta.fee / 20
		if guard < 1_000 {
			guard = 1_000
		}

		remaining := r.remainingFeeBudget()
		if remaining != lnwire.MaxMilliSatoshi && guard > remaining {
			guard = remaining
		}
		r.budgetGuard += guard
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskPriceMsat      = float64(420_000)
	hopCostMsat        = float64(75_000)
	reusedEdgeCostMsat = float64(900_000)
	extraPartCostMsat  = float64(55_000)

	maxSearchHops        = 24
	maxLabelsPerNode     = 12
	maxRouterAttempts    = 80
	maxConsecutiveMisses = 52
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))

	// The inbound fee is charged on the amount arriving at the node:
	// the amount forwarded onward plus the node's outbound fee.
	basis := int64(amt) + outbound
	inbound := int64(in.inboundBase) +
		basis*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		// Failure bounds remain soft because held shards and background
		// traffic can make a genuine observation transient.
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	var cutoff lnwire.MilliSatoshi
	switch r.localFails[key] {
	case 0, 1:
		cutoff = upper * 4 / 5
	case 2:
		cutoff = upper * 2 / 3
	default:
		cutoff = upper / 2
	}

	if cutoff <= 0 {
		return 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.995
			}

			localPenalty := float64(0)
			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				// Keep a low-probability escape hatch for transient
				// self-contention, but strongly prefer a lower retry or
				// another corridor.
				ratio := float64(cutoff) / float64(totalLoad)
				scale := 0.12 * ratio
				if scale < 0.015 {
					scale = 0.015
				}
				p *= scale
				localPenalty = 400_000 +
					float64(r.localFails[edge.key])*300_000
			}

			if p < 0.003 {
				p = 0.003
			}

			score := cur.score +
				float64(nodeCharge) +
				riskPriceMsat*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key] +
				localPenalty

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.60
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			int64(remaining) * weight / remainingWeight,
		)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			part = 1
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	switch parts {
	case 2:
		for _, weights := range [][]int64{
			{1, 7}, {7, 1},
			{1, 3}, {3, 1},
			{1, 2}, {2, 1},
			{2, 3}, {3, 2},
			{9, 11}, {11, 9},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 3:
		for _, weights := range [][]int64{
			{1, 1, 2},
			{2, 1, 1},
			{1, 2, 3},
			{3, 2, 1},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 4:
		for _, weights := range [][]int64{
			{1, 1, 1, 2},
			{2, 1, 1, 1},
			{1, 2, 3, 4},
			{4, 3, 2, 1},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	default:
		if parts > 4 {
			ascending := make([]int64, parts)
			descending := make([]int64, parts)
			for i := 0; i < parts; i++ {
				ascending[i] = int64(i + 1)
				descending[i] = int64(parts - i)
			}

			patterns = append(
				patterns,
				weightedAllocation(total, ascending),
				weightedAllocation(total, descending),
			)
		}
	}

	return patterns
}

func (r *candidateRouter) informedAllocations(
	total lnwire.MilliSatoshi) [][]lnwire.MilliSatoshi {

	var result [][]lnwire.MilliSatoshi
	added := 0

	addLimit := func(limit lnwire.MilliSatoshi) {
		if added >= 16 || limit <= 0 {
			return
		}

		// Leave room for fees and uncertainty when the limit came from a
		// first-hop balance or raw capacity.
		shard := limit * 9 / 10
		if shard <= total/10 || shard >= total*9/10 {
			return
		}

		result = append(result,
			[]lnwire.MilliSatoshi{shard, total - shard},
			[]lnwire.MilliSatoshi{total - shard, shard},
		)
		added++
	}

	// Destination limits constrain the delivered shard directly.
	for _, edge := range r.incomingEdges[r.spec.Target] {
		limit := edge.capacity
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}
		addLimit(limit)
	}

	// First-hop balance and advertised limits often identify the useful
	// unequal split without spending an attempt to discover it.
	for _, edge := range r.edgeLookup {
		if edge.from != r.source {
			continue
		}

		limit := edge.capacity
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}
		if balance, ok := r.localBalances[edge.chanID];
			ok && balance < limit {

			limit = balance
		}
		addLimit(limit)
	}

	return result
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := remainingBudget

		if remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			// Keep half of the proportional remainder in reserve. This
			// permits unequal path fees while preventing an early shard
			// from consuming the entire aggregate budget.
			laterShare := remainingBudget *
				(remainingAmount - shard) / remainingAmount
			reserve := laterShare / 2
			if reserve < remainingBudget {
				shardCap = remainingBudget - reserve
			}
		}

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat
	return plan, totalScore, true
}

func (r *candidateRouter) reorderPlan(plan []*plannedRoute) {
	// Send the hardest shard first. If it fails, replanning happens before
	// easier shards lock liquidity and consume MPP slots.
	sort.SliceStable(plan, func(i, j int) bool {
		return plan[i].score > plan[j].score
	})

	reservations := cloneReservations(r.reserved)
	for _, pr := range plan {
		for i, edge := range pr.meta.path {
			pr.meta.loads[i] =
				pr.meta.amounts[i] + reservations[edge.key]
		}
		addReservationSet(reservations, pr.meta)
	}
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		patterns := allocationPatterns(total, parts)
		if parts == 2 {
			patterns = append(patterns, r.informedAllocations(total)...)
		}

		for _, allocation := range patterns {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		r.reorderPlan(best)
		return best, nil
	}

	// A partial shard is useful only while at least two slots remain.
	// Start near an equal split, then reduce materially so each failed
	// size explores a genuinely different liquidity region.
	if slots > 1 {
		shard := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		for shard >= 10_000 {
			cap := feeBudget
			if feeBudget != lnwire.MaxMilliSatoshi {
				cap = feeBudget * shard / total
				allowance := feeBudget / 10
				if allowance > 20_000 {
					allowance = 20_000
				}
				if cap <= feeBudget-allowance {
					cap += allowance
				} else {
					cap = feeBudget
				}
			}

			pr, err := r.findRoute(shard, r.reserved, cap)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}

			next := shard * 2 / 3
			if next >= shard {
				next = shard - 1
			}
			shard = next
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			// A forwarding node reports a failure on its outgoing edge.
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.25

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if failIdx < 0 &&
		code == lnwire.CodeTemporaryChannelFailure &&
		len(meta.path) > 0 {

		failIdx = 0
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
		r.edgePenalty[meta.path[i].key] *= 0.50
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.recordLocalFailure(edge.key, meta.loads[failIdx])

			count := r.localFails[edge.key]
			r.edgePenalty[edge.key] +=
				450_000 + float64(count)*275_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			// Policy mismatches are deterministic for this payment and
			// must not contaminate liquidity evidence.
			r.blocked[edge.key] = true
			r.edgePenalty[edge.key] += 10_000_000

		default:
			r.edgePenalty[edge.key] += 2_500_000
		}

		return nil
	}

	// Unknown failures are not liquidity evidence. They may be transient
	// dispatch or payment-level failures, so diversify without inventing a
	// hard channel bound or reducing the known fee budget.
	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 900_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(260_000)

	hopCostMsat        = float64(42_000)
	reusedEdgeCostMsat = float64(950_000)
	extraPartCostMsat  = float64(105_000)

	maxSearchHops        = 32
	maxLabelsPerNode     = 10
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 72
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inbound := int64(in.inboundBase) +
		int64(amt)*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi
	budgetGuard   lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	if p < 0.006 {
		return 0.006
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))

	return clampProbability(0.005 + lowMode + highMode)
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/2400)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.018
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.018 + 0.977*pos
		hasEvidence = true

	case b.upperBad > 0 && amt < b.upperBad:
		ratio := float64(amt) / float64(b.upperBad)
		switch {
		case ratio <= 0.55:
			evidence = math.Max(prior, 0.72)
		case ratio <= 0.78:
			evidence = math.Max(prior, 0.38)
		default:
			evidence = math.Min(prior, 0.16)
		}
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	return clampProbability(prior*(1-conf) + evidence*conf)
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.52)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees + r.budgetGuard
	if spent >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap)
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) localProbabilityFactor(key edgeKey,
	load lnwire.MilliSatoshi) float64 {

	upper := r.localUpper[key]
	if upper <= 0 || load <= 0 {
		return 1
	}

	ratio := float64(load) / float64(upper)
	fails := r.localFails[key]

	var factor float64
	switch {
	case ratio <= 0.50:
		factor = 1
	case ratio <= 0.65:
		factor = 0.82
	case ratio <= 0.78:
		factor = 0.42
	case ratio < 1:
		factor = 0.15
	default:
		factor = 0.045
	}

	if fails >= 3 && ratio > 0.65 {
		factor *= 0.55
	}
	if fails >= 6 && ratio >= 1 {
		factor *= 0.55
	}

	if factor < 0.012 {
		return 0.012
	}
	return factor
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				p = 0.995
			}

			p = clampProbability(
				p * r.localProbabilityFactor(edge.key, totalLoad),
			)

			hopCost := hopCostMsat *
				(1 + 0.025*float64(cur.hops))

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCost +
				r.edgePenalty[edge.key]

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.60
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	result := make([]lnwire.MilliSatoshi, len(weights))
	if len(weights) == 0 {
		return result
	}
	if len(weights) == 1 {
		result[0] = total
		return result
	}

	var sum int64
	for _, weight := range weights {
		if weight > 0 {
			sum += weight
		}
	}
	if sum <= 0 {
		return result
	}

	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		partsLeft := lnwire.MilliSatoshi(len(weights) - i - 1)
		if weight <= 0 {
			weight = 1
		}

		part := lnwire.MilliSatoshi(
			int64(remaining) * weight / remainingWeight,
		)
		maxPart := remaining - partsLeft
		if part < 1 {
			part = 1
		}
		if part > maxPart {
			part = maxPart
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
		if remainingWeight <= 0 {
			remainingWeight = int64(len(weights) - i - 1)
		}
	}

	return result
}

func rotateWeights(weights []int64, shift int) []int64 {
	n := len(weights)
	out := make([]int64, n)
	for i := range weights {
		out[i] = weights[(i+shift)%n]
	}
	return out
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	if parts <= 0 || total < lnwire.MilliSatoshi(parts) {
		return nil
	}

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	weightSets := [][]int64{equal}

	if parts == 2 {
		for first := int64(10); first <= 90; first += 10 {
			weightSets = append(weightSets, []int64{
				first, 100 - first,
			})
		}

		for _, pair := range [][]int64{
			{33, 67}, {67, 33},
			{45, 55}, {55, 45},
		} {
			weightSets = append(weightSets, pair)
		}
	} else {
		ascending := make([]int64, parts)
		descending := make([]int64, parts)
		alternating := make([]int64, parts)

		for i := 0; i < parts; i++ {
			ascending[i] = int64(i + 1)
			descending[i] = int64(parts - i)
			if i%2 == 0 {
				alternating[i] = 1
			} else {
				alternating[i] = 3
			}
		}

		weightSets = append(
			weightSets, ascending, descending, alternating,
			rotateWeights(alternating, 1),
		)

		dominant := make([]int64, parts)
		for i := range dominant {
			dominant[i] = 1
		}
		dominant[0] = int64(parts + 2)

		rotations := parts
		if rotations > 6 {
			rotations = 6
		}
		for i := 0; i < rotations; i++ {
			weightSets = append(
				weightSets, rotateWeights(dominant, i),
			)
		}

		if parts == 3 {
			for _, weights := range [][]int64{
				{2, 3, 5}, {5, 3, 2},
				{1, 2, 5}, {5, 2, 1},
				{2, 5, 3}, {3, 5, 2},
			} {
				weightSets = append(weightSets, weights)
			}
		}

		if parts == 4 {
			for _, weights := range [][]int64{
				{1, 2, 3, 5}, {5, 3, 2, 1},
				{1, 1, 3, 5}, {5, 3, 1, 1},
				{2, 5, 2, 1}, {1, 2, 5, 2},
			} {
				weightSets = append(weightSets, weights)
			}
		}
	}

	patterns := make([][]lnwire.MilliSatoshi, 0, len(weightSets))
	seen := make(map[string]bool)

	for _, weights := range weightSets {
		allocation := weightedAllocation(total, weights)
		key := ""
		valid := true
		for _, part := range allocation {
			if part <= 0 {
				valid = false
				break
			}
			key += string(rune(part%2147483647)) + ":"
		}
		if valid && !seen[key] {
			seen[key] = true
			patterns = append(patterns, allocation)
		}
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) shardFeeCap(
	remainingBudget, remainingAmount,
	shard lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if remainingBudget == lnwire.MaxMilliSatoshi {
		return remainingBudget
	}
	if remainingAmount <= shard {
		return remainingBudget
	}

	proportional := remainingBudget * shard / remainingAmount
	slack := remainingBudget / 3
	if slack > 100_000 {
		slack = 100_000
	}

	if proportional >= remainingBudget-slack {
		return remainingBudget
	}
	return proportional + slack
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := r.shardFeeCap(
			remainingBudget, remainingAmount, shard,
		)

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	maxParts := int(slots)
	if lnwire.MilliSatoshi(maxParts) > total {
		maxParts = int(total)
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= maxParts; parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	if slots > 1 {
		base := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		candidates := []lnwire.MilliSatoshi{
			base,
			base * 5 / 6,
			base * 2 / 3,
			base / 2,
			base / 3,
		}

		for _, shard := range candidates {
			if shard <= 0 || shard >= total {
				continue
			}

			cap := r.shardFeeCap(feeBudget, total, shard)
			pr, err := r.findRoute(shard, r.reserved, cap)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.22

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if failIdx < 0 &&
		code == lnwire.CodeTemporaryChannelFailure &&
		len(meta.path) > 0 {

		failIdx = 0
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		key := meta.path[i].key
		updateBelief(key, meta.loads[i], true, now)
		r.edgePenalty[key] *= 0.65
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.recordLocalFailure(edge.key, meta.loads[failIdx])

			count := r.localFails[edge.key]
			increment := 220_000 + float64(count)*95_000
			if increment > 900_000 {
				increment = 900_000
			}
			r.edgePenalty[edge.key] += increment

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.blocked[edge.key] = true
			r.edgePenalty[edge.key] += 8_000_000

		default:
			r.edgePenalty[edge.key] += 1_500_000
		}

		return nil
	}

	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 350_000
	}

	if r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
		guard := meta.fee / 50
		if guard < 500 {
			guard = 500
		}
		if guard > 5_000 {
			guard = 5_000
		}

		remaining := r.remainingFeeBudget()
		if remaining != lnwire.MaxMilliSatoshi && guard > remaining {
			guard = remaining
		}
		r.budgetGuard += guard
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(30_000)

	hopCostMsat        = float64(18_000)
	reusedEdgeCostMsat = float64(1_100_000)
	extraPartCostMsat  = float64(35_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 10
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 44
	maxFallbackSearches  = 16
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inboundBasis := int64(amt) + outbound
	if inboundBasis < int64(amt) {
		return lnwire.MaxMilliSatoshi
	}

	inbound := int64(in.inboundBase) +
		inboundBasis*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	if total > int64(lnwire.MaxMilliSatoshi) {
		return lnwire.MaxMilliSatoshi
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved     map[edgeKey]lnwire.MilliSatoshi
	pendingLoads map[edgeKey]lnwire.MilliSatoshi

	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi
	pendingFees   lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		pendingLoads:   make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) activeReservations(
) map[edgeKey]lnwire.MilliSatoshi {

	result := cloneReservations(r.reserved)
	for key, amt := range r.pendingLoads {
		if amt > lnwire.MaxMilliSatoshi-result[key] {
			result[key] = lnwire.MaxMilliSatoshi
			continue
		}
		result[key] += amt
	}

	return result
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees
	if r.pendingFees > lnwire.MaxMilliSatoshi-spent {
		return 0
	}
	spent += r.pendingFees

	if spent >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 4 / 5
	if r.localFails[key] >= 3 {
		cutoff = upper * 3 / 5
	}
	if cutoff <= 0 {
		cutoff = 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			if reserved > lnwire.MaxMilliSatoshi-over {
				continue
			}
			totalLoad := over + reserved
			if totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.82
				}
				if reserved > 0 {
					p *= 0.93
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		if reservations[edge.key] >
			lnwire.MaxMilliSatoshi-amounts[i] {

			return nil, errors.New("route load overflow")
		}
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			int64(remaining) * weight / remainingWeight,
		)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			return nil
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	if parts <= 0 || total < lnwire.MilliSatoshi(parts) {
		return nil
	}

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	switch parts {
	case 2:
		for _, weights := range [][]int64{
			{40, 60}, {60, 40},
			{33, 67}, {67, 33},
			{25, 75}, {75, 25},
			{15, 85}, {85, 15},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 3:
		for _, weights := range [][]int64{
			{20, 30, 50}, {50, 30, 20},
			{15, 25, 60}, {60, 25, 15},
			{20, 40, 40}, {40, 40, 20},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	default:
		ascending := make([]int64, parts)
		descending := make([]int64, parts)

		for i := 0; i < parts; i++ {
			ascending[i] = int64(i + 1)
			descending[i] = int64(parts - i)
		}

		patterns = append(
			patterns,
			weightedAllocation(total, ascending),
			weightedAllocation(total, descending),
		)
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) bool {

	for i, edge := range meta.path {
		if dst[edge.key] >
			lnwire.MaxMilliSatoshi-meta.amounts[i] {

			return false
		}
		dst[edge.key] += meta.amounts[i]
	}

	return true
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := r.activeReservations()
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 ||
			shard > lnwire.MaxMilliSatoshi-remainingAmount {

			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := remainingBudget

		if remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			shardCap = remainingBudget * shard / remainingAmount
			allowance := remainingBudget / 16
			if allowance > 35_000 {
				allowance = 35_000
			}

			if shardCap <= remainingBudget-allowance {
				shardCap += allowance
			} else {
				shardCap = remainingBudget
			}
		}

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		if !addReservationSet(reservations, pr.meta) {
			return nil, 0, false
		}
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

func proportionalFeeCap(total, shard,
	budget lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if budget == lnwire.MaxMilliSatoshi || total <= 0 {
		return budget
	}

	cap := budget * shard / total
	allowance := budget / 12
	if allowance > 50_000 {
		allowance = 50_000
	}

	if cap <= budget-allowance {
		cap += allowance
	} else {
		cap = budget
	}

	if cap == 0 && budget > 0 {
		cap = 1
	}

	return cap
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	slots uint32, feeBudget lnwire.MilliSatoshi) (*plannedRoute, error) {

	divisor := lnwire.MilliSatoshi(slots)
	if divisor < 2 {
		divisor = 2
	}

	shard := (total + divisor - 1) / divisor
	reservations := r.activeReservations()
	seen := make(map[lnwire.MilliSatoshi]bool)

	for searches := 0;
		searches < maxFallbackSearches && shard > 0;
		searches++ {

		if !seen[shard] {
			seen[shard] = true
			cap := proportionalFeeCap(total, shard, feeBudget)

			pr, err := r.findRoute(shard, reservations, cap)
			if err == nil {
				return pr, nil
			}
		}

		if shard <= 1 {
			break
		}

		next := shard * 3 / 4
		if next >= shard {
			next = shard - 1
		}
		shard = next
	}

	return nil, errors.New("no useful shard found")
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			if len(allocation) != parts {
				continue
			}

			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	pr, err := r.fallbackShard(total, slots, feeBudget)
	if err == nil {
		return []*plannedRoute{pr}, nil
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		if pr.meta.delivered > lnwire.MaxMilliSatoshi-total {
			return lnwire.MaxMilliSatoshi
		}
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) addPending(meta *routeMeta) {
	if meta.fee <= lnwire.MaxMilliSatoshi-r.pendingFees {
		r.pendingFees += meta.fee
	} else {
		r.pendingFees = lnwire.MaxMilliSatoshi
	}

	for i, edge := range meta.path {
		if meta.amounts[i] >
			lnwire.MaxMilliSatoshi-r.pendingLoads[edge.key] {

			r.pendingLoads[edge.key] = lnwire.MaxMilliSatoshi
			continue
		}
		r.pendingLoads[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) removePending(meta *routeMeta) {
	if meta.fee >= r.pendingFees {
		r.pendingFees = 0
	} else {
		r.pendingFees -= meta.fee
	}

	for i, edge := range meta.path {
		old := r.pendingLoads[edge.key]
		if meta.amounts[i] >= old {
			delete(r.pendingLoads, edge.key)
			continue
		}
		r.pendingLoads[edge.key] = old - meta.amounts[i]
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.addPending(next.meta)
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)

		load := amount
		reserved := r.reserved[key]
		if reserved <= lnwire.MaxMilliSatoshi-load {
			load += reserved
		} else {
			load = lnwire.MaxMilliSatoshi
		}
		loads = append(loads, load)
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}
	r.removePending(meta)

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)

			if meta.amounts[i] <=
				lnwire.MaxMilliSatoshi-r.reserved[edge.key] {

				r.reserved[edge.key] += meta.amounts[i]
			} else {
				r.reserved[edge.key] = lnwire.MaxMilliSatoshi
			}

			r.edgePenalty[edge.key] *= 0.25

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		if meta.fee <= lnwire.MaxMilliSatoshi-r.committedFees {
			r.committedFees += meta.fee
		} else {
			r.committedFees = lnwire.MaxMilliSatoshi
		}

		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.recordLocalFailure(edge.key, meta.loads[failIdx])

			count := r.localFails[edge.key]
			r.edgePenalty[edge.key] +=
				350_000 + float64(count)*225_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.blocked[edge.key] = true
			r.edgePenalty[edge.key] += 10_000_000

		default:
			r.edgePenalty[edge.key] += 2_500_000
		}

		return nil
	}

	penalty := float64(850_000)
	if code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry {

		penalty = 3_000_000
	}

	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += penalty
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta     = uint32(40)
	baseRiskPriceMsat  = float64(420_000)
	minRiskPriceMsat   = float64(25_000)
	hopCostMsat        = float64(2_000)
	reusedEdgeCostMsat = float64(650_000)
	maxSearchHops      = 60
	maxLabelsPerNode   = 8
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	if outbound < 0 {
		outbound = 0
	}

	// The inbound fee is assessed on the outgoing amount plus the
	// forwarding node's outbound fee.
	basis := int64(amt)
	if outbound <= int64(lnwire.MaxMilliSatoshi)-basis {
		basis += outbound
	} else {
		return lnwire.MaxMilliSatoshi
	}

	inbound := int64(in.inboundBase) +
		basis*int64(in.inboundRate)/1_000_000
	total := outbound + inbound

	if total <= 0 {
		return 0
	}
	if total >= int64(lnwire.MaxMilliSatoshi) {
		return lnwire.MaxMilliSatoshi
	}
	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	// reserved records liquidity consumed or held by successful shards of
	// this payment. localUpper records failures only for this payment, so
	// the same load is not retried while smaller loads remain eligible.
	reserved      map[edgeKey]lnwire.MilliSatoshi
	localUpper    map[edgeKey]lnwire.MilliSatoshi
	policyBlocked map[edgeKey]bool
	edgePenalty   map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi
	budgetGuard   lnwire.MilliSatoshi

	issuedAttempts      uint32
	consecutiveFailures uint32
	unlocatedFailures   uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		policyBlocked:  make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		// Cross-payment evidence stays soft because the failed liquidity
		// may have been held by another payment and may already be free.
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees + r.budgetGuard
	if spent >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}
	return price
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.policyBlocked[edge.key] ||
				containsNode(cur, edge.from) {

				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)
			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			held := reservations[edge.key]
			if held > lnwire.MaxMilliSatoshi-over {
				continue
			}
			totalLoad := over + held
			if totalLoad > edge.capacity {
				continue
			}

			// A failure is a hard bound only within this payment and only
			// at the observed total load. Lower-load retries remain valid.
			if upper := r.localUpper[edge.key]; upper != 0 &&
				totalLoad >= upper {

				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.985
			}

			score := cur.score + float64(nodeCharge) +
				price*(-math.Log(p)) + hopCostMsat +
				r.edgePenalty[edge.key]

			if held > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.45
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		if reservations[edge.key] >
			lnwire.MaxMilliSatoshi-amounts[i] {

			return nil, errors.New("route load overflow")
		}
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)
	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		if weight > 0 {
			sum += weight
		}
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	if sum <= 0 || total < lnwire.MilliSatoshi(len(weights)) {
		return result
	}

	remaining := total
	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		base := total / lnwire.MilliSatoshi(sum)
		remainder := total % lnwire.MilliSatoshi(sum)
		part := base*lnwire.MilliSatoshi(weight) +
			remainder*lnwire.MilliSatoshi(weight)/
				lnwire.MilliSatoshi(sum)

		partsLeft := lnwire.MilliSatoshi(len(weights) - i - 1)
		if part < 1 {
			part = 1
		}
		if part > remaining-partsLeft {
			part = remaining - partsLeft
		}

		result[i] = part
		remaining -= part
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	switch parts {
	case 2:
		for _, weights := range [][]int64{
			{45, 55}, {55, 45},
			{35, 65}, {65, 35},
			{25, 75}, {75, 25},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 3:
		for _, weights := range [][]int64{
			{20, 30, 50}, {50, 30, 20},
			{25, 35, 40}, {40, 35, 25},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 4:
		for _, weights := range [][]int64{
			{15, 20, 25, 40}, {40, 25, 20, 15},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	default:
		if parts > 4 && parts <= 8 {
			ascending := make([]int64, parts)
			descending := make([]int64, parts)
			for i := 0; i < parts; i++ {
				ascending[i] = int64(i + 1)
				descending[i] = int64(parts - i)
			}
			patterns = append(
				patterns,
				weightedAllocation(total, ascending),
				weightedAllocation(total, descending),
			)
		}
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func proportionalBudget(budget, shard,
	remaining lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if budget == lnwire.MaxMilliSatoshi {
		return budget
	}
	if budget <= 0 || shard <= 0 || remaining <= 0 {
		return 0
	}
	if shard >= remaining {
		return budget
	}

	cap := lnwire.MilliSatoshi(
		float64(budget) * float64(shard) / float64(remaining),
	)
	if cap > budget {
		return budget
	}
	return cap
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)
	for _, shard := range allocation {
		if shard <= 0 ||
			remainingAmount > lnwire.MaxMilliSatoshi-shard {

			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := proportionalBudget(
			remainingBudget, shard, remainingAmount,
		)

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	// Each extra part adds a base-fee surface and one more opportunity for
	// the changing network to invalidate the atomic set.
	totalScore += float64(len(plan)-1) * 40_000

	return plan, totalScore, true
}

func (r *candidateRouter) publicEdgeLimit(
	edge *candidateEdge) lnwire.MilliSatoshi {

	limit := edge.capacity
	if edge.maxHTLC != 0 && edge.maxHTLC < limit {
		limit = edge.maxHTLC
	}

	if upper := r.localUpper[edge.key]; upper != 0 {
		if upper <= 1 {
			return 0
		}
		if upper-1 < limit {
			limit = upper - 1
		}
	}

	if edge.from == r.source {
		balance, ok := r.localBalances[edge.chanID]
		if !ok {
			return 0
		}
		if balance < limit {
			limit = balance
		}
	}

	held := r.reserved[edge.key]
	if held >= limit {
		return 0
	}
	return limit - held
}

func (r *candidateRouter) minimumPublicParts(
	total lnwire.MilliSatoshi) int {

	var sourceMax lnwire.MilliSatoshi
	var targetMax lnwire.MilliSatoshi

	for _, edge := range r.edgeLookup {
		if r.policyBlocked[edge.key] {
			continue
		}

		limit := r.publicEdgeLimit(edge)
		if edge.from == r.source && limit > sourceMax {
			sourceMax = limit
		}
		if edge.to == r.spec.Target && limit > targetMax {
			targetMax = limit
		}
	}

	maxShard := sourceMax
	if targetMax < maxShard {
		maxShard = targetMax
	}
	if maxShard <= 0 {
		return 0
	}

	parts := (total-1)/maxShard + 1
	if parts > lnwire.MilliSatoshi(^uint(0)>>1) {
		return 0
	}
	return int(parts)
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	minParts := r.minimumPublicParts(total)
	if minParts == 0 || minParts > int(slots) {
		return nil, errors.New("public htlc limits require too many parts")
	}
	if minParts < 1 {
		minParts = 1
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)
	firstFeasible := 0

	for parts := minParts; parts <= int(slots); parts++ {
		if firstFeasible != 0 && parts > firstFeasible+2 {
			break
		}

		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if !ok {
				continue
			}

			if firstFeasible == 0 {
				firstFeasible = parts
			}
			if score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) != 0 {
		return best, nil
	}

	// A partial fallback is only useful if the remaining amount can still
	// fit in the remaining slots. It never descends into an endless
	// halving ladder.
	if slots > 1 {
		minUseful := (total-1)/lnwire.MilliSatoshi(slots) + 1
		shardCap := proportionalBudget(
			feeBudget, minUseful, total,
		)

		pr, err := r.findRoute(minUseful, r.reserved, shardCap)
		if err == nil {
			return []*plannedRoute{pr}, nil
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func (r *candidateRouter) attemptLimit(maxParts uint32) uint32 {
	limit := uint32(24) + 4*maxParts
	if limit > 64 {
		limit = 64
	}
	return limit
}

func (r *candidateRouter) failureLimit(maxParts uint32) uint32 {
	limit := uint32(12) + 3*maxParts
	if limit > 40 {
		limit = 40
	}
	return limit
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	if r.issuedAttempts >= r.attemptLimit(maxParts) {
		return nil, errors.New("routing attempt limit reached")
	}
	if r.consecutiveFailures >= r.failureLimit(maxParts) {
		return nil, errors.New("no progress after repeated failures")
	}
	if r.unlocatedFailures >= 3 {
		return nil, errors.New("repeated unclassified route failures")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) != 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.issuedAttempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		if r.reserved[key] > lnwire.MaxMilliSatoshi-amount {
			return nil
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		r.consecutiveFailures++
		r.unlocatedFailures++
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.35
		}

		r.committedFees += meta.fee
		r.consecutiveFailures = 0
		r.unlocatedFailures = 0
		return nil
	}

	r.plan = nil
	r.consecutiveFailures++

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}
	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
	}

	code := result.Failure.Code()

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]
		r.unlocatedFailures = 0

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			load := meta.loads[failIdx]
			updateBelief(edge.key, load, false, now)

			if old := r.localUpper[edge.key]; old == 0 || load < old {
				r.localUpper[edge.key] = load
			}
			r.edgePenalty[edge.key] += 350_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			// Public-policy disagreements are not liquidity evidence.
			// Retire the mismatched direction for this payment.
			r.policyBlocked[edge.key] = true
			r.edgePenalty[edge.key] += 5_000_000

		default:
			r.edgePenalty[edge.key] += 2_000_000
		}
	} else {
		// A refusal without a source did not probe liquidity. Tighten the
		// local budget estimate and terminate after a small bounded number
		// of such non-informative attempts.
		r.unlocatedFailures++

		if r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
			guard := meta.fee / 20
			if guard < 1_000 {
				guard = 1_000
			}

			if r.budgetGuard <=
				lnwire.MaxMilliSatoshi-guard {

				r.budgetGuard += guard
			}
		}

		for _, edge := range meta.path {
			r.edgePenalty[edge.key] += 250_000
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskPriceMsat  = 420000.0
	hopCostMsat    = 6000.0
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) outboundFee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	fee := int64(e.baseFeeMsat) +
		int64(amt)*int64(e.feeRatePPM)/1_000_000
	if fee <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(fee)
}

func (e *candidateEdge) inboundFee(
	amt lnwire.MilliSatoshi) int64 {

	return int64(e.inboundBase) +
		int64(amt)*int64(e.inboundRate)/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.06)
	highMode := 0.5 / (1 + math.Exp((x-0.92)/0.05))
	p := lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	prior := bimodalPrior(load, e.capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[e.key]
	sharedBeliefs.Unlock()
	if !ok || b.conf == 0 {
		return prior
	}

	if b.lowerOK > 0 && load <= b.lowerOK {
		return 0.995
	}
	if b.upperFail > 0 && load >= b.upperFail {
		// A failure can be caused by a transient reservation, so an old
		// upper observation is deliberately a soft rather than hard wall.
		return 0.012
	}

	if b.estimate == 0 {
		return prior
	}

	scale := math.Max(float64(e.capacity)*0.10, 1_000_000)
	q := 1 / (1 + math.Exp(
		(float64(load)-float64(b.estimate))/scale,
	))
	weight := math.Min(0.80, b.conf/(b.conf+3))
	p := prior*(1-weight) + q*weight
	if p < 0.012 {
		return 0.012
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func recordLiquiditySuccess(e *candidateEdge,
	load lnwire.MilliSatoshi) {

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[e.key]
	if load > b.lowerOK {
		b.lowerOK = load
	}
	if b.upperFail > 0 && load >= b.upperFail {
		b.upperFail = 0
	}

	highEstimate := load + load/3
	if highEstimate > e.capacity {
		highEstimate = e.capacity
	}
	if b.estimate == 0 || highEstimate > b.estimate {
		b.estimate = highEstimate
	} else {
		b.estimate = lnwire.MilliSatoshi(
			(float64(b.estimate)*b.conf + float64(highEstimate)) /
				(b.conf + 1),
		)
	}
	b.conf = math.Min(12, b.conf+1)
	sharedBeliefs.m[e.key] = b
}

func recordLiquidityFailure(e *candidateEdge,
	load lnwire.MilliSatoshi) {

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[e.key]
	if b.upperFail == 0 || load < b.upperFail {
		b.upperFail = load
	}
	if b.lowerOK >= load {
		b.lowerOK = 0
	}

	lowEstimate := load * 2 / 5
	if b.estimate == 0 {
		b.estimate = lowEstimate
	} else {
		b.estimate = lnwire.MilliSatoshi(
			(float64(b.estimate)*b.conf + float64(lowEstimate)*1.5) /
				(b.conf + 1.5),
		)
	}
	b.conf = math.Min(12, b.conf+1.5)
	sharedBeliefs.m[e.key] = b
}

type routeRecord struct {
	rt       *route.Route
	path     []*candidateEdge
	edgeAmts []lnwire.MilliSatoshi
	observed []lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	committed bool
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	active  []*routeRecord
	records map[*route.Route]*routeRecord

	committedFee lnwire.MilliSatoshi
	retryHint   lnwire.MilliSatoshi
	failPenalty map[edgeKey]int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		records:       make(map[*route.Route]*routeRecord),
		failPenalty:   make(map[edgeKey]int),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &candidateEdge{
					key: edgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], e,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

type searchLabel struct {
	edge     *candidateEdge
	amount   lnwire.MilliSatoshi
	score    float64
	logProb  float64
	path     []*candidateEdge
	amounts  []lnwire.MilliSatoshi
	index    int
}

type searchQueue []*searchLabel

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *searchQueue) Push(x any) {
	item := x.(*searchLabel)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type paretoPoint struct {
	amount lnwire.MilliSatoshi
	score  float64
}

type routeChoice struct {
	rt       *route.Route
	path     []*candidateEdge
	edgeAmts []lnwire.MilliSatoshi
	observed []lnwire.MilliSatoshi
	prob     float64
	fee      lnwire.MilliSatoshi
}

func (r *candidateRouter) reconcileActive(inFlight uint32) {
	for len(r.active) > int(inFlight) {
		remove := -1
		for i, rec := range r.active {
			if rec.committed {
				remove = i
				break
			}
		}
		if remove < 0 {
			remove = 0
		}
		r.active = append(
			r.active[:remove], r.active[remove+1:]...,
		)
	}
}

func (r *candidateRouter) reservations() map[edgeKey]lnwire.MilliSatoshi {
	reserved := make(map[edgeKey]lnwire.MilliSatoshi)
	for _, rec := range r.active {
		for i, e := range rec.path {
			reserved[e.key] += rec.edgeAmts[i]
		}
	}
	return reserved
}

func (r *candidateRouter) reservedUncommittedFees() lnwire.MilliSatoshi {
	var fees lnwire.MilliSatoshi
	for _, rec := range r.active {
		if !rec.committed {
			fees += rec.fee
		}
	}
	return fees
}

func (r *candidateRouter) remainingBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	used := r.committedFee + r.reservedUncommittedFees()
	if used >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - used
}

func (r *candidateRouter) edgeAllowed(e *candidateEdge,
	amt, reserved lnwire.MilliSatoshi) bool {

	if !e.usable(amt) {
		return false
	}
	if e.key.from == r.source {
		balance, ok := r.localBalances[e.key.chanID]
		if !ok || amt+reserved > balance {
			return false
		}
	}
	return true
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt, reserved lnwire.MilliSatoshi) float64 {

	load := amt + reserved
	p := beliefProbability(e, load)

	if e.key.from == r.source {
		balance := r.localBalances[e.key.chanID]
		if load > balance {
			return 0.001
		}
		if p < 0.08 {
			return 0.08
		}
		if p < 0.985 {
			return p
		}
		return 0.995
	}
	return p
}

func pathContains(path []*candidateEdge, node route.Vertex) bool {
	for _, e := range path {
		if e.key.from == node || e.key.to == node {
			return true
		}
	}
	return false
}

func addPareto(labels map[*candidateEdge][]paretoPoint,
	e *candidateEdge, amount lnwire.MilliSatoshi, score float64) bool {

	points := labels[e]
	for _, p := range points {
		if p.amount <= amount && p.score <= score {
			return false
		}
	}

	kept := points[:0]
	for _, p := range points {
		if amount <= p.amount && score <= p.score {
			continue
		}
		kept = append(kept, p)
	}
	kept = append(kept, paretoPoint{
		amount: amount,
		score:  score,
	})
	if len(kept) > 4 {
		worst := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].score > kept[worst].score {
				worst = i
			}
		}
		kept = append(kept[:worst], kept[worst+1:]...)
	}
	labels[e] = kept
	return true
}

func (r *candidateRouter) findRoute(deliver,
	feeBudget lnwire.MilliSatoshi,
	reserved map[edgeKey]lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}

	pq := &searchQueue{}
	heap.Init(pq)
	labels := make(map[*candidateEdge][]paretoPoint)

	for _, e := range r.incomingEdges[r.spec.Target] {
		res := reserved[e.key]
		if !r.edgeAllowed(e, deliver, res) {
			continue
		}

		p := r.edgeProbability(e, deliver, res)
		logProb := -math.Log(math.Max(p, 0.001))
		score := riskPriceMsat*logProb + hopCostMsat
		if res > 0 {
			score += 500000
		}
		score += float64(r.failPenalty[e.key]) * 260000

		label := &searchLabel{
			edge:    e,
			amount:  deliver,
			score:   score,
			logProb: logProb,
			path:    []*candidateEdge{e},
			amounts: []lnwire.MilliSatoshi{deliver},
		}
		if addPareto(labels, e, deliver, score) {
			heap.Push(pq, label)
		}
	}

	for pq.Len() != 0 {
		cur := heap.Pop(pq).(*searchLabel)

		if cur.edge.key.from == r.source {
			fee := cur.amount - deliver
			if feeBudget != lnwire.MaxMilliSatoshi &&
				fee > feeBudget {

				continue
			}

			rt, err := buildRoute(
				r.source, deliver, cur.path, cur.amounts,
			)
			if err != nil {
				continue
			}

			observed := make([]lnwire.MilliSatoshi,
				len(cur.amounts))
			for i, e := range cur.path {
				observed[i] = cur.amounts[i] +
					reserved[e.key]
			}

			prob := math.Exp(-cur.logProb)
			if prob < 1e-12 {
				prob = 1e-12
			}
			return &routeChoice{
				rt:       rt,
				path:     cur.path,
				edgeAmts: cur.amounts,
				observed: observed,
				prob:     prob,
				fee:      fee,
			}, nil
		}

		if len(cur.path) >= 32 {
			continue
		}

		node := cur.edge.key.from
		outFee := cur.edge.outboundFee(cur.amount)

		for _, prev := range r.incomingEdges[node] {
			if pathContains(cur.path, prev.key.from) {
				continue
			}

			inFee := prev.inboundFee(cur.amount + outFee)
			nodeFee := int64(outFee) + inFee
			if nodeFee < 0 {
				nodeFee = 0
			}
			if nodeFee > math.MaxInt64-int64(cur.amount) {
				continue
			}

			prevAmt := cur.amount +
				lnwire.MilliSatoshi(nodeFee)
			res := reserved[prev.key]
			if !r.edgeAllowed(prev, prevAmt, res) {
				continue
			}

			p := r.edgeProbability(prev, prevAmt, res)
			logProb := cur.logProb -
				math.Log(math.Max(p, 0.001))
			score := cur.score + float64(nodeFee) +
				riskPriceMsat*(-math.Log(math.Max(p, 0.001))) +
				hopCostMsat
			if res > 0 {
				score += 500000
			}
			score += float64(r.failPenalty[prev.key]) * 260000

			path := make([]*candidateEdge, len(cur.path)+1)
			path[0] = prev
			copy(path[1:], cur.path)

			amounts := make([]lnwire.MilliSatoshi,
				len(cur.amounts)+1)
			amounts[0] = prevAmt
			copy(amounts[1:], cur.amounts)

			if !addPareto(labels, prev, prevAmt, score) {
				continue
			}
			heap.Push(pq, &searchLabel{
				edge:     prev,
				amount:   prevAmt,
				score:    score,
				logProb:  logProb,
				path:     path,
				amounts:  amounts,
			})
		}
	}

	return nil, errors.New("no route found")
}

func buildRoute(source route.Vertex, deliver lnwire.MilliSatoshi,
	path []*candidateEdge,
	amounts []lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 || len(path) != len(amounts) {
		return nil, errors.New("invalid path")
	}

	expiries := make([]uint32, len(path))
	expiries[len(path)-1] = finalCltvDelta
	for i := len(path) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, e := range path {
		if !e.usable(amounts[i]) {
			return nil, errors.New("path violates htlc limits")
		}

		forward := deliver
		outgoingExpiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      e.key.to,
			ChannelID:        e.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  source,
		Hops:          hops,
	}, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func appendCandidate(dst []lnwire.MilliSatoshi,
	value, minimum, maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 {
		return dst
	}
	for _, existing := range dst {
		if existing == value {
			return dst
		}
	}
	return append(dst, value)
}

func proportionalBudget(budget, shard,
	remaining lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if budget == lnwire.MaxMilliSatoshi {
		return budget
	}
	if remaining <= 0 || shard >= remaining {
		return budget
	}
	return lnwire.MilliSatoshi(
		float64(budget) * float64(shard) / float64(remaining),
	)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum in-flight parts reached")
	}

	r.reconcileActive(inFlightHtlcs)
	reserved := r.reservations()
	budget := r.remainingBudget()

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		return nil, errors.New("no part slots available")
	}
	minimum := ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))

	var sizes []lnwire.MilliSatoshi
	if r.retryHint >= minimum && r.retryHint < amt {
		sizes = appendCandidate(
			sizes, r.retryHint, minimum, amt,
		)
	}
	sizes = appendCandidate(sizes, amt, minimum, amt)
	sizes = appendCandidate(sizes, amt*3/4, minimum, amt)
	sizes = appendCandidate(sizes, amt*2/3, minimum, amt)
	sizes = appendCandidate(sizes, amt/2, minimum, amt)
	sizes = appendCandidate(sizes, minimum*2, minimum, amt)
	sizes = appendCandidate(
		sizes, minimum+minimum/2, minimum, amt,
	)
	sizes = appendCandidate(sizes, minimum, minimum, amt)

	var best *routeChoice
	bestUtility := math.Inf(1)

	for _, shard := range sizes {
		shardBudget := proportionalBudget(budget, shard, amt)
		choice, err := r.findRoute(shard, shardBudget, reserved)
		if err != nil {
			continue
		}

		parts := float64((amt + shard - 1) / shard)
		if parts > float64(partsLeft) {
			continue
		}

		utility := parts*(-math.Log(choice.prob)) +
			parts*float64(choice.fee)/riskPriceMsat +
			0.10*parts
		if utility < bestUtility {
			bestUtility = utility
			best = choice
		}
	}

	// If a balanced atomic plan is impossible, retain a sequential,
	// lower-amount escape path for non-atomic payments and recovery.
	if best == nil && inFlightHtlcs == 0 {
		fallback := minimum
		for i := 0; i < 4 && fallback > 1_000_000; i++ {
			fallback /= 2
			choice, err := r.findRoute(
				fallback,
				proportionalBudget(budget, fallback, amt),
				reserved,
			)
			if err == nil {
				best = choice
				break
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	rec := &routeRecord{
		rt:       best.rt,
		path:     best.path,
		edgeAmts: best.edgeAmts,
		observed: best.observed,
		fee:      best.fee,
	}
	r.records[best.rt] = rec
	r.active = append(r.active, rec)
	r.retryHint = 0

	return best.rt, nil
}

func (r *candidateRouter) findRecord(rt *route.Route) *routeRecord {
	if rec := r.records[rt]; rec != nil {
		return rec
	}

	for candidate, rec := range r.records {
		if candidate.TotalAmount != rt.TotalAmount ||
			len(candidate.Hops) != len(rt.Hops) {

			continue
		}

		match := true
		for i := range candidate.Hops {
			if candidate.Hops[i].ChannelID !=
				rt.Hops[i].ChannelID {

				match = false
				break
			}
		}
		if match {
			return rec
		}
	}
	return nil
}

func (r *candidateRouter) removeActive(rec *routeRecord) {
	for i, active := range r.active {
		if active == rec {
			r.active = append(
				r.active[:i], r.active[i+1:]...,
			)
			return
		}
	}
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	rec := r.findRecord(rt)
	if rec == nil {
		return fmt.Errorf("unknown attempted route")
	}
	delete(r.records, rec.rt)

	if result.Failure == nil {
		for i, e := range rec.path {
			recordLiquiditySuccess(e, rec.observed[i])
			if r.failPenalty[e.key] > 0 {
				r.failPenalty[e.key]--
			}
		}
		if !rec.committed {
			r.committedFee += rec.fee
			rec.committed = true
		}
		return nil
	}

	failIdx := failureEdgeIndex(rt, result.FailureSource)
	if failIdx > len(rec.path) {
		failIdx = -1
	}

	// Every edge before the failing node demonstrably carried the HTLC.
	if failIdx >= 0 {
		for i := 0; i < failIdx && i < len(rec.path); i++ {
			recordLiquiditySuccess(
				rec.path[i], rec.observed[i],
			)
		}
	}

	code := result.Failure.Code()
	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		if failIdx >= 0 && failIdx < len(rec.path) {
			e := rec.path[failIdx]
			recordLiquidityFailure(e, rec.observed[failIdx])
			r.failPenalty[e.key] += 3
		} else {
			for _, e := range rec.path {
				r.failPenalty[e.key]++
			}
		}

		delivered := rec.edgeAmts[len(rec.edgeAmts)-1]
		retry := delivered * 11 / 20
		if retry > 0 &&
			(r.retryHint == 0 || retry < r.retryHint) {

			r.retryHint = retry
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry,
		lnwire.CodeExpiryTooSoon:

		if failIdx >= 0 && failIdx < len(rec.path) {
			r.failPenalty[rec.path[failIdx].key] += 5
		} else {
			for _, e := range rec.path {
				r.failPenalty[e.key] += 2
			}
		}

	default:
		if failIdx >= 0 && failIdx < len(rec.path) {
			r.failPenalty[rec.path[failIdx].key] += 2
		} else {
			for _, e := range rec.path {
				r.failPenalty[e.key]++
			}
		}
	}

	r.removeActive(rec)
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCLTV   = uint32(40)
	candidateRiskPrice   = 420000.0
	candidateHopPrice    = 30000.0
	candidatePartPrice   = 140000.0
	candidateFeeWeight   = 1.25
	candidateReuseNats   = 2.10
	candidateMinShard    = lnwire.MilliSatoshi(10000)
	candidateProbFloor   = 0.012
	candidateProbCeiling = 0.995
	candidateMaxHops     = 20
	candidateMaxLabels   = 8
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat int64
	feeRatePPM  int64
	cltvDelta   uint16
	minHTLC     lnwire.MilliSatoshi
	maxHTLC     lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func (e *candidateEdge) outgoingFee(amt lnwire.MilliSatoshi) int64 {
	fee := e.baseFeeMsat + int64(amt)*e.feeRatePPM/1_000_000
	if fee < 0 {
		return 0
	}
	return fee
}

func forwardingFee(incoming, outgoing *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if incoming == nil || outgoing == nil {
		return 0
	}

	outFee := outgoing.outgoingFee(amt)
	inBasis := int64(amt) + outFee
	inFee := incoming.inboundBase +
		inBasis*incoming.inboundRate/1_000_000

	total := outFee + inFee
	if total < 0 {
		total = 0
	}

	return lnwire.MilliSatoshi(total)
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	success  uint32
	failure  uint32
}

var candidateSharedBeliefs = struct {
	sync.Mutex
	m map[candidateEdgeKey]candidateBelief
}{
	m: make(map[candidateEdgeKey]candidateBelief),
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return candidateProbFloor
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.045)
	highMode := 0.5 / (1 + math.Exp((x-0.94)/0.035))
	p := lowMode + highMode

	if p < candidateProbFloor {
		return candidateProbFloor
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	prior := candidatePrior(load, e.capacity)

	candidateSharedBeliefs.Lock()
	belief, ok := candidateSharedBeliefs.m[e.key]
	candidateSharedBeliefs.Unlock()

	if !ok {
		return prior
	}

	if belief.lowerOK > 0 && load <= belief.lowerOK {
		return candidateProbCeiling
	}

	if belief.upperBad > 0 && load >= belief.upperBad {
		p := prior * 0.08
		if p < candidateProbFloor {
			p = candidateProbFloor
		}
		return p
	}

	observations := float64(belief.success + belief.failure)
	observationConfidence := 1 - math.Exp(-observations/3.0)

	var learned, confidence float64

	switch {
	case belief.lowerOK > 0 && belief.upperBad > belief.lowerOK:
		mid := 0.5 * float64(belief.lowerOK+belief.upperBad)
		width := math.Max(
			float64(belief.upperBad-belief.lowerOK)*0.16,
			float64(e.capacity)*0.01,
		)
		learned = 1 / (1 + math.Exp(
			(float64(load)-mid)/width,
		))
		confidence = 0.68 + 0.27*observationConfidence

	case belief.upperBad > 0:
		width := math.Max(
			float64(belief.upperBad)*0.12,
			float64(e.capacity)*0.012,
		)
		learned = 1 / (1 + math.Exp(
			(float64(load)-float64(belief.upperBad))/width,
		))
		confidence = 0.55 + 0.30*observationConfidence

	case belief.lowerOK > 0:
		if load <= belief.lowerOK {
			learned = candidateProbCeiling
		} else {
			excess := float64(load-belief.lowerOK) /
				math.Max(float64(e.capacity), 1)
			learned = candidateProbCeiling *
				math.Exp(-excess/0.14)
		}
		confidence = 0.48 + 0.28*observationConfidence

	default:
		return prior
	}

	p := confidence*learned + (1-confidence)*prior
	if p < candidateProbFloor {
		return candidateProbFloor
	}
	if p > candidateProbCeiling {
		return candidateProbCeiling
	}
	return p
}

func candidateRecordSuccess(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	b := candidateSharedBeliefs.m[key]

	// A success at or above an earlier failure contradicts that failure.
	// This is common when a temporary concurrent hold has been released.
	if b.upperBad > 0 && load >= b.upperBad {
		b.upperBad = 0
	}

	if load > b.lowerOK {
		b.lowerOK = load
	}
	b.success++
	candidateSharedBeliefs.m[key] = b
}

func candidateRecordFailure(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	b := candidateSharedBeliefs.m[key]

	// Do not preserve a stale hard success bound across a contradictory
	// failure. Amounts strictly below the failure remain plausible.
	if b.lowerOK >= load {
		if load > 1 {
			b.lowerOK = load - 1
		} else {
			b.lowerOK = 0
		}
	}

	if b.upperBad == 0 || load < b.upperBad {
		b.upperBad = load
	}
	b.failure++
	candidateSharedBeliefs.m[key] = b
}

type candidateSearchItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   int
	path   []*candidateEdge
	index  int
}

type candidateSearchQueue []*candidateSearchItem

func (q candidateSearchQueue) Len() int {
	return len(q)
}

func (q candidateSearchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateSearchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateSearchQueue) Push(x any) {
	item := x.(*candidateSearchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateSearchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	*q = old[:n-1]
	return item
}

type candidateLabel struct {
	amount lnwire.MilliSatoshi
	score  float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[candidateEdgeKey]*candidateEdge
	local    map[uint64]lnwire.MilliSatoshi

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	issued   map[*route.Route]bool
	penalty  map[candidateEdgeKey]float64
	banned   map[candidateEdgeKey]bool

	plan          []*route.Route
	committedFees lnwire.MilliSatoshi
	failures      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:   source,
		spec:     spec,
		incoming: make(map[route.Vertex][]*candidateEdge),
		edges:    make(map[candidateEdgeKey]*candidateEdge),
		local:    localBalances,
		reserved: make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		issued:   make(map[*route.Route]bool),
		penalty:  make(map[candidateEdgeKey]float64),
		banned:   make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:      key,
					capacity: lnwire.NewMSatFromSatoshis(ch.Capacity),

					baseFeeMsat: int64(policy.FeeBaseMSat),
					feeRatePPM: int64(
						policy.FeeProportionalMillionths,
					),
					cltvDelta: policy.TimeLockDelta,
					minHTLC:   policy.MinHTLC,

					inboundBase: int64(ch.InboundFee.BaseFee),
					inboundRate: int64(ch.InboundFee.FeeRate),
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incoming[node] = append(r.incoming[node], edge)
				r.edges[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) budgetLeft() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) routeFee(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	if rt.TotalAmount <= delivered {
		return 0
	}
	return rt.TotalAmount - delivered
}

func (r *candidateRouter) routeAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateAdd(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b > 0 && a > lnwire.MaxMilliSatoshi-b {
		return lnwire.MaxMilliSatoshi
	}
	return a + b
}

func candidatePathContains(path []*candidateEdge,
	node route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == node || edge.key.to == node {
			return true
		}
	}
	return false
}

func candidateDominated(labels []candidateLabel,
	amount lnwire.MilliSatoshi, score float64) bool {

	for _, label := range labels {
		if label.amount <= amount && label.score <= score {
			return true
		}
	}
	return false
}

func candidateInsertLabel(labels []candidateLabel,
	amount lnwire.MilliSatoshi, score float64) []candidateLabel {

	filtered := labels[:0]
	for _, label := range labels {
		if amount <= label.amount && score <= label.score {
			continue
		}
		filtered = append(filtered, label)
	}

	filtered = append(filtered, candidateLabel{
		amount: amount,
		score:  score,
	})

	if len(filtered) <= candidateMaxLabels {
		return filtered
	}

	worst := 0
	for i := 1; i < len(filtered); i++ {
		if filtered[i].score > filtered[worst].score {
			worst = i
		}
	}

	filtered[worst] = filtered[len(filtered)-1]
	return filtered[:len(filtered)-1]
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi,
	maxFee lnwire.MilliSatoshi) (*route.Route, float64, float64, error) {

	if deliver <= 0 {
		return nil, 0, 0, errors.New("invalid shard amount")
	}

	labels := make(map[route.Vertex][]candidateLabel)
	labels[r.spec.Target] = []candidateLabel{{
		amount: deliver,
		score:  0,
	}}

	pq := &candidateSearchQueue{}
	heap.Push(pq, &candidateSearchItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateSearchItem)

		if candidateDominated(
			labels[item.node], item.amount, item.score-0.0001,
		) {
			continue
		}

		if item.node == r.source {
			rt, err := r.buildRoute(item.path, deliver)
			if err != nil {
				return nil, 0, 0, err
			}
			if r.routeFee(rt) > maxFee {
				continue
			}

			return rt, math.Exp(-item.risk), item.score, nil
		}

		if item.hops >= candidateMaxHops {
			continue
		}

		var outgoing *candidateEdge
		if len(item.path) > 0 {
			outgoing = item.path[0]
		}

		for _, incoming := range r.incoming[item.node] {
			if r.banned[incoming.key] {
				continue
			}
			if candidatePathContains(item.path, incoming.key.from) {
				continue
			}

			amountOver := item.amount
			if item.node != r.spec.Target {
				amountOver = candidateAdd(
					amountOver,
					forwardingFee(incoming, outgoing, item.amount),
				)
			}

			if !incoming.usable(amountOver) {
				continue
			}

			if maxFee != lnwire.MaxMilliSatoshi &&
				amountOver-deliver > maxFee {

				continue
			}

			load := candidateAdd(
				amountOver, r.reserved[incoming.key],
			)
			if extra != nil {
				load = candidateAdd(load, extra[incoming.key])
			}
			if load > incoming.capacity {
				continue
			}

			var probability float64
			if incoming.key.from == r.source {
				balance, ok := r.local[incoming.key.chanID]
				if !ok || load > balance {
					continue
				}
				probability = 0.999
			} else {
				probability = candidateProbability(incoming, load)
			}

			risk := -math.Log(probability)
			reuse := 0.0
			if r.reserved[incoming.key] > 0 ||
				(extra != nil && extra[incoming.key] > 0) {

				reuse = candidateReuseNats
			}

			feeIncrement := float64(amountOver - item.amount)
			newScore := item.score +
				candidateFeeWeight*feeIncrement +
				candidateRiskPrice*(
					risk+r.penalty[incoming.key]+reuse,
				) +
				candidateHopPrice

			if candidateDominated(
				labels[incoming.key.from], amountOver, newScore,
			) {
				continue
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = incoming
			copy(path[1:], item.path)

			labels[incoming.key.from] = candidateInsertLabel(
				labels[incoming.key.from], amountOver, newScore,
			)
			heap.Push(pq, &candidateSearchItem{
				node:   incoming.key.from,
				amount: amountOver,
				score:  newScore,
				risk:   item.risk + risk,
				hops:   item.hops + 1,
				path:   path,
			})
		}
	}

	return nil, 0, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = deliver
	expiries[n-1] = candidateFinalCLTV

	for i := n - 2; i >= 0; i-- {
		fee := forwardingFee(path[i], path[i+1], amounts[i+1])
		amounts[i] = candidateAdd(amounts[i+1], fee)
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].cltvDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := deliver
		expiry := candidateFinalCLTV
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) forEachRouteEdge(rt *route.Route,
	fn func(candidateEdgeKey, lnwire.MilliSatoshi, int)) {

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		fn(key, amount, i)
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) addVirtualReservation(
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		reserved[key] = candidateAdd(reserved[key], amount)
	})
}

func (r *candidateRouter) reserveIssued(rt *route.Route) {
	if r.issued[rt] {
		return
	}

	r.issued[rt] = true
	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		r.reserved[key] = candidateAdd(r.reserved[key], amount)
	})
}

func (r *candidateRouter) releaseIssued(rt *route.Route) {
	if !r.issued[rt] {
		return
	}

	delete(r.issued, rt)
	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		current := r.reserved[key]
		if current <= amount {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = current - amount
		}
	})
}

func (r *candidateRouter) maxFeeForPlan(
	already lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	left := r.budgetLeft()
	if left == lnwire.MaxMilliSatoshi {
		return left
	}
	if already >= left {
		return 0
	}
	return left - already
}

func candidateEqualWeights(parts int) []int {
	weights := make([]int, parts)
	for i := range weights {
		weights[i] = 1
	}
	return weights
}

func candidateRotateWeights(weights []int, shift int) []int {
	rotated := make([]int, len(weights))
	for i := range weights {
		rotated[i] = weights[(i+shift)%len(weights)]
	}
	return rotated
}

func candidateWeightPlans(parts int) [][]int {
	if parts == 1 {
		return [][]int{{1}}
	}

	if parts == 2 {
		return [][]int{
			{1, 1},
			{11, 9}, {9, 11},
			{3, 2}, {2, 3},
			{2, 1}, {1, 2},
			{3, 1}, {1, 3},
			{4, 1}, {1, 4},
		}
	}

	plans := [][]int{candidateEqualWeights(parts)}
	bases := [][]int{
		candidateEqualWeights(parts),
		candidateEqualWeights(parts),
	}

	bases[0][0] = 2
	bases[1][0] = 3
	if parts > 2 {
		bases[1][1] = 2
	}

	for _, base := range bases {
		for shift := 0; shift < parts; shift++ {
			plans = append(
				plans, candidateRotateWeights(base, shift),
			)
		}
	}

	return plans
}

func candidatePartition(amount lnwire.MilliSatoshi,
	weights []int) ([]lnwire.MilliSatoshi, bool) {

	parts := len(weights)
	if parts == 0 ||
		amount < candidateMinShard*lnwire.MilliSatoshi(parts) {

		return nil, false
	}

	remaining := amount
	remainingWeight := 0
	for _, weight := range weights {
		if weight <= 0 {
			return nil, false
		}
		remainingWeight += weight
	}

	shards := make([]lnwire.MilliSatoshi, parts)
	for i, weight := range weights {
		left := parts - i
		if left == 1 {
			shards[i] = remaining
			break
		}

		shard := remaining *
			lnwire.MilliSatoshi(weight) /
			lnwire.MilliSatoshi(remainingWeight)

		maximum := remaining -
			candidateMinShard*lnwire.MilliSatoshi(left-1)
		if shard < candidateMinShard {
			shard = candidateMinShard
		}
		if shard > maximum {
			shard = maximum
		}

		shards[i] = shard
		remaining -= shard
		remainingWeight -= weight
	}

	return shards, true
}

func (r *candidateRouter) tryPlan(amount lnwire.MilliSatoshi,
	weights []int) ([]*route.Route, float64, bool) {

	shards, ok := candidatePartition(amount, weights)
	if !ok {
		return nil, 0, false
	}

	virtual := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	plannedFees := lnwire.MilliSatoshi(0)
	plan := make([]*route.Route, 0, len(shards))
	totalScore := candidatePartPrice * float64(len(shards)-1)

	for _, shard := range shards {
		maxFee := r.maxFeeForPlan(plannedFees)
		rt, _, score, err := r.findRoute(shard, virtual, maxFee)
		if err != nil {
			return nil, 0, false
		}

		fee := r.routeFee(rt)
		if r.budgetLeft() != lnwire.MaxMilliSatoshi &&
			plannedFees+fee > r.budgetLeft() {

			return nil, 0, false
		}

		plan = append(plan, rt)
		totalScore += score
		plannedFees += fee
		r.addVirtualReservation(virtual, rt)
	}

	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(amount lnwire.MilliSatoshi,
	slots uint32) ([]*route.Route, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts already in flight")
	}

	maxParts := int(slots)
	if maxParts > 8 {
		maxParts = 8
	}

	var bestPlan []*route.Route
	bestScore := math.Inf(1)

	for parts := 1; parts <= maxParts; parts++ {
		if amount <
			candidateMinShard*lnwire.MilliSatoshi(parts) {

			break
		}

		for _, weights := range candidateWeightPlans(parts) {
			plan, score, ok := r.tryPlan(amount, weights)
			if !ok {
				continue
			}

			// After failures, modestly favor a split plan. It permits
			// retries below a learned upper bound without forcing a
			// long reactive halving ladder.
			if r.failures > 0 && parts > 1 {
				discount := math.Min(
					float64(r.failures), 4,
				) * 45000
				score -= discount
			}

			if score < bestScore {
				bestScore = score
				bestPlan = plan
			}
		}
	}

	if len(bestPlan) != 0 {
		return bestPlan, nil
	}

	// If the full amount cannot be jointly allocated, try a useful
	// evidence-gathering shard. This also handles non-atomic runners
	// where successful shards immediately reduce the remainder.
	divisors := []lnwire.MilliSatoshi{2, 3, 4, 6, 8, 12, 16}
	for _, divisor := range divisors {
		shard := amount / divisor
		if shard < candidateMinShard {
			continue
		}

		rt, _, _, err := r.findRoute(
			shard, nil, r.budgetLeft(),
		)
		if err == nil {
			return []*route.Route{rt}, nil
		}
	}

	return nil, errors.New("no route plan found")
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	for {
		if amt <= 0 {
			return nil, errors.New("invalid remaining amount")
		}

		if len(r.plan) == 0 {
			maxParts := r.spec.MaxParts
			if maxParts == 0 {
				maxParts = 1
			}
			if inFlightHtlcs >= maxParts {
				return nil, errors.New("maximum parts already in flight")
			}

			plan, err := r.makePlan(
				amt, maxParts-inFlightHtlcs,
			)
			if err != nil {
				return nil, err
			}
			r.plan = plan
		}

		rt := r.plan[0]
		r.plan = r.plan[1:]

		if r.routeAmount(rt) > amt {
			r.plan = nil
			continue
		}

		fee := r.routeFee(rt)
		budget := r.budgetLeft()
		if budget != lnwire.MaxMilliSatoshi && fee > budget {
			r.plan = nil
			r.failures++
			continue
		}

		r.reserveIssued(rt)
		return rt, nil
	}
}

func (r *candidateRouter) routeFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) routeEdgeAt(rt *route.Route,
	index int) (candidateEdgeKey, lnwire.MilliSatoshi, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, 0, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	amount := rt.TotalAmount
	if index > 0 {
		amount = rt.Hops[index-1].AmtToForward
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, amount, true
}

func (r *candidateRouter) observedLoad(key candidateEdgeKey,
	fallback lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if load := r.reserved[key]; load > 0 {
		return load
	}
	return fallback
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		r.forEachRouteEdge(rt, func(key candidateEdgeKey,
			amount lnwire.MilliSatoshi, _ int) {

			candidateRecordSuccess(
				key, r.observedLoad(key, amount),
			)
			if r.penalty[key] > 0.35 {
				r.penalty[key] -= 0.35
			} else {
				delete(r.penalty, key)
			}
		})

		r.committedFees = candidateAdd(
			r.committedFees, r.routeFee(rt),
		)
		return nil
	}

	r.failures++
	r.plan = nil

	failIndex := r.routeFailureIndex(rt, result.FailureSource)

	// All earlier channels demonstrably carried their aggregate load.
	for i := 0; i < failIndex && i < len(rt.Hops); i++ {
		key, amount, ok := r.routeEdgeAt(rt, i)
		if ok {
			candidateRecordSuccess(
				key, r.observedLoad(key, amount),
			)
		}
	}

	// Encourage a genuinely different route, rather than cycling through
	// the same long prefix while only changing its final edge.
	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		_ lnwire.MilliSatoshi, _ int) {

		r.penalty[key] += 0.06
	})

	code := result.Failure.Code()
	if key, amount, ok := r.routeEdgeAt(rt, failIndex); ok {
		load := r.observedLoad(key, amount)

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(key, load)
			r.penalty[key] += 1.45

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.banned[key] = true

		default:
			r.penalty[key] += 0.75
		}
	} else {
		// An unattributed failure may be a transient sender-side refusal.
		// Penalize the attempted route softly without poisoning liquidity.
		r.forEachRouteEdge(rt, func(key candidateEdgeKey,
			_ lnwire.MilliSatoshi, _ int) {

			r.penalty[key] += 0.14
		})
	}

	r.releaseIssued(rt)
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strings"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskPriceMsat  = 420000.0
	maxAttempts    = 96
	beamWidth      = 12
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	forward lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if out == nil {
		return 0
	}

	outFee := int64(out.fee(forward))
	basis := int64(forward) + outFee
	inFee := in.inboundBase + basis*in.inboundRate/1_000_000
	total := outFee + inFee
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	epoch     uint64
}

var sharedKnowledge = struct {
	sync.Mutex
	epoch   uint64
	beliefs map[edgeKey]liquidityBelief
}{
	beliefs: make(map[edgeKey]liquidityBelief),
}

type localEdgeState struct {
	belief   liquidityBelief
	failures int
	uses     int
	lastFail lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	state        map[edgeKey]*localEdgeState
	reserved     map[edgeKey]lnwire.MilliSatoshi
	committedFee lnwire.MilliSatoshi
	reported     map[*route.Route]bool

	plan          []*route.Route
	attempts      int
	failureStreak int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	sharedKnowledge.Lock()
	sharedKnowledge.epoch++
	epoch := sharedKnowledge.epoch
	sharedKnowledge.Unlock()

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		epoch:         epoch,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		state:         make(map[edgeKey]*localEdgeState),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		reported:      make(map[*route.Route]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				e := &candidateEdge{
					key:      key,
					chanID:   ch.ChannelID,
					from:     ch.OtherNode,
					to:       node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase: int64(
						ch.InboundFee.BaseFee,
					),
					inboundRate: int64(
						ch.InboundFee.FeeRate,
					),
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.edgeByKey[key] = e
				r.incomingEdges[e.to] = append(
					r.incomingEdges[e.to], e,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedKnowledge.Lock()
	for key, e := range r.edgeByKey {
		b, ok := sharedKnowledge.beliefs[key]
		if !ok {
			b.estimate = e.capacity / 2
		}
		r.state[key] = &localEdgeState{belief: b}
	}
	sharedKnowledge.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.025)
	highMode := 0.5 / (1 + math.Exp((x-0.90)/0.035))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	if load > e.capacity {
		return 0.005
	}

	if e.from == r.source {
		if load <= r.localBalances[e.chanID] {
			return 0.999
		}
		return 0.001
	}

	prior := bimodalPrior(load, e.capacity)
	st := r.state[e.key]
	if st == nil || st.belief.conf <= 0 {
		return prior
	}

	b := st.belief
	var age uint64
	if r.epoch > b.epoch {
		age = r.epoch - b.epoch
	}

	conf := b.conf * math.Exp(-float64(age)/14)
	if conf < 0.025 {
		return prior
	}

	var learned float64
	switch {
	case age <= 10 && b.lowerOK > 0 && load <= b.lowerOK:
		learned = 0.995

	case age <= 10 && b.upperFail > 0 && load >= b.upperFail:
		learned = 0.012

	default:
		estimate := b.estimate
		if estimate <= 0 {
			estimate = e.capacity / 2
		}

		width := float64(e.capacity) * 0.075
		if width < 1_000_000 {
			width = 1_000_000
		}

		z := (float64(load) - float64(estimate)) / width
		learned = clampProbability(1 / (1 + math.Exp(z)))
	}

	return clampProbability(conf*learned + (1-conf)*prior)
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFee >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFee
}

type searchItem struct {
	node route.Vertex
	cost float64
	amt  lnwire.MilliSatoshi
}

type searchQueue []*searchItem

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].cost < q[j].cost
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchItem))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type routeMeta struct {
	path    []*candidateEdge
	fee     lnwire.MilliSatoshi
	logProb float64
	score   float64
}

func (r *candidateRouter) edgePenalty(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	st := r.state[e.key]
	penalty := 0.0

	reserved := r.reserved[e.key]
	if reserved > 0 {
		penalty += 760000
		if e.capacity > 0 {
			penalty += 520000 *
				float64(reserved) / float64(e.capacity)
		}
	}

	if st == nil {
		return penalty
	}

	penalty += float64(st.uses) * 55000

	if st.failures == 0 {
		return penalty
	}

	unit := 480000.0
	if st.lastFail > 0 && load*2 < st.lastFail {
		unit = 70000
	} else if st.lastFail > 0 && load*4 < st.lastFail*3 {
		unit = 190000
	}

	return penalty + float64(st.failures)*unit
}

func (r *candidateRouter) search(amt lnwire.MilliSatoshi,
	riskScale float64) (*route.Route, *routeMeta, error) {

	best := make(map[route.Vertex]float64)
	amount := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	best[r.spec.Target] = 0
	amount[r.spec.Target] = amt

	pq := &searchQueue{}
	heap.Push(pq, &searchItem{
		node: r.spec.Target,
		cost: 0,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*searchItem)
		currentBest, ok := best[item.node]
		if !ok || item.cost > currentBest+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		out := next[item.node]
		for _, in := range r.incomingEdges[item.node] {
			fee := lnwire.MilliSatoshi(0)
			if item.node != r.spec.Target {
				fee = nodeFee(in, out, item.amt)
			}
			if fee > lnwire.MaxMilliSatoshi-item.amt {
				continue
			}

			over := item.amt + fee
			if !in.usable(over) {
				continue
			}

			reserved := r.reserved[in.key]
			if reserved > in.capacity ||
				over > in.capacity-reserved {

				continue
			}

			load := over + reserved
			if in.from == r.source {
				balance := r.localBalances[in.chanID]
				if reserved > balance ||
					over > balance-reserved {

					continue
				}
			}

			p := r.edgeProbability(in, load)
			step := float64(fee) -
				riskScale*math.Log(p) + 1800
			step += r.edgePenalty(in, load)

			newCost := item.cost + step
			old, exists := best[in.from]
			if exists && newCost >= old {
				continue
			}

			best[in.from] = newCost
			amount[in.from] = over
			next[in.from] = in
			heap.Push(pq, &searchItem{
				node: in.from,
				cost: newCost,
				amt:  over,
			})
		}
	}

	if _, ok := best[r.source]; !ok {
		return nil, nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, nil, err
	}

	fee := rt.TotalAmount - amt
	logProb := 0.0
	for i, e := range path {
		load := routeAmountAt(rt, i) + r.reserved[e.key]
		logProb += math.Log(r.edgeProbability(e, load))
	}

	return rt, &routeMeta{
		path:    path,
		fee:     fee,
		logProb: logProb,
	}, nil
}

func (r *candidateRouter) findRoute(amt,
	feeCap lnwire.MilliSatoshi) (*route.Route, *routeMeta, error) {

	baseScale := riskPriceMsat
	if feeCap != lnwire.MaxMilliSatoshi {
		budgetScale := float64(feeCap) * 0.45
		if budgetScale < 4000 {
			budgetScale = 4000
		}
		if budgetScale < baseScale {
			baseScale = budgetScale
		}
	}

	scales := []float64{
		baseScale,
		baseScale / 4,
		0,
		riskPriceMsat,
	}

	var bestRoute *route.Route
	var bestMeta *routeMeta

	for _, scale := range scales {
		rt, meta, err := r.search(amt, scale)
		if err != nil {
			continue
		}
		if feeCap != lnwire.MaxMilliSatoshi &&
			meta.fee > feeCap {

			continue
		}

		meta.score = float64(meta.fee) -
			baseScale*meta.logProb +
			float64(len(meta.path))*1800

		if bestMeta == nil || meta.score < bestMeta.score {
			bestRoute = rt
			bestMeta = meta
		}
	}

	if bestRoute == nil {
		return nil, nil, errors.New("no route found")
	}

	return bestRoute, bestMeta, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	path := make([]*candidateEdge, 0, 12)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, nil, errors.New("routing cycle")
		}
		visited[node] = true

		e, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, e)
		node = e.to
	}

	n := len(path)
	if n == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, n)
	expiryOver := make([]uint32, n)
	amtOver[n-1] = deliver
	expiryOver[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fee := nodeFee(path[i], path[i+1], amtOver[i+1])
		if fee > lnwire.MaxMilliSatoshi-amtOver[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amtOver[i] = amtOver[i+1] + fee
		expiryOver[i] = expiryOver[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)

		if i < n-1 {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func ceilDiv(a lnwire.MilliSatoshi, b int) lnwire.MilliSatoshi {
	if b <= 1 {
		return a
	}

	d := lnwire.MilliSatoshi(b)
	return (a + d - 1) / d
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func reserveRoute(reserved map[edgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key := routeEdgeKey(rt, i)
		reserved[key] += routeAmountAt(rt, i)
	}
}

func routeDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateShardSizes(remaining lnwire.MilliSatoshi,
	parts int) []lnwire.MilliSatoshi {

	if parts <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	equal := ceilDiv(remaining, parts)
	raw := []lnwire.MilliSatoshi{
		equal,
		equal * 3 / 4,
		equal * 5 / 4,
		equal * 3 / 2,
		equal * 2,
		remaining,
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	result := make([]lnwire.MilliSatoshi, 0, len(raw))

	for _, shard := range raw {
		if shard <= 0 {
			shard = 1
		}
		if shard > remaining {
			shard = remaining
		}
		if seen[shard] {
			continue
		}

		seen[shard] = true
		result = append(result, shard)
	}

	return result
}

type planState struct {
	remaining lnwire.MilliSatoshi
	budget    lnwire.MilliSatoshi
	routes    []*route.Route
	reserved  map[edgeKey]lnwire.MilliSatoshi
	score     float64
}

func (r *candidateRouter) planRiskPrice(
	budget lnwire.MilliSatoshi) float64 {

	if budget == lnwire.MaxMilliSatoshi {
		return riskPriceMsat
	}

	scale := float64(budget) * 0.55
	if scale < 5000 {
		scale = 5000
	}
	if scale > riskPriceMsat {
		scale = riskPriceMsat
	}
	return scale
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, error) {

	if total <= 0 || parts <= 0 {
		return nil, errors.New("no route found")
	}

	actualReserved := r.reserved
	defer func() {
		r.reserved = actualReserved
	}()

	initialBudget := r.remainingFeeBudget()
	riskPrice := r.planRiskPrice(initialBudget)

	frontier := []*planState{{
		remaining: total,
		budget:    initialBudget,
		reserved:  cloneReservations(actualReserved),
	}}

	var complete []*planState

	for depth := 0; depth < parts && len(frontier) > 0; depth++ {
		nextFrontier := make([]*planState, 0, len(frontier)*4)

		for _, state := range frontier {
			if state.remaining == 0 {
				complete = append(complete, state)
				continue
			}

			partsLeft := parts - depth
			for _, shard := range candidateShardSizes(
				state.remaining, partsLeft,
			) {
				r.reserved = state.reserved

				rt, meta, err := r.findRoute(
					shard, state.budget,
				)
				if err != nil {
					continue
				}

				nextBudget := state.budget
				if nextBudget != lnwire.MaxMilliSatoshi {
					if meta.fee > nextBudget {
						continue
					}
					nextBudget -= meta.fee
				}

				nextReserved := cloneReservations(
					state.reserved,
				)
				reserveRoute(nextReserved, rt)

				nextRoutes := make(
					[]*route.Route, len(state.routes), len(state.routes)+1,
				)
				copy(nextRoutes, state.routes)
				nextRoutes = append(nextRoutes, rt)

				nextScore := state.score +
					float64(meta.fee) -
					riskPrice*meta.logProb +
					float64(len(meta.path))*1800 +
					12000

				nextFrontier = append(nextFrontier, &planState{
					remaining: state.remaining - shard,
					budget:    nextBudget,
					routes:    nextRoutes,
					reserved:  nextReserved,
					score:     nextScore,
				})
			}
		}

		sort.Slice(nextFrontier, func(i, j int) bool {
			left := nextFrontier[i]
			right := nextFrontier[j]

			leftEstimate := left.score
			rightEstimate := right.score

			if left.remaining > 0 {
				leftEstimate += 4000
			}
			if right.remaining > 0 {
				rightEstimate += 4000
			}

			return leftEstimate < rightEstimate
		})

		if len(nextFrontier) > beamWidth {
			nextFrontier = nextFrontier[:beamWidth]
		}
		frontier = nextFrontier
	}

	for _, state := range frontier {
		if state.remaining == 0 {
			complete = append(complete, state)
		}
	}

	if len(complete) == 0 {
		return nil, errors.New("no route found")
	}

	sort.Slice(complete, func(i, j int) bool {
		return complete[i].score < complete[j].score
	})

	return complete[0].routes, nil
}

func plannedAmount(plan []*route.Route) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, rt := range plan {
		amt := routeDelivered(rt)
		if amt > lnwire.MaxMilliSatoshi-total {
			return lnwire.MaxMilliSatoshi
		}
		total += amt
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment complete")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt limit reached")
	}

	if len(r.plan) > 0 && plannedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		partsLeft := int(r.spec.MaxParts - inFlightHtlcs)
		plan, err := r.makePlan(amt, partsLeft)
		if err != nil && r.failureStreak > 0 {
			plan, err = r.makePlan(amt, partsLeft)
		}
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	rt := r.plan[0]
	r.plan = r.plan[1:]
	r.attempts++

	return rt, nil
}

func routeAmountAt(rt *route.Route, index int) lnwire.MilliSatoshi {
	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func routeEdgeKey(rt *route.Route, index int) edgeKey {
	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return edgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
	}
}

func (r *candidateRouter) saveBelief(key edgeKey,
	b liquidityBelief) {

	if st := r.state[key]; st != nil {
		st.belief = b
	}

	sharedKnowledge.Lock()
	sharedKnowledge.beliefs[key] = b
	sharedKnowledge.Unlock()
}

func (r *candidateRouter) recordSuccess(key edgeKey,
	load lnwire.MilliSatoshi) {

	e := r.edgeByKey[key]
	st := r.state[key]
	if e == nil || st == nil {
		return
	}

	b := st.belief
	if load > b.lowerOK {
		b.lowerOK = load
	}

	highEstimate := e.capacity * 88 / 100
	if load > highEstimate {
		highEstimate = load
	}
	if highEstimate > b.estimate {
		b.estimate = highEstimate
	}
	if b.upperFail > 0 && load >= b.upperFail {
		b.upperFail = 0
	}

	b.conf = 0.92
	b.epoch = r.epoch

	if st.failures > 0 {
		st.failures /= 2
	}
	if st.uses > 0 {
		st.uses--
	}

	r.saveBelief(key, b)
}

func (r *candidateRouter) recordFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	e := r.edgeByKey[key]
	st := r.state[key]
	if e == nil || st == nil {
		return
	}

	st.failures++
	st.lastFail = load

	b := st.belief
	if b.upperFail == 0 || load < b.upperFail {
		b.upperFail = load
	}

	depletedEstimate := load * 22 / 100
	if b.estimate == 0 || depletedEstimate < b.estimate {
		b.estimate = depletedEstimate
	}

	if b.lowerOK >= load {
		b.lowerOK = load * 3 / 4
		b.conf = 0.68
	} else {
		b.conf = 0.90
	}

	if e.from == r.source {
		b.conf *= 0.8
	}

	b.epoch = r.epoch
	r.saveBelief(key, b)
}

func (r *candidateRouter) markAttemptedPath(rt *route.Route,
	weight int) {

	for i := range rt.Hops {
		key := routeEdgeKey(rt, i)
		st := r.state[key]
		if st == nil {
			continue
		}

		st.uses += weight
		st.lastFail = routeAmountAt(rt, i) +
			r.reserved[key]
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if rt == nil || r.reported[rt] {
		return nil
	}
	r.reported[rt] = true

	if result.Failure == nil {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			over := routeAmountAt(rt, i)
			load := over + r.reserved[key]

			r.recordSuccess(key, load)
			r.reserved[key] += over
		}

		delivered := routeDelivered(rt)
		if rt.TotalAmount > delivered {
			r.committedFee += rt.TotalAmount - delivered
		}

		r.failureStreak = 0
		return nil
	}

	r.plan = nil
	r.failureStreak++
	r.markAttemptedPath(rt, 1)

	desc := fmt.Sprintf("%T %v", result.Failure, result.Failure)
	isLiquidity := strings.Contains(
		desc, "TemporaryChannelFailure",
	)
	isPolicy := strings.Contains(desc, "FeeInsufficient") ||
		strings.Contains(desc, "IncorrectCltvExpiry")

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex >= 0 && failIndex < len(rt.Hops) {
		key := routeEdgeKey(rt, failIndex)
		load := routeAmountAt(rt, failIndex) +
			r.reserved[key]

		switch {
		case isLiquidity:
			r.recordFailure(key, load)

		case isPolicy:
			if st := r.state[key]; st != nil {
				st.failures += 4
				st.uses += 2
				st.lastFail = load
			}

		default:
			if st := r.state[key]; st != nil {
				st.failures++
				st.lastFail = load
			}
		}

		return nil
	}

	if isLiquidity {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			st := r.state[key]
			if st == nil {
				continue
			}

			st.uses++
			st.lastFail = routeAmountAt(rt, i) +
				r.reserved[key]
		}
	} else {
		r.markAttemptedPath(rt, 2)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)
	riskPriceMsat  = 420000.0
	hopTimeCost    = 12000.0
	reuseRiskNats  = 0.55
)

type edgeKey struct {
	chanID   uint64
	from     route.Vertex
	to       route.Vertex
	capacity int64
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) key() edgeKey {
	return edgeKey{
		chanID:   e.chanID,
		from:     e.from,
		to:       e.to,
		capacity: int64(e.capacity),
	}
}

func (e *candidateEdge) outboundFee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	fee := int64(e.baseFeeMsat) +
		int64(amt)*int64(e.feeRatePPM)/1_000_000
	if fee < 0 {
		return 0
	}

	return lnwire.MilliSatoshi(fee)
}

func (e *candidateEdge) usableShard(
	amt lnwire.MilliSatoshi) bool {

	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

// forwardingFee returns the complete fee charged by the recipient of
// incoming when it forwards amtOut over outgoing. The inbound component is
// assessed on the forwarded amount plus the advertised outbound fee, and
// the combined fee is floored at zero.
func forwardingFee(incoming, outgoing *candidateEdge,
	amtOut lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	out := int64(outgoing.outboundFee(amtOut))
	basis := int64(amtOut) + out
	in := incoming.inboundBase +
		basis*incoming.inboundRate/1_000_000

	total := out + in
	if total < 0 {
		total = 0
	}

	return lnwire.MilliSatoshi(total)
}

type plannedRoute struct {
	rt      *route.Route
	keys    []edgeKey
	amounts []lnwire.MilliSatoshi
	score   float64
}

type attemptMeta struct {
	keys          []edgeKey
	amounts       []lnwire.MilliSatoshi
	observedLoads []lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs  map[edgeKey]liquidityBelief
	disabled map[edgeKey]bool
	held     map[edgeKey]lnwire.MilliSatoshi

	committedFees lnwire.MilliSatoshi
	plan          []plannedRoute
	attemptMeta   map[*route.Route]attemptMeta
	attempts      int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]liquidityBelief),
		disabled:      make(map[edgeKey]bool),
		held:          make(map[edgeKey]lnwire.MilliSatoshi),
		attemptMeta:   make(map[*route.Route]attemptMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase: int64(
						ch.InboundFee.BaseFee,
					),
					inboundRate: int64(
						ch.InboundFee.FeeRate,
					),
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for _, edges := range r.incomingEdges {
		for _, edge := range edges {
			if b, ok := sharedBeliefs.m[edge.key()]; ok {
				r.beliefs[edge.key()] = b
			}
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

type searchItem struct {
	node  route.Vertex
	amt   lnwire.MilliSatoshi
	score float64
	path  []*candidateEdge
	index int
}

type searchQueue []*searchItem

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *searchQueue) Push(x any) {
	item := x.(*searchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	*q = old[:n-1]
	return item
}

func clampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)

	// One mode represents a nearly empty direction and decays quickly for
	// tiny probes. The other represents a funded direction and falls at
	// the public-capacity cliff.
	lowMode := 0.5 * math.Exp(-x/0.025)
	highMode := 0.5 / (1 + math.Exp((x-0.88)*28))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		return 0.995
	}

	p := bimodalPrior(load, edge.capacity)
	b := r.beliefs[edge.key()]

	if b.lowerOK > 0 {
		if load <= b.lowerOK {
			return 0.995
		}

		// A success above the prior's likely range remains useful, but
		// softens rather than becoming an eternal hard guarantee.
		ratio := float64(b.lowerOK) / float64(load)
		p = math.Max(p, 0.985*ratio*ratio)
	}

	if b.upperFail > 0 {
		if load >= b.upperFail {
			return math.Max(0.012, p*0.03)
		}

		x := float64(load) / float64(b.upperFail)
		p *= 1 - 0.85*math.Pow(x, 4)
	}

	if p < 0.012 {
		p = 0.012
	}
	if p > 0.995 {
		p = 0.995
	}

	return p
}

func addAmount(a, b lnwire.MilliSatoshi) (
	lnwire.MilliSatoshi, bool) {

	if b > lnwire.MaxMilliSatoshi-a {
		return 0, false
	}
	return a + b, true
}

func prependEdge(edge *candidateEdge,
	path []*candidateEdge) []*candidateEdge {

	result := make([]*candidateEdge, len(path)+1)
	result[0] = edge
	copy(result[1:], path)
	return result
}

func (r *candidateRouter) findRoute(deliver,
	maxFee lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi) (
	plannedRoute, error) {

	if deliver <= 0 {
		return plannedRoute{}, errors.New("invalid shard amount")
	}
	if r.source == r.spec.Target {
		return plannedRoute{}, errors.New("source is target")
	}

	best := make(map[route.Vertex]float64)
	best[r.spec.Target] = 0

	pq := &searchQueue{}
	heap.Push(pq, &searchItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*searchItem)
		bestScore, ok := best[item.node]
		if !ok || item.score > bestScore+0.0001 {
			continue
		}

		if item.node == r.source {
			rt, keys, amounts, err := r.buildRoute(
				deliver, item.path,
			)
			if err != nil {
				return plannedRoute{}, err
			}

			fee := routeFee(rt)
			if fee > maxFee {
				continue
			}

			return plannedRoute{
				rt:      rt,
				keys:    keys,
				amounts: amounts,
				score:   item.score,
			}, nil
		}

		for _, edge := range r.incomingEdges[item.node] {
			key := edge.key()
			if r.disabled[key] {
				continue
			}

			over := deliver
			var fee lnwire.MilliSatoshi

			if item.node != r.spec.Target {
				if len(item.path) == 0 {
					continue
				}

				fee = forwardingFee(
					edge, item.path[0], item.amt,
				)

				var valid bool
				over, valid = addAmount(item.amt, fee)
				if !valid {
					continue
				}
			}

			if !edge.usableShard(over) {
				continue
			}

			reserved := reservations[key]
			load, valid := addAmount(over, reserved)
			if !valid || load > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance := r.localBalances[edge.chanID]
				if load > balance {
					continue
				}
			}

			feesSoFar := over - deliver
			if feesSoFar > maxFee {
				continue
			}

			p := r.probability(edge, load)
			risk := -math.Log(p)
			if reserved > 0 {
				risk += reuseRiskNats
			}

			score := item.score + float64(fee) +
				riskPriceMsat*risk + hopTimeCost

			if old, exists := best[edge.from]; exists &&
				score >= old {

				continue
			}

			best[edge.from] = score
			heap.Push(pq, &searchItem{
				node:  edge.from,
				amt:   over,
				score: score,
				path:  prependEdge(edge, item.path),
			})
		}
	}

	return plannedRoute{}, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty path")
	}

	for i := 0; i+1 < len(path); i++ {
		if path[i].to != path[i+1].from {
			return nil, nil, nil, fmt.Errorf(
				"disconnected path at hop %d", i,
			)
		}
	}
	if path[0].from != r.source ||
		path[len(path)-1].to != r.spec.Target {

		return nil, nil, nil, errors.New("path endpoints mismatch")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)
	keys := make([]edgeKey, n)

	amounts[n-1] = deliver
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fee := forwardingFee(
			path[i], path[i+1], amounts[i+1],
		)

		var valid bool
		amounts[i], valid = addAmount(amounts[i+1], fee)
		if !valid {
			return nil, nil, nil, errors.New(
				"route amount overflow",
			)
		}

		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		if !edge.usableShard(amounts[i]) {
			return nil, nil, nil, errors.New(
				"path violates announced htlc limits",
			)
		}

		keys[i] = edge.key()

		amtToForward := deliver
		outgoingExpiry := finalCltvDelta
		if i+1 < n {
			amtToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func routeDeliverAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeFee(rt *route.Route) lnwire.MilliSatoshi {
	deliver := routeDeliverAmount(rt)
	if rt == nil || rt.TotalAmount < deliver {
		return 0
	}
	return rt.TotalAmount - deliver
}

func copyReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amount := range src {
		dst[key] = amount
	}
	return dst
}

func proportionalBudget(budget, shard,
	remaining lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if budget == lnwire.MaxMilliSatoshi {
		return budget
	}
	if remaining <= 0 || shard >= remaining {
		return budget
	}

	return lnwire.MilliSatoshi(
		uint64(budget) * uint64(shard) / uint64(remaining),
	)
}

func skewedShare(remaining lnwire.MilliSatoshi, partsLeft,
	skew int64) lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return remaining
	}

	base := (remaining + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	share := lnwire.MilliSatoshi(int64(base) * skew / 100)
	if share < 1 {
		share = 1
	}

	// Leave a nonzero shard for every later part.
	maxShare := remaining - lnwire.MilliSatoshi(partsLeft-1)
	if share > maxShare {
		share = maxShare
	}

	return share
}

func (r *candidateRouter) remainingBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) buildPlan(amount lnwire.MilliSatoshi,
	parts int, skew int64) ([]plannedRoute, float64, error) {

	if parts <= 0 {
		return nil, 0, errors.New("no parts available")
	}

	reservations := copyReservations(r.held)
	remaining := amount
	budget := r.remainingBudget()
	plan := make([]plannedRoute, 0, parts)
	totalScore := 0.0

	for i := 0; i < parts && remaining > 0; i++ {
		left := parts - i
		share := skewedShare(remaining, left, skew)
		shardBudget := proportionalBudget(
			budget, share, remaining,
		)

		pr, err := r.findRoute(
			share, shardBudget, reservations,
		)
		if err != nil {
			return nil, 0, err
		}

		fee := routeFee(pr.rt)
		if budget != lnwire.MaxMilliSatoshi {
			if fee > budget {
				return nil, 0, errors.New(
					"plan exceeds fee budget",
				)
			}
			budget -= fee
		}

		for j, key := range pr.keys {
			next, valid := addAmount(
				reservations[key], pr.amounts[j],
			)
			if !valid {
				return nil, 0, errors.New(
					"reservation overflow",
				)
			}
			reservations[key] = next
		}

		plan = append(plan, pr)
		totalScore += pr.score + 60000
		remaining -= share
	}

	if remaining != 0 {
		return nil, 0, errors.New("incomplete shard plan")
	}

	return plan, totalScore, nil
}

func (r *candidateRouter) planRoutes(amount lnwire.MilliSatoshi,
	slots int) error {

	var (
		bestPlan  []plannedRoute
		bestScore = math.Inf(1)
	)

	skews := []int64{100, 135, 70}

	for parts := 1; parts <= slots; parts++ {
		for _, skew := range skews {
			if parts == 1 && skew != 100 {
				continue
			}

			plan, score, err := r.buildPlan(
				amount, parts, skew,
			)
			if err != nil {
				continue
			}

			if score < bestScore {
				bestScore = score
				bestPlan = plan
			}
		}
	}

	if len(bestPlan) == 0 {
		return errors.New("no route found")
	}

	r.plan = bestPlan
	return nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	maxAttempts := 12 + int(r.spec.MaxParts)*4
	if maxAttempts > 48 {
		maxAttempts = 48
	}
	if maxAttempts < 16 {
		maxAttempts = 16
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("attempt limit reached")
	}

	maxParts := int(r.spec.MaxParts)
	if maxParts <= 0 {
		maxParts = 1
	}
	if int(inFlightHtlcs) >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	for len(r.plan) != 0 {
		pr := r.plan[0]
		deliver := routeDeliverAmount(pr.rt)
		if deliver <= 0 || deliver > amt ||
			routeFee(pr.rt) > r.remainingBudget() {

			r.plan = nil
			break
		}

		r.plan = r.plan[1:]

		meta := attemptMeta{
			keys:          append([]edgeKey(nil), pr.keys...),
			amounts:       append([]lnwire.MilliSatoshi(nil), pr.amounts...),
			observedLoads: make(
				[]lnwire.MilliSatoshi, len(pr.keys),
			),
		}
		for i, key := range pr.keys {
			load, valid := addAmount(
				r.held[key], pr.amounts[i],
			)
			if !valid {
				r.plan = nil
				return nil, errors.New(
					"attempt load overflow",
				)
			}
			meta.observedLoads[i] = load
		}

		r.attemptMeta[pr.rt] = meta
		r.attempts++
		return pr.rt, nil
	}

	slots := maxParts - int(inFlightHtlcs)
	if err := r.planRoutes(amt, slots); err != nil {
		return nil, err
	}

	return r.RequestRoute(amt, inFlightHtlcs)
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.m[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(
	key edgeKey, load lnwire.MilliSatoshi) {

	b := r.beliefs[key]
	if load > b.lowerOK {
		b.lowerOK = load
	}

	// A proven success at or above an old failure bound demonstrates that
	// the old observation was stale or caused by temporary reservations.
	if b.upperFail != 0 && load >= b.upperFail {
		b.upperFail = 0
	}

	r.storeBelief(key, b)
}

func (r *candidateRouter) recordFailure(
	key edgeKey, load lnwire.MilliSatoshi) {

	b := r.beliefs[key]
	if b.upperFail == 0 || load < b.upperFail {
		b.upperFail = load
	}

	if b.lowerOK >= b.upperFail {
		b.lowerOK = b.upperFail * 3 / 4
	}

	r.storeBelief(key, b)
}

func failureIndex(rt *route.Route,
	source route.Vertex) int {

	if rt == nil {
		return -1
	}
	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	meta, haveMeta := r.attemptMeta[rt]
	delete(r.attemptMeta, rt)

	if result.Failure == nil {
		fee := routeFee(rt)
		if next, valid := addAmount(r.committedFees, fee); valid {
			r.committedFees = next
		}

		if haveMeta {
			for i, key := range meta.keys {
				next, valid := addAmount(
					r.held[key], meta.amounts[i],
				)
				if valid {
					r.held[key] = next
				}
				r.recordSuccess(
					key, meta.observedLoads[i],
				)
			}
		}

		return nil
	}

	// Any failed member invalidates the remainder of an up-front plan.
	// Replanning incorporates the new evidence while preserving held
	// reservations from siblings that already succeeded.
	r.plan = nil

	if !haveMeta {
		return nil
	}

	failIdx := failureIndex(rt, result.FailureSource)
	code := result.Failure.Code()

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		if failIdx < 0 || failIdx >= len(meta.keys) {
			return nil
		}

		// Every channel before the failing outgoing channel demonstrably
		// carried its total concurrent load.
		for i := 0; i < failIdx; i++ {
			r.recordSuccess(
				meta.keys[i], meta.observedLoads[i],
			)
		}
		r.recordFailure(
			meta.keys[failIdx],
			meta.observedLoads[failIdx],
		)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		if failIdx >= 0 && failIdx < len(meta.keys) {
			r.disabled[meta.keys[failIdx]] = true
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(25_000)

	hopCostMsat        = float64(12_000)
	reusedEdgeCostMsat = float64(1_250_000)
	extraPartCostMsat  = float64(55_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 10
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 48
	maxAllocationPlans   = 40
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inbound := int64(in.inboundBase) +
		int64(amt)*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}

	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFees
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) * 0.55
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	var cutoff lnwire.MilliSatoshi
	switch {
	case r.localFails[key] >= 3:
		cutoff = upper * 35 / 100
	case r.localFails[key] == 2:
		cutoff = upper / 2
	default:
		cutoff = upper * 65 / 100
	}

	if cutoff <= 0 {
		cutoff = 1
	}
	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.72
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := total / lnwire.MilliSatoshi(sum) *
			lnwire.MilliSatoshi(weight)
		part += (total % lnwire.MilliSatoshi(sum)) *
			lnwire.MilliSatoshi(weight) /
			lnwire.MilliSatoshi(sum)

		if part <= 0 {
			part = 1
		}
		minRest := lnwire.MilliSatoshi(len(weights) - i - 1)
		if part > remaining-minRest {
			part = remaining - minRest
		}

		result[i] = part
		remaining -= part
		sum -= weight
		total = remaining
	}

	return result
}

func equalAllocation(total lnwire.MilliSatoshi,
	parts int) []lnwire.MilliSatoshi {

	weights := make([]int64, parts)
	for i := range weights {
		weights[i] = 1
	}
	return weightedAllocation(total, weights)
}

func sameAllocation(a, b []lnwire.MilliSatoshi) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func appendAllocation(dst *[][]lnwire.MilliSatoshi,
	allocation []lnwire.MilliSatoshi,
	total lnwire.MilliSatoshi) {

	if len(allocation) == 0 {
		return
	}

	var sum lnwire.MilliSatoshi
	for _, amt := range allocation {
		if amt <= 0 {
			return
		}
		sum += amt
	}
	if sum != total {
		return
	}

	for _, old := range *dst {
		if sameAllocation(old, allocation) {
			return
		}
	}
	if len(*dst) < maxAllocationPlans {
		*dst = append(*dst, allocation)
	}
}

func allocationWithFirst(total, first lnwire.MilliSatoshi,
	parts int) []lnwire.MilliSatoshi {

	if parts < 2 || first <= 0 ||
		first > total-lnwire.MilliSatoshi(parts-1) {

		return nil
	}

	result := make([]lnwire.MilliSatoshi, 0, parts)
	result = append(result, first)
	result = append(
		result, equalAllocation(total-first, parts-1)...,
	)
	return result
}

func reverseAllocation(src []lnwire.MilliSatoshi) []lnwire.MilliSatoshi {
	dst := make([]lnwire.MilliSatoshi, len(src))
	for i := range src {
		dst[len(src)-1-i] = src[i]
	}
	return dst
}

func (r *candidateRouter) planningBoundaries(
	total lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	bounds := make([]lnwire.MilliSatoshi, 0)

	add := func(v lnwire.MilliSatoshi) {
		if v <= 0 || v >= total {
			return
		}
		for _, old := range bounds {
			diff := old - v
			if diff < 0 {
				diff = -diff
			}
			if diff <= v/20 {
				return
			}
		}
		bounds = append(bounds, v)
	}

	for key := range r.localUpper {
		cutoff := r.retryCutoff(key)
		if cutoff > r.reserved[key] {
			add((cutoff - r.reserved[key]) * 9 / 10)
		}
	}

	for key, edge := range r.edgeLookup {
		if edge.from != r.source {
			continue
		}

		limit := edge.capacity
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}
		if balance, ok := r.localBalances[edge.chanID];
			ok && balance < limit {

			limit = balance
		}
		if cutoff := r.retryCutoff(key);
			cutoff > 0 && cutoff < limit {

			limit = cutoff
		}
		if limit > r.reserved[key] {
			add((limit - r.reserved[key]) * 9 / 10)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 12 {
		bounds = bounds[:12]
	}
	return bounds
}

func (r *candidateRouter) allocationPatterns(
	total lnwire.MilliSatoshi, parts int) [][]lnwire.MilliSatoshi {

	var patterns [][]lnwire.MilliSatoshi
	appendAllocation(&patterns, equalAllocation(total, parts), total)

	var weightSets [][]int64
	switch parts {
	case 2:
		weightSets = [][]int64{
			{40, 60}, {60, 40},
			{33, 67}, {67, 33},
			{25, 75}, {75, 25},
			{15, 85}, {85, 15},
		}

	case 3:
		weightSets = [][]int64{
			{20, 30, 50}, {50, 30, 20},
			{15, 35, 50}, {50, 35, 15},
			{20, 40, 40}, {40, 40, 20},
		}

	case 4:
		weightSets = [][]int64{
			{15, 20, 25, 40},
			{40, 25, 20, 15},
			{10, 20, 30, 40},
			{40, 30, 20, 10},
		}

	default:
		if parts > 4 {
			ascending := make([]int64, parts)
			descending := make([]int64, parts)
			for i := 0; i < parts; i++ {
				ascending[i] = int64(i + 1)
				descending[i] = int64(parts - i)
			}
			weightSets = append(weightSets, ascending, descending)
		}
	}

	for _, weights := range weightSets {
		appendAllocation(
			&patterns, weightedAllocation(total, weights), total,
		)
	}

	if parts > 1 {
		for _, boundary := range r.planningBoundaries(total) {
			allocation := allocationWithFirst(
				total, boundary, parts,
			)
			if allocation == nil {
				continue
			}
			appendAllocation(&patterns, allocation, total)
			appendAllocation(
				&patterns, reverseAllocation(allocation), total,
			)
		}
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	var remainingAmount lnwire.MilliSatoshi

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	var totalScore float64

	for _, shard := range allocation {
		shardCap := remainingBudget

		if remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			shardCap = remainingBudget * shard / remainingAmount
			allowance := remainingBudget * 15 / 100
			if allowance > 100_000 {
				allowance = 100_000
			}
			if shardCap <= remainingBudget-allowance {
				shardCap += allowance
			} else {
				shardCap = remainingBudget
			}
		}

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat
	return plan, totalScore, true
}

func appendAmount(dst *[]lnwire.MilliSatoshi,
	amt, total lnwire.MilliSatoshi) {

	if amt <= 0 || amt >= total {
		return
	}
	for _, old := range *dst {
		diff := old - amt
		if diff < 0 {
			diff = -diff
		}
		if diff <= amt/50 {
			return
		}
	}
	*dst = append(*dst, amt)
}

func (r *candidateRouter) partialCandidates(
	total lnwire.MilliSatoshi, slots uint32) []lnwire.MilliSatoshi {

	var candidates []lnwire.MilliSatoshi

	for _, pair := range [][2]int64{
		{7, 8}, {3, 4}, {2, 3}, {1, 2},
		{2, 5}, {1, 3}, {1, 4}, {1, 6},
		{1, 8}, {1, 12}, {1, 16},
	} {
		appendAmount(
			&candidates,
			total*lnwire.MilliSatoshi(pair[0])/
				lnwire.MilliSatoshi(pair[1]),
			total,
		)
	}

	if slots > 1 {
		appendAmount(
			&candidates,
			(total+lnwire.MilliSatoshi(slots)-1)/
				lnwire.MilliSatoshi(slots),
			total,
		)
	}

	for _, boundary := range r.planningBoundaries(total) {
		appendAmount(&candidates, boundary, total)
	}

	sort.Slice(candidates, func(i, j int) bool {
		return candidates[i] > candidates[j]
	})
	return candidates
}

func (r *candidateRouter) makePartialPlan(total lnwire.MilliSatoshi,
	slots uint32, feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, error) {

	candidates := r.partialCandidates(total, slots)
	for _, shard := range candidates {
		cap := feeBudget
		if feeBudget != lnwire.MaxMilliSatoshi {
			cap = feeBudget * shard / total
			allowance := feeBudget * 15 / 100
			if allowance > 100_000 {
				allowance = 100_000
			}
			if cap <= feeBudget-allowance {
				cap += allowance
			} else {
				cap = feeBudget
			}
			if cap <= 0 {
				continue
			}
		}

		pr, err := r.findRoute(shard, r.reserved, cap)
		if err == nil {
			return []*plannedRoute{pr}, nil
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		if total < lnwire.MilliSatoshi(parts) {
			break
		}

		for _, allocation := range r.allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	return r.makePartialPlan(total, slots, feeBudget)
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.25

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if failIdx < 0 &&
		code == lnwire.CodeTemporaryChannelFailure &&
		len(meta.path) > 0 {

		failIdx = 0
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
		r.edgePenalty[meta.path[i].key] *= 0.85
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.recordLocalFailure(edge.key, meta.loads[failIdx])

			count := r.localFails[edge.key]
			r.edgePenalty[edge.key] +=
				850_000 + float64(count)*350_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.blocked[edge.key] = true
			r.edgePenalty[edge.key] += 10_000_000

		default:
			r.edgePenalty[edge.key] += 2_500_000
		}

		return nil
	}

	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 750_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskPriceMsat  = 420000.0
	maxNodeLabels  = 7
	minShardMsat   = lnwire.MilliSatoshi(1000)
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	// The inbound fee belongs to the receiving node and is charged when
	// that node forwards through its next outgoing channel.
	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) outboundFee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func forwardingFee(incoming, outgoing *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if outgoing == nil {
		return 0
	}

	outFee := outgoing.outboundFee(amt)
	inBase := int64(amt) + int64(outFee)
	inFee := incoming.inboundBase +
		inBase*incoming.inboundRate/1_000_000

	total := int64(outFee) + inFee
	if total <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(total)
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	okCount   uint32
	failCount uint32
}

var sharedBeliefs = struct {
	sync.RWMutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type localFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type activeRoute struct {
	rt  *route.Route
	fee lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	localFailures map[edgeKey]localFailure
	policyBad     map[edgeKey]bool

	active  []activeRoute
	planned []*route.Route

	committedFees lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		localFailures: make(map[edgeKey]localFailure),
		policyBad:     make(map[edgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				e := &candidateEdge{
					key: edgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   int64(ch.InboundFee.BaseFee),
					inboundRate:   int64(ch.InboundFee.FeeRate),
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], e,
				)
				r.edges[e.key] = e
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.055)
	highMode := 0.5 / (1 + math.Exp((x-0.94)/0.025))
	p := lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	p := bimodalPrior(load, e.capacity)

	sharedBeliefs.RLock()
	b, ok := sharedBeliefs.m[e.key]
	sharedBeliefs.RUnlock()
	if !ok {
		return p
	}

	if b.lowerOK > 0 && load <= b.lowerOK {
		conf := 1 - math.Exp(-float64(b.okCount)/2)
		p = p*(1-conf) + 0.995*conf
	}

	if b.upperFail > 0 {
		conf := 1 - math.Exp(-float64(b.failCount)/2)
		switch {
		case load >= b.upperFail:
			softCeiling := 0.012
			p = p*(1-conf) + softCeiling*conf

		case b.lowerOK > 0 && b.upperFail > b.lowerOK &&
			load > b.lowerOK:

			span := float64(b.upperFail - b.lowerOK)
			room := float64(b.upperFail-load) / span
			informed := 0.012 + 0.983*room
			p = p*(1-conf) + informed*conf
		}
	}

	if b.estimate > 0 {
		scale := float64(e.capacity) * 0.08
		if scale < 1 {
			scale = 1
		}
		estimateP := 1 / (1 + math.Exp(
			(float64(load)-float64(b.estimate))/scale,
		))
		conf := 1 - math.Exp(
			-float64(b.okCount+b.failCount)/4,
		)
		p = p*(1-0.45*conf) + estimateP*0.45*conf
	}

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func recordSuccess(key edgeKey, load lnwire.MilliSatoshi) {
	sharedBeliefs.Lock()
	b := sharedBeliefs.m[key]
	if load > b.lowerOK {
		b.lowerOK = load
	}
	if b.estimate < load {
		b.estimate = load
	}
	b.okCount++
	if b.upperFail > 0 && b.lowerOK >= b.upperFail {
		b.upperFail = 0
		b.failCount /= 2
	}
	sharedBeliefs.m[key] = b
	sharedBeliefs.Unlock()
}

func recordFailure(key edgeKey, load lnwire.MilliSatoshi) {
	sharedBeliefs.Lock()
	b := sharedBeliefs.m[key]
	if b.upperFail == 0 || load < b.upperFail {
		b.upperFail = load
	}
	if b.estimate == 0 || load < b.estimate {
		b.estimate = load
	}
	b.failCount++
	if b.lowerOK >= b.upperFail {
		b.lowerOK = 0
		b.okCount /= 2
	}
	sharedBeliefs.m[key] = b
	sharedBeliefs.Unlock()
}

func routeFee(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	if rt.TotalAmount <= delivered {
		return 0
	}
	return rt.TotalAmount - delivered
}

func routeDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeEdges(rt *route.Route) []edgeKey {
	keys := make([]edgeKey, 0, len(rt.Hops))
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		keys = append(keys, edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		})
		from = hop.PubKeyBytes
	}
	return keys
}

func routeAmounts(rt *route.Route) []lnwire.MilliSatoshi {
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	for i := range rt.Hops {
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
	}
	return amounts
}

func cloneReservations(src map[edgeKey]lnwire.MilliSatoshi) map[
	edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func addRouteReservations(res map[edgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	keys := routeEdges(rt)
	amounts := routeAmounts(rt)
	for i, key := range keys {
		res[key] += amounts[i]
	}
}

func (r *candidateRouter) reservations() map[
	edgeKey]lnwire.MilliSatoshi {

	res := make(map[edgeKey]lnwire.MilliSatoshi)
	for _, active := range r.active {
		addRouteReservations(res, active.rt)
	}
	return res
}

func (r *candidateRouter) budgetRemaining() (
	lnwire.MilliSatoshi, bool) {

	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi, false
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0, true
	}
	return r.spec.FeeLimitMsat - r.committedFees, true
}

type pathItem struct {
	node  route.Vertex
	need  lnwire.MilliSatoshi
	fees  lnwire.MilliSatoshi
	score float64
	out   *candidateEdge
	path  []*candidateEdge
	index int
}

type pathQueue []*pathItem

func (q pathQueue) Len() int { return len(q) }
func (q pathQueue) Less(i, j int) bool {
	if q[i].score == q[j].score {
		return q[i].need < q[j].need
	}
	return q[i].score < q[j].score
}
func (q pathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}
func (q *pathQueue) Push(x any) {
	item := x.(*pathItem)
	item.index = len(*q)
	*q = append(*q, item)
}
func (q *pathQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	*q = old[:n-1]
	return item
}

type nodeLabel struct {
	need  lnwire.MilliSatoshi
	fees  lnwire.MilliSatoshi
	score float64
}

func acceptLabel(labels map[route.Vertex][]nodeLabel,
	node route.Vertex, label nodeLabel) bool {

	current := labels[node]
	for _, old := range current {
		if old.need <= label.need &&
			old.fees <= label.fees &&
			old.score <= label.score {

			return false
		}
	}

	filtered := current[:0]
	for _, old := range current {
		if label.need <= old.need &&
			label.fees <= old.fees &&
			label.score <= old.score {

			continue
		}
		filtered = append(filtered, old)
	}
	filtered = append(filtered, label)

	if len(filtered) > maxNodeLabels {
		worst := 0
		for i := 1; i < len(filtered); i++ {
			if filtered[i].score > filtered[worst].score {
				worst = i
			}
		}
		if worst == len(filtered)-1 {
			labels[node] = filtered[:len(filtered)-1]
			return false
		}
		filtered[worst] = filtered[len(filtered)-1]
		filtered = filtered[:len(filtered)-1]
	}

	labels[node] = filtered
	return true
}

func pathContains(path []*candidateEdge, node route.Vertex) bool {
	for _, e := range path {
		if e.key.from == node || e.key.to == node {
			return true
		}
	}
	return false
}

func prependEdge(e *candidateEdge,
	path []*candidateEdge) []*candidateEdge {

	next := make([]*candidateEdge, len(path)+1)
	next[0] = e
	copy(next[1:], path)
	return next
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	load lnwire.MilliSatoshi,
	reserved lnwire.MilliSatoshi) float64 {

	if e.key.from == r.source {
		p := 0.985
		if reserved > 0 {
			p *= 0.92
		}
		return p
	}

	p := beliefProbability(e, load)
	if failure, ok := r.localFailures[e.key]; ok &&
		failure.upper > 0 {

		if load >= failure.upper {
			p *= math.Pow(0.25, float64(failure.count))
		} else if load*4 >= failure.upper*3 {
			p *= math.Pow(0.55, float64(failure.count))
		}
	}

	if reserved > 0 {
		// This is both a load adjustment and a corridor-reuse surcharge.
		p *= 0.42
	}
	if p < 0.0002 {
		return 0.0002
	}
	return p
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	maxFee lnwire.MilliSatoshi, feeBounded bool) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	pq := &pathQueue{}
	heap.Push(pq, &pathItem{
		node: r.spec.Target,
		need: amt,
	})

	labels := make(map[route.Vertex][]nodeLabel)
	labels[r.spec.Target] = []nodeLabel{{
		need: amt,
	}}

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*pathItem)
		if item.node == r.source {
			return r.buildRoute(amt, item.path)
		}

		for _, incoming := range r.incomingEdges[item.node] {
			if r.policyBad[incoming.key] ||
				pathContains(item.path, incoming.key.from) {

				continue
			}

			nodeFee := forwardingFee(
				incoming, item.out, item.need,
			)
			over := item.need + nodeFee
			if !incoming.usableHTLC(over) {
				continue
			}

			reserved := reservations[incoming.key]
			load := over + reserved
			if load > incoming.capacity {
				continue
			}

			if incoming.key.from == r.source {
				balance, ok := r.localBalances[
					incoming.key.chanID]
				if !ok || load > balance {
					continue
				}
			}

			fees := item.fees + nodeFee
			if feeBounded && fees > maxFee {
				continue
			}

			p := r.edgeProbability(incoming, load, reserved)
			score := item.score + float64(nodeFee) +
				riskPriceMsat*(-math.Log(p)) + 12000

			label := nodeLabel{
				need:  over,
				fees:  fees,
				score: score,
			}
			if !acceptLabel(labels, incoming.key.from, label) {
				continue
			}

			heap.Push(pq, &pathItem{
				node:  incoming.key.from,
				need:  over,
				fees:  fees,
				score: score,
				out:   incoming,
				path: prependEdge(
					incoming, item.path,
				),
			})
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fee := forwardingFee(
			path[i], path[i+1], amounts[i+1],
		)
		amounts[i] = amounts[i+1] + fee
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		forward := amt
		expiry := uint32(finalCltvDelta)
		if i+1 < n {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      e.key.to,
			ChannelID:        e.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	rt := &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	if !r.validateRoutePolicies(rt, path) {
		return nil, errors.New("constructed route violates policy")
	}
	return rt, nil
}

func (r *candidateRouter) validateRoutePolicies(rt *route.Route,
	path []*candidateEdge) bool {

	amounts := routeAmounts(rt)
	if len(amounts) != len(path) {
		return false
	}
	for i, e := range path {
		if !e.usableHTLC(amounts[i]) {
			return false
		}
	}
	return true
}

func proportionalBudget(total, shard,
	remaining lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if remaining <= 0 || shard >= remaining {
		return total
	}

	share := lnwire.MilliSatoshi(
		int64(total) * int64(shard) / int64(remaining),
	)
	// Give each shard a little flexibility for base fees while retaining
	// most of the budget for the rest of the planned set.
	slack := total / 20
	if share+slack < share || share+slack > total {
		return total
	}
	return share + slack
}

func (r *candidateRouter) routeAtAmount(
	amt, remaining lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	budget lnwire.MilliSatoshi, bounded bool) (*route.Route, error) {

	maxFee := budget
	if bounded {
		maxFee = proportionalBudget(budget, amt, remaining)
	}
	return r.findRoute(
		amt, reservations, maxFee, bounded,
	)
}

func (r *candidateRouter) largestShard(
	remaining lnwire.MilliSatoshi, slots uint32,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	budget lnwire.MilliSatoshi, bounded bool) (*route.Route, error) {

	if rt, err := r.findRoute(
		remaining, reservations, budget, bounded,
	); err == nil {
		return rt, nil
	}

	if slots == 0 {
		return nil, errors.New("no parts available")
	}

	average := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)
	if average < minShardMsat {
		average = minShardMsat
	}

	var base *route.Route
	probes := []lnwire.MilliSatoshi{
		average,
		average * 2,
		average * 3 / 2,
		average / 2,
		average / 3,
		average / 4,
	}

	for _, probe := range probes {
		if probe < minShardMsat {
			probe = minShardMsat
		}
		if probe > remaining {
			probe = remaining
		}
		rt, err := r.routeAtAmount(
			probe, remaining, reservations, budget, bounded,
		)
		if err == nil {
			if base == nil ||
				routeDelivered(rt) > routeDelivered(base) {

				base = rt
			}
		}
	}

	if base == nil {
		return nil, errors.New("no shard route found")
	}

	low := routeDelivered(base)
	high := remaining
	best := base

	// Public maxima and capacity make feasibility nearly monotonic. A
	// short binary search finds unequal corridor-sized shards without
	// spending wire attempts probing those boundaries.
	for i := 0; i < 8 && high-low > minShardMsat; i++ {
		mid := low + (high-low+1)/2
		rt, err := r.routeAtAmount(
			mid, remaining, reservations, budget, bounded,
		)
		if err != nil {
			high = mid - 1
			continue
		}
		best = rt
		low = mid
	}

	return best, nil
}

func (r *candidateRouter) makePlan(amt lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("maximum parts reached")
	}

	budget, bounded := r.budgetRemaining()
	if bounded && budget <= 0 {
		return nil, errors.New("fee budget exhausted")
	}

	reservations := cloneReservations(r.reservations())
	remaining := amt
	plan := make([]*route.Route, 0, parts)

	for slots := parts; slots > 0 && remaining > 0; slots-- {
		rt, err := r.largestShard(
			remaining, slots, reservations, budget, bounded,
		)
		if err != nil {
			break
		}

		delivered := routeDelivered(rt)
		if delivered <= 0 || delivered > remaining {
			break
		}

		fee := routeFee(rt)
		if bounded {
			if fee > budget {
				break
			}
			budget -= fee
		}

		plan = append(plan, rt)
		addRouteReservations(reservations, rt)
		remaining -= delivered
	}

	if len(plan) == 0 {
		return nil, errors.New("no route found")
	}
	return plan, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if len(r.planned) != 0 {
		rt := r.planned[0]
		if routeDelivered(rt) <= amt {
			r.planned = r.planned[1:]
			fee := routeFee(rt)
			r.active = append(r.active, activeRoute{
				rt:  rt,
				fee: fee,
			})
			r.committedFees += fee
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	parts := r.spec.MaxParts - inFlightHtlcs
	plan, err := r.makePlan(amt, parts)
	if err != nil {
		return nil, err
	}
	r.planned = plan

	rt := r.planned[0]
	r.planned = r.planned[1:]
	fee := routeFee(rt)
	r.active = append(r.active, activeRoute{
		rt:  rt,
		fee: fee,
	})
	r.committedFees += fee
	r.attempts++

	return rt, nil
}

func sameRoute(a, b *route.Route) bool {
	if a == b {
		return true
	}
	if a == nil || b == nil ||
		a.TotalAmount != b.TotalAmount ||
		len(a.Hops) != len(b.Hops) {

		return false
	}
	for i := range a.Hops {
		if a.Hops[i].ChannelID != b.Hops[i].ChannelID ||
			a.Hops[i].PubKeyBytes != b.Hops[i].PubKeyBytes ||
			a.Hops[i].AmtToForward !=
				b.Hops[i].AmtToForward {

			return false
		}
	}
	return true
}

func (r *candidateRouter) removeFailedRoute(rt *route.Route) {
	for i, active := range r.active {
		if !sameRoute(active.rt, rt) {
			continue
		}

		if r.committedFees >= active.fee {
			r.committedFees -= active.fee
		} else {
			r.committedFees = 0
		}
		copy(r.active[i:], r.active[i+1:])
		r.active = r.active[:len(r.active)-1]
		return
	}
}

func failureChannelIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) observedLoads(
	rt *route.Route) []lnwire.MilliSatoshi {

	keys := routeEdges(rt)
	amounts := routeAmounts(rt)
	reserved := r.reservations()
	loads := make([]lnwire.MilliSatoshi, len(keys))

	for i, key := range keys {
		loads[i] = reserved[key]
		if loads[i] < amounts[i] {
			loads[i] = amounts[i]
		}
	}
	return loads
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID
	if rt == nil {
		return nil
	}

	keys := routeEdges(rt)
	loads := r.observedLoads(rt)

	if result.Failure == nil {
		for i, key := range keys {
			recordSuccess(key, loads[i])
		}
		return nil
	}

	r.removeFailedRoute(rt)
	r.planned = nil

	failIdx := failureChannelIndex(
		rt, result.FailureSource,
	)
	if failIdx < 0 {
		// Dispatcher-side refusals, including fee-budget rejection, reveal
		// no liquidity information.
		return nil
	}

	// Every channel preceding the failing node successfully carried the
	// total load imposed by all of our currently held shards.
	passed := failIdx
	if passed > len(keys) {
		passed = len(keys)
	}
	for i := 0; i < passed; i++ {
		recordSuccess(keys[i], loads[i])
	}

	if failIdx >= len(keys) {
		return nil
	}

	code := result.Failure.Code()
	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		key := keys[failIdx]
		load := loads[failIdx]
		recordFailure(key, load)

		local := r.localFailures[key]
		if local.upper == 0 || load < local.upper {
			local.upper = load
		}
		local.count++
		r.localFailures[key] = local

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// These are deterministic policy failures. Avoid repeating the
		// same invalid directed edge while retaining liquidity evidence
		// learned from the hops that preceded it.
		r.policyBad[keys[failIdx]] = true
	}

	return nil
}

func (r *candidateRouter) String() string {
	return fmt.Sprintf(
		"bimodal-budget-router(source=%v,target=%v)",
		r.source, r.spec.Target,
	)
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxSearchHops  = 40
	maxRouterTries = 64
)

type edgeKey struct {
	scope    route.Vertex
	from     route.Vertex
	to       route.Vertex
	chanID   uint64
	capacity lnwire.MilliSatoshi
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	fee := int64(e.baseFeeMsat) +
		int64(amt)*int64(e.feeRatePPM)/1_000_000
	if fee < 0 {
		return 0
	}
	return lnwire.MilliSatoshi(fee)
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func forwardingFee(incoming, outgoing *candidateEdge,
	outAmt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outFee := int64(outgoing.fee(outAmt))
	inboundBase := int64(incoming.inboundBase)
	inboundRate := int64(incoming.inboundRate)

	inboundFee := inboundBase +
		(int64(outAmt)+outFee)*inboundRate/1_000_000

	total := outFee + inboundFee
	if total < 0 {
		total = 0
	}

	return lnwire.MilliSatoshi(total)
}

type attemptMeta struct {
	deliver      lnwire.MilliSatoshi
	edgeKeys     []edgeKey
	edgeAmounts  []lnwire.MilliSatoshi
	observedLoad []lnwire.MilliSatoshi
	fee          lnwire.MilliSatoshi
}

type plannedRoute struct {
	route *route.Route
	meta  *attemptMeta
	score float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs  map[edgeKey]liquidityBelief
	penalty  map[edgeKey]float64
	badEdges map[edgeKey]bool

	liveReserved map[edgeKey]lnwire.MilliSatoshi
	pending      map[*route.Route]*attemptMeta
	plan         []*plannedRoute

	committedFee   lnwire.MilliSatoshi
	outstandingFee lnwire.MilliSatoshi
	attempts       uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[edgeKey]liquidityBelief),
		penalty:        make(map[edgeKey]float64),
		badEdges:       make(map[edgeKey]bool),
		liveReserved:   make(map[edgeKey]lnwire.MilliSatoshi),
		pending:        make(map[*route.Route]*attemptMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				capacity := lnwire.NewMSatFromSatoshis(ch.Capacity)
				key := edgeKey{
					scope:    source,
					from:     ch.OtherNode,
					to:       node,
					chanID:   ch.ChannelID,
					capacity: capacity,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      capacity,
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				sharedBeliefs.Lock()
				belief, ok := sharedBeliefs.values[key]
				sharedBeliefs.Unlock()
				if ok {
					r.beliefs[key] = belief
				}

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.012:
		return 0.012
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-ratio/0.018)
	highMode := 0.5 / (1 + math.Exp((ratio-0.82)*18))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	if load <= 0 || load > edge.capacity {
		return 0.005
	}
	if edge.from == r.source {
		return 0.995
	}

	prior := bimodalPrior(load, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return prior
	}

	if belief.lowerOK > 0 && load <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && load >= belief.upperFail {
		return 0.012
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(load-belief.lowerOK) / width
		evidence := 0.995*(1-position) + 0.012*position
		confidence := math.Min(
			0.9,
			0.35+0.1*float64(belief.successes+belief.failures),
		)
		return clampProbability(
			confidence*evidence + (1-confidence)*prior,
		)
	}

	if belief.upperFail > 0 {
		ratio := float64(load) / float64(belief.upperFail)
		if ratio > 0.2 {
			prior *= math.Exp(-2.0 * (ratio - 0.2))
		}
		return clampProbability(prior)
	}

	if belief.lowerOK > 0 && load > belief.lowerOK {
		remaining := edge.capacity - belief.lowerOK
		if remaining <= 0 {
			return 0.012
		}
		position := float64(load-belief.lowerOK) / float64(remaining)
		evidence := 0.92 / (1 + math.Exp((position-0.72)*14))
		return clampProbability(0.7*evidence + 0.3*prior)
	}

	return prior
}

func applySuccess(b liquidityBelief,
	amt lnwire.MilliSatoshi) liquidityBelief {

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail > 0 && amt >= b.upperFail {
		b.upperFail = 0
	}
	b.successes++
	return b
}

func applyFailure(b liquidityBelief,
	amt lnwire.MilliSatoshi) liquidityBelief {

	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}
	if b.lowerOK >= amt {
		b.lowerOK = amt * 3 / 4
	}
	b.failures++
	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	r.beliefs[key] = applySuccess(r.beliefs[key], amt)

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = applySuccess(
		sharedBeliefs.values[key], amt,
	)
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	r.beliefs[key] = applyFailure(r.beliefs[key], amt)

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = applyFailure(
		sharedBeliefs.values[key], amt,
	)
	sharedBeliefs.Unlock()
}

type searchLabel struct {
	edge   *candidateEdge
	next   *searchLabel
	amount lnwire.MilliSatoshi
	score  float64
	hops   int
	index  int
}

type searchQueue []*searchLabel

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *searchQueue) Push(value any) {
	item := value.(*searchLabel)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *searchQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	old[last] = nil
	*q = old[:last]
	return item
}

func pathContains(label *searchLabel, vertex route.Vertex) bool {
	for current := label; current != nil; current = current.next {
		if current.edge.from == vertex || current.edge.to == vertex {
			return true
		}
	}
	return false
}

func copyReservations(src map[edgeKey]lnwire.MilliSatoshi) map[
	edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) riskValue(maxFee lnwire.MilliSatoshi,
	limited bool) float64 {

	if !limited {
		return 420_000
	}

	value := float64(maxFee) / 2
	if value < 25_000 {
		value = 25_000
	}
	if value > 420_000 {
		value = 420_000
	}
	return value
}

func (r *candidateRouter) edgeCost(edge *candidateEdge,
	load lnwire.MilliSatoshi, used map[edgeKey]int,
	riskValue float64) float64 {

	probability := r.edgeProbability(edge, load)
	cost := -math.Log(probability)*riskValue + r.penalty[edge.key]

	if count := used[edge.key]; count > 0 {
		cost += 360_000 * float64(count)
	}

	if edge.capacity > 0 {
		utilization := float64(load) / float64(edge.capacity)
		cost += utilization * utilization * 90_000
	}

	return cost
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	reserved map[edgeKey]lnwire.MilliSatoshi,
	used map[edgeKey]int, maxFee lnwire.MilliSatoshi,
	limited bool) (*plannedRoute, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid shard amount")
	}
	if r.source == r.spec.Target {
		rt := &route.Route{
			TotalTimeLock: finalCltvDelta,
			TotalAmount:   deliver,
			SourcePubKey:  r.source,
		}
		return &plannedRoute{
			route: rt,
			meta: &attemptMeta{
				deliver: deliver,
			},
		}, nil
	}

	riskValue := r.riskValue(maxFee, limited)
	queue := &searchQueue{}
	best := make(map[edgeKey]float64)

	for _, edge := range r.incomingEdges[r.spec.Target] {
		if r.badEdges[edge.key] || !edge.usable(deliver) {
			continue
		}

		load := deliver + reserved[edge.key]
		if load > edge.capacity {
			continue
		}
		if edge.from == r.source &&
			r.localBalances[edge.chanID] < load {

			continue
		}

		score := r.edgeCost(edge, load, used, riskValue)
		label := &searchLabel{
			edge:   edge,
			amount: deliver,
			score:  score,
			hops:   1,
		}
		best[edge.key] = score
		heap.Push(queue, label)
	}

	var result *searchLabel
	for queue.Len() != 0 {
		current := heap.Pop(queue).(*searchLabel)
		known, ok := best[current.edge.key]
		if ok && current.score > known+0.0001 {
			continue
		}

		if current.edge.from == r.source {
			fee := current.amount - deliver
			if !limited || fee <= maxFee {
				result = current
				break
			}
		}
		if current.hops >= maxSearchHops {
			continue
		}

		node := current.edge.from
		for _, incoming := range r.incomingEdges[node] {
			if r.badEdges[incoming.key] ||
				pathContains(current, incoming.from) {

				continue
			}

			nodeFee := forwardingFee(
				incoming, current.edge, current.amount,
			)
			amount := current.amount + nodeFee
			if !incoming.usable(amount) {
				continue
			}

			feeSoFar := amount - deliver
			if limited && feeSoFar > maxFee {
				continue
			}

			load := amount + reserved[incoming.key]
			if load > incoming.capacity {
				continue
			}
			if incoming.from == r.source &&
				r.localBalances[incoming.chanID] < load {

				continue
			}

			score := current.score + float64(nodeFee) +
				r.edgeCost(incoming, load, used, riskValue)

			old, exists := best[incoming.key]
			if exists && score >= old {
				continue
			}

			best[incoming.key] = score
			heap.Push(queue, &searchLabel{
				edge:   incoming,
				next:   current,
				amount: amount,
				score:  score,
				hops:   current.hops + 1,
			})
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(deliver, result, reserved)
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	label *searchLabel,
	reserved map[edgeKey]lnwire.MilliSatoshi) (*plannedRoute, error) {

	var (
		path    []*candidateEdge
		amounts []lnwire.MilliSatoshi
	)
	for current := label; current != nil; current = current.next {
		path = append(path, current.edge)
		amounts = append(amounts, current.amount)
	}

	if len(path) == 0 || path[len(path)-1].to != r.spec.Target {
		return nil, errors.New("broken route")
	}

	expiries := make([]uint32, len(path))
	expiries[len(path)-1] = finalCltvDelta
	for i := len(path) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	meta := &attemptMeta{
		deliver:      deliver,
		edgeKeys:     make([]edgeKey, len(path)),
		edgeAmounts:  make([]lnwire.MilliSatoshi, len(path)),
		observedLoad: make([]lnwire.MilliSatoshi, len(path)),
		fee:          amounts[0] - deliver,
	}

	for i, edge := range path {
		forward := deliver
		outgoingExpiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: outgoingExpiry,
		}
		meta.edgeKeys[i] = edge.key
		meta.edgeAmounts[i] = amounts[i]
		meta.observedLoad[i] = amounts[i] + reserved[edge.key]
	}

	rt := &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}

	return &plannedRoute{
		route: rt,
		meta:  meta,
		score: label.score,
	}, nil
}

func splitAmounts(total lnwire.MilliSatoshi, parts, mode int) (
	[]lnwire.MilliSatoshi, bool) {

	if parts <= 0 || total < lnwire.MilliSatoshi(parts) {
		return nil, false
	}

	weights := make([]int64, parts)
	var totalWeight int64
	for i := 0; i < parts; i++ {
		switch mode {
		case 1:
			weights[i] = int64(parts - i)
		case 2:
			value := int64(parts - i)
			weights[i] = value * value
		default:
			weights[i] = 1
		}
		totalWeight += weights[i]
	}

	totalValue := int64(total)
	base := totalValue / totalWeight
	remainder := totalValue % totalWeight
	amounts := make([]lnwire.MilliSatoshi, parts)

	var assigned int64
	for i, weight := range weights {
		value := base*weight + remainder*weight/totalWeight
		if value <= 0 {
			return nil, false
		}
		amounts[i] = lnwire.MilliSatoshi(value)
		assigned += value
	}
	amounts[0] += lnwire.MilliSatoshi(totalValue - assigned)

	return amounts, true
}

func (r *candidateRouter) remainingFeeBudget() (
	lnwire.MilliSatoshi, bool) {

	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return 0, false
	}

	spent := r.committedFee + r.outstandingFee
	if spent >= r.spec.FeeLimitMsat {
		return 0, true
	}

	return r.spec.FeeLimitMsat - spent, true
}

func (r *candidateRouter) planVariant(
	amounts []lnwire.MilliSatoshi,
	maxFee lnwire.MilliSatoshi, limited bool) (
	[]*plannedRoute, float64, bool) {

	reserved := copyReservations(r.liveReserved)
	used := make(map[edgeKey]int)
	for key, amount := range reserved {
		if amount > 0 {
			used[key] = 1
		}
	}

	remainingFee := maxFee
	plan := make([]*plannedRoute, 0, len(amounts))
	var totalScore float64

	for _, amount := range amounts {
		candidate, err := r.findRoute(
			amount, reserved, used, remainingFee, limited,
		)
		if err != nil {
			return nil, 0, false
		}

		if limited {
			if candidate.meta.fee > remainingFee {
				return nil, 0, false
			}
			remainingFee -= candidate.meta.fee
		}

		plan = append(plan, candidate)
		totalScore += candidate.score + 18_000

		for i, key := range candidate.meta.edgeKeys {
			reserved[key] += candidate.meta.edgeAmounts[i]
			used[key]++
		}
	}

	return plan, totalScore, true
}

func (r *candidateRouter) createPlan(total lnwire.MilliSatoshi,
	partsLeft uint32) error {

	if partsLeft == 0 {
		return errors.New("maximum parts already in flight")
	}

	maxParts := int(partsLeft)
	if maxParts > 32 {
		maxParts = 32
	}

	feeBudget, limited := r.remainingFeeBudget()
	var (
		bestPlan  []*plannedRoute
		bestScore = math.Inf(1)
	)

	for parts := 1; parts <= maxParts; parts++ {
		modes := 1
		if parts > 1 {
			modes = 3
		}

		for mode := 0; mode < modes; mode++ {
			amounts, ok := splitAmounts(total, parts, mode)
			if !ok {
				continue
			}

			plan, score, ok := r.planVariant(
				amounts, feeBudget, limited,
			)
			if !ok {
				continue
			}

			if score < bestScore {
				bestScore = score
				bestPlan = plan
			}
		}
	}

	if len(bestPlan) == 0 {
		return errors.New("no feasible route set")
	}

	r.plan = bestPlan
	return nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount already satisfied")
	}
	if r.attempts >= maxRouterTries {
		return nil, errors.New("routing attempt limit reached")
	}

	if len(r.plan) > 0 {
		next := r.plan[0]
		remainingFee, limited := r.remainingFeeBudget()
		if next.meta.deliver > amt ||
			(limited && next.meta.fee > remainingFee) {

			r.plan = nil
		}
	}

	if len(r.plan) == 0 {
		if inFlightHtlcs >= r.spec.MaxParts {
			return nil, errors.New("maximum parts already in flight")
		}

		partsLeft := r.spec.MaxParts - inFlightHtlcs
		if err := r.createPlan(amt, partsLeft); err != nil {
			return nil, err
		}
	}

	next := r.plan[0]
	r.plan = r.plan[1:]

	for i, key := range next.meta.edgeKeys {
		r.liveReserved[key] += next.meta.edgeAmounts[i]
	}
	r.pending[next.route] = next.meta
	r.outstandingFee += next.meta.fee
	r.attempts++

	return next.route, nil
}

func (r *candidateRouter) release(meta *attemptMeta) {
	for i, key := range meta.edgeKeys {
		amount := meta.edgeAmounts[i]
		if r.liveReserved[key] <= amount {
			delete(r.liveReserved, key)
		} else {
			r.liveReserved[key] -= amount
		}
	}
}

func failureIndex(rt *route.Route, source route.Vertex) int {
	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	meta := r.pending[rt]
	delete(r.pending, rt)

	if meta != nil {
		if r.outstandingFee <= meta.fee {
			r.outstandingFee = 0
		} else {
			r.outstandingFee -= meta.fee
		}
	}

	if result.Failure == nil {
		if meta == nil {
			return nil
		}

		r.committedFee += meta.fee
		for i, key := range meta.edgeKeys {
			r.learnSuccess(key, meta.observedLoad[i])
			r.penalty[key] *= 0.35
		}
		return nil
	}

	r.plan = nil
	if meta != nil {
		r.release(meta)
	}

	failIdx := failureIndex(rt, result.FailureSource)
	code := result.Failure.Code()

	if meta == nil {
		return nil
	}

	if failIdx > len(meta.edgeKeys) {
		failIdx = -1
	}

	if failIdx >= 0 {
		for i := 0; i < failIdx && i < len(meta.edgeKeys); i++ {
			r.learnSuccess(
				meta.edgeKeys[i], meta.observedLoad[i],
			)
		}
	}

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		if failIdx >= 0 && failIdx < len(meta.edgeKeys) {
			key := meta.edgeKeys[failIdx]
			r.learnFailure(key, meta.observedLoad[failIdx])
			r.penalty[key] += 140_000
		} else {
			for _, key := range meta.edgeKeys {
				r.penalty[key] += 30_000
			}
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		if failIdx >= 0 && failIdx < len(meta.edgeKeys) {
			key := meta.edgeKeys[failIdx]
			r.badEdges[key] = true
			r.penalty[key] += 1_000_000
		}

	default:
		if failIdx >= 0 && failIdx < len(meta.edgeKeys) {
			r.penalty[meta.edgeKeys[failIdx]] += 100_000
		} else {
			for _, key := range meta.edgeKeys {
				r.penalty[key] += 20_000
			}
		}
	}

	return nil
}

var _ routing.SimRouter = (*candidateRouter)(nil)

func (r *candidateRouter) String() string {
	return fmt.Sprintf(
		"candidate-router(source=%v,target=%v,attempts=%d)",
		r.source, r.spec.Target, r.attempts,
	)
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta       = uint32(40)
	baseRiskPriceMsat    = float64(420_000)
	minRiskPriceMsat     = float64(20_000)
	hopCostMsat          = float64(6_000)
	reusedEdgeCostMsat   = float64(1_800_000)
	failedLoadCostMsat   = float64(6_000_000)
	maxSearchHops        = 60
	maxLabelsPerNode     = 10
	reservationLifetime  = 45 * time.Second
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type transientReservation struct {
	amount  lnwire.MilliSatoshi
	updated time.Time
}

var sharedReservations = struct {
	sync.Mutex
	nextOwner uint64
	byEdge    map[edgeKey]map[uint64]transientReservation
}{
	byEdge: make(map[edgeKey]map[uint64]transientReservation),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))

	// The inbound fee is charged on the amount forwarded plus the
	// forwarding node's outbound fee.
	basis := int64(amt) + outbound
	inbound := int64(in.inboundBase) +
		basis*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
	signature uint64
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec
	owner  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved        map[edgeKey]lnwire.MilliSatoshi
	edgePenalty     map[edgeKey]float64
	failedAt        map[edgeKey]lnwire.MilliSatoshi
	failureHits     map[edgeKey]int
	pathPenalty     map[uint64]float64
	issued          map[*route.Route]*routeMeta
	plan            []*plannedRoute
	committedFees   lnwire.MilliSatoshi
	successfulParts uint32
	numFailures     int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	sharedReservations.Lock()
	sharedReservations.nextOwner++
	owner := sharedReservations.nextOwner
	sharedReservations.Unlock()

	r := &candidateRouter{
		view:          view,
		source:        source,
		spec:          spec,
		owner:         owner,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeLookup:    make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[edgeKey]float64),
		failedAt:      make(map[edgeKey]lnwire.MilliSatoshi),
		failureHits:   make(map[edgeKey]int),
		pathPenalty:   make(map[uint64]float64),
		issued:        make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}
	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

func addAmounts(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		old := dst[edge.key]
		if meta.amounts[i] > lnwire.MaxMilliSatoshi-old {
			dst[edge.key] = lnwire.MaxMilliSatoshi
		} else {
			dst[edge.key] = old + meta.amounts[i]
		}
	}
}

func (r *candidateRouter) ownReservations() map[edgeKey]lnwire.MilliSatoshi {
	result := make(map[edgeKey]lnwire.MilliSatoshi, len(r.reserved))
	for key, amount := range r.reserved {
		result[key] = amount
	}
	for _, meta := range r.issued {
		addAmounts(result, meta)
	}
	return result
}

func (r *candidateRouter) syncSharedReservations(now time.Time) {
	own := r.ownReservations()

	sharedReservations.Lock()
	defer sharedReservations.Unlock()

	for key, owners := range sharedReservations.byEdge {
		entry, exists := owners[r.owner]
		amount, wanted := own[key]

		if wanted && amount > 0 {
			owners[r.owner] = transientReservation{
				amount:  amount,
				updated: now,
			}
		} else if exists {
			delete(owners, r.owner)
		}

		for owner, reservation := range owners {
			if now.Before(reservation.updated) ||
				now.Sub(reservation.updated) > reservationLifetime {

				delete(owners, owner)
			}
		}
		if len(owners) == 0 {
			delete(sharedReservations.byEdge, key)
		}
	}

	for key, amount := range own {
		if amount <= 0 {
			continue
		}
		owners := sharedReservations.byEdge[key]
		if owners == nil {
			owners = make(map[uint64]transientReservation)
			sharedReservations.byEdge[key] = owners
		}
		owners[r.owner] = transientReservation{
			amount:  amount,
			updated: now,
		}
	}
}

func (r *candidateRouter) externalReservations(
	now time.Time) map[edgeKey]lnwire.MilliSatoshi {

	result := make(map[edgeKey]lnwire.MilliSatoshi)

	sharedReservations.Lock()
	defer sharedReservations.Unlock()

	for key, owners := range sharedReservations.byEdge {
		for owner, reservation := range owners {
			if now.Before(reservation.updated) ||
				now.Sub(reservation.updated) > reservationLifetime {

				delete(owners, owner)
				continue
			}
			if owner == r.owner {
				continue
			}

			old := result[key]
			if reservation.amount > lnwire.MaxMilliSatoshi-old {
				result[key] = lnwire.MaxMilliSatoshi
			} else {
				result[key] = old + reservation.amount
			}
		}
		if len(owners) == 0 {
			delete(sharedReservations.byEdge, key)
		}
	}

	return result
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amount := range src {
		dst[key] = amount
	}
	return dst
}

func (r *candidateRouter) baseReservations(
	now time.Time) map[edgeKey]lnwire.MilliSatoshi {

	result := r.ownReservations()
	for key, amount := range r.externalReservations(now) {
		old := result[key]
		if amount > lnwire.MaxMilliSatoshi-old {
			result[key] = lnwire.MaxMilliSatoshi
		} else {
			result[key] = old + amount
		}
	}
	return result
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func mixHash(hash, value uint64) uint64 {
	hash ^= value
	hash *= 1099511628211
	return hash
}

func statePathHash(first *candidateEdge, remainder *searchState) uint64 {
	hash := uint64(1469598103934665603)
	hash = mixHash(hash, first.chanID)

	for cur := remainder; cur != nil && cur.nextEdge != nil;
		cur = cur.child {

		hash = mixHash(hash, cur.nextEdge.chanID)
	}
	return hash
}

func pathHash(path []*candidateEdge) uint64 {
	hash := uint64(1469598103934665603)
	for _, edge := range path {
		hash = mixHash(hash, edge.chanID)
	}
	return hash
}

func riskPrice(feeAllowance lnwire.MilliSatoshi) float64 {
	if feeAllowance == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeAllowance) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}
	return price
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap, riskAllowance lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	now := r.view.Now()
	price := riskPrice(riskAllowance)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)
			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}
				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			if reserved > lnwire.MaxMilliSatoshi-over {
				continue
			}
			totalLoad := over + reserved
			if totalLoad > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.985
			}

			score := cur.score + float64(nodeCharge) +
				price*(-math.Log(p)) + hopCostMsat +
				r.edgePenalty[edge.key]

			if reserved > 0 {
				score += reusedEdgeCostMsat
			}

			if ceiling := r.failedAt[edge.key]; ceiling > 0 &&
				totalLoad >= ceiling {

				score += failedLoadCostMsat +
					float64(r.failureHits[edge.key])*400_000
			}

			if edge.from == r.source {
				signature := statePathHash(edge, cur)
				score += r.pathPenalty[signature]
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		reserved := reservations[edge.key]
		if reserved > lnwire.MaxMilliSatoshi-amounts[i] {
			return nil, errors.New("route load overflow")
		}
		loads[i] = amounts[i] + reserved
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
		signature: pathHash(path),
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)
	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}
		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			float64(total) * float64(weight) / float64(sum),
		)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - lnwire.MilliSatoshi(len(weights)-i-1)
		}
		if part <= 0 {
			return nil
		}

		result[i] = part
		remaining -= part
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 10
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	if parts > 1 {
		ascending := make([]int64, parts)
		descending := make([]int64, parts)
		for i := 0; i < parts; i++ {
			ascending[i] = int64(i + 1)
			descending[i] = int64(parts - i)
		}
		patterns = append(
			patterns,
			weightedAllocation(total, ascending),
			weightedAllocation(total, descending),
		)
	}

	hotCount := parts
	if hotCount > 6 {
		hotCount = 3
	}

	for ratio := int64(2); ratio <= 3; ratio++ {
		for j := 0; j < hotCount; j++ {
			hot := j
			if parts > 6 {
				switch j {
				case 0:
					hot = 0
				case 1:
					hot = parts / 2
				default:
					hot = parts - 1
				}
			}

			weights := make([]int64, parts)
			for i := range weights {
				weights[i] = 10
			}
			weights[hot] = 10 * ratio
			patterns = append(
				patterns,
				weightedAllocation(total, weights),
			)
		}
	}

	return patterns
}

func ratioAmount(value, part,
	total lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if total <= 0 || value <= 0 || part <= 0 {
		return 0
	}
	if part >= total {
		return value
	}

	result := lnwire.MilliSatoshi(
		float64(value) * float64(part) / float64(total),
	)
	if result < 0 {
		return 0
	}
	if result > value {
		return value
	}
	return result
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		old := dst[edge.key]
		if meta.amounts[i] > lnwire.MaxMilliSatoshi-old {
			dst[edge.key] = lnwire.MaxMilliSatoshi
		} else {
			dst[edge.key] = old + meta.amounts[i]
		}
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	base map[edgeKey]lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(base)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)
	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		riskAllowance := lnwire.MaxMilliSatoshi
		if remainingBudget != lnwire.MaxMilliSatoshi {
			riskAllowance = ratioAmount(
				remainingBudget, shard, remainingAmount,
			)
		}

		pr, err := r.findRoute(
			shard, reservations, remainingBudget, riskAllowance,
		)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * 30_000
	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	now := r.view.Now()
	base := r.baseReservations(now)
	feeBudget := r.remainingFeeBudget()

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			if len(allocation) != parts {
				continue
			}
			plan, score, ok := r.tryAllocation(
				allocation, base, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	// If a complete static plan cannot be formed, send a shard that is
	// still large enough for the remaining part count to finish. Starting
	// at the minimum viable size also gives failed corridors a genuine
	// lower-amount retry instead of repeating the failed load.
	if slots > 1 {
		for k := uint32(1); k < slots; k++ {
			shard := lnwire.MilliSatoshi(
				math.Ceil(
					float64(total) * float64(k) /
						float64(slots),
				),
			)
			if shard <= 0 || shard >= total {
				continue
			}

			riskAllowance := feeBudget
			if feeBudget != lnwire.MaxMilliSatoshi {
				riskAllowance = ratioAmount(
					feeBudget, shard, total,
				)
			}

			pr, err := r.findRoute(
				shard, base, feeBudget, riskAllowance,
			)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	now := r.view.Now()
	r.syncSharedReservations(now)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	used := r.successfulParts
	if inFlightHtlcs > used {
		used = inFlightHtlcs
	}
	if used >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - used

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.syncSharedReservations(now)

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey
	base := r.baseReservations(r.view.Now())

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		load := amount
		if base[key] <= lnwire.MaxMilliSatoshi-amount {
			load += base[key]
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, load)
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
		signature: pathHash(path),
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		r.syncSharedReservations(r.view.Now())
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)

			old := r.reserved[edge.key]
			if meta.amounts[i] > lnwire.MaxMilliSatoshi-old {
				r.reserved[edge.key] = lnwire.MaxMilliSatoshi
			} else {
				r.reserved[edge.key] = old + meta.amounts[i]
			}

			r.edgePenalty[edge.key] *= 0.25
			if ceiling := r.failedAt[edge.key]; ceiling > 0 &&
				meta.loads[i] >= ceiling {

				delete(r.failedAt, edge.key)
				delete(r.failureHits, edge.key)
			}
		}

		r.pathPenalty[meta.signature] *= 0.2
		r.committedFees += meta.fee
		r.successfulParts++
		r.syncSharedReservations(now)
		return nil
	}

	r.numFailures++
	r.plan = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}
	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
	}

	code := result.Failure.Code()

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			load := meta.loads[failIdx]
			updateBelief(edge.key, load, false, now)

			old := r.failedAt[edge.key]
			if old == 0 || load < old {
				r.failedAt[edge.key] = load
			}
			r.failureHits[edge.key]++
			r.edgePenalty[edge.key] += 50_000
			r.pathPenalty[meta.signature] += 250_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.edgePenalty[edge.key] += 8_000_000
			r.pathPenalty[meta.signature] += 4_000_000

		default:
			r.edgePenalty[edge.key] += 1_500_000
			r.pathPenalty[meta.signature] += 1_500_000
		}
	} else {
		// Unknown-source failures must diversify the whole route. They do
		// not establish a liquidity bound on any particular channel.
		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			r.pathPenalty[meta.signature] += 3_000_000
			for _, edge := range meta.path {
				r.edgePenalty[edge.key] += 300_000
			}

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.pathPenalty[meta.signature] += 6_000_000
			for _, edge := range meta.path {
				r.edgePenalty[edge.key] += 750_000
			}

		default:
			r.pathPenalty[meta.signature] += 2_000_000
			for _, edge := range meta.path {
				r.edgePenalty[edge.key] += 200_000
			}
		}
	}

	r.syncSharedReservations(now)
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta       = uint32(40)
	baseRiskPriceMsat    = float64(420_000)
	minRiskPriceMsat     = float64(25_000)
	hopCostMsat          = float64(8_000)
	reusedEdgeCostMsat   = float64(700_000)
	partCostMsat         = float64(35_000)
	maxSearchHops        = 60
	maxLabelsPerNode     = 8
	maxFailedAttempts    = uint32(24)
	maxIssuedAttempts    = uint32(32)
	maxDuplicateReplans  = 5
	minAdaptiveShardMsat = lnwire.MilliSatoshi(1_000)
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := out.fee(amt)
	if outbound > lnwire.MaxMilliSatoshi-amt {
		return lnwire.MaxMilliSatoshi
	}

	// The inbound rate applies to the amount arriving at the forwarding
	// node: its outgoing amount plus its outbound forwarding fee.
	inboundBasis := amt + outbound
	inbound := int64(in.inboundBase) +
		int64(inboundBasis)*int64(in.inboundRate)/1_000_000

	total := int64(outbound) + inbound
	if total <= 0 {
		return 0
	}
	if total > int64(lnwire.MaxMilliSatoshi) {
		return lnwire.MaxMilliSatoshi
	}
	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved        map[edgeKey]lnwire.MilliSatoshi
	edgePenalty     map[edgeKey]float64
	issued          map[*route.Route]*routeMeta
	attempted       map[uint64]uint32
	plan            []*plannedRoute
	committedFees   lnwire.MilliSatoshi
	budgetGuard     lnwire.MilliSatoshi
	retryCeiling    lnwire.MilliSatoshi
	successfulParts uint32
	failedAttempts  uint32
	issuedAttempts  uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:          view,
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeLookup:    make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[edgeKey]float64),
		issued:        make(map[*route.Route]*routeMeta),
		attempted:     make(map[uint64]uint32),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}
	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
		if b.conf < 0.05 {
			b = liquidityBelief{}
		}
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int           { return len(q) }
func (q searchQueue) Less(i, j int) bool { return q[i].score < q[j].score }
func (q searchQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i] }

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}
		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}
		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}
		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees + r.budgetGuard
	if spent >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}
	return price
}

func cloneReservations(src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {
	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 && r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)
			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}
				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			totalLoad := over + reservations[edge.key]
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.985
			}

			score := cur.score + float64(nodeCharge) +
				price*(-math.Log(p)) + hopCostMsat +
				r.edgePenalty[edge.key]

			if reservations[edge.key] > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.45
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}
	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)
	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}
		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	whole := total / lnwire.MilliSatoshi(sum)
	remainder := total % lnwire.MilliSatoshi(sum)

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := whole*lnwire.MilliSatoshi(weight) +
			remainder*lnwire.MilliSatoshi(weight)/
				lnwire.MilliSatoshi(sum)
		if part <= 0 {
			part = 1
		}
		result[i] = part
		remaining -= part
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int, wide bool) [][]lnwire.MilliSatoshi {

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}
	if !wide {
		return patterns
	}

	var variants [][]int64
	switch parts {
	case 2:
		variants = [][]int64{{35, 65}, {65, 35}}
	case 3:
		variants = [][]int64{
			{20, 30, 50}, {50, 30, 20},
		}
	case 4:
		variants = [][]int64{
			{15, 20, 25, 40}, {40, 25, 20, 15},
		}
	default:
		if parts > 4 && parts <= 8 {
			up := make([]int64, parts)
			down := make([]int64, parts)
			for i := 0; i < parts; i++ {
				up[i] = int64(i + 1)
				down[i] = int64(parts - i)
			}
			variants = [][]int64{up, down}
		}
	}

	for _, weights := range variants {
		patterns = append(
			patterns, weightedAllocation(total, weights),
		)
	}
	return patterns
}

func ceilingAllocation(total, ceiling lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if ceiling <= 0 || ceiling >= total || slots < 2 {
		return nil
	}

	parts := (total + ceiling - 1) / ceiling
	if parts < 2 || parts > lnwire.MilliSatoshi(slots) {
		return nil
	}

	weights := make([]int64, int(parts))
	for i := range weights {
		weights[i] = 1
	}
	return weightedAllocation(total, weights)
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}

		pr, err := r.findRoute(shard, reservations, remainingBudget)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
	}

	totalScore += float64(len(plan)-1) * partCostMsat
	return plan, totalScore, true
}

func (r *candidateRouter) largestRoutable(
	limit lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) (*plannedRoute, error) {

	if limit < minAdaptiveShardMsat {
		return nil, errors.New("amount below adaptive minimum")
	}

	first, err := r.findRoute(limit, reservations, feeBudget)
	if err == nil {
		return first, nil
	}

	bad := limit
	probe := limit
	var best *plannedRoute
	var good lnwire.MilliSatoshi

	for i := 0; i < 18; i++ {
		next := probe * 3 / 4
		if next >= probe {
			next = probe - 1
		}
		if next < minAdaptiveShardMsat {
			next = minAdaptiveShardMsat
		}

		pr, findErr := r.findRoute(next, reservations, feeBudget)
		if findErr == nil {
			best = pr
			good = next
			break
		}

		bad = next
		probe = next
		if next == minAdaptiveShardMsat {
			break
		}
	}

	if best == nil {
		return nil, errors.New("no adaptive shard found")
	}

	// Route feasibility is nearly monotone above the public HTLC floors.
	// Refine the largest feasible shard within the successful bracket.
	for i := 0; i < 8 && bad-good > 1; i++ {
		mid := good + (bad-good)/2
		pr, findErr := r.findRoute(mid, reservations, feeBudget)
		if findErr == nil {
			best = pr
			good = mid
		} else {
			bad = mid
		}
	}

	return best, nil
}

func (r *candidateRouter) greedyPlan(total lnwire.MilliSatoshi,
	slots uint32, feeBudget lnwire.MilliSatoshi) ([]*plannedRoute,
	float64, bool) {

	reservations := cloneReservations(r.reserved)
	remaining := total
	remainingBudget := feeBudget
	plan := make([]*plannedRoute, 0, slots)
	totalScore := float64(0)

	for left := slots; left > 0 && remaining > 0; left-- {
		pr, err := r.largestRoutable(
			remaining, reservations, remainingBudget,
		)
		if err != nil {
			return nil, 0, false
		}

		if pr.meta.delivered <= 0 ||
			pr.meta.delivered > remaining {

			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remaining -= pr.meta.delivered
	}

	if remaining != 0 {
		return nil, 0, false
	}

	totalScore += float64(len(plan)-1) * partCostMsat
	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	var best []*plannedRoute
	bestScore := math.Inf(1)
	wide := r.failedAttempts < 3

	maxEnumerated := int(slots)
	if maxEnumerated > 8 {
		maxEnumerated = 8
	}

	for parts := 1; parts <= maxEnumerated; parts++ {
		for _, allocation := range allocationPatterns(
			total, parts, wide,
		) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if int(slots) > maxEnumerated {
		allocation := allocationPatterns(
			total, int(slots), false,
		)[0]
		plan, score, ok := r.tryAllocation(allocation, feeBudget)
		if ok && score < bestScore {
			best = plan
			bestScore = score
		}
	}

	if allocation := ceilingAllocation(
		total, r.retryCeiling, slots,
	); allocation != nil {

		plan, score, ok := r.tryAllocation(allocation, feeBudget)
		if ok && score < bestScore {
			best = plan
			bestScore = score
		}
	}

	if len(best) != 0 {
		return best, nil
	}

	// This fallback derives unequal shards from the actual route ceilings
	// exposed by gossip instead of relying only on fixed ratios.
	if plan, _, ok := r.greedyPlan(total, slots, feeBudget); ok {
		return plan, nil
	}

	// If a complete set cannot be committed, send one bounded shard so
	// feedback can still make progress without an unbounded halving loop.
	if slots > 1 {
		shard := (total + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)
		if r.retryCeiling > 0 && shard > r.retryCeiling {
			shard = r.retryCeiling
		}

		for i := 0; i < 8 && shard >= minAdaptiveShardMsat; i++ {
			cap := feeBudget
			if feeBudget != lnwire.MaxMilliSatoshi {
				cap = feeBudget * shard / total
				if cap == 0 {
					break
				}
			}

			pr, err := r.findRoute(shard, r.reserved, cap)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}
			shard = shard * 2 / 3
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func routeFingerprint(meta *routeMeta) uint64 {
	h := uint64(1469598103934665603)
	h ^= uint64(meta.delivered)
	h *= 1099511628211
	for _, edge := range meta.path {
		h ^= edge.chanID
		h *= 1099511628211
		h ^= uint64(edge.from[0])<<8 | uint64(edge.to[0])
		h *= 1099511628211
	}
	return h
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.failedAttempts >= maxFailedAttempts ||
		r.issuedAttempts >= maxIssuedAttempts {

		return nil, errors.New("attempt limit reached")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	used := r.successfulParts
	if inFlightHtlcs > used {
		used = inFlightHtlcs
	}
	if used >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - used

	for replan := 0; replan < maxDuplicateReplans; replan++ {
		if len(r.plan) != 0 && queuedAmount(r.plan) != amt {
			r.plan = nil
		}

		if len(r.plan) == 0 {
			plan, err := r.makePlan(amt, slots)
			if err != nil {
				return nil, err
			}
			r.plan = plan
		}

		next := r.plan[0]
		fingerprint := routeFingerprint(next.meta)
		if r.attempted[fingerprint] >= 2 {
			for _, edge := range next.meta.path {
				r.edgePenalty[edge.key] += 1_500_000
			}
			r.plan = nil
			continue
		}

		r.plan = r.plan[1:]
		r.attempted[fingerprint]++
		r.issuedAttempts++
		r.issued[next.rt] = next.meta
		return next.rt, nil
	}

	return nil, errors.New("no untried route found")
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.35
		}

		r.committedFees += meta.fee
		r.successfulParts++
		return nil
	}

	r.failedAttempts++
	r.plan = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}
	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
		r.edgePenalty[meta.path[i].key] *= 0.75
	}

	code := result.Failure.Code()
	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.edgePenalty[edge.key] += 900_000

			lower := meta.delivered * 2 / 3
			if lower < minAdaptiveShardMsat {
				lower = minAdaptiveShardMsat
			}
			if r.retryCeiling == 0 || lower < r.retryCeiling {
				r.retryCeiling = lower
			}

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.edgePenalty[edge.key] += 8_000_000

		default:
			r.edgePenalty[edge.key] += 2_000_000
		}
	} else {
		if r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
			guard := meta.fee / 20
			if guard < 1_000 {
				guard = 1_000
			}
			r.budgetGuard += guard
		}
		for _, edge := range meta.path {
			r.edgePenalty[edge.key] += 150_000
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta       = uint32(40)
	baseRiskPriceMsat    = float64(420_000)
	minRiskPriceMsat     = float64(25_000)
	hopCostMsat          = float64(4_000)
	reusedEdgeCostMsat   = float64(800_000)
	additionalPartCost   = float64(90_000)
	maxSearchHops        = 64
	maxLabelsPerNode     = 14
	maxLiquidityPenalty  = float64(8_000_000)
	maxPolicyPenalty     = float64(20_000_000)
	beliefHalfLifeSeconds = float64(1800)
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inbound := int64(in.inboundBase) +
		int64(amt)*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type edgeFailureCost struct {
	cost      float64
	failedAmt lnwire.MilliSatoshi
	updated   time.Time
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved          map[edgeKey]lnwire.MilliSatoshi
	liquidityPenalty  map[edgeKey]edgeFailureCost
	policyPenalty     map[edgeKey]float64
	issued            map[*route.Route]*routeMeta
	plan              []*plannedRoute
	committedFees     lnwire.MilliSatoshi
	budgetGuard       lnwire.MilliSatoshi
	successfulParts   uint32
	unknownFailures   uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:             view,
		source:           source,
		spec:             spec,
		incomingEdges:    make(map[route.Vertex][]*candidateEdge),
		edgeLookup:       make(map[edgeKey]*candidateEdge),
		localBalances:    localBalances,
		reserved:         make(map[edgeKey]lnwire.MilliSatoshi),
		liquidityPenalty: make(map[edgeKey]edgeFailureCost),
		policyPenalty:    make(map[edgeKey]float64),
		issued:           make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated).Seconds()
	if age <= 0 {
		return b.conf
	}
	return b.conf * math.Exp(-age/beliefHalfLifeSeconds)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int           { return len(q) }
func (q searchQueue) Less(i, j int) bool { return q[i].score < q[j].score }
func (q searchQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i] }

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		cheapest := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[cheapest].fee {
				cheapest = i
			}
		}

		worst := -1
		for i := range kept {
			if i == cheapest {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees + r.budgetGuard
	if spent >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}
	return price
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) edgeFailurePenalty(key edgeKey,
	load lnwire.MilliSatoshi, now time.Time) float64 {

	state, ok := r.liquidityPenalty[key]
	if !ok || state.cost <= 0 {
		return 0
	}

	cost := state.cost
	if !state.updated.IsZero() && !now.Before(state.updated) {
		cost *= math.Exp(-now.Sub(state.updated).Seconds() / 900)
	}

	if state.failedAmt > 0 && load < state.failedAmt {
		ratio := float64(load) / float64(state.failedAmt)
		cost *= ratio * ratio * ratio
	}

	return cost
}

func (r *candidateRouter) recordLiquidityFailure(key edgeKey,
	load lnwire.MilliSatoshi, now time.Time, strength float64) {

	state := r.liquidityPenalty[key]
	if !state.updated.IsZero() && !now.Before(state.updated) {
		state.cost *= math.Exp(-now.Sub(state.updated).Seconds() / 900)
	}

	state.cost = state.cost*0.55 + strength
	if state.cost > maxLiquidityPenalty {
		state.cost = maxLiquidityPenalty
	}
	if load > 0 {
		state.failedAmt = load
	}
	state.updated = now
	r.liquidityPenalty[key] = state
}

func (r *candidateRouter) recordEdgeSuccess(key edgeKey,
	load lnwire.MilliSatoshi, now time.Time) {

	state, ok := r.liquidityPenalty[key]
	if !ok {
		return
	}

	state.cost *= 0.18
	if state.failedAmt != 0 && load >= state.failedAmt {
		state.failedAmt = 0
	}
	state.updated = now

	if state.cost < 1 {
		delete(r.liquidityPenalty, key)
		return
	}
	r.liquidityPenalty[key] = state
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)
			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}
				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			totalLoad := over + reserved
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.985
			}

			score := cur.score + float64(nodeCharge) +
				price*(-math.Log(p)) + hopCostMsat +
				r.policyPenalty[edge.key] +
				r.edgeFailurePenalty(edge.key, totalLoad, now)

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.45
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)
	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}
		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := lnwire.MilliSatoshi(
			float64(total) * float64(weight) / float64(sum),
		)
		if part <= 0 {
			part = 1
		}

		minTail := lnwire.MilliSatoshi(len(weights) - i - 1)
		if part > remaining-minTail {
			part = remaining - minTail
		}

		result[i] = part
		remaining -= part
	}

	return result
}

func allocationFingerprint(parts []lnwire.MilliSatoshi) uint64 {
	h := uint64(1469598103934665603)
	for _, part := range parts {
		v := uint64(part)
		for i := 0; i < 8; i++ {
			h ^= v & 0xff
			h *= 1099511628211
			v >>= 8
		}
	}
	return h
}

func appendAllocation(patterns *[][]lnwire.MilliSatoshi,
	seen map[uint64]bool, total lnwire.MilliSatoshi, weights []int64) {

	allocation := weightedAllocation(total, weights)
	for _, part := range allocation {
		if part <= 0 {
			return
		}
	}

	key := allocationFingerprint(allocation)
	if seen[key] {
		return
	}
	seen[key] = true
	*patterns = append(*patterns, allocation)
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	patterns := make([][]lnwire.MilliSatoshi, 0)
	seen := make(map[uint64]bool)

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}
	appendAllocation(&patterns, seen, total, equal)

	if parts == 1 {
		return patterns
	}

	if parts == 2 {
		for pct := int64(10); pct <= 90; pct += 5 {
			appendAllocation(
				&patterns, seen, total,
				[]int64{pct, 100 - pct},
			)
		}
		return patterns
	}

	ascending := make([]int64, parts)
	descending := make([]int64, parts)
	for i := 0; i < parts; i++ {
		ascending[i] = int64(i + 1)
		descending[i] = int64(parts - i)
	}
	appendAllocation(&patterns, seen, total, ascending)
	appendAllocation(&patterns, seen, total, descending)

	heavyValues := []int64{2, 3, 5}
	if parts > 4 {
		heavyValues = []int64{3}
	}

	for _, heavy := range heavyValues {
		indices := []int{0, parts - 1}
		if parts <= 4 {
			indices = indices[:0]
			for i := 0; i < parts; i++ {
				indices = append(indices, i)
			}
		}

		for _, idx := range indices {
			weights := make([]int64, parts)
			for i := range weights {
				weights[i] = 1
			}
			weights[idx] = heavy
			appendAllocation(&patterns, seen, total, weights)
		}
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)
	for _, shard := range allocation {
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for i, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}

		searchCap := remainingBudget
		if remainingBudget != lnwire.MaxMilliSatoshi &&
			i < len(allocation)-1 {

			proportional := lnwire.MilliSatoshi(
				float64(remainingBudget) *
					float64(shard) / float64(remainingAmount),
			)
			slack := remainingBudget / 12
			if proportional <= lnwire.MaxMilliSatoshi-slack {
				proportional += slack
			}
			if proportional < searchCap {
				searchCap = proportional
			}
		}

		pr, err := r.findRoute(shard, reservations, searchCap)
		if err != nil && searchCap != remainingBudget {
			pr, err = r.findRoute(
				shard, reservations, remainingBudget,
			)
		}
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * additionalPartCost
	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 && r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(allocation, feeBudget)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	if slots > 1 {
		candidates := make([]lnwire.MilliSatoshi, 0, 20)
		for divisor := lnwire.MilliSatoshi(slots);
			divisor <= lnwire.MilliSatoshi(slots)*8;
			divisor++ {

			shard := (total + divisor - 1) / divisor
			if shard > 0 {
				candidates = append(candidates, shard)
			}
		}

		shard := total / 2
		for shard >= 1_000 {
			candidates = append(candidates, shard)
			shard /= 2
		}

		for _, candidate := range candidates {
			cap := feeBudget
			if feeBudget != lnwire.MaxMilliSatoshi {
				cap = lnwire.MilliSatoshi(
					float64(feeBudget) *
						float64(candidate) / float64(total),
				)
				cap += feeBudget / 10
				if cap > feeBudget {
					cap = feeBudget
				}
			}

			pr, err := r.findRoute(candidate, r.reserved, cap)
			if err == nil {
				return []*plannedRoute{pr}, nil
			}
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	used := r.successfulParts
	if inFlightHtlcs > used {
		used = inFlightHtlcs
	}
	if used >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - used

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if rt == nil {
		return -1
	}
	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) penalizeUnknownFailure(meta *routeMeta,
	now time.Time) {

	r.unknownFailures++
	if len(meta.path) == 0 {
		return
	}

	base := 140_000.0 +
		float64(r.unknownFailures%8)*45_000

	var suspect int
	worst := -1.0
	for i, edge := range meta.path {
		r.recordLiquidityFailure(
			edge.key, meta.loads[i], now, base,
		)

		if edge.from == r.source {
			continue
		}

		p := channelProbability(
			edge.key, meta.loads[i], edge.capacity, now,
		)
		risk := -math.Log(p)
		if risk > worst {
			worst = risk
			suspect = i
		}
	}

	rotation := int(r.unknownFailures) % len(meta.path)
	if worst < 0 || r.unknownFailures%3 == 0 {
		suspect = rotation
	}

	edge := meta.path[suspect]
	r.recordLiquidityFailure(
		edge.key, meta.loads[suspect], now, 900_000,
	)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			recorded := r.reserved[edge.key]
			if meta.amounts[i] <= lnwire.MaxMilliSatoshi-recorded {
				r.reserved[edge.key] = recorded + meta.amounts[i]
			}
			r.recordEdgeSuccess(edge.key, meta.loads[i], now)
			r.policyPenalty[edge.key] *= 0.5
		}

		if meta.fee <= lnwire.MaxMilliSatoshi-r.committedFees {
			r.committedFees += meta.fee
		}
		r.successfulParts++
		r.unknownFailures = 0
		return nil
	}

	r.plan = nil

	failIdx := failureEdgeIndex(rt, result.FailureSource)
	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
		r.recordEdgeSuccess(meta.path[i].key, meta.loads[i], now)
	}

	code := result.Failure.Code()

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.recordLiquidityFailure(
				edge.key, meta.loads[failIdx], now, 1_100_000,
			)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.policyPenalty[edge.key] += 8_000_000
			if r.policyPenalty[edge.key] > maxPolicyPenalty {
				r.policyPenalty[edge.key] = maxPolicyPenalty
			}

		default:
			r.policyPenalty[edge.key] += 2_500_000
			if r.policyPenalty[edge.key] > maxPolicyPenalty {
				r.policyPenalty[edge.key] = maxPolicyPenalty
			}
		}

		return nil
	}

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		r.penalizeUnknownFailure(meta, now)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		for _, edge := range meta.path {
			r.policyPenalty[edge.key] += 600_000
			if r.policyPenalty[edge.key] > maxPolicyPenalty {
				r.policyPenalty[edge.key] = maxPolicyPenalty
			}
		}

	default:
		for i, edge := range meta.path {
			r.recordLiquidityFailure(
				edge.key, meta.loads[i], now, 250_000,
			)
		}
	}

	if result.FailureSource == (route.Vertex{}) &&
		r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {

		guard := meta.fee / 50
		if guard < 500 {
			guard = 500
		}
		if guard <= lnwire.MaxMilliSatoshi-r.budgetGuard {
			r.budgetGuard += guard
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCLTV     = uint32(40)
	candidateRiskPrice     = 420000.0
	candidateHopPrice      = 8000.0
	candidateReuseNats     = 1.35
	candidateMinShard      = lnwire.MilliSatoshi(10000)
	candidateProbFloor     = 0.012
	candidateProbCeiling   = 0.995
	candidatePlanBeamWidth = 10
	candidateMaxFailures   = uint32(64)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat int64
	feeRatePPM  int64
	cltvDelta   uint16
	minHTLC     lnwire.MilliSatoshi
	maxHTLC     lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func (e *candidateEdge) outgoingFee(amt lnwire.MilliSatoshi) int64 {
	fee := e.baseFeeMsat + int64(amt)*e.feeRatePPM/1_000_000
	if fee < 0 {
		return 0
	}
	return fee
}

func forwardingFee(incoming, outgoing *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if incoming == nil || outgoing == nil {
		return 0
	}

	outFee := outgoing.outgoingFee(amt)
	inBasis := int64(amt) + outFee
	inFee := incoming.inboundBase +
		inBasis*incoming.inboundRate/1_000_000

	total := outFee + inFee
	if total < 0 {
		total = 0
	}

	return lnwire.MilliSatoshi(total)
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	success  uint32
	failure  uint32
}

var candidateSharedBeliefs = struct {
	sync.Mutex
	m map[candidateEdgeKey]candidateBelief
}{
	m: make(map[candidateEdgeKey]candidateBelief),
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return candidateProbFloor
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.045)
	highMode := 0.5 / (1 + math.Exp((x-0.94)/0.035))
	p := lowMode + highMode

	if p < candidateProbFloor {
		return candidateProbFloor
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	prior := candidatePrior(load, e.capacity)

	candidateSharedBeliefs.Lock()
	belief, ok := candidateSharedBeliefs.m[e.key]
	candidateSharedBeliefs.Unlock()

	if !ok {
		return prior
	}

	if belief.lowerOK > 0 && load <= belief.lowerOK {
		return candidateProbCeiling
	}

	if belief.upperBad > 0 && load >= belief.upperBad {
		p := prior * 0.08
		if p < candidateProbFloor {
			p = candidateProbFloor
		}
		return p
	}

	var learned, confidence float64

	switch {
	case belief.lowerOK > 0 && belief.upperBad > belief.lowerOK:
		mid := 0.5 * float64(belief.lowerOK+belief.upperBad)
		width := math.Max(
			float64(belief.upperBad-belief.lowerOK)*0.18,
			float64(e.capacity)*0.012,
		)
		learned = 1 / (1 + math.Exp((float64(load)-mid)/width))
		confidence = 0.88

	case belief.upperBad > 0:
		width := math.Max(
			float64(belief.upperBad)*0.14,
			float64(e.capacity)*0.015,
		)
		learned = 1 / (1 + math.Exp(
			(float64(load)-float64(belief.upperBad))/width,
		))
		confidence = 0.72

	case belief.lowerOK > 0:
		excess := float64(load-belief.lowerOK) /
			math.Max(float64(e.capacity), 1)
		learned = candidateProbCeiling * math.Exp(-excess/0.12)
		confidence = 0.62

	default:
		return prior
	}

	p := confidence*learned + (1-confidence)*prior
	if p < candidateProbFloor {
		return candidateProbFloor
	}
	if p > candidateProbCeiling {
		return candidateProbCeiling
	}
	return p
}

func candidateRecordSuccess(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	b := candidateSharedBeliefs.m[key]
	if load > b.lowerOK {
		b.lowerOK = load
	}
	b.success++

	if b.upperBad > 0 && b.lowerOK >= b.upperBad {
		b.upperBad = b.lowerOK + 1
	}

	candidateSharedBeliefs.m[key] = b
}

func candidateRecordFailure(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	b := candidateSharedBeliefs.m[key]
	if b.upperBad == 0 || load < b.upperBad {
		b.upperBad = load
	}
	b.failure++

	candidateSharedBeliefs.m[key] = b
}

type candidateSearchState struct {
	node       route.Vertex
	nextChanID uint64
	nextNode   route.Vertex
	amountBin  uint64
}

type candidateSearchItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   int
	path   []*candidateEdge
	index  int
	state  candidateSearchState
}

type candidateSearchQueue []*candidateSearchItem

func (q candidateSearchQueue) Len() int {
	return len(q)
}

func (q candidateSearchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateSearchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateSearchQueue) Push(x any) {
	item := x.(*candidateSearchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateSearchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	*q = old[:n-1]
	return item
}

type candidatePlanState struct {
	remaining lnwire.MilliSatoshi
	virtual   map[candidateEdgeKey]lnwire.MilliSatoshi
	routes    []*route.Route
	fees      lnwire.MilliSatoshi
	merit     float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[candidateEdgeKey]*candidateEdge
	local    map[uint64]lnwire.MilliSatoshi

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	issued   map[*route.Route]bool
	penalty  map[candidateEdgeKey]float64
	banned   map[candidateEdgeKey]bool

	routeStrikes map[uint64]uint32
	plan         []*route.Route

	committedFees lnwire.MilliSatoshi
	failures      uint32
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:       source,
		spec:         spec,
		incoming:     make(map[route.Vertex][]*candidateEdge),
		edges:        make(map[candidateEdgeKey]*candidateEdge),
		local:        localBalances,
		reserved:     make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		issued:       make(map[*route.Route]bool),
		penalty:      make(map[candidateEdgeKey]float64),
		banned:       make(map[candidateEdgeKey]bool),
		routeStrikes: make(map[uint64]uint32),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:      key,
					capacity: lnwire.NewMSatFromSatoshis(ch.Capacity),

					baseFeeMsat: int64(policy.FeeBaseMSat),
					feeRatePPM: int64(
						policy.FeeProportionalMillionths,
					),
					cltvDelta: policy.TimeLockDelta,
					minHTLC:   policy.MinHTLC,

					inboundBase: int64(ch.InboundFee.BaseFee),
					inboundRate: int64(ch.InboundFee.FeeRate),
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incoming[node] = append(r.incoming[node], edge)
				r.edges[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateAdd(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b > 0 && a > lnwire.MaxMilliSatoshi-b {
		return lnwire.MaxMilliSatoshi
	}
	return a + b
}

func (r *candidateRouter) budgetLeft() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) routeFee(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	if rt.TotalAmount <= delivered {
		return 0
	}
	return rt.TotalAmount - delivered
}

func (r *candidateRouter) routeAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidatePathContains(path []*candidateEdge,
	node route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == node || edge.key.to == node {
			return true
		}
	}
	return false
}

func candidateAmountBin(amt,
	deliver lnwire.MilliSatoshi) uint64 {

	width := deliver / 64
	if width < 1000 {
		width = 1000
	}
	return uint64(amt / width)
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi,
	maxFee lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("invalid shard amount")
	}

	initialState := candidateSearchState{
		node:      r.spec.Target,
		amountBin: candidateAmountBin(deliver, deliver),
	}
	dist := map[candidateSearchState]float64{
		initialState: 0,
	}

	pq := &candidateSearchQueue{}
	heap.Push(pq, &candidateSearchItem{
		node:   r.spec.Target,
		amount: deliver,
		state:  initialState,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateSearchItem)

		best, ok := dist[item.state]
		if !ok || item.score > best+0.0001 {
			continue
		}

		if item.node == r.source {
			rt, err := r.buildRoute(item.path, deliver)
			if err != nil {
				return nil, 0, err
			}
			if r.routeFee(rt) > maxFee {
				continue
			}

			quality := math.Exp(-item.risk)
			if quality < 1e-12 {
				quality = 1e-12
			}
			return rt, quality, nil
		}

		var outgoing *candidateEdge
		if len(item.path) > 0 {
			outgoing = item.path[0]
		}

		for _, incoming := range r.incoming[item.node] {
			if r.banned[incoming.key] ||
				candidatePathContains(item.path, incoming.key.from) {

				continue
			}

			amountOver := item.amount
			if item.node != r.spec.Target {
				amountOver = candidateAdd(
					amountOver,
					forwardingFee(incoming, outgoing, item.amount),
				)
			}

			if !incoming.usable(amountOver) {
				continue
			}

			if maxFee != lnwire.MaxMilliSatoshi &&
				amountOver-deliver > maxFee {

				continue
			}

			load := candidateAdd(
				amountOver, r.reserved[incoming.key],
			)
			if extra != nil {
				load = candidateAdd(load, extra[incoming.key])
			}
			if load > incoming.capacity {
				continue
			}

			var probability float64
			if incoming.key.from == r.source {
				balance, ok := r.local[incoming.key.chanID]
				if !ok || load > balance {
					continue
				}
				probability = 0.999
			} else {
				probability = candidateProbability(incoming, load)
			}

			risk := -math.Log(probability)
			reuse := 0.0
			if r.reserved[incoming.key] > 0 ||
				(extra != nil && extra[incoming.key] > 0) {

				reuse = candidateReuseNats
			}

			feeIncrement := float64(amountOver - item.amount)
			newScore := item.score + feeIncrement +
				candidateRiskPrice*(
					risk+r.penalty[incoming.key]+reuse,
				) + candidateHopPrice

			state := candidateSearchState{
				node:       incoming.key.from,
				nextChanID: incoming.key.chanID,
				nextNode:   incoming.key.to,
				amountBin:  candidateAmountBin(amountOver, deliver),
			}
			oldScore, exists := dist[state]
			if exists && oldScore <= newScore {
				continue
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = incoming
			copy(path[1:], item.path)

			dist[state] = newScore
			heap.Push(pq, &candidateSearchItem{
				node:   incoming.key.from,
				amount: amountOver,
				score:  newScore,
				risk:   item.risk + risk,
				hops:   item.hops + 1,
				path:   path,
				state:  state,
			})
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = deliver
	expiries[n-1] = candidateFinalCLTV

	for i := n - 2; i >= 0; i-- {
		fee := forwardingFee(path[i], path[i+1], amounts[i+1])
		amounts[i] = candidateAdd(amounts[i+1], fee)
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].cltvDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := deliver
		expiry := candidateFinalCLTV
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) forEachRouteEdge(rt *route.Route,
	fn func(candidateEdgeKey, lnwire.MilliSatoshi, int)) {

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		fn(key, amount, i)
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) addVirtualReservation(
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		reserved[key] = candidateAdd(reserved[key], amount)
	})
}

func candidateCloneReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	clone := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		clone[key] = amount
	}
	return clone
}

func (r *candidateRouter) reserveIssued(rt *route.Route) {
	if r.issued[rt] {
		return
	}

	r.issued[rt] = true
	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		r.reserved[key] = candidateAdd(r.reserved[key], amount)
	})
}

func (r *candidateRouter) releaseIssued(rt *route.Route) {
	if !r.issued[rt] {
		return
	}

	delete(r.issued, rt)
	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		current := r.reserved[key]
		if current <= amount {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = current - amount
		}
	})
}

func (r *candidateRouter) maxFeeForPlan(
	already lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	left := r.budgetLeft()
	if left == lnwire.MaxMilliSatoshi {
		return left
	}
	if already >= left {
		return 0
	}
	return left - already
}

func candidateAppendShard(values []lnwire.MilliSatoshi,
	shard, minimum, maximum lnwire.MilliSatoshi,
) []lnwire.MilliSatoshi {

	if shard < minimum || shard > maximum {
		return values
	}
	for _, value := range values {
		if value == shard {
			return values
		}
	}
	return append(values, shard)
}

func candidateShardChoices(remaining lnwire.MilliSatoshi,
	left int) []lnwire.MilliSatoshi {

	if left <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := candidateMinShard
	maximum := remaining -
		candidateMinShard*lnwire.MilliSatoshi(left-1)
	if maximum < minimum {
		return nil
	}

	equal := remaining / lnwire.MilliSatoshi(left)
	var choices []lnwire.MilliSatoshi

	choices = candidateAppendShard(
		choices, equal, minimum, maximum,
	)
	choices = candidateAppendShard(
		choices, equal+equal/2, minimum, maximum,
	)
	choices = candidateAppendShard(
		choices, equal*3/4, minimum, maximum,
	)
	choices = candidateAppendShard(
		choices, equal+equal/4, minimum, maximum,
	)
	choices = candidateAppendShard(
		choices, equal*2/3, minimum, maximum,
	)

	return choices
}

func candidateKeepBest(states []candidatePlanState,
	limit int) []candidatePlanState {

	if len(states) <= limit {
		return states
	}

	for i := 0; i < limit; i++ {
		best := i
		for j := i + 1; j < len(states); j++ {
			if states[j].merit < states[best].merit {
				best = j
			}
		}
		states[i], states[best] = states[best], states[i]
	}

	return states[:limit]
}

func (r *candidateRouter) tryPlan(amount lnwire.MilliSatoshi,
	parts int) ([]*route.Route, bool) {

	if parts < 1 ||
		amount < candidateMinShard*lnwire.MilliSatoshi(parts) {

		return nil, false
	}

	states := []candidatePlanState{{
		remaining: amount,
		virtual:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}}

	for index := 0; index < parts; index++ {
		left := parts - index
		next := make([]candidatePlanState, 0, len(states)*3)

		for _, state := range states {
			for _, shard := range candidateShardChoices(
				state.remaining, left,
			) {
				maxFee := r.maxFeeForPlan(state.fees)
				rt, quality, err := r.findRoute(
					shard, state.virtual, maxFee,
				)
				if err != nil {
					continue
				}

				fee := r.routeFee(rt)
				budget := r.budgetLeft()
				if budget != lnwire.MaxMilliSatoshi &&
					state.fees+fee > budget {

					continue
				}

				virtual := candidateCloneReservations(
					state.virtual,
				)
				r.addVirtualReservation(virtual, rt)

				routes := make([]*route.Route, len(state.routes)+1)
				copy(routes, state.routes)
				routes[len(state.routes)] = rt

				if quality < 1e-12 {
					quality = 1e-12
				}

				next = append(next, candidatePlanState{
					remaining: state.remaining -
						r.routeAmount(rt),
					virtual: virtual,
					routes:  routes,
					fees:    state.fees + fee,
					merit: state.merit + float64(fee) +
						candidateRiskPrice*
							(-math.Log(quality)),
				})
			}
		}

		if len(next) == 0 {
			return nil, false
		}
		states = candidateKeepBest(next, candidatePlanBeamWidth)
	}

	var best *candidatePlanState
	for i := range states {
		if states[i].remaining != 0 {
			continue
		}
		if best == nil || states[i].merit < best.merit {
			best = &states[i]
		}
	}
	if best == nil {
		return nil, false
	}

	return best.routes, true
}

func (r *candidateRouter) makePlan(amount lnwire.MilliSatoshi,
	slots uint32) ([]*route.Route, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts already in flight")
	}

	full, quality, fullErr := r.findRoute(
		amount, nil, r.budgetLeft(),
	)

	if slots == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	preferred := 1
	switch {
	case fullErr != nil:
		preferred = 2

	case quality < 0.08:
		preferred = 3

	case quality < 0.35 && amount >= 20_000_000:
		preferred = 2
	}

	if r.failures > 0 && preferred < 2 {
		preferred = 2
	}
	if r.failures >= 3 && preferred < 3 {
		preferred = 3
	}
	if preferred > int(slots) {
		preferred = int(slots)
	}

	if preferred == 1 && fullErr == nil {
		return []*route.Route{full}, nil
	}

	for parts := preferred; parts <= int(slots); parts++ {
		plan, ok := r.tryPlan(amount, parts)
		if ok {
			return plan, nil
		}
	}

	if fullErr == nil {
		return []*route.Route{full}, nil
	}

	shard := amount / lnwire.MilliSatoshi(slots)
	if shard < candidateMinShard {
		shard = candidateMinShard
	}

	for shard >= candidateMinShard {
		rt, _, err := r.findRoute(
			shard, nil, r.budgetLeft(),
		)
		if err == nil {
			return []*route.Route{rt}, nil
		}

		if shard == candidateMinShard {
			break
		}
		shard = shard * 2 / 3
		if shard < candidateMinShard {
			shard = candidateMinShard
		}
	}

	return nil, fullErr
}

func candidateRouteHash(rt *route.Route) uint64 {
	hash := uint64(1469598103934665603)
	mix := func(value uint64) {
		hash ^= value
		hash *= 1099511628211
	}

	mix(uint64(len(rt.Hops)))
	mix(uint64(rt.TotalAmount))
	for _, hop := range rt.Hops {
		mix(hop.ChannelID)
		mix(uint64(hop.AmtToForward))
	}

	return hash
}

func (r *candidateRouter) penalizeRepeatedRoute(
	rt *route.Route, strike uint32) {

	if len(rt.Hops) == 0 {
		return
	}

	index := int(strike % uint32(len(rt.Hops)))
	key, _, ok := r.routeEdgeAt(rt, index)
	if !ok {
		return
	}

	r.penalty[key] += 0.55 + 0.08*float64(strike)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if r.failures >= candidateMaxFailures {
		return nil, errors.New("routing failure budget exhausted")
	}

	for replans := 0; replans < 12; replans++ {
		if len(r.plan) == 0 {
			maxParts := r.spec.MaxParts
			if maxParts == 0 {
				maxParts = 1
			}
			if inFlightHtlcs >= maxParts {
				return nil, errors.New("maximum parts already in flight")
			}

			plan, err := r.makePlan(
				amt, maxParts-inFlightHtlcs,
			)
			if err != nil {
				return nil, err
			}
			r.plan = plan
		}

		rt := r.plan[0]
		r.plan = r.plan[1:]

		if r.routeAmount(rt) > amt {
			r.plan = nil
			continue
		}

		fee := r.routeFee(rt)
		budget := r.budgetLeft()
		if budget != lnwire.MaxMilliSatoshi && fee > budget {
			r.plan = nil
			continue
		}

		hash := candidateRouteHash(rt)
		strikes := r.routeStrikes[hash]
		if strikes >= 3 && replans < 11 {
			r.penalizeRepeatedRoute(rt, strikes)
			r.plan = nil
			continue
		}

		if strikes >= 12 {
			return nil, errors.New("no untried route found")
		}

		r.reserveIssued(rt)
		r.attempts++
		return rt, nil
	}

	return nil, errors.New("unable to construct a distinct route")
}

func (r *candidateRouter) routeFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) routeEdgeAt(rt *route.Route,
	index int) (candidateEdgeKey, lnwire.MilliSatoshi, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, 0, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	amount := rt.TotalAmount
	if index > 0 {
		amount = rt.Hops[index-1].AmtToForward
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, amount, true
}

func (r *candidateRouter) observedLoad(key candidateEdgeKey,
	fallback lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if load := r.reserved[key]; load > 0 {
		return load
	}
	return fallback
}

func (r *candidateRouter) weakestRouteEdge(
	rt *route.Route) (candidateEdgeKey, lnwire.MilliSatoshi, bool) {

	var weakest candidateEdgeKey
	var weakestAmount lnwire.MilliSatoshi
	weakestProbability := 2.0
	found := false

	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		edge := r.edges[key]
		if edge == nil {
			return
		}

		load := r.observedLoad(key, amount)
		probability := candidateProbability(edge, load)
		if key.from == r.source {
			probability = 0.998
		}

		if !found || probability < weakestProbability {
			found = true
			weakest = key
			weakestAmount = load
			weakestProbability = probability
		}
	})

	return weakest, weakestAmount, found
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	hash := candidateRouteHash(rt)

	if result.Failure == nil {
		delete(r.routeStrikes, hash)

		r.forEachRouteEdge(rt, func(key candidateEdgeKey,
			amount lnwire.MilliSatoshi, _ int) {

			candidateRecordSuccess(
				key, r.observedLoad(key, amount),
			)
			if r.penalty[key] > 0.30 {
				r.penalty[key] -= 0.30
			} else {
				delete(r.penalty, key)
			}
		})

		r.committedFees = candidateAdd(
			r.committedFees, r.routeFee(rt),
		)
		return nil
	}

	r.failures++
	r.routeStrikes[hash]++
	r.plan = nil

	failIndex := r.routeFailureIndex(
		rt, result.FailureSource,
	)

	for i := 0; i < failIndex && i < len(rt.Hops); i++ {
		key, amount, ok := r.routeEdgeAt(rt, i)
		if ok {
			candidateRecordSuccess(
				key, r.observedLoad(key, amount),
			)
		}
	}

	code := result.Failure.Code()
	if key, amount, ok := r.routeEdgeAt(rt, failIndex); ok {
		load := r.observedLoad(key, amount)

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(key, load)
			r.penalty[key] += 1.65

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.banned[key] = true

		default:
			r.penalty[key] += 0.85
		}
	} else {
		if code == lnwire.CodeTemporaryChannelFailure {
			key, load, ok := r.weakestRouteEdge(rt)
			if ok {
				candidateRecordFailure(key, load)
				r.penalty[key] += 1.85
			}
		}

		r.forEachRouteEdge(rt, func(key candidateEdgeKey,
			_ lnwire.MilliSatoshi, _ int) {

			r.penalty[key] += 0.06
		})

		r.penalizeRepeatedRoute(
			rt, r.routeStrikes[hash],
		)
	}

	r.releaseIssued(rt)
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"strings"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	riskPriceMsat = 420000.0
	hopPriceMsat  = 8000.0
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	forward lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if out == nil {
		return 0
	}

	outFee := int64(out.fee(forward))
	inboundBasis := int64(forward) + outFee
	inboundFee := in.inboundBase +
		inboundBasis*in.inboundRate/1_000_000

	total := outFee + inboundFee
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	epoch     uint64
}

var sharedKnowledge = struct {
	sync.Mutex
	epoch   uint64
	beliefs map[edgeKey]liquidityBelief
}{
	beliefs: make(map[edgeKey]liquidityBelief),
}

type localEdgeState struct {
	belief   liquidityBelief
	failures int
	lastFail lnwire.MilliSatoshi
	policyBad bool
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	state        map[edgeKey]*localEdgeState
	reserved     map[edgeKey]lnwire.MilliSatoshi
	diversion    map[edgeKey]int
	attempted    map[uint64]int
	reported     map[*route.Route]bool
	committedFee lnwire.MilliSatoshi

	failureStreak int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	sharedKnowledge.Lock()
	sharedKnowledge.epoch++
	epoch := sharedKnowledge.epoch
	sharedKnowledge.Unlock()

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		epoch:         epoch,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		state:         make(map[edgeKey]*localEdgeState),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		diversion:     make(map[edgeKey]int),
		attempted:     make(map[uint64]int),
		reported:      make(map[*route.Route]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key:      key,
					chanID:   ch.ChannelID,
					from:     ch.OtherNode,
					to:       node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase: int64(
						ch.InboundFee.BaseFee,
					),
					inboundRate: int64(
						ch.InboundFee.FeeRate,
					),
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[edge.to] = append(
					r.incomingEdges[edge.to], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedKnowledge.Lock()
	for key, edge := range r.edgeByKey {
		belief, ok := sharedKnowledge.beliefs[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}

		r.state[key] = &localEdgeState{
			belief: belief,
		}
	}
	sharedKnowledge.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.025)
	highMode := 0.5 /
		(1 + math.Exp((x-0.90)/0.035))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	if load > e.capacity {
		return 0.005
	}

	if e.from == r.source {
		if load <= r.localBalances[e.chanID] {
			return 0.995
		}

		return 0.005
	}

	prior := bimodalPrior(load, e.capacity)
	state := r.state[e.key]
	if state == nil || state.belief.conf <= 0 {
		return prior
	}

	belief := state.belief
	var age uint64
	if r.epoch > belief.epoch {
		age = r.epoch - belief.epoch
	}

	conf := belief.conf * math.Exp(-float64(age)/8)
	if conf < 0.025 {
		return prior
	}

	activeBounds := age <= 4
	var learned float64

	switch {
	case activeBounds && belief.lowerOK > 0 &&
		load <= belief.lowerOK:

		learned = 0.995

	case activeBounds && belief.upperFail > 0 &&
		load >= belief.upperFail:

		learned = 0.015

	default:
		estimate := belief.estimate
		if estimate <= 0 {
			estimate = e.capacity / 2
		}

		width := float64(e.capacity) * 0.07
		if width < 1_000_000 {
			width = 1_000_000
		}

		z := (float64(load) - float64(estimate)) / width
		learned = clampProbability(1 / (1 + math.Exp(z)))
	}

	return clampProbability(
		conf*learned + (1-conf)*prior,
	)
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFee >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFee
}

func (r *candidateRouter) shardFeeBudget(shard, remaining,
	partsLeft lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	budget := r.remainingFeeBudget()
	if budget == lnwire.MaxMilliSatoshi ||
		shard >= remaining {

		return budget
	}
	if budget <= 0 || remaining <= 0 {
		return 0
	}

	share := budget * shard / remaining

	// Give a shard a small allowance for base fees while retaining most
	// of the budget for the remaining parts.
	headroom := budget / 20
	if partsLeft > 1 {
		headroom /= partsLeft
	}
	if share > budget-headroom {
		return budget
	}

	return share + headroom
}

type searchItem struct {
	node route.Vertex
	cost float64
	amt  lnwire.MilliSatoshi
}

type searchQueue []*searchItem

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].cost < q[j].cost
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchItem))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]

	return item
}

type routeMeta struct {
	path    []*candidateEdge
	fee     lnwire.MilliSatoshi
	logProb float64
	score   float64
}

func (r *candidateRouter) edgePenalty(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	penalty := float64(r.diversion[e.key]) * 300000

	reserved := r.reserved[e.key]
	if reserved > 0 {
		penalty += 1_600_000
		if e.capacity > 0 {
			penalty += 900000 *
				float64(reserved) / float64(e.capacity)
		}
	}

	state := r.state[e.key]
	if state == nil || state.failures == 0 {
		return penalty
	}

	failures := state.failures
	if failures > 6 {
		failures = 6
	}

	unit := 1_150_000.0
	if state.lastFail > 0 &&
		load*5 < state.lastFail*4 {

		unit = 120000
	}

	return penalty + float64(failures)*unit
}

func (r *candidateRouter) search(amt lnwire.MilliSatoshi,
	riskScale float64, avoidReserved bool) (*route.Route,
	*routeMeta, error) {

	best := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	best[r.spec.Target] = 0

	pq := &searchQueue{}
	heap.Push(pq, &searchItem{
		node: r.spec.Target,
		cost: 0,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*searchItem)

		currentBest, ok := best[item.node]
		if !ok || item.cost > currentBest+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		out := next[item.node]
		for _, in := range r.incomingEdges[item.node] {
			state := r.state[in.key]
			if state != nil && state.policyBad {
				continue
			}

			reserved := r.reserved[in.key]
			if avoidReserved && reserved > 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if item.node != r.spec.Target {
				fee = nodeFee(in, out, item.amt)
			}
			if fee > lnwire.MaxMilliSatoshi-item.amt {
				continue
			}

			amountOver := item.amt + fee
			if !in.usable(amountOver) {
				continue
			}

			if reserved > in.capacity ||
				amountOver > in.capacity-reserved {

				continue
			}

			load := amountOver + reserved
			if in.from == r.source {
				balance := r.localBalances[in.chanID]
				if reserved > balance ||
					amountOver > balance-reserved {

					continue
				}
			}

			probability := r.edgeProbability(in, load)
			step := float64(fee) -
				riskScale*math.Log(probability) +
				hopPriceMsat
			step += r.edgePenalty(in, load)

			newCost := item.cost + step
			oldCost, seen := best[in.from]
			if seen && newCost >= oldCost {
				continue
			}

			best[in.from] = newCost
			next[in.from] = in
			heap.Push(pq, &searchItem{
				node: in.from,
				cost: newCost,
				amt:  amountOver,
			})
		}
	}

	if _, ok := best[r.source]; !ok {
		return nil, nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, nil, err
	}

	fee := rt.TotalAmount - amt
	logProb := 0.0
	for i, edge := range path {
		amountOver := routeAmountAt(rt, i)
		load := amountOver + r.reserved[edge.key]
		logProb += math.Log(
			r.edgeProbability(edge, load),
		)
	}

	return rt, &routeMeta{
		path:    path,
		fee:     fee,
		logProb: logProb,
	}, nil
}

func (r *candidateRouter) findRoute(amt,
	feeCap lnwire.MilliSatoshi) (*route.Route, *routeMeta, error) {

	baseScale := riskPriceMsat
	if feeCap != lnwire.MaxMilliSatoshi {
		budgetScale := float64(feeCap) * 0.45
		if budgetScale < 3500 {
			budgetScale = 3500
		}
		if budgetScale < baseScale {
			baseScale = budgetScale
		}
	}

	scales := []float64{
		baseScale,
		baseScale / 4,
		0,
		riskPriceMsat,
		riskPriceMsat * 2,
	}

	var bestRoute *route.Route
	var bestMeta *routeMeta

	for pass := 0; pass < 2; pass++ {
		avoidReserved := pass == 0

		for _, scale := range scales {
			rt, meta, err := r.search(
				amt, scale, avoidReserved,
			)
			if err != nil {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				meta.fee > feeCap {

				continue
			}

			meta.score = float64(meta.fee) -
				baseScale*meta.logProb +
				float64(len(meta.path))*hopPriceMsat

			if bestMeta == nil ||
				meta.score < bestMeta.score {

				bestRoute = rt
				bestMeta = meta
			}
		}

		if bestRoute != nil {
			break
		}
	}

	if bestRoute == nil {
		return nil, nil, errors.New("no route found")
	}

	return bestRoute, bestMeta, nil
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	path := make([]*candidateEdge, 0, 12)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, nil, errors.New("routing cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.to
	}

	n := len(path)
	if n == 0 {
		return nil, nil, errors.New("empty route")
	}

	amountOver := make([]lnwire.MilliSatoshi, n)
	expiryOver := make([]uint32, n)

	amountOver[n-1] = deliver
	expiryOver[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fee := nodeFee(
			path[i], path[i+1], amountOver[i+1],
		)
		amountOver[i] = amountOver[i+1] + fee
		expiryOver[i] = expiryOver[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)

		if i < n-1 {
			forward = amountOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amountOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func ceilDiv(a lnwire.MilliSatoshi,
	b int) lnwire.MilliSatoshi {

	if b <= 1 {
		return a
	}

	divisor := lnwire.MilliSatoshi(b)
	return (a + divisor - 1) / divisor
}

func appendShardCandidate(candidates []lnwire.MilliSatoshi,
	shard, remaining lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if shard <= 0 {
		return candidates
	}
	if shard > remaining {
		shard = remaining
	}

	for _, existing := range candidates {
		if existing == shard {
			return candidates
		}
	}

	return append(candidates, shard)
}

func shardCandidates(remaining lnwire.MilliSatoshi,
	partsLeft, failureStreak int) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minShard := ceilDiv(remaining, partsLeft)
	candidates := make([]lnwire.MilliSatoshi, 0, 9)

	candidates = appendShardCandidate(
		candidates, remaining, remaining,
	)
	candidates = appendShardCandidate(
		candidates, remaining*3/4, remaining,
	)
	candidates = appendShardCandidate(
		candidates, remaining/2, remaining,
	)
	candidates = appendShardCandidate(
		candidates, minShard*9/4, remaining,
	)
	candidates = appendShardCandidate(
		candidates, minShard*3/2, remaining,
	)
	candidates = appendShardCandidate(
		candidates, minShard, remaining,
	)

	if failureStreak > 0 {
		candidates = appendShardCandidate(
			candidates, minShard*3/4, remaining,
		)
		candidates = appendShardCandidate(
			candidates, minShard/2, remaining,
		)
	}

	for i := 0; i < len(candidates); i++ {
		for j := i + 1; j < len(candidates); j++ {
			if candidates[j] > candidates[i] {
				candidates[i], candidates[j] =
					candidates[j], candidates[i]
			}
		}
	}

	return candidates
}

func routeFingerprint(rt *route.Route) uint64 {
	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	hash := offset
	mix := func(value uint64) {
		hash ^= value
		hash *= prime
	}

	mix(uint64(rt.TotalAmount))
	for _, hop := range rt.Hops {
		mix(hop.ChannelID)
		mix(uint64(hop.AmtToForward))
	}

	return hash
}

func (r *candidateRouter) selectShard(remaining,
	partsLeft lnwire.MilliSatoshi, relaxedBudget bool) (
	*route.Route, *routeMeta, error) {

	partCount := int(partsLeft)
	minShard := ceilDiv(remaining, partCount)
	candidates := shardCandidates(
		remaining, partCount, r.failureStreak,
	)

	var bestRoute *route.Route
	var bestMeta *routeMeta
	bestValue := math.Inf(-1)

	for _, shard := range candidates {
		feeCap := r.shardFeeBudget(
			shard, remaining, partsLeft,
		)
		if relaxedBudget {
			feeCap = r.remainingFeeBudget()
		}

		rt, meta, err := r.findRoute(shard, feeCap)
		if err != nil {
			continue
		}

		value := math.Log(float64(shard)) +
			0.70*meta.logProb -
			float64(meta.fee)/riskPriceMsat -
			float64(len(meta.path))*0.025

		if shard < minShard {
			value -= 0.85
		}

		if bestMeta == nil || value > bestValue {
			bestRoute = rt
			bestMeta = meta
			bestValue = value
		}
	}

	if bestRoute == nil {
		return nil, nil, errors.New("no route found")
	}

	return bestRoute, bestMeta, nil
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment complete")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts reached")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var lastErr error

	for diversify := 0; diversify < 4; diversify++ {
		rt, meta, err := r.selectShard(
			amt, lnwire.MilliSatoshi(partsLeft), false,
		)
		if err != nil {
			rt, meta, err = r.selectShard(
				amt, lnwire.MilliSatoshi(partsLeft), true,
			)
		}
		if err != nil {
			lastErr = err
			break
		}

		fingerprint := routeFingerprint(rt)
		if r.attempted[fingerprint] == 0 ||
			diversify == 3 {

			r.attempted[fingerprint]++
			return rt, nil
		}

		// An exact route-and-amount retry is usually wasted in a
		// bimodal network. Penalize its complete corridor and search
		// again, while still allowing it if no alternative exists.
		for _, edge := range meta.path {
			r.diversion[edge.key]++
		}
		lastErr = errors.New("route already attempted")
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}

	return nil, lastErr
}

func routeAmountAt(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func routeEdgeKey(rt *route.Route, index int) edgeKey {
	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return edgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
	}
}

func (r *candidateRouter) saveBelief(key edgeKey,
	belief liquidityBelief) {

	if state := r.state[key]; state != nil {
		state.belief = belief
	}

	sharedKnowledge.Lock()
	sharedKnowledge.beliefs[key] = belief
	sharedKnowledge.Unlock()
}

func (r *candidateRouter) recordSuccess(key edgeKey,
	load lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	state := r.state[key]
	if edge == nil || state == nil {
		return
	}

	belief := state.belief
	if load > belief.lowerOK {
		belief.lowerOK = load
	}

	estimate := edge.capacity * 88 / 100
	if load > estimate {
		estimate = load
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	if belief.upperFail > 0 &&
		load >= belief.upperFail {

		belief.upperFail = 0
	}

	belief.conf = 0.92
	belief.epoch = r.epoch

	if state.lastFail == 0 || load >= state.lastFail {
		state.failures = 0
		state.lastFail = 0
	} else if state.failures > 0 {
		state.failures--
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	state := r.state[key]
	if edge == nil || state == nil {
		return
	}

	if state.failures < 8 {
		state.failures++
	}
	state.lastFail = load

	belief := state.belief
	if belief.upperFail == 0 ||
		load < belief.upperFail {

		belief.upperFail = load
	}

	estimate := load * 18 / 100
	if belief.estimate == 0 ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	if belief.lowerOK >= load {
		belief.lowerOK = load * 2 / 3
		belief.conf = 0.64
	} else {
		belief.conf = 0.90
	}

	if edge.from == r.source {
		belief.conf *= 0.75
	}

	belief.epoch = r.epoch
	r.saveBelief(key, belief)
}

func failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) recordPassedPrefix(
	rt *route.Route, stop int) {

	if stop > len(rt.Hops) {
		stop = len(rt.Hops)
	}

	for i := 0; i < stop; i++ {
		key := routeEdgeKey(rt, i)
		load := routeAmountAt(rt, i) +
			r.reserved[key]
		r.recordSuccess(key, load)
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if rt == nil || r.reported[rt] {
		return nil
	}
	r.reported[rt] = true

	if result.Failure == nil {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			amountOver := routeAmountAt(rt, i)
			load := amountOver + r.reserved[key]

			r.recordSuccess(key, load)
			r.reserved[key] += amountOver
		}

		delivered := rt.Hops[len(rt.Hops)-1].
			AmtToForward
		if rt.TotalAmount > delivered {
			r.committedFee +=
				rt.TotalAmount - delivered
		}

		r.failureStreak = 0
		return nil
	}

	failureType := fmt.Sprintf("%T", result.Failure)
	isLiquidity := strings.Contains(
		failureType, "TemporaryChannelFailure",
	)
	isPolicy := strings.Contains(
		failureType, "FeeInsufficient",
	) || strings.Contains(
		failureType, "IncorrectCltvExpiry",
	)

	failAt := failureIndex(
		rt, result.FailureSource,
	)

	if failAt >= 0 && failAt < len(rt.Hops) {
		// Every edge before the failing node carried the HTLC. This
		// positive evidence is particularly valuable in a bimodal
		// liquidity distribution.
		if isLiquidity || isPolicy {
			r.recordPassedPrefix(rt, failAt)
		}

		key := routeEdgeKey(rt, failAt)
		load := routeAmountAt(rt, failAt) +
			r.reserved[key]

		switch {
		case isLiquidity:
			r.recordFailure(key, load)
			r.failureStreak++

		case isPolicy:
			if state := r.state[key]; state != nil {
				state.policyBad = true
				state.failures = 8
				state.lastFail = load
			}
			r.failureStreak++
		}

		return nil
	}

	if isLiquidity {
		// The source is unknown, so diversify without manufacturing a
		// liquidity bound for every edge.
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			state := r.state[key]
			if state == nil {
				continue
			}

			if state.failures < 6 {
				state.failures++
			}
			state.lastFail = routeAmountAt(rt, i) +
				r.reserved[key]
			r.diversion[key]++
		}

		r.failureStreak++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	baseRiskPriceMsat = float64(420_000)
	minRiskPriceMsat  = float64(25_000)

	hopCostMsat        = float64(25_000)
	reusedEdgeCostMsat = float64(1_150_000)
	extraPartCostMsat  = float64(50_000)

	maxSearchHops        = 48
	maxLabelsPerNode     = 10
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 40
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amt <= 0 {
		return e.baseFeeMsat
	}

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inboundBasis := int64(amt) + outbound

	inbound := int64(in.inboundBase) +
		inboundBasis*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi
	budgetGuard   lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		pos := float64(b.upperBad-amt) /
			float64(b.upperBad-b.lowerOK)

		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)

			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees + r.budgetGuard
	if spent >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}

	return price
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	var cutoff lnwire.MilliSatoshi
	switch {
	case r.localFails[key] >= 3:
		cutoff = upper / 2
	case r.localFails[key] == 2:
		cutoff = upper * 2 / 3
	default:
		cutoff = upper * 4 / 5
	}

	if cutoff <= 0 {
		return 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			totalLoad := over + reserved
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.80
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				price*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}

				loadFraction := float64(totalLoad) /
					math.Max(1, float64(edge.capacity))

				score += reuse * (1 + loadFraction)
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}

		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func proportionalAmount(total lnwire.MilliSatoshi,
	weight, sum int64) lnwire.MilliSatoshi {

	if total <= 0 || weight <= 0 || sum <= 0 {
		return 0
	}

	q := total / lnwire.MilliSatoshi(sum)
	rem := total % lnwire.MilliSatoshi(sum)

	return q*lnwire.MilliSatoshi(weight) +
		rem*lnwire.MilliSatoshi(weight)/lnwire.MilliSatoshi(sum)
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		if weight > 0 {
			sum += weight
		}
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		if weight <= 0 || remainingWeight <= 0 {
			return nil
		}

		part := proportionalAmount(remaining, weight, remainingWeight)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			return nil
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	if parts <= 0 || total < lnwire.MilliSatoshi(parts) {
		return nil
	}

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	switch parts {
	case 2:
		for _, weights := range [][]int64{
			{40, 60}, {60, 40},
			{25, 75}, {75, 25},
			{15, 85}, {85, 15},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 3:
		for _, weights := range [][]int64{
			{20, 30, 50},
			{50, 30, 20},
			{15, 25, 60},
			{60, 25, 15},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 4:
		for _, weights := range [][]int64{
			{10, 15, 25, 50},
			{50, 25, 15, 10},
			{15, 20, 25, 40},
			{40, 25, 20, 15},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	default:
		ascending := make([]int64, parts)
		descending := make([]int64, parts)

		for i := 0; i < parts; i++ {
			ascending[i] = int64(i + 1)
			descending[i] = int64(parts - i)
		}

		patterns = append(
			patterns,
			weightedAllocation(total, ascending),
			weightedAllocation(total, descending),
		)
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}

		pr, err := r.findRoute(shard, reservations, remainingBudget)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

type amountFraction struct {
	num int64
	den int64
}

func amountProbes(limit lnwire.MilliSatoshi) []lnwire.MilliSatoshi {
	fractions := []amountFraction{
		{1, 1},
		{7, 8},
		{3, 4},
		{2, 3},
		{3, 5},
		{1, 2},
		{2, 5},
		{1, 3},
		{1, 4},
		{1, 5},
		{1, 6},
		{1, 8},
		{1, 10},
		{1, 12},
		{1, 16},
		{1, 24},
		{1, 32},
		{1, 48},
		{1, 64},
	}

	seen := make(map[lnwire.MilliSatoshi]struct{})
	result := make([]lnwire.MilliSatoshi, 0, len(fractions)+1)

	for _, fraction := range fractions {
		amt := proportionalAmount(limit, fraction.num, fraction.den)
		if amt <= 0 {
			amt = 1
		}
		if amt > limit {
			amt = limit
		}
		if _, ok := seen[amt]; ok {
			continue
		}

		seen[amt] = struct{}{}
		result = append(result, amt)
	}

	if _, ok := seen[1]; !ok {
		result = append(result, 1)
	}

	sort.Slice(result, func(i, j int) bool {
		return result[i] > result[j]
	})

	return result
}

func (r *candidateRouter) findLargestRoute(
	limit lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) (*plannedRoute,
	lnwire.MilliSatoshi, error) {

	if limit <= 0 {
		return nil, 0, errors.New("invalid shard limit")
	}

	var failedAbove lnwire.MilliSatoshi

	for _, probe := range amountProbes(limit) {
		pr, err := r.findRoute(probe, reservations, feeBudget)
		if err != nil {
			failedAbove = probe
			continue
		}

		best := pr
		bestAmt := probe

		if failedAbove > probe+1 {
			low := probe
			high := failedAbove - 1

			for iteration := 0; iteration < 5 && low < high; iteration++ {
				mid := low + (high-low+1)/2
				candidate, findErr := r.findRoute(
					mid, reservations, feeBudget,
				)
				if findErr != nil {
					high = mid - 1
					continue
				}

				low = mid
				bestAmt = mid
				best = candidate
			}
		}

		return best, bestAmt, nil
	}

	return nil, 0, errors.New("no shard route found")
}

func (r *candidateRouter) tryGreedyPlan(total lnwire.MilliSatoshi,
	partLimit int, firstFraction amountFraction,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	if total <= 0 || partLimit <= 0 {
		return nil, 0, false
	}

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remaining := total
	plan := make([]*plannedRoute, 0, partLimit)
	totalScore := float64(0)

	for part := 0; part < partLimit && remaining > 0; part++ {
		partsLeft := partLimit - part

		if partsLeft == 1 {
			pr, err := r.findRoute(
				remaining, reservations, remainingBudget,
			)
			if err != nil {
				return nil, 0, false
			}

			if remainingBudget != lnwire.MaxMilliSatoshi {
				if pr.meta.fee > remainingBudget {
					return nil, 0, false
				}
				remainingBudget -= pr.meta.fee
			}

			plan = append(plan, pr)
			totalScore += pr.score
			addReservationSet(reservations, pr.meta)
			remaining = 0
			break
		}

		maxLimit := remaining -
			lnwire.MilliSatoshi(partsLeft-1)
		if maxLimit <= 0 {
			return nil, 0, false
		}

		maxRoute, maxAmount, err := r.findLargestRoute(
			maxLimit, reservations, remainingBudget,
		)
		if err != nil {
			return nil, 0, false
		}

		shard := maxAmount
		if part == 0 && firstFraction.den > 0 {
			scaled := proportionalAmount(
				maxAmount,
				firstFraction.num,
				firstFraction.den,
			)
			if scaled > 0 && scaled < shard {
				shard = scaled
			}
		}

		var pr *plannedRoute
		if shard == maxAmount {
			pr = maxRoute
		} else {
			pr, err = r.findRoute(
				shard, reservations, remainingBudget,
			)
			if err != nil {
				pr = maxRoute
				shard = maxAmount
			}
		}

		if shard <= 0 || shard >= remaining {
			if shard == remaining {
				plan = append(plan, pr)
				totalScore += pr.score
				remaining = 0
				break
			}

			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remaining -= shard
	}

	if remaining != 0 || len(plan) == 0 {
		return nil, 0, false
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	greedyFractions := []amountFraction{
		{1, 1},
		{4, 5},
		{2, 3},
		{1, 2},
	}

	for parts := 2; parts <= int(slots); parts++ {
		for _, fraction := range greedyFractions {
			plan, score, ok := r.tryGreedyPlan(
				total, parts, fraction, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) == 0 {
		return nil, errors.New("no route found")
	}

	return best, nil
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 {
		if queuedAmount(r.plan) != amt ||
			uint32(len(r.plan)) > slots {

			r.plan = nil
		}
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.30

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if failIdx < 0 &&
		code == lnwire.CodeTemporaryChannelFailure &&
		len(meta.path) > 0 {

		failIdx = 0
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.recordLocalFailure(edge.key, meta.loads[failIdx])

			count := r.localFails[edge.key]
			r.edgePenalty[edge.key] +=
				325_000 + float64(count)*200_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.blocked[edge.key] = true
			r.edgePenalty[edge.key] += 8_000_000

		default:
			r.edgePenalty[edge.key] += 2_000_000
		}

		return nil
	}

	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 650_000
	}

	if r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
		remaining := r.remainingFeeBudget()
		if remaining != lnwire.MaxMilliSatoshi &&
			remaining > 0 &&
			meta.fee*20 >= remaining*19 {

			guard := meta.fee / 25
			if guard < 1_000 {
				guard = 1_000
			}
			if guard > remaining {
				guard = remaining
			}

			r.budgetGuard += guard
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = 40
	riskPriceMsat    = 420000.0
	hopPriceMsat     = 7000.0
	partPriceMsat    = 12000.0
	maxRouterAttempts = 36
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	forward lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if out == nil {
		return 0
	}

	outFee := int64(out.fee(forward))
	basis := int64(forward) + outFee
	inFee := in.inboundBase + basis*in.inboundRate/1_000_000
	total := outFee + inFee
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
	epoch     uint64
}

var sharedKnowledge = struct {
	sync.Mutex
	epoch   uint64
	beliefs map[edgeKey]liquidityBelief
}{
	beliefs: make(map[edgeKey]liquidityBelief),
}

type localEdgeState struct {
	belief   liquidityBelief
	failures int
	lastFail lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	state        map[edgeKey]*localEdgeState
	reserved     map[edgeKey]lnwire.MilliSatoshi
	blocked      map[edgeKey]bool
	committedFee lnwire.MilliSatoshi
	reported     map[*route.Route]bool

	routeFailures  map[string]int
	amountFailures map[string]int
	failureStreak  int
	lastFailedAmt  lnwire.MilliSatoshi
	attempts       int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	sharedKnowledge.Lock()
	sharedKnowledge.epoch++
	epoch := sharedKnowledge.epoch
	sharedKnowledge.Unlock()

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		epoch:          epoch,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		state:         make(map[edgeKey]*localEdgeState),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		blocked:       make(map[edgeKey]bool),
		reported:      make(map[*route.Route]bool),
		routeFailures: make(map[string]int),
		amountFailures: make(map[string]int),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				e := &candidateEdge{
					key:      key,
					chanID:   ch.ChannelID,
					from:     ch.OtherNode,
					to:       node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase: int64(
						ch.InboundFee.BaseFee,
					),
					inboundRate: int64(
						ch.InboundFee.FeeRate,
					),
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.edgeByKey[key] = e
				r.incomingEdges[e.to] = append(
					r.incomingEdges[e.to], e,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedKnowledge.Lock()
	for key, e := range r.edgeByKey {
		b, ok := sharedKnowledge.beliefs[key]
		if !ok {
			b.estimate = e.capacity / 2
		}
		r.state[key] = &localEdgeState{belief: b}
	}
	sharedKnowledge.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.025)
	highMode := 0.5 / (1 + math.Exp((x-0.90)/0.035))
	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	if load > e.capacity {
		return 0.005
	}

	st := r.state[e.key]
	if e.from == r.source {
		if load > r.localBalances[e.chanID] {
			return 0.005
		}
		if st == nil || st.belief.conf <= 0 ||
			st.belief.upperFail == 0 ||
			load < st.belief.upperFail {

			return 0.995
		}

		age := uint64(0)
		if r.epoch > st.belief.epoch {
			age = r.epoch - st.belief.epoch
		}
		conf := st.belief.conf * math.Exp(-float64(age)/5)
		return clampProbability(
			conf*0.025 + (1-conf)*0.995,
		)
	}

	prior := bimodalPrior(load, e.capacity)
	if st == nil || st.belief.conf <= 0 {
		return prior
	}

	b := st.belief
	age := uint64(0)
	if r.epoch > b.epoch {
		age = r.epoch - b.epoch
	}

	conf := b.conf * math.Exp(-float64(age)/14)
	if conf < 0.025 {
		return prior
	}

	activeBounds := age <= 10
	var learned float64

	switch {
	case activeBounds && b.lowerOK > 0 && load <= b.lowerOK:
		learned = 0.995

	case activeBounds && b.upperFail > 0 && load >= b.upperFail:
		learned = 0.015

	default:
		estimate := b.estimate
		if estimate <= 0 {
			estimate = e.capacity / 2
		}

		width := float64(e.capacity) * 0.07
		if width < 1_000_000 {
			width = 1_000_000
		}
		z := (float64(load) - float64(estimate)) / width
		learned = clampProbability(1 / (1 + math.Exp(z)))
	}

	return clampProbability(conf*learned + (1-conf)*prior)
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFee >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFee
}

type searchItem struct {
	node route.Vertex
	cost float64
	amt  lnwire.MilliSatoshi
}

type searchQueue []*searchItem

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].cost < q[j].cost
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchItem))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type routeMeta struct {
	path    []*candidateEdge
	fee     lnwire.MilliSatoshi
	logProb float64
	score   float64
	id      string
}

func (r *candidateRouter) edgePenalty(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	penalty := 0.0
	reserved := r.reserved[e.key]
	if reserved > 0 {
		penalty += 1_400_000
		if e.capacity > 0 {
			penalty += 900_000 *
				float64(reserved) / float64(e.capacity)
		}
	}

	st := r.state[e.key]
	if st == nil || st.failures == 0 {
		return penalty
	}

	unit := 900_000.0
	if st.lastFail > 0 && load*2 < st.lastFail {
		unit = 100_000
	} else if st.lastFail > 0 && load*4 < st.lastFail*3 {
		unit = 300_000
	}

	return penalty + float64(st.failures)*unit
}

func (r *candidateRouter) search(amt lnwire.MilliSatoshi,
	riskScale float64) (*route.Route, *routeMeta, error) {

	best := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	best[r.spec.Target] = 0

	pq := &searchQueue{}
	heap.Push(pq, &searchItem{
		node: r.spec.Target,
		cost: 0,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*searchItem)
		currentBest, ok := best[item.node]
		if !ok || item.cost > currentBest+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		out := next[item.node]
		for _, in := range r.incomingEdges[item.node] {
			if r.blocked[in.key] {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if item.node != r.spec.Target {
				fee = nodeFee(in, out, item.amt)
			}
			if fee > lnwire.MaxMilliSatoshi-item.amt {
				continue
			}

			over := item.amt + fee
			if !in.usable(over) {
				continue
			}

			reserved := r.reserved[in.key]
			if reserved > in.capacity ||
				over > in.capacity-reserved {

				continue
			}

			load := over + reserved
			if in.from == r.source {
				balance := r.localBalances[in.chanID]
				if reserved > balance ||
					over > balance-reserved {

					continue
				}
			}

			p := r.edgeProbability(in, load)
			step := float64(fee) -
				riskScale*math.Log(p) + hopPriceMsat
			step += r.edgePenalty(in, load)
			newCost := item.cost + step

			old, seen := best[in.from]
			if seen && newCost >= old {
				continue
			}

			best[in.from] = newCost
			next[in.from] = in
			heap.Push(pq, &searchItem{
				node: in.from,
				cost: newCost,
				amt:  over,
			})
		}
	}

	if _, ok := best[r.source]; !ok {
		return nil, nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, nil, err
	}

	fee := rt.TotalAmount - amt
	logProb := 0.0
	for i, e := range path {
		over := routeAmountAt(rt, i)
		load := over + r.reserved[e.key]
		logProb += math.Log(r.edgeProbability(e, load))
	}

	return rt, &routeMeta{
		path:    path,
		fee:     fee,
		logProb: logProb,
		id:      routeID(rt),
	}, nil
}

func (r *candidateRouter) findRoute(amt,
	feeCap lnwire.MilliSatoshi) (*route.Route, *routeMeta, error) {

	scales := []float64{
		riskPriceMsat,
		riskPriceMsat / 3,
		0,
		riskPriceMsat * 2,
	}

	var bestRoute *route.Route
	var bestMeta *routeMeta
	seen := make(map[string]bool)

	for _, scale := range scales {
		rt, meta, err := r.search(amt, scale)
		if err != nil {
			continue
		}
		if feeCap != lnwire.MaxMilliSatoshi &&
			meta.fee > feeCap {

			continue
		}

		if seen[meta.id] {
			continue
		}
		seen[meta.id] = true

		meta.score = float64(meta.fee) -
			riskPriceMsat*meta.logProb +
			float64(len(meta.path))*hopPriceMsat

		if bestMeta == nil || meta.score < bestMeta.score {
			bestRoute = rt
			bestMeta = meta
		}
	}

	if bestRoute == nil {
		return nil, nil, errors.New("no route found")
	}

	return bestRoute, bestMeta, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	path := make([]*candidateEdge, 0, 12)
	visited := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, nil, errors.New("routing cycle")
		}
		visited[node] = true

		e, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, e)
		node = e.to
	}

	n := len(path)
	if n == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, n)
	expiryOver := make([]uint32, n)
	amtOver[n-1] = deliver
	expiryOver[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		fee := nodeFee(path[i], path[i+1], amtOver[i+1])
		if fee > lnwire.MaxMilliSatoshi-amtOver[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}
		amtOver[i] = amtOver[i+1] + fee
		expiryOver[i] = expiryOver[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i < n-1 {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      e.to,
			ChannelID:        e.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func ceilDiv(a lnwire.MilliSatoshi, b int) lnwire.MilliSatoshi {
	if b <= 1 {
		return a
	}

	d := lnwire.MilliSatoshi(b)
	return a/d + func() lnwire.MilliSatoshi {
		if a%d != 0 {
			return 1
		}
		return 0
	}()
}

func numParts(remaining, shard lnwire.MilliSatoshi) int {
	if shard <= 0 {
		return 1
	}
	n := int(remaining / shard)
	if remaining%shard != 0 {
		n++
	}
	if n < 1 {
		return 1
	}
	return n
}

func candidateShardAmounts(amt lnwire.MilliSatoshi,
	partsLeft int) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minShard := ceilDiv(amt, partsLeft)
	values := make(map[lnwire.MilliSatoshi]bool)
	add := func(v lnwire.MilliSatoshi) {
		if v < minShard {
			v = minShard
		}
		if v > amt {
			v = amt
		}
		if v > 0 {
			values[v] = true
		}
	}

	add(amt)
	fractions := [][2]int{
		{7, 8},
		{3, 4},
		{2, 3},
		{1, 2},
		{2, 5},
		{1, 3},
		{1, 4},
	}
	for _, fraction := range fractions {
		add(amt * lnwire.MilliSatoshi(fraction[0]) /
			lnwire.MilliSatoshi(fraction[1]))
	}
	for parts := 2; parts <= partsLeft; parts++ {
		add(ceilDiv(amt, parts))
	}

	result := make([]lnwire.MilliSatoshi, 0, len(values))
	for value := range values {
		result = append(result, value)
	}
	sort.Slice(result, func(i, j int) bool {
		return result[i] > result[j]
	})

	return result
}

func routeID(rt *route.Route) string {
	if rt == nil {
		return ""
	}

	var b strings.Builder
	for _, hop := range rt.Hops {
		b.WriteString(strconv.FormatUint(hop.ChannelID, 10))
		b.WriteByte('/')
	}
	return b.String()
}

func amountFailureID(rt *route.Route) string {
	if rt == nil || len(rt.Hops) == 0 {
		return ""
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return routeID(rt) + "#" +
		strconv.FormatInt(int64(delivered), 10)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment complete")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts reached")
	}

	partsLeft := int(r.spec.MaxParts - inFlightHtlcs)
	if partsLeft < 1 {
		return nil, errors.New("maximum parts reached")
	}

	feeBudget := r.remainingFeeBudget()
	amounts := candidateShardAmounts(amt, partsLeft)

	var bestRoute *route.Route
	var bestMeta *routeMeta
	bestScore := math.Inf(1)
	var lastErr error

	for _, shard := range amounts {
		plannedParts := numParts(amt, shard)
		if plannedParts > partsLeft {
			continue
		}

		rt, meta, err := r.findRoute(shard, feeBudget)
		if err != nil {
			lastErr = err
			continue
		}

		failureID := amountFailureID(rt)
		exactFailures := r.amountFailures[failureID]
		if exactFailures >= 4 {
			continue
		}

		planScore := float64(plannedParts) *
			(meta.score + partPriceMsat)

		if feeBudget != lnwire.MaxMilliSatoshi {
			projectedFee := float64(meta.fee) *
				float64(plannedParts)
			if projectedFee > float64(feeBudget) {
				planScore += 6 *
					(projectedFee - float64(feeBudget))
			}
		}

		planScore += float64(r.routeFailures[meta.id]) *
			1_100_000
		planScore += float64(exactFailures) * 1_800_000

		if r.failureStreak > 0 && r.lastFailedAmt > 0 &&
			shard*5 >= r.lastFailedAmt*4 {

			planScore += float64(r.failureStreak) * 1_500_000
		}

		if planScore < bestScore {
			bestScore = planScore
			bestRoute = rt
			bestMeta = meta
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	_ = bestMeta
	r.attempts++
	return bestRoute, nil
}

func routeAmountAt(rt *route.Route, index int) lnwire.MilliSatoshi {
	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func routeEdgeKey(rt *route.Route, index int) edgeKey {
	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}
	return edgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
	}
}

func (r *candidateRouter) saveBelief(key edgeKey,
	b liquidityBelief) {

	if st := r.state[key]; st != nil {
		st.belief = b
	}

	sharedKnowledge.Lock()
	sharedKnowledge.beliefs[key] = b
	sharedKnowledge.Unlock()
}

func (r *candidateRouter) recordSuccess(key edgeKey,
	load lnwire.MilliSatoshi) {

	e := r.edgeByKey[key]
	st := r.state[key]
	if e == nil || st == nil {
		return
	}

	b := st.belief
	if load > b.lowerOK {
		b.lowerOK = load
	}

	highEstimate := e.capacity * 88 / 100
	if load > highEstimate {
		highEstimate = load
	}
	if highEstimate > b.estimate {
		b.estimate = highEstimate
	}
	if b.upperFail > 0 && load >= b.upperFail {
		b.upperFail = 0
	}

	b.conf = 0.92
	b.epoch = r.epoch
	st.failures = 0
	st.lastFail = 0
	r.saveBelief(key, b)
}

func (r *candidateRouter) recordFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	e := r.edgeByKey[key]
	st := r.state[key]
	if e == nil || st == nil {
		return
	}

	st.failures++
	st.lastFail = load

	b := st.belief
	if b.upperFail == 0 || load < b.upperFail {
		b.upperFail = load
	}

	depletedEstimate := load / 5
	if b.estimate == 0 || depletedEstimate < b.estimate {
		b.estimate = depletedEstimate
	}

	if b.lowerOK >= load {
		b.lowerOK = load * 2 / 3
		b.conf = 0.65
	} else {
		b.conf = 0.90
	}
	if e.from == r.source {
		b.conf = 0.72
	}

	b.epoch = r.epoch
	r.saveBelief(key, b)
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			index := i + 1
			if index >= len(rt.Hops) {
				return len(rt.Hops) - 1
			}
			return index
		}
	}

	return -1
}

func (r *candidateRouter) penalizeWholeRoute(rt *route.Route) {
	for i := range rt.Hops {
		key := routeEdgeKey(rt, i)
		if st := r.state[key]; st != nil {
			st.failures++
			st.lastFail = routeAmountAt(rt, i) +
				r.reserved[key]
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if rt == nil || r.reported[rt] {
		return nil
	}
	r.reported[rt] = true

	if result.Failure == nil {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			over := routeAmountAt(rt, i)
			load := over + r.reserved[key]
			r.recordSuccess(key, load)
			r.reserved[key] += over
		}

		delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
		if rt.TotalAmount > delivered {
			r.committedFee += rt.TotalAmount - delivered
		}

		r.failureStreak = 0
		r.lastFailedAmt = 0
		return nil
	}

	id := routeID(rt)
	r.routeFailures[id]++
	r.amountFailures[amountFailureID(rt)]++

	if len(rt.Hops) > 0 {
		r.lastFailedAmt =
			rt.Hops[len(rt.Hops)-1].AmtToForward
	}
	r.failureStreak++

	kind := fmt.Sprintf("%T", result.Failure)
	isLiquidity := strings.Contains(
		kind, "TemporaryChannelFailure",
	)
	isPolicy := strings.Contains(kind, "FeeInsufficient") ||
		strings.Contains(kind, "IncorrectCltvExpiry")

	failIndex := failureEdgeIndex(rt, result.FailureSource)
	if failIndex >= 0 && failIndex < len(rt.Hops) {
		key := routeEdgeKey(rt, failIndex)
		load := routeAmountAt(rt, failIndex) +
			r.reserved[key]

		switch {
		case isLiquidity:
			r.recordFailure(key, load)

		case isPolicy:
			r.blocked[key] = true
			if st := r.state[key]; st != nil {
				st.failures += 4
				st.lastFail = load
			}

		default:
			if st := r.state[key]; st != nil {
				st.failures += 2
				st.lastFail = load
			}
		}

		return nil
	}

	r.penalizeWholeRoute(rt)
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskPriceMsat      = float64(420_000)
	hopCostMsat        = float64(20_000)
	reusedEdgeCostMsat = float64(950_000)
	extraPartCostMsat  = float64(70_000)

	maxSearchHops        = 60
	maxLabelsPerNode     = 10
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 64
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amt <= 0 {
		return e.baseFeeMsat
	}

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

// nodeFee computes the fee charged by the node between in and out. The
// inbound fee is assessed on the forwarded amount plus the node's outbound
// fee. The combined inbound and outbound fee is floored at zero.
func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inboundAmt := int64(amt)
	if outbound > 0 && inboundAmt <= math.MaxInt64-outbound {
		inboundAmt += outbound
	}

	inbound := int64(in.inboundBase) +
		inboundAmt*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	// reserved is the cumulative load from successful shards of this
	// payment. It represents either held atomic shards or liquidity already
	// moved by settled non-atomic shards.
	reserved map[edgeKey]lnwire.MilliSatoshi

	// localUpper is payment-local evidence. Unlike shared beliefs, it is
	// used to force a material amount reduction immediately after failure.
	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	// Evidence remains useful across nearby payments, while gradually
	// becoming soft enough for a moving network to contradict it.
	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		// Failure bounds are deliberately soft. A concurrent shard or
		// another payment may have caused a temporary depletion.
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	cutoff := upper * 3 / 4
	if r.localFails[key] >= 2 {
		cutoff = upper * 3 / 5
	}
	if r.localFails[key] >= 4 {
		cutoff = upper / 2
	}
	if cutoff <= 0 {
		cutoff = 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}
	if feeCap == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	now := r.view.Now()
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			totalLoad := over + reserved
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)

			if edge.from == r.source {
				// The local snapshot plus our reservation ledger makes the
				// first hop much more certain than an unknown remote edge.
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.80
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				riskPriceMsat*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	if len(weights) == 0 || total < lnwire.MilliSatoshi(len(weights)) {
		return nil
	}

	var sum int64
	for _, weight := range weights {
		if weight <= 0 {
			return nil
		}
		sum += weight
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}

		part := remaining *
			lnwire.MilliSatoshi(weight) /
			lnwire.MilliSatoshi(remainingWeight)

		minTail := lnwire.MilliSatoshi(len(weights) - i - 1)
		if part <= 0 {
			part = 1
		}
		if part > remaining-minTail {
			part = remaining - minTail
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func sameAllocation(a, b []lnwire.MilliSatoshi) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}

	return true
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	if parts <= 0 || total < lnwire.MilliSatoshi(parts) {
		return nil
	}

	var patterns [][]lnwire.MilliSatoshi
	add := func(weights []int64) {
		allocation := weightedAllocation(total, weights)
		if allocation == nil {
			return
		}
		for _, old := range patterns {
			if sameAllocation(old, allocation) {
				return
			}
		}
		patterns = append(patterns, allocation)
	}

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}
	add(equal)

	if parts == 1 {
		return patterns
	}

	ascending := make([]int64, parts)
	descending := make([]int64, parts)
	for i := 0; i < parts; i++ {
		ascending[i] = int64(i + 1)
		descending[i] = int64(parts - i)
	}
	add(ascending)
	add(descending)

	// Rotate one dominant shard through the plan. This captures unequal
	// parallel corridors and, importantly, tries both cheap-first and
	// expensive-first fee-budget orderings.
	for _, dominant := range []int64{3, 6} {
		for pos := 0; pos < parts; pos++ {
			weights := make([]int64, parts)
			for i := range weights {
				weights[i] = 1
			}
			weights[pos] = dominant
			add(weights)
		}
	}

	// Geometric shapes cover public maximum-HTLC ceilings that do not line
	// up with equal halves.
	if parts <= 6 {
		for shift := 0; shift < parts; shift++ {
			weights := make([]int64, parts)
			weight := int64(1)
			for i := 0; i < parts; i++ {
				weights[(i+shift)%parts] = weight
				if weight < 8 {
					weight *= 2
				}
			}
			add(weights)
		}
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi,
	reserveBudget bool) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remainingAmount := lnwire.MilliSatoshi(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		shardCap := remainingBudget

		// Try both exact flexible accounting and a proportional mode. The
		// former permits unequal base fees; the latter prevents an early
		// shard from consuming a budget needed to complete the route set.
		if reserveBudget &&
			remainingBudget != lnwire.MaxMilliSatoshi &&
			remainingAmount > shard {

			shardCap = remainingBudget * shard / remainingAmount
			allowance := remainingBudget / 20
			if allowance > 25_000 {
				allowance = 25_000
			}
			if shardCap <= remainingBudget-allowance {
				shardCap += allowance
			} else {
				shardCap = remainingBudget
			}
		}

		pr, err := r.findRoute(shard, reservations, shardCap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat

	return plan, totalScore, true
}

func addShardCandidate(dst *[]lnwire.MilliSatoshi,
	amt, total lnwire.MilliSatoshi) {

	if amt <= 0 || amt >= total {
		return
	}
	for _, old := range *dst {
		if old == amt {
			return
		}
	}

	*dst = append(*dst, amt)
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	slots uint32, feeBudget lnwire.MilliSatoshi) (*plannedRoute, error) {

	if slots <= 1 {
		return nil, errors.New("no route found")
	}

	var candidates []lnwire.MilliSatoshi
	addShardCandidate(&candidates, total*7/8, total)
	addShardCandidate(&candidates, total*3/4, total)
	addShardCandidate(&candidates, total*2/3, total)
	addShardCandidate(&candidates, total/2, total)

	average := (total + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)
	addShardCandidate(&candidates, average, total)
	addShardCandidate(&candidates, average*3/4, total)
	addShardCandidate(&candidates, average/2, total)

	for shard := total / 3; shard >= 10_000; shard = shard * 2 / 3 {
		addShardCandidate(&candidates, shard, total)
		next := shard * 2 / 3
		if next >= shard {
			break
		}
	}

	sort.Slice(candidates, func(i, j int) bool {
		return candidates[i] > candidates[j]
	})

	var best *plannedRoute
	bestUtility := math.Inf(1)

	for _, shard := range candidates {
		pr, err := r.findRoute(shard, r.reserved, feeBudget)
		if err != nil {
			continue
		}

		// Prefer progress when an exact route set is unavailable, while
		// retaining enough cost pressure to reject an extreme detour.
		progressCredit := 0.00035 * float64(shard)
		utility := pr.score - progressCredit
		if utility < bestUtility {
			best = pr
			bestUtility = utility
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	return best, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	if feeBudget == 0 {
		return nil, errors.New("fee budget exhausted")
	}

	var best []*plannedRoute
	bestScore := math.Inf(1)

	maxParts := int(slots)
	if total < lnwire.MilliSatoshi(maxParts) {
		maxParts = int(total)
	}

	for parts := 1; parts <= maxParts; parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			for _, reserveBudget := range []bool{false, true} {
				plan, score, ok := r.tryAllocation(
					allocation, feeBudget, reserveBudget,
				)
				if ok && score < bestScore {
					best = plan
					bestScore = score
				}
			}
		}
	}

	if len(best) > 0 {
		return best, nil
	}

	pr, err := r.fallbackShard(total, slots, feeBudget)
	if err != nil {
		return nil, err
	}

	return []*plannedRoute{pr}, nil
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			// A forwarding node reports a failure of its outgoing edge.
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.30

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.recordLocalFailure(edge.key, meta.loads[failIdx])

			count := r.localFails[edge.key]
			r.edgePenalty[edge.key] +=
				300_000 + float64(count)*175_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			// These indicate a deterministic mismatch with the advertised
			// outgoing policy for this payment.
			r.blocked[edge.key] = true
			r.edgePenalty[edge.key] += 8_000_000

			// A fee failure can also involve the inbound policy on the
			// preceding edge. Penalize that edge without permanently
			// blocking it, since it may work with another outgoing edge.
			if code == lnwire.CodeFeeInsufficient && failIdx > 0 {
				prev := meta.path[failIdx-1]
				r.edgePenalty[prev.key] += 2_000_000
			}

		default:
			r.edgePenalty[edge.key] += 2_000_000
		}

		return nil
	}

	// An unknown failure source may be a dispatch refusal or another
	// failure that never established which channel lacked liquidity. Do
	// not invent a hard liquidity bound for the first edge.
	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 650_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskPriceMsat      = float64(420_000)
	hopCostMsat        = float64(70_000)
	reusedEdgeCostMsat = float64(1_200_000)
	extraPartCostMsat  = float64(55_000)

	maxSearchHops        = 40
	maxLabelsPerNode     = 18
	maxRouterAttempts    = 72
	maxConsecutiveMisses = 64
	maxBoundRelaxations  = 3
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amt <= 0 {
		return e.baseFeeMsat
	}

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inboundBasis := int64(amt) + outbound
	inbound := int64(in.inboundBase) +
		inboundBasis*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved map[edgeKey]lnwire.MilliSatoshi

	localUpper  map[edgeKey]lnwire.MilliSatoshi
	localFails  map[edgeKey]int
	blocked     map[edgeKey]bool
	edgePenalty map[edgeKey]float64

	issued map[*route.Route]*routeMeta
	plan   []*plannedRoute

	committedFees lnwire.MilliSatoshi

	attempts          int
	consecutiveMisses int
	boundRelaxations  int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localUpper:     make(map[edgeKey]lnwire.MilliSatoshi),
		localFails:     make(map[edgeKey]int),
		blocked:        make(map[edgeKey]bool),
		edgePenalty:    make(map[edgeKey]float64),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		pos := float64(b.upperBad-amt) /
			float64(b.upperBad-b.lowerOK)
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}

	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		minFeeIdx := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[minFeeIdx].fee {
				minFeeIdx = i
			}
		}

		worst := -1
		for i := range kept {
			if i == minFeeIdx {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)

			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}

	return dst
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}

	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) retryCutoff(key edgeKey) lnwire.MilliSatoshi {
	upper := r.localUpper[key]
	if upper <= 0 {
		return 0
	}

	var cutoff lnwire.MilliSatoshi
	switch {
	case r.localFails[key] >= 3:
		cutoff = upper / 3
	case r.localFails[key] == 2:
		cutoff = upper / 2
	default:
		cutoff = upper * 2 / 3
	}

	if cutoff <= 0 {
		return 1
	}

	return cutoff
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	now := r.view.Now()
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.blocked[edge.key] || containsNode(cur, edge.from) {
				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)

			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			totalLoad := over + reserved
			if totalLoad < over || totalLoad > edge.capacity {
				continue
			}

			cutoff := r.retryCutoff(edge.key)
			if cutoff > 0 && totalLoad >= cutoff {
				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.995
				if r.localUpper[edge.key] > 0 {
					p = 0.80
				}
			}

			score := cur.score +
				float64(nodeCharge) +
				riskPriceMsat*(-math.Log(p)) +
				hopCostMsat +
				r.edgePenalty[edge.key]

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.55
				}

				loadFraction := float64(totalLoad) /
					math.Max(1, float64(edge.capacity))
				score += reuse * (1 + loadFraction)
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}

		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		loads[i] = amounts[i] + reservations[edge.key]
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}

	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func proportionalAmount(total lnwire.MilliSatoshi,
	weight, sum int64) lnwire.MilliSatoshi {

	if total <= 0 || weight <= 0 || sum <= 0 {
		return 0
	}

	q := total / lnwire.MilliSatoshi(sum)
	rem := total % lnwire.MilliSatoshi(sum)

	return q*lnwire.MilliSatoshi(weight) +
		rem*lnwire.MilliSatoshi(weight)/lnwire.MilliSatoshi(sum)
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	var sum int64
	for _, weight := range weights {
		if weight > 0 {
			sum += weight
		}
	}

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	remainingWeight := sum

	for i, weight := range weights {
		if i == len(weights)-1 {
			result[i] = remaining
			break
		}
		if weight <= 0 || remainingWeight <= 0 {
			return nil
		}

		part := proportionalAmount(remaining, weight, remainingWeight)
		if part <= 0 {
			part = 1
		}
		if part >= remaining {
			part = remaining - 1
		}
		if part <= 0 {
			return nil
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func allocationPatterns(total lnwire.MilliSatoshi,
	parts int) [][]lnwire.MilliSatoshi {

	if parts <= 0 || total < lnwire.MilliSatoshi(parts) {
		return nil
	}

	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}

	patterns := [][]lnwire.MilliSatoshi{
		weightedAllocation(total, equal),
	}

	switch parts {
	case 2:
		for _, weights := range [][]int64{
			{40, 60}, {60, 40},
			{30, 70}, {70, 30},
			{20, 80}, {80, 20},
			{10, 90}, {90, 10},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 3:
		for _, weights := range [][]int64{
			{20, 30, 50},
			{50, 30, 20},
			{15, 25, 60},
			{60, 25, 15},
			{10, 30, 60},
			{60, 30, 10},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	case 4:
		for _, weights := range [][]int64{
			{10, 15, 25, 50},
			{50, 25, 15, 10},
			{15, 20, 25, 40},
			{40, 25, 20, 15},
			{10, 20, 30, 40},
			{40, 30, 20, 10},
		} {
			patterns = append(
				patterns, weightedAllocation(total, weights),
			)
		}

	default:
		ascending := make([]int64, parts)
		descending := make([]int64, parts)

		for i := 0; i < parts; i++ {
			ascending[i] = int64(i + 1)
			descending[i] = int64(parts - i)
		}

		patterns = append(
			patterns,
			weightedAllocation(total, ascending),
			weightedAllocation(total, descending),
		)
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		if shard <= 0 {
			return nil, 0, false
		}

		pr, err := r.findRoute(shard, reservations, remainingBudget)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat
	return plan, totalScore, true
}

type amountFraction struct {
	num int64
	den int64
}

func amountProbes(limit lnwire.MilliSatoshi) []lnwire.MilliSatoshi {
	fractions := []amountFraction{
		{1, 1},
		{7, 8},
		{3, 4},
		{2, 3},
		{3, 5},
		{1, 2},
		{2, 5},
		{1, 3},
		{1, 4},
		{1, 5},
		{1, 6},
		{1, 8},
		{1, 10},
		{1, 12},
		{1, 16},
		{1, 24},
		{1, 32},
		{1, 48},
		{1, 64},
	}

	seen := make(map[lnwire.MilliSatoshi]struct{})
	result := make([]lnwire.MilliSatoshi, 0, len(fractions)+1)

	for _, fraction := range fractions {
		amt := proportionalAmount(limit, fraction.num, fraction.den)
		if amt <= 0 {
			amt = 1
		}
		if amt > limit {
			amt = limit
		}
		if _, ok := seen[amt]; ok {
			continue
		}

		seen[amt] = struct{}{}
		result = append(result, amt)
	}

	if _, ok := seen[1]; !ok {
		result = append(result, 1)
	}

	sort.Slice(result, func(i, j int) bool {
		return result[i] > result[j]
	})

	return result
}

func (r *candidateRouter) findLargestRoute(
	limit lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) (*plannedRoute,
	lnwire.MilliSatoshi, error) {

	if limit <= 0 {
		return nil, 0, errors.New("invalid shard limit")
	}

	var failedAbove lnwire.MilliSatoshi

	for _, probe := range amountProbes(limit) {
		pr, err := r.findRoute(probe, reservations, feeBudget)
		if err != nil {
			failedAbove = probe
			continue
		}

		best := pr
		bestAmt := probe

		if failedAbove > probe+1 {
			low := probe
			high := failedAbove - 1

			for iteration := 0; iteration < 6 && low < high; iteration++ {
				mid := low + (high-low+1)/2
				candidate, findErr := r.findRoute(
					mid, reservations, feeBudget,
				)
				if findErr != nil {
					high = mid - 1
					continue
				}

				low = mid
				bestAmt = mid
				best = candidate
			}
		}

		return best, bestAmt, nil
	}

	return nil, 0, errors.New("no shard route found")
}

func (r *candidateRouter) tryGreedyPlan(total lnwire.MilliSatoshi,
	partLimit int, firstFraction amountFraction,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	if total <= 0 || partLimit <= 0 {
		return nil, 0, false
	}

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	remaining := total
	plan := make([]*plannedRoute, 0, partLimit)
	totalScore := float64(0)

	for part := 0; part < partLimit && remaining > 0; part++ {
		partsLeft := partLimit - part

		if partsLeft == 1 {
			pr, err := r.findRoute(
				remaining, reservations, remainingBudget,
			)
			if err != nil {
				return nil, 0, false
			}

			if remainingBudget != lnwire.MaxMilliSatoshi {
				if pr.meta.fee > remainingBudget {
					return nil, 0, false
				}
				remainingBudget -= pr.meta.fee
			}

			plan = append(plan, pr)
			totalScore += pr.score
			addReservationSet(reservations, pr.meta)
			remaining = 0
			break
		}

		maxLimit := remaining -
			lnwire.MilliSatoshi(partsLeft-1)
		if maxLimit <= 0 {
			return nil, 0, false
		}

		maxRoute, maxAmount, err := r.findLargestRoute(
			maxLimit, reservations, remainingBudget,
		)
		if err != nil {
			return nil, 0, false
		}

		shard := maxAmount
		if part == 0 && firstFraction.den > 0 {
			scaled := proportionalAmount(
				maxAmount,
				firstFraction.num,
				firstFraction.den,
			)
			if scaled > 0 && scaled < shard {
				shard = scaled
			}
		}

		var pr *plannedRoute
		if shard == maxAmount {
			pr = maxRoute
		} else {
			pr, err = r.findRoute(
				shard, reservations, remainingBudget,
			)
			if err != nil {
				pr = maxRoute
				shard = maxAmount
			}
		}

		if shard <= 0 || shard >= remaining {
			if shard == remaining {
				plan = append(plan, pr)
				totalScore += pr.score
				remaining = 0
				break
			}

			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remaining -= shard
	}

	if remaining != 0 || len(plan) == 0 {
		return nil, 0, false
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat
	return plan, totalScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	feeBudget := r.remainingFeeBudget()
	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := 1; parts <= int(slots); parts++ {
		for _, allocation := range allocationPatterns(total, parts) {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	greedyFractions := []amountFraction{
		{1, 1},
		{4, 5},
		{3, 4},
		{2, 3},
		{3, 5},
		{1, 2},
		{2, 5},
		{1, 3},
	}

	for parts := 2; parts <= int(slots); parts++ {
		for _, fraction := range greedyFractions {
			plan, score, ok := r.tryGreedyPlan(
				total, parts, fraction, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) == 0 {
		return nil, errors.New("no route found")
	}

	return best, nil
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}

	return total
}

func (r *candidateRouter) relaxLocalBounds() bool {
	if r.boundRelaxations >= maxBoundRelaxations ||
		len(r.localUpper) == 0 {

		return false
	}

	for key := range r.localUpper {
		delete(r.localUpper, key)
		delete(r.localFails, key)
	}
	r.boundRelaxations++
	return true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("attempt limit reached")
	}
	if r.consecutiveMisses >= maxConsecutiveMisses {
		return nil, errors.New("no progress after repeated failures")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}

	slots := maxParts - inFlightHtlcs

	if len(r.plan) > 0 {
		if queuedAmount(r.plan) != amt ||
			uint32(len(r.plan)) > slots {

			r.plan = nil
		}
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil && r.relaxLocalBounds() {
			plan, err = r.makePlan(amt, slots)
		}
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+r.reserved[key])
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	load lnwire.MilliSatoshi) {

	if load <= 0 {
		return
	}

	upper := r.localUpper[key]
	if upper == 0 || load < upper {
		r.localUpper[key] = load
	}
	r.localFails[key]++
}

func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	result routing.SimHtlcResult) int {

	if rt == nil {
		return -1
	}
	if result.FailureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.25

			if upper := r.localUpper[edge.key];
				upper > 0 && meta.loads[i] >= upper {

				delete(r.localUpper, edge.key)
				delete(r.localFails, edge.key)
			}
		}

		r.committedFees += meta.fee
		r.consecutiveMisses = 0
		return nil
	}

	r.plan = nil
	r.consecutiveMisses++

	code := result.Failure.Code()
	failIdx := r.failureEdgeIndex(rt, result)

	if failIdx < 0 &&
		code == lnwire.CodeTemporaryChannelFailure &&
		len(meta.path) > 0 {

		failIdx = 0
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}

	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
		r.edgePenalty[meta.path[i].key] *= 0.75
	}

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.recordLocalFailure(edge.key, meta.loads[failIdx])

			count := r.localFails[edge.key]
			r.edgePenalty[edge.key] +=
				425_000 + float64(count)*275_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.blocked[edge.key] = true
			r.edgePenalty[edge.key] += 10_000_000

		default:
			r.edgePenalty[edge.key] += 2_500_000
		}

		return nil
	}

	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 800_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCLTV   = uint32(40)
	candidateRiskPrice   = 420000.0
	candidateHopPrice    = 7000.0
	candidateReuseNats   = 1.85
	candidateMinShard    = lnwire.MilliSatoshi(10000)
	candidateProbFloor   = 0.012
	candidateProbCeiling = 0.995
	candidateLabelLimit  = 16
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat int64
	feeRatePPM  int64
	cltvDelta   uint16
	minHTLC     lnwire.MilliSatoshi
	maxHTLC     lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func (e *candidateEdge) outgoingFee(amt lnwire.MilliSatoshi) int64 {
	fee := e.baseFeeMsat + int64(amt)*e.feeRatePPM/1_000_000
	if fee < 0 {
		return 0
	}
	return fee
}

func candidateForwardingFee(incoming, outgoing *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if incoming == nil || outgoing == nil {
		return 0
	}

	outFee := outgoing.outgoingFee(amt)
	inBasis := int64(amt) + outFee
	inFee := incoming.inboundBase +
		inBasis*incoming.inboundRate/1_000_000

	total := outFee + inFee
	if total < 0 {
		total = 0
	}

	return lnwire.MilliSatoshi(total)
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	success  uint32
	failure  uint32
}

var candidateSharedBeliefs = struct {
	sync.Mutex
	m map[candidateEdgeKey]candidateBelief
}{
	m: make(map[candidateEdgeKey]candidateBelief),
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return candidateProbFloor
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.045)
	highMode := 0.5 / (1 + math.Exp((x-0.94)/0.035))
	p := lowMode + highMode

	if p < candidateProbFloor {
		return candidateProbFloor
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	prior := candidatePrior(load, e.capacity)

	candidateSharedBeliefs.Lock()
	belief, ok := candidateSharedBeliefs.m[e.key]
	candidateSharedBeliefs.Unlock()

	if !ok {
		return prior
	}

	if belief.lowerOK > 0 && load <= belief.lowerOK {
		return candidateProbCeiling
	}

	if belief.upperBad > 0 && load >= belief.upperBad {
		p := prior * 0.10
		if p < candidateProbFloor {
			p = candidateProbFloor
		}
		return p
	}

	var learned, confidence float64

	switch {
	case belief.lowerOK > 0 && belief.upperBad > belief.lowerOK:
		mid := 0.5 * float64(belief.lowerOK+belief.upperBad)
		width := math.Max(
			float64(belief.upperBad-belief.lowerOK)*0.20,
			float64(e.capacity)*0.012,
		)
		learned = 1 / (1 + math.Exp(
			(float64(load)-mid)/width,
		))
		confidence = 0.88

	case belief.upperBad > 0:
		width := math.Max(
			float64(belief.upperBad)*0.16,
			float64(e.capacity)*0.018,
		)
		learned = 1 / (1 + math.Exp(
			(float64(load)-float64(belief.upperBad))/width,
		))
		confidence = 0.72

	case belief.lowerOK > 0:
		excess := float64(load-belief.lowerOK) /
			math.Max(float64(e.capacity), 1)
		learned = candidateProbCeiling * math.Exp(-excess/0.14)
		confidence = 0.64

	default:
		return prior
	}

	p := confidence*learned + (1-confidence)*prior
	if p < candidateProbFloor {
		return candidateProbFloor
	}
	if p > candidateProbCeiling {
		return candidateProbCeiling
	}
	return p
}

func candidateRecordSuccess(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	b := candidateSharedBeliefs.m[key]
	if load > b.lowerOK {
		b.lowerOK = load
	}
	b.success++

	if b.upperBad > 0 && b.lowerOK >= b.upperBad {
		b.upperBad = b.lowerOK + 1
	}

	candidateSharedBeliefs.m[key] = b
}

func candidateRecordFailure(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	b := candidateSharedBeliefs.m[key]
	if b.upperBad == 0 || load < b.upperBad {
		b.upperBad = load
	}
	b.failure++

	candidateSharedBeliefs.m[key] = b
}

type candidateFailurePenalty struct {
	amount lnwire.MilliSatoshi
	count  uint32
}

type candidateSearchItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   int
	path   []*candidateEdge
	index  int
}

type candidateSearchQueue []*candidateSearchItem

func (q candidateSearchQueue) Len() int {
	return len(q)
}

func (q candidateSearchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateSearchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateSearchQueue) Push(x any) {
	item := x.(*candidateSearchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateSearchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	*q = old[:n-1]
	return item
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[candidateEdgeKey]*candidateEdge
	local    map[uint64]lnwire.MilliSatoshi

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	issued   map[*route.Route]bool
	failures map[candidateEdgeKey]candidateFailurePenalty
	banned   map[candidateEdgeKey]bool

	plan          []*route.Route
	committedFees lnwire.MilliSatoshi
	numFailures   uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:   source,
		spec:     spec,
		incoming: make(map[route.Vertex][]*candidateEdge),
		edges:    make(map[candidateEdgeKey]*candidateEdge),
		local:    localBalances,
		reserved: make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		issued:   make(map[*route.Route]bool),
		failures: make(map[candidateEdgeKey]candidateFailurePenalty),
		banned:   make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:      key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: int64(policy.FeeBaseMSat),
					feeRatePPM: int64(
						policy.FeeProportionalMillionths,
					),
					cltvDelta: policy.TimeLockDelta,
					minHTLC:   policy.MinHTLC,
					inboundBase: int64(
						ch.InboundFee.BaseFee,
					),
					inboundRate: int64(
						ch.InboundFee.FeeRate,
					),
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incoming[node] = append(
					r.incoming[node], edge,
				)
				r.edges[key] = edge

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateAdd(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b > 0 && a > lnwire.MaxMilliSatoshi-b {
		return lnwire.MaxMilliSatoshi
	}
	return a + b
}

func (r *candidateRouter) budgetLeft() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) routeFee(
	rt *route.Route) lnwire.MilliSatoshi {

	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	if rt.TotalAmount <= delivered {
		return 0
	}

	return rt.TotalAmount - delivered
}

func (r *candidateRouter) routeAmount(
	rt *route.Route) lnwire.MilliSatoshi {

	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidatePathContains(path []*candidateEdge,
	node route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == node || edge.key.to == node {
			return true
		}
	}
	return false
}

func candidateAcceptLabel(labels map[route.Vertex][]float64,
	node route.Vertex, score float64) bool {

	current := labels[node]
	if len(current) < candidateLabelLimit {
		labels[node] = append(current, score)
		return true
	}

	worstIndex := 0
	for i := 1; i < len(current); i++ {
		if current[i] > current[worstIndex] {
			worstIndex = i
		}
	}

	if score >= current[worstIndex] {
		return false
	}

	current[worstIndex] = score
	labels[node] = current
	return true
}

func candidateLabelLive(labels map[route.Vertex][]float64,
	node route.Vertex, score float64) bool {

	current := labels[node]
	if len(current) < candidateLabelLimit {
		return true
	}

	worst := current[0]
	for _, value := range current[1:] {
		if value > worst {
			worst = value
		}
	}

	return score <= worst+0.0001
}

func (r *candidateRouter) failurePenalty(key candidateEdgeKey,
	load lnwire.MilliSatoshi) float64 {

	failure, ok := r.failures[key]
	if !ok || failure.amount <= 0 {
		return 0
	}

	ratio := float64(load) / float64(failure.amount)
	base := 0.72 + 0.30*float64(failure.count)
	if base > 3.2 {
		base = 3.2
	}

	switch {
	case ratio <= 0.50:
		return base * 0.025
	case ratio < 0.82:
		x := (ratio - 0.50) / 0.32
		return base * (0.025 + 0.30*x*x)
	case ratio < 1:
		x := (ratio - 0.82) / 0.18
		return base * (0.325 + 0.675*x)
	default:
		return base
	}
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi,
	maxFee lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("invalid shard amount")
	}

	labels := make(map[route.Vertex][]float64)
	labels[r.spec.Target] = []float64{0}

	pq := &candidateSearchQueue{}
	heap.Push(pq, &candidateSearchItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateSearchItem)
		if !candidateLabelLive(labels, item.node, item.score) {
			continue
		}

		if item.node == r.source {
			rt, err := r.buildRoute(item.path, deliver)
			if err != nil {
				return nil, 0, err
			}
			if r.routeFee(rt) > maxFee {
				continue
			}

			quality := 1.0
			if item.hops > 0 {
				quality = math.Exp(
					-item.risk / float64(item.hops),
				)
			}
			return rt, quality, nil
		}

		var outgoing *candidateEdge
		if len(item.path) > 0 {
			outgoing = item.path[0]
		}

		for _, incoming := range r.incoming[item.node] {
			if r.banned[incoming.key] {
				continue
			}
			if candidatePathContains(
				item.path, incoming.key.from,
			) {
				continue
			}

			amountOver := item.amount
			if item.node != r.spec.Target {
				amountOver = candidateAdd(
					amountOver,
					candidateForwardingFee(
						incoming, outgoing, item.amount,
					),
				)
			}

			if !incoming.usable(amountOver) {
				continue
			}

			if maxFee != lnwire.MaxMilliSatoshi &&
				amountOver-deliver > maxFee {

				continue
			}

			load := candidateAdd(
				amountOver, r.reserved[incoming.key],
			)
			if extra != nil {
				load = candidateAdd(load, extra[incoming.key])
			}
			if load > incoming.capacity {
				continue
			}

			var probability float64
			if incoming.key.from == r.source {
				balance, ok := r.local[incoming.key.chanID]
				if !ok || load > balance {
					continue
				}
				probability = 0.999
			} else {
				probability = candidateProbability(
					incoming, load,
				)
			}

			risk := -math.Log(probability)
			penalty := r.failurePenalty(incoming.key, load)
			reuse := 0.0
			if r.reserved[incoming.key] > 0 ||
				(extra != nil && extra[incoming.key] > 0) {

				reuse = candidateReuseNats
			}

			feeIncrement := float64(amountOver - item.amount)
			newScore := item.score + feeIncrement +
				candidateRiskPrice*(risk+penalty+reuse) +
				candidateHopPrice

			if !candidateAcceptLabel(
				labels, incoming.key.from, newScore,
			) {
				continue
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = incoming
			copy(path[1:], item.path)

			heap.Push(pq, &candidateSearchItem{
				node:   incoming.key.from,
				amount: amountOver,
				score:  newScore,
				risk:   item.risk + risk,
				hops:   item.hops + 1,
				path:   path,
			})
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = deliver
	expiries[n-1] = candidateFinalCLTV

	for i := n - 2; i >= 0; i-- {
		fee := candidateForwardingFee(
			path[i], path[i+1], amounts[i+1],
		)
		amounts[i] = candidateAdd(amounts[i+1], fee)
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].cltvDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := deliver
		expiry := candidateFinalCLTV
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) forEachRouteEdge(rt *route.Route,
	fn func(candidateEdgeKey, lnwire.MilliSatoshi, int)) {

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		fn(key, amount, i)
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) addVirtualReservation(
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		reserved[key] = candidateAdd(reserved[key], amount)
	})
}

func (r *candidateRouter) reserveIssued(rt *route.Route) {
	if r.issued[rt] {
		return
	}

	r.issued[rt] = true
	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		r.reserved[key] = candidateAdd(
			r.reserved[key], amount,
		)
	})
}

func (r *candidateRouter) releaseIssued(rt *route.Route) {
	if !r.issued[rt] {
		return
	}

	delete(r.issued, rt)
	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		current := r.reserved[key]
		if current <= amount {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = current - amount
		}
	})
}

func candidateAppendAmount(values []lnwire.MilliSatoshi,
	value, minimum, maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 {
		return values
	}

	for _, existing := range values {
		if existing == value {
			return values
		}
	}

	return append(values, value)
}

func (r *candidateRouter) tryPlan(amount lnwire.MilliSatoshi,
	parts, biasNum, biasDen int) ([]*route.Route, bool, float64) {

	if parts < 1 || biasNum < 1 || biasDen < 1 {
		return nil, false, 0
	}

	remaining := amount
	virtual := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	plannedFees := lnwire.MilliSatoshi(0)
	plan := make([]*route.Route, 0, parts)
	planScore := 0.0

	for i := 0; i < parts; i++ {
		left := parts - i
		minimumLater := candidateMinShard *
			lnwire.MilliSatoshi(left-1)

		if remaining < candidateMinShard*
			lnwire.MilliSatoshi(left) {

			return nil, false, 0
		}

		if left == 1 {
			maxFee := r.budgetLeft()
			if maxFee != lnwire.MaxMilliSatoshi {
				if plannedFees >= maxFee {
					maxFee = 0
				} else {
					maxFee -= plannedFees
				}
			}

			rt, quality, err := r.findRoute(
				remaining, virtual, maxFee,
			)
			if err != nil {
				return nil, false, 0
			}

			fee := r.routeFee(rt)
			plan = append(plan, rt)
			plannedFees = candidateAdd(plannedFees, fee)
			planScore += float64(fee) +
				candidateRiskPrice*
					(-math.Log(quality))*
					float64(len(rt.Hops))
			remaining = 0
			continue
		}

		base := remaining / lnwire.MilliSatoshi(left)
		maximum := remaining - minimumLater
		target := base * lnwire.MilliSatoshi(biasNum) /
			lnwire.MilliSatoshi(biasDen)

		var amounts []lnwire.MilliSatoshi
		amounts = candidateAppendAmount(
			amounts, target, candidateMinShard, maximum,
		)
		amounts = candidateAppendAmount(
			amounts, base+base/4,
			candidateMinShard, maximum,
		)
		amounts = candidateAppendAmount(
			amounts, base, candidateMinShard, maximum,
		)
		amounts = candidateAppendAmount(
			amounts, base*3/4,
			candidateMinShard, maximum,
		)
		amounts = candidateAppendAmount(
			amounts, base/2,
			candidateMinShard, maximum,
		)

		var selected *route.Route
		selectedQuality := 0.0

		for _, shard := range amounts {
			maxFee := r.budgetLeft()
			if maxFee != lnwire.MaxMilliSatoshi {
				if plannedFees >= maxFee {
					maxFee = 0
				} else {
					maxFee -= plannedFees
				}
			}

			rt, quality, err := r.findRoute(
				shard, virtual, maxFee,
			)
			if err != nil {
				continue
			}

			selected = rt
			selectedQuality = quality
			break
		}

		if selected == nil {
			return nil, false, 0
		}

		fee := r.routeFee(selected)
		if r.budgetLeft() != lnwire.MaxMilliSatoshi &&
			plannedFees+fee > r.budgetLeft() {

			return nil, false, 0
		}

		plan = append(plan, selected)
		plannedFees = candidateAdd(plannedFees, fee)
		planScore += float64(fee) +
			candidateRiskPrice*
				(-math.Log(selectedQuality))*
				float64(len(selected.Hops))

		r.addVirtualReservation(virtual, selected)
		remaining -= r.routeAmount(selected)
	}

	return plan, remaining == 0, planScore
}

func (r *candidateRouter) bestPlan(amount lnwire.MilliSatoshi,
	parts int) ([]*route.Route, bool) {

	biases := [][2]int{
		{3, 2},
		{5, 4},
		{1, 1},
		{3, 4},
	}

	var best []*route.Route
	bestScore := math.Inf(1)

	for _, bias := range biases {
		plan, ok, score := r.tryPlan(
			amount, parts, bias[0], bias[1],
		)
		if !ok {
			continue
		}

		if score < bestScore {
			best = plan
			bestScore = score
		}
	}

	return best, best != nil
}

func (r *candidateRouter) makePlan(amount lnwire.MilliSatoshi,
	slots uint32) ([]*route.Route, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts already in flight")
	}

	full, quality, fullErr := r.findRoute(
		amount, nil, r.budgetLeft(),
	)

	if slots == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	preferred := 1
	switch {
	case fullErr != nil:
		preferred = 2
	case quality < 0.48:
		preferred = 3
	case quality < 0.68:
		preferred = 2
	case amount >= 300_000_000 && quality < 0.78:
		preferred = 2
	}

	if r.numFailures > 0 && preferred < 2 {
		preferred = 2
	}
	if r.numFailures >= 3 && preferred < 3 {
		preferred = 3
	}
	if preferred > int(slots) {
		preferred = int(slots)
	}

	if preferred == 1 && fullErr == nil {
		return []*route.Route{full}, nil
	}

	for parts := preferred; parts <= int(slots); parts++ {
		plan, ok := r.bestPlan(amount, parts)
		if ok {
			return plan, nil
		}
	}

	if fullErr == nil {
		return []*route.Route{full}, nil
	}

	shard := amount / lnwire.MilliSatoshi(slots)
	if shard < candidateMinShard {
		shard = candidateMinShard
	}

	for shard >= candidateMinShard {
		rt, _, err := r.findRoute(
			shard, nil, r.budgetLeft(),
		)
		if err == nil {
			return []*route.Route{rt}, nil
		}

		if shard == candidateMinShard {
			break
		}

		shard = shard * 2 / 3
		if shard < candidateMinShard {
			shard = candidateMinShard
		}
	}

	return nil, fullErr
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	for {
		if len(r.plan) == 0 {
			maxParts := r.spec.MaxParts
			if maxParts == 0 {
				maxParts = 1
			}
			if inFlightHtlcs >= maxParts {
				return nil, errors.New(
					"maximum parts already in flight",
				)
			}

			plan, err := r.makePlan(
				amt, maxParts-inFlightHtlcs,
			)
			if err != nil {
				return nil, err
			}
			r.plan = plan
		}

		rt := r.plan[0]
		r.plan = r.plan[1:]

		if r.routeAmount(rt) > amt {
			r.plan = nil
			continue
		}

		fee := r.routeFee(rt)
		budget := r.budgetLeft()
		if budget != lnwire.MaxMilliSatoshi && fee > budget {
			r.plan = nil
			continue
		}

		r.reserveIssued(rt)
		return rt, nil
	}
}

func (r *candidateRouter) routeFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) routeEdgeAt(rt *route.Route,
	index int) (candidateEdgeKey, lnwire.MilliSatoshi, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, 0, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	amount := rt.TotalAmount
	if index > 0 {
		amount = rt.Hops[index-1].AmtToForward
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, amount, true
}

func (r *candidateRouter) observedLoad(key candidateEdgeKey,
	fallback lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if load := r.reserved[key]; load > 0 {
		return load
	}
	return fallback
}

func (r *candidateRouter) noteFailure(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	old := r.failures[key]
	if old.amount == 0 || load < old.amount {
		old.amount = load
	}
	old.count++
	r.failures[key] = old
}

func (r *candidateRouter) noteSuccess(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	old, ok := r.failures[key]
	if !ok {
		return
	}

	if load >= old.amount || old.count <= 1 {
		delete(r.failures, key)
		return
	}

	old.count--
	r.failures[key] = old
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		r.forEachRouteEdge(rt, func(key candidateEdgeKey,
			amount lnwire.MilliSatoshi, _ int) {

			load := r.observedLoad(key, amount)
			candidateRecordSuccess(key, load)
			r.noteSuccess(key, load)
		})

		r.committedFees = candidateAdd(
			r.committedFees, r.routeFee(rt),
		)
		return nil
	}

	r.numFailures++
	r.plan = nil

	failIndex := r.routeFailureIndex(
		rt, result.FailureSource,
	)

	for i := 0; i < failIndex && i < len(rt.Hops); i++ {
		key, amount, ok := r.routeEdgeAt(rt, i)
		if !ok {
			continue
		}

		load := r.observedLoad(key, amount)
		candidateRecordSuccess(key, load)
		r.noteSuccess(key, load)
	}

	code := result.Failure.Code()
	if key, amount, ok := r.routeEdgeAt(
		rt, failIndex,
	); ok {
		load := r.observedLoad(key, amount)

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(key, load)
			r.noteFailure(key, load)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.banned[key] = true

		default:
			r.noteFailure(key, load)
		}
	} else {
		r.forEachRouteEdge(rt, func(key candidateEdgeKey,
			amount lnwire.MilliSatoshi, _ int) {

			load := r.observedLoad(key, amount)
			old := r.failures[key]
			if old.amount == 0 || load < old.amount {
				old.amount = load
			}
			if old.count < 2 {
				old.count++
			}
			r.failures[key] = old
		})
	}

	r.releaseIssued(rt)
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta       = uint32(40)
	baseRiskPriceMsat    = float64(420_000)
	minRiskPriceMsat     = float64(25_000)
	hopCostMsat          = float64(8_000)
	reusedEdgeCostMsat   = float64(650_000)
	extraPartCostMsat    = float64(50_000)
	maxSearchHops        = 60
	maxLabelsPerNode     = 10
	maxRouterAttempts    = uint32(80)
	minFallbackShardMsat = lnwire.MilliSatoshi(10_000)
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     float64
	updated  time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi

	inboundBase int32
	inboundRate int32
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func (e *candidateEdge) publicCeiling() lnwire.MilliSatoshi {
	limit := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < limit {
		limit = e.maxHTLC
	}
	return limit
}

func nodeFee(in, out *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	outbound := int64(out.fee(amt))
	inbound := int64(in.inboundBase) +
		int64(amt)*int64(in.inboundRate)/1_000_000

	total := outbound + inbound
	if total <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(total)
}

type routeMeta struct {
	path      []*candidateEdge
	amounts   []lnwire.MilliSatoshi
	loads     []lnwire.MilliSatoshi
	delivered lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
}

type plannedRoute struct {
	rt    *route.Route
	meta  *routeMeta
	score float64
}

type localFailure struct {
	upperBad  lnwire.MilliSatoshi
	retryAt   uint32
	failCount uint32
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeLookup    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved      map[edgeKey]lnwire.MilliSatoshi
	edgePenalty   map[edgeKey]float64
	localFailures map[edgeKey]localFailure
	policyBad     map[edgeKey]bool
	issued        map[*route.Route]*routeMeta
	plan          []*plannedRoute

	committedFees  lnwire.MilliSatoshi
	budgetGuard    lnwire.MilliSatoshi
	successfulParts uint32
	attempts        uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeLookup:     make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		edgePenalty:    make(map[edgeKey]float64),
		localFailures:  make(map[edgeKey]localFailure),
		policyBad:      make(map[edgeKey]bool),
		issued:         make(map[*route.Route]*routeMeta),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
					inboundBase:   ch.InboundFee.BaseFee,
					inboundRate:   ch.InboundFee.FeeRate,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeLookup[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.025)
	highMode := 0.49 / (1 + math.Exp((x-0.97)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func beliefConfidence(b liquidityBelief, now time.Time) float64 {
	if b.updated.IsZero() || now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	if age <= 0 {
		return b.conf
	}

	return b.conf * math.Exp(-age.Seconds()/1800)
}

func channelProbability(key edgeKey, amt, capacity lnwire.MilliSatoshi,
	now time.Time) float64 {

	prior := bimodalPrior(amt, capacity)

	sharedBeliefs.Lock()
	b, ok := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	if !ok {
		return prior
	}

	conf := beliefConfidence(b, now)
	if conf < 0.01 {
		return prior
	}

	evidence := prior
	hasEvidence := false

	switch {
	case b.lowerOK > 0 && amt <= b.lowerOK:
		evidence = 0.995
		hasEvidence = true

	case b.upperBad > 0 && amt >= b.upperBad:
		evidence = 0.012
		hasEvidence = true

	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(b.upperBad-amt) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence = 0.012 + 0.983*pos
		hasEvidence = true
	}

	if !hasEvidence {
		return prior
	}

	p := prior*(1-conf) + evidence*conf
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func updateBelief(key edgeKey, amt lnwire.MilliSatoshi, success bool,
	now time.Time) {

	if amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	b := sharedBeliefs.m[key]
	if !b.updated.IsZero() && now.Before(b.updated) {
		b = liquidityBelief{}
	} else {
		b.conf = beliefConfidence(b, now)
	}

	if success {
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
		if b.upperBad != 0 && amt >= b.upperBad {
			b.upperBad = 0
		}
	} else {
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
		if b.lowerOK >= amt {
			b.lowerOK = 0
		}
	}

	b.conf = math.Min(1, b.conf+0.55)
	b.updated = now
	sharedBeliefs.m[key] = b
}

type searchState struct {
	node     route.Vertex
	amount   lnwire.MilliSatoshi
	fee      lnwire.MilliSatoshi
	score    float64
	hops     int
	nextEdge *candidateEdge
	child    *searchState
	active   bool
}

type searchQueue []*searchState

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchState))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func containsNode(s *searchState, node route.Vertex) bool {
	for cur := s; cur != nil; cur = cur.child {
		if cur.node == node {
			return true
		}
	}
	return false
}

func addSearchLabel(labels map[route.Vertex][]*searchState,
	s *searchState) bool {

	old := labels[s.node]
	kept := old[:0]

	for _, other := range old {
		if !other.active {
			continue
		}

		if other.score <= s.score &&
			other.fee <= s.fee &&
			other.amount <= s.amount {

			return false
		}

		if s.score <= other.score &&
			s.fee <= other.fee &&
			s.amount <= other.amount {

			other.active = false
			continue
		}

		kept = append(kept, other)
	}

	s.active = true
	kept = append(kept, s)

	if len(kept) > maxLabelsPerNode {
		protected := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].fee < kept[protected].fee {
				protected = i
			}
		}

		worst := -1
		for i := range kept {
			if i == protected {
				continue
			}
			if worst < 0 || kept[i].score > kept[worst].score {
				worst = i
			}
		}

		if worst >= 0 {
			removed := kept[worst]
			removed.active = false
			kept = append(kept[:worst], kept[worst+1:]...)
			if removed == s {
				labels[s.node] = kept
				return false
			}
		}
	}

	labels[s.node] = kept
	return true
}

func (r *candidateRouter) remainingFeeBudget() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}

	spent := r.committedFees + r.budgetGuard
	if spent < r.committedFees || spent >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - spent
}

func riskPrice(feeCap lnwire.MilliSatoshi) float64 {
	if feeCap == lnwire.MaxMilliSatoshi {
		return baseRiskPriceMsat
	}

	price := float64(feeCap) / 2
	if price < minRiskPriceMsat {
		price = minRiskPriceMsat
	}
	if price > baseRiskPriceMsat {
		price = baseRiskPriceMsat
	}
	return price
}

func cloneReservations(
	src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) edgeCooling(key edgeKey,
	load lnwire.MilliSatoshi) bool {

	failure, ok := r.localFailures[key]
	if !ok || failure.upperBad == 0 || load < failure.upperBad {
		return false
	}
	return r.attempts < failure.retryAt
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	feeCap lnwire.MilliSatoshi) (*plannedRoute, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	now := r.view.Now()
	price := riskPrice(feeCap)
	labels := make(map[route.Vertex][]*searchState)
	pq := &searchQueue{}

	start := &searchState{
		node:   r.spec.Target,
		amount: amt,
		active: true,
	}
	labels[start.node] = []*searchState{start}
	heap.Push(pq, start)

	var result *searchState

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(*searchState)
		if !cur.active {
			continue
		}
		if cur.node == r.source {
			result = cur
			break
		}
		if cur.hops >= maxSearchHops {
			continue
		}

		for _, edge := range r.incomingEdges[cur.node] {
			if r.policyBad[edge.key] ||
				containsNode(cur, edge.from) {

				continue
			}

			over := cur.amount
			nodeCharge := lnwire.MilliSatoshi(0)
			if cur.node != r.spec.Target {
				if cur.nextEdge == nil {
					continue
				}

				nodeCharge = nodeFee(edge, cur.nextEdge, cur.amount)
				if nodeCharge > lnwire.MaxMilliSatoshi-cur.amount {
					continue
				}
				over += nodeCharge
			}

			if !edge.usableHTLC(over) {
				continue
			}

			reserved := reservations[edge.key]
			if reserved > lnwire.MaxMilliSatoshi-over {
				continue
			}
			totalLoad := over + reserved
			if totalLoad > edge.capacity ||
				r.edgeCooling(edge.key, totalLoad) {

				continue
			}

			if edge.from == r.source {
				balance, ok := r.localBalances[edge.chanID]
				if !ok || totalLoad > balance {
					continue
				}
			}

			totalFee := cur.fee + nodeCharge
			if totalFee < cur.fee {
				continue
			}
			if feeCap != lnwire.MaxMilliSatoshi &&
				totalFee > feeCap {

				continue
			}

			p := channelProbability(
				edge.key, totalLoad, edge.capacity, now,
			)
			if edge.from == r.source {
				p = 0.99
			}

			score := cur.score + float64(nodeCharge) +
				price*(-math.Log(p)) + hopCostMsat +
				r.edgePenalty[edge.key]

			if reserved > 0 {
				reuse := reusedEdgeCostMsat
				if edge.from == r.source {
					reuse *= 0.45
				}
				score += reuse
			}

			next := &searchState{
				node:     edge.from,
				amount:   over,
				fee:      totalFee,
				score:    score,
				hops:     cur.hops + 1,
				nextEdge: edge,
				child:    cur,
			}
			if addSearchLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if result == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, result.hops)
	for cur := result; cur.node != r.spec.Target; cur = cur.child {
		if cur.nextEdge == nil || cur.child == nil {
			return nil, errors.New("broken route state")
		}
		path = append(path, cur.nextEdge)
	}

	rt, amounts, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	loads := make([]lnwire.MilliSatoshi, len(path))
	for i, edge := range path {
		reserved := reservations[edge.key]
		if reserved > lnwire.MaxMilliSatoshi-amounts[i] {
			return nil, errors.New("route load overflow")
		}
		loads[i] = amounts[i] + reserved
	}

	meta := &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: amt,
		fee:       rt.TotalAmount - amt,
	}
	if feeCap != lnwire.MaxMilliSatoshi && meta.fee > feeCap {
		return nil, errors.New("route exceeds fee budget")
	}

	return &plannedRoute{
		rt:    rt,
		meta:  meta,
		score: result.score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, []lnwire.MilliSatoshi, error) {

	if len(path) == 0 {
		return nil, nil, errors.New("empty path")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)
	amounts[n-1] = amt
	expiries[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		charge := nodeFee(path[i], path[i+1], amounts[i+1])
		if charge > lnwire.MaxMilliSatoshi-amounts[i+1] {
			return nil, nil, errors.New("route amount overflow")
		}
		amounts[i] = amounts[i+1] + charge
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, amounts, nil
}

func weightedAllocation(total lnwire.MilliSatoshi,
	weights []int64) []lnwire.MilliSatoshi {

	result := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total
	var remainingWeight int64
	for _, weight := range weights {
		if weight > 0 {
			remainingWeight += weight
		}
	}

	for i, weight := range weights {
		left := len(weights) - i
		if left == 1 {
			result[i] = remaining
			break
		}

		maxPart := remaining - lnwire.MilliSatoshi(left-1)
		part := lnwire.MilliSatoshi(
			float64(remaining) * float64(weight) /
				float64(remainingWeight),
		)
		if part < 1 {
			part = 1
		}
		if part > maxPart {
			part = maxPart
		}

		result[i] = part
		remaining -= part
		remainingWeight -= weight
	}

	return result
}

func sameAllocation(a, b []lnwire.MilliSatoshi) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func appendAllocation(patterns *[][]lnwire.MilliSatoshi,
	allocation []lnwire.MilliSatoshi) {

	for _, old := range *patterns {
		if sameAllocation(old, allocation) {
			return
		}
	}
	*patterns = append(*patterns, allocation)
}

func reverseWeights(weights []int64) []int64 {
	reversed := make([]int64, len(weights))
	for i := range weights {
		reversed[len(weights)-1-i] = weights[i]
	}
	return reversed
}

func (r *candidateRouter) capacityWeights(parts int) []int64 {
	sourceCaps := make([]lnwire.MilliSatoshi, 0)
	targetCaps := make([]lnwire.MilliSatoshi, 0)

	for _, edge := range r.edgeLookup {
		if edge.from != r.source {
			continue
		}

		limit := edge.publicCeiling()
		balance, ok := r.localBalances[edge.chanID]
		if !ok {
			continue
		}
		if balance < limit {
			limit = balance
		}
		if limit > 0 {
			sourceCaps = append(sourceCaps, limit)
		}
	}

	for _, edge := range r.incomingEdges[r.spec.Target] {
		limit := edge.publicCeiling()
		if limit > 0 {
			targetCaps = append(targetCaps, limit)
		}
	}

	if len(sourceCaps) == 0 || len(targetCaps) == 0 {
		return nil
	}

	sort.Slice(sourceCaps, func(i, j int) bool {
		return sourceCaps[i] > sourceCaps[j]
	})
	sort.Slice(targetCaps, func(i, j int) bool {
		return targetCaps[i] > targetCaps[j]
	})

	raw := make([]lnwire.MilliSatoshi, parts)
	var largest lnwire.MilliSatoshi
	for i := 0; i < parts; i++ {
		si := i
		if si >= len(sourceCaps) {
			si = len(sourceCaps) - 1
		}
		ti := i
		if ti >= len(targetCaps) {
			ti = len(targetCaps) - 1
		}

		raw[i] = sourceCaps[si]
		if targetCaps[ti] < raw[i] {
			raw[i] = targetCaps[ti]
		}
		if raw[i] > largest {
			largest = raw[i]
		}
	}
	if largest <= 0 {
		return nil
	}

	weights := make([]int64, parts)
	for i, capacity := range raw {
		weight := int64(
			1 + 999*float64(capacity)/float64(largest),
		)
		if weight < 1 {
			weight = 1
		}
		weights[i] = weight
	}
	return weights
}

func (r *candidateRouter) allocationPatterns(
	total lnwire.MilliSatoshi, parts int) [][]lnwire.MilliSatoshi {

	if parts <= 0 || total < lnwire.MilliSatoshi(parts) {
		return nil
	}

	patterns := make([][]lnwire.MilliSatoshi, 0, 8)
	equal := make([]int64, parts)
	for i := range equal {
		equal[i] = 1
	}
	appendAllocation(&patterns, weightedAllocation(total, equal))

	switch parts {
	case 1:
		return patterns

	case 2:
		for _, weights := range [][]int64{
			{45, 55}, {55, 45},
			{35, 65}, {65, 35},
			{25, 75}, {75, 25},
		} {
			appendAllocation(
				&patterns, weightedAllocation(total, weights),
			)
		}

	default:
		ascending := make([]int64, parts)
		heavy := make([]int64, parts)
		for i := 0; i < parts; i++ {
			ascending[i] = int64(i + 1)
			heavy[i] = 1
		}
		heavy[0] = int64(parts)

		appendAllocation(
			&patterns, weightedAllocation(total, ascending),
		)
		appendAllocation(
			&patterns,
			weightedAllocation(total, reverseWeights(ascending)),
		)
		appendAllocation(
			&patterns, weightedAllocation(total, heavy),
		)
		appendAllocation(
			&patterns,
			weightedAllocation(total, reverseWeights(heavy)),
		)
	}

	if weights := r.capacityWeights(parts); len(weights) != 0 {
		appendAllocation(
			&patterns, weightedAllocation(total, weights),
		)
		appendAllocation(
			&patterns,
			weightedAllocation(total, reverseWeights(weights)),
		)
	}

	return patterns
}

func addReservationSet(dst map[edgeKey]lnwire.MilliSatoshi,
	meta *routeMeta) {

	for i, edge := range meta.path {
		dst[edge.key] += meta.amounts[i]
	}
}

func proportionalBudget(budget, part,
	total lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if budget == lnwire.MaxMilliSatoshi {
		return budget
	}
	if total <= 0 || part >= total {
		return budget
	}

	share := lnwire.MilliSatoshi(
		float64(budget) * float64(part) / float64(total),
	)
	if share < 0 {
		return 0
	}
	if share > budget {
		return budget
	}
	return share
}

func (r *candidateRouter) tryAllocation(
	allocation []lnwire.MilliSatoshi,
	feeBudget lnwire.MilliSatoshi) ([]*plannedRoute, float64, bool) {

	reservations := cloneReservations(r.reserved)
	remainingBudget := feeBudget
	var remainingAmount lnwire.MilliSatoshi
	for _, shard := range allocation {
		if shard <= 0 ||
			shard > lnwire.MaxMilliSatoshi-remainingAmount {

			return nil, 0, false
		}
		remainingAmount += shard
	}

	plan := make([]*plannedRoute, 0, len(allocation))
	totalScore := float64(0)

	for _, shard := range allocation {
		cap := remainingBudget
		if remainingBudget != lnwire.MaxMilliSatoshi &&
			shard < remainingAmount {

			cap = proportionalBudget(
				remainingBudget, shard, remainingAmount,
			)
			slack := remainingBudget / 20
			if cap <= remainingBudget-slack {
				cap += slack
			} else {
				cap = remainingBudget
			}
		}

		pr, err := r.findRoute(shard, reservations, cap)
		if err != nil {
			return nil, 0, false
		}

		if remainingBudget != lnwire.MaxMilliSatoshi {
			if pr.meta.fee > remainingBudget {
				return nil, 0, false
			}
			remainingBudget -= pr.meta.fee
		}

		plan = append(plan, pr)
		totalScore += pr.score
		addReservationSet(reservations, pr.meta)
		remainingAmount -= shard
	}

	totalScore += float64(len(plan)-1) * extraPartCostMsat
	return plan, totalScore, true
}

func (r *candidateRouter) maximumPublicShard() lnwire.MilliSatoshi {
	var sourceLimit lnwire.MilliSatoshi
	var targetLimit lnwire.MilliSatoshi

	for _, edge := range r.edgeLookup {
		if edge.from != r.source {
			continue
		}

		limit := edge.publicCeiling()
		balance, ok := r.localBalances[edge.chanID]
		if !ok {
			continue
		}
		if balance < limit {
			limit = balance
		}
		if limit > sourceLimit {
			sourceLimit = limit
		}
	}

	for _, edge := range r.incomingEdges[r.spec.Target] {
		limit := edge.publicCeiling()
		if limit > targetLimit {
			targetLimit = limit
		}
	}

	if sourceLimit == 0 || targetLimit == 0 {
		return 0
	}
	if targetLimit < sourceLimit {
		return targetLimit
	}
	return sourceLimit
}

func (r *candidateRouter) minimumParts(
	total lnwire.MilliSatoshi) int {

	ceiling := r.maximumPublicShard()
	if ceiling <= 0 {
		return 1
	}
	if total <= ceiling {
		return 1
	}

	return int((total-1)/ceiling + 1)
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots uint32) ([]*plannedRoute, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts exhausted")
	}

	minParts := r.minimumParts(total)
	if minParts > int(slots) {
		return nil, errors.New("public htlc limits exceed maximum parts")
	}

	feeBudget := r.remainingFeeBudget()
	var best []*plannedRoute
	bestScore := math.Inf(1)

	for parts := minParts; parts <= int(slots); parts++ {
		patterns := r.allocationPatterns(total, parts)
		for _, allocation := range patterns {
			plan, score, ok := r.tryAllocation(
				allocation, feeBudget,
			)
			if ok && score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) != 0 {
		return best, nil
	}

	if slots <= 1 {
		return nil, errors.New("no route found")
	}

	average := total / lnwire.MilliSatoshi(slots)
	if average <= 0 {
		average = 1
	}

	candidates := []lnwire.MilliSatoshi{
		average,
		average - average/4,
		average / 2,
		average / 4,
	}

	for _, shard := range candidates {
		if shard < minFallbackShardMsat {
			continue
		}

		cap := feeBudget
		if feeBudget != lnwire.MaxMilliSatoshi {
			cap = proportionalBudget(feeBudget, shard, total)
			slack := feeBudget / 20
			if cap <= feeBudget-slack {
				cap += slack
			} else {
				cap = feeBudget
			}
		}

		pr, err := r.findRoute(shard, r.reserved, cap)
		if err == nil {
			return []*plannedRoute{pr}, nil
		}
	}

	return nil, errors.New("no route found")
}

func queuedAmount(plan []*plannedRoute) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, pr := range plan {
		total += pr.meta.delivered
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= maxRouterAttempts {
		return nil, errors.New("routing attempt limit reached")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	used := r.successfulParts
	if inFlightHtlcs > used {
		used = inFlightHtlcs
	}
	if used >= maxParts {
		return nil, errors.New("maximum parts exhausted")
	}
	slots := maxParts - used

	if len(r.plan) != 0 && queuedAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, slots)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	next := r.plan[0]
	r.plan = r.plan[1:]
	r.issued[next.rt] = next.meta
	r.attempts++

	return next.rt, nil
}

func (r *candidateRouter) metaForRoute(rt *route.Route) *routeMeta {
	if meta, ok := r.issued[rt]; ok {
		return meta
	}
	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	loads := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeLookup[key]
		if edge == nil {
			return nil
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		reserved := r.reserved[key]
		if reserved > lnwire.MaxMilliSatoshi-amount {
			return nil
		}

		path = append(path, edge)
		amounts = append(amounts, amount)
		loads = append(loads, amount+reserved)
		from = hop.PubKeyBytes
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	return &routeMeta{
		path:      path,
		amounts:   amounts,
		loads:     loads,
		delivered: delivered,
		fee:       rt.TotalAmount - delivered,
	}
}

func (r *candidateRouter) recordLocalFailure(key edgeKey,
	amount lnwire.MilliSatoshi) {

	failure := r.localFailures[key]
	if failure.upperBad == 0 || amount < failure.upperBad {
		failure.upperBad = amount
	}
	failure.failCount++

	cooldown := uint32(6) + failure.failCount*3
	if cooldown > 24 {
		cooldown = 24
	}
	failure.retryAt = r.attempts + cooldown
	r.localFailures[key] = failure
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	meta := r.metaForRoute(rt)
	delete(r.issued, rt)
	if meta == nil {
		r.plan = nil
		return nil
	}

	now := r.view.Now()

	if result.Failure == nil {
		for i, edge := range meta.path {
			updateBelief(edge.key, meta.loads[i], true, now)
			r.reserved[edge.key] += meta.amounts[i]
			r.edgePenalty[edge.key] *= 0.35
			delete(r.localFailures, edge.key)
		}

		if meta.fee <= lnwire.MaxMilliSatoshi-r.committedFees {
			r.committedFees += meta.fee
		}
		r.successfulParts++
		return nil
	}

	r.plan = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(meta.path) {
		passed = len(meta.path)
	}
	for i := 0; i < passed; i++ {
		updateBelief(meta.path[i].key, meta.loads[i], true, now)
	}

	code := result.Failure.Code()

	if failIdx >= 0 && failIdx < len(meta.path) {
		edge := meta.path[failIdx]

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			updateBelief(edge.key, meta.loads[failIdx], false, now)
			r.recordLocalFailure(edge.key, meta.loads[failIdx])
			r.edgePenalty[edge.key] += 180_000

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.policyBad[edge.key] = true
			r.edgePenalty[edge.key] += 5_000_000

		default:
			r.recordLocalFailure(edge.key, meta.loads[failIdx])
			r.edgePenalty[edge.key] += 1_500_000
		}

		return nil
	}

	if failIdx == len(meta.path) && len(meta.path) != 0 {
		last := meta.path[len(meta.path)-1]
		r.edgePenalty[last.key] += 750_000
		return nil
	}

	if r.spec.FeeLimitMsat != lnwire.MaxMilliSatoshi {
		guard := meta.fee / 20
		if guard < 1_000 {
			guard = 1_000
		}
		if guard <= lnwire.MaxMilliSatoshi-r.budgetGuard {
			r.budgetGuard += guard
		}
	}
	for _, edge := range meta.path {
		r.edgePenalty[edge.key] += 100_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCLTV   = uint32(40)
	candidateRiskPrice   = 420000.0
	candidateHopPrice    = 8000.0
	candidateReuseNats   = 1.20
	candidateMinShard    = lnwire.MilliSatoshi(10000)
	candidateProbFloor   = 0.012
	candidateProbCeiling = 0.995
	candidateMaxLabels   = 8
	candidateMaxHops     = 40
	candidatePlanNodes   = 120
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat int64
	feeRatePPM  int64
	cltvDelta   uint16
	minHTLC     lnwire.MilliSatoshi
	maxHTLC     lnwire.MilliSatoshi

	inboundBase int64
	inboundRate int64
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func (e *candidateEdge) outgoingFee(amt lnwire.MilliSatoshi) int64 {
	fee := e.baseFeeMsat + int64(amt)*e.feeRatePPM/1_000_000
	if fee < 0 {
		return 0
	}
	return fee
}

func candidateForwardingFee(incoming, outgoing *candidateEdge,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if incoming == nil || outgoing == nil {
		return 0
	}

	outFee := outgoing.outgoingFee(amt)
	inBasis := int64(amt) + outFee
	inFee := incoming.inboundBase +
		inBasis*incoming.inboundRate/1_000_000

	total := outFee + inFee
	if total < 0 {
		total = 0
	}
	return lnwire.MilliSatoshi(total)
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	success  uint32
	failure  uint32
}

var candidateSharedBeliefs = struct {
	sync.Mutex
	m map[candidateEdgeKey]candidateBelief
}{
	m: make(map[candidateEdgeKey]candidateBelief),
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return candidateProbFloor
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.045)
	highMode := 0.5 / (1 + math.Exp((x-0.94)/0.035))
	p := lowMode + highMode

	if p < candidateProbFloor {
		return candidateProbFloor
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateProbability(e *candidateEdge,
	load lnwire.MilliSatoshi) float64 {

	prior := candidatePrior(load, e.capacity)

	candidateSharedBeliefs.Lock()
	belief, ok := candidateSharedBeliefs.m[e.key]
	candidateSharedBeliefs.Unlock()

	if !ok {
		return prior
	}

	if belief.lowerOK > 0 && load <= belief.lowerOK {
		return candidateProbCeiling
	}

	if belief.upperBad > 0 && load >= belief.upperBad {
		p := prior * 0.08
		if p < candidateProbFloor {
			p = candidateProbFloor
		}
		return p
	}

	var learned, confidence float64

	switch {
	case belief.lowerOK > 0 && belief.upperBad > belief.lowerOK:
		mid := 0.5 * float64(belief.lowerOK+belief.upperBad)
		width := math.Max(
			float64(belief.upperBad-belief.lowerOK)*0.18,
			float64(e.capacity)*0.012,
		)
		learned = 1 / (1 + math.Exp((float64(load)-mid)/width))
		confidence = 0.88

	case belief.upperBad > 0:
		width := math.Max(
			float64(belief.upperBad)*0.14,
			float64(e.capacity)*0.015,
		)
		learned = 1 / (1 + math.Exp(
			(float64(load)-float64(belief.upperBad))/width,
		))
		confidence = 0.72

	case belief.lowerOK > 0:
		excess := float64(load-belief.lowerOK) /
			math.Max(float64(e.capacity), 1)
		learned = candidateProbCeiling * math.Exp(-excess/0.12)
		confidence = 0.62

	default:
		return prior
	}

	p := confidence*learned + (1-confidence)*prior
	if p < candidateProbFloor {
		return candidateProbFloor
	}
	if p > candidateProbCeiling {
		return candidateProbCeiling
	}
	return p
}

func candidateRecordSuccess(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	b := candidateSharedBeliefs.m[key]
	if load > b.lowerOK {
		b.lowerOK = load
	}
	b.success++

	if b.upperBad > 0 && b.lowerOK >= b.upperBad {
		b.upperBad = b.lowerOK + 1
	}

	candidateSharedBeliefs.m[key] = b
}

func candidateRecordFailure(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	candidateSharedBeliefs.Lock()
	defer candidateSharedBeliefs.Unlock()

	b := candidateSharedBeliefs.m[key]
	if b.upperBad == 0 || load < b.upperBad {
		b.upperBad = load
	}
	b.failure++
	candidateSharedBeliefs.m[key] = b
}

type candidateSearchItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   int
	path   []*candidateEdge
	index  int
}

type candidateSearchQueue []*candidateSearchItem

func (q candidateSearchQueue) Len() int {
	return len(q)
}

func (q candidateSearchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateSearchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateSearchQueue) Push(x any) {
	item := x.(*candidateSearchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateSearchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	*q = old[:n-1]
	return item
}

type candidateLabel struct {
	score  float64
	amount lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[candidateEdgeKey]*candidateEdge
	local    map[uint64]lnwire.MilliSatoshi

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	issued   map[*route.Route]bool
	penalty  map[candidateEdgeKey]float64
	banned   map[candidateEdgeKey]bool

	failedLoad   map[candidateEdgeKey]lnwire.MilliSatoshi
	failureCount map[candidateEdgeKey]uint32
	failedRoutes map[uint64]uint32

	plan          []*route.Route
	committedFees lnwire.MilliSatoshi
	failures      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:       source,
		spec:         spec,
		incoming:     make(map[route.Vertex][]*candidateEdge),
		edges:        make(map[candidateEdgeKey]*candidateEdge),
		local:        localBalances,
		reserved:     make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		issued:       make(map[*route.Route]bool),
		penalty:      make(map[candidateEdgeKey]float64),
		banned:       make(map[candidateEdgeKey]bool),
		failedLoad:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		failureCount: make(map[candidateEdgeKey]uint32),
		failedRoutes: make(map[uint64]uint32),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:      key,
					capacity: lnwire.NewMSatFromSatoshis(ch.Capacity),

					baseFeeMsat: int64(policy.FeeBaseMSat),
					feeRatePPM: int64(
						policy.FeeProportionalMillionths,
					),
					cltvDelta: policy.TimeLockDelta,
					minHTLC:   policy.MinHTLC,

					inboundBase: int64(ch.InboundFee.BaseFee),
					inboundRate: int64(ch.InboundFee.FeeRate),
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incoming[node] = append(r.incoming[node], edge)
				r.edges[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateAdd(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b > 0 && a > lnwire.MaxMilliSatoshi-b {
		return lnwire.MaxMilliSatoshi
	}
	return a + b
}

func (r *candidateRouter) budgetLeft() lnwire.MilliSatoshi {
	if r.spec.FeeLimitMsat == lnwire.MaxMilliSatoshi {
		return lnwire.MaxMilliSatoshi
	}
	if r.committedFees >= r.spec.FeeLimitMsat {
		return 0
	}
	return r.spec.FeeLimitMsat - r.committedFees
}

func (r *candidateRouter) routeFee(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	if rt.TotalAmount <= delivered {
		return 0
	}
	return rt.TotalAmount - delivered
}

func (r *candidateRouter) routeAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	h := offset
	for _, hop := range rt.Hops {
		h ^= hop.ChannelID
		h *= prime
	}
	h ^= uint64(candidateRouteAmount(rt) / 10000)
	h *= prime
	return h
}

func candidateRouteAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidatePathContains(path []*candidateEdge, node route.Vertex) bool {
	for _, edge := range path {
		if edge.key.from == node || edge.key.to == node {
			return true
		}
	}
	return false
}

func candidateAddLabel(labels map[route.Vertex][]candidateLabel,
	node route.Vertex, score float64,
	amount lnwire.MilliSatoshi) bool {

	current := labels[node]
	for _, label := range current {
		if label.score <= score && label.amount <= amount {
			return false
		}
	}

	filtered := current[:0]
	for _, label := range current {
		if score <= label.score && amount <= label.amount {
			continue
		}
		filtered = append(filtered, label)
	}

	filtered = append(filtered, candidateLabel{
		score:  score,
		amount: amount,
	})

	sort.Slice(filtered, func(i, j int) bool {
		return filtered[i].score < filtered[j].score
	})
	if len(filtered) > candidateMaxLabels {
		filtered = filtered[:candidateMaxLabels]
	}

	labels[node] = filtered
	return true
}

func (r *candidateRouter) liquidityPenalty(key candidateEdgeKey,
	load lnwire.MilliSatoshi) float64 {

	failed := r.failedLoad[key]
	if failed <= 0 {
		return 0
	}

	ratio := float64(load) / math.Max(float64(failed), 1)
	count := float64(r.failureCount[key])
	extra := math.Min(count*0.08, 0.40)

	switch {
	case ratio >= 1:
		return 2.25 + extra
	case ratio >= 0.88:
		return 1.25 + extra
	case ratio >= 0.72:
		return 0.48 + extra/2
	case ratio >= 0.58:
		return 0.14
	default:
		return 0
	}
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi,
	maxFee lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("invalid shard amount")
	}

	labels := make(map[route.Vertex][]candidateLabel)
	labels[r.spec.Target] = []candidateLabel{{}}

	pq := &candidateSearchQueue{}
	heap.Push(pq, &candidateSearchItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	var fallback *route.Route
	var fallbackQuality float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateSearchItem)

		if item.node == r.source {
			rt, err := r.buildRoute(item.path, deliver)
			if err != nil {
				continue
			}
			if r.routeFee(rt) > maxFee {
				continue
			}

			quality := 1.0
			if item.hops > 0 {
				quality = math.Exp(-item.risk / float64(item.hops))
			}

			if r.failedRoutes[candidateRouteHash(rt)] == 0 {
				return rt, quality, nil
			}
			if fallback == nil {
				fallback = rt
				fallbackQuality = quality
			}
			continue
		}

		if item.hops >= candidateMaxHops {
			continue
		}

		var outgoing *candidateEdge
		if len(item.path) > 0 {
			outgoing = item.path[0]
		}

		for _, incoming := range r.incoming[item.node] {
			if r.banned[incoming.key] ||
				candidatePathContains(item.path, incoming.key.from) {

				continue
			}

			amountOver := item.amount
			if item.node != r.spec.Target {
				amountOver = candidateAdd(
					amountOver,
					candidateForwardingFee(
						incoming, outgoing, item.amount,
					),
				)
			}

			if !incoming.usable(amountOver) {
				continue
			}

			if maxFee != lnwire.MaxMilliSatoshi &&
				amountOver-deliver > maxFee {

				continue
			}

			load := candidateAdd(
				amountOver, r.reserved[incoming.key],
			)
			if extra != nil {
				load = candidateAdd(load, extra[incoming.key])
			}
			if load > incoming.capacity {
				continue
			}

			var probability float64
			if incoming.key.from == r.source {
				balance, ok := r.local[incoming.key.chanID]
				if !ok || load > balance {
					continue
				}
				probability = 0.999
			} else {
				probability = candidateProbability(incoming, load)
			}

			risk := -math.Log(probability)
			edgePenalty := r.penalty[incoming.key] +
				r.liquidityPenalty(incoming.key, load)

			reuse := 0.0
			if r.reserved[incoming.key] > 0 ||
				(extra != nil && extra[incoming.key] > 0) {

				reuse = candidateReuseNats
			}

			feeIncrement := float64(amountOver - item.amount)
			newScore := item.score + feeIncrement +
				candidateRiskPrice*(risk+edgePenalty+reuse) +
				candidateHopPrice

			if incoming.key.from != r.source &&
				!candidateAddLabel(
					labels, incoming.key.from,
					newScore, amountOver,
				) {

				continue
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = incoming
			copy(path[1:], item.path)

			heap.Push(pq, &candidateSearchItem{
				node:   incoming.key.from,
				amount: amountOver,
				score:  newScore,
				risk:   item.risk + risk,
				hops:   item.hops + 1,
				path:   path,
			})
		}
	}

	if fallback != nil {
		return fallback, fallbackQuality, nil
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	n := len(path)
	amounts := make([]lnwire.MilliSatoshi, n)
	expiries := make([]uint32, n)

	amounts[n-1] = deliver
	expiries[n-1] = candidateFinalCLTV

	for i := n - 2; i >= 0; i-- {
		fee := candidateForwardingFee(
			path[i], path[i+1], amounts[i+1],
		)
		amounts[i] = candidateAdd(amounts[i+1], fee)
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].cltvDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		forward := deliver
		expiry := candidateFinalCLTV
		if i < n-1 {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) forEachRouteEdge(rt *route.Route,
	fn func(candidateEdgeKey, lnwire.MilliSatoshi, int)) {

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		fn(key, amount, i)
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) addVirtualReservation(
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		reserved[key] = candidateAdd(reserved[key], amount)
	})
}

func candidateCloneReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	clone := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		clone[key] = amount
	}
	return clone
}

func (r *candidateRouter) reserveIssued(rt *route.Route) {
	if r.issued[rt] {
		return
	}

	r.issued[rt] = true
	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		r.reserved[key] = candidateAdd(r.reserved[key], amount)
	})
}

func (r *candidateRouter) releaseIssued(rt *route.Route) {
	if !r.issued[rt] {
		return
	}

	delete(r.issued, rt)
	r.forEachRouteEdge(rt, func(key candidateEdgeKey,
		amount lnwire.MilliSatoshi, _ int) {

		current := r.reserved[key]
		if current <= amount {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = current - amount
		}
	})
}

type candidatePlanChoice struct {
	amount  lnwire.MilliSatoshi
	route   *route.Route
	quality float64
	metric  float64
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amount, minimum, maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amount < minimum || amount > maximum {
		return amounts
	}
	for _, existing := range amounts {
		if existing == amount {
			return amounts
		}
	}
	return append(amounts, amount)
}

func (r *candidateRouter) partFeeLimit(planned lnwire.MilliSatoshi,
	parts int) lnwire.MilliSatoshi {

	left := r.budgetLeft()
	if left == lnwire.MaxMilliSatoshi {
		return left
	}
	if planned >= left {
		return 0
	}

	left -= planned
	if parts <= 2 {
		return left
	}

	share := left / lnwire.MilliSatoshi(parts)
	return candidateAdd(share, share)
}

func (r *candidateRouter) planSearch(
	remaining lnwire.MilliSatoshi,
	parts int,
	virtual map[candidateEdgeKey]lnwire.MilliSatoshi,
	plannedFees lnwire.MilliSatoshi,
	nodes *int) ([]*route.Route, bool) {

	*nodes++
	if *nodes > candidatePlanNodes || parts < 1 {
		return nil, false
	}

	if parts == 1 {
		rt, _, err := r.findRoute(
			remaining, virtual,
			r.partFeeLimit(plannedFees, parts),
		)
		if err != nil {
			return nil, false
		}

		fee := r.routeFee(rt)
		left := r.budgetLeft()
		if left != lnwire.MaxMilliSatoshi &&
			plannedFees+fee > left {

			return nil, false
		}

		return []*route.Route{rt}, true
	}

	minimum := candidateMinShard
	maximum := remaining -
		minimum*lnwire.MilliSatoshi(parts-1)
	if maximum < minimum {
		return nil, false
	}

	average := remaining / lnwire.MilliSatoshi(parts)
	amounts := make([]lnwire.MilliSatoshi, 0, 7)
	amounts = candidateAppendAmount(
		amounts, average, minimum, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, average*4/5, minimum, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, average*2/3, minimum, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, average/2, minimum, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, average*5/4, minimum, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, average*3/2, minimum, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, maximum, minimum, maximum,
	)

	choices := make([]candidatePlanChoice, 0, len(amounts))
	maxFee := r.partFeeLimit(plannedFees, parts)

	for _, amount := range amounts {
		rt, quality, err := r.findRoute(amount, virtual, maxFee)
		if err != nil {
			continue
		}

		fee := r.routeFee(rt)
		left := r.budgetLeft()
		if left != lnwire.MaxMilliSatoshi &&
			plannedFees+fee > left {

			continue
		}

		if quality < candidateProbFloor {
			quality = candidateProbFloor
		}

		balanceCost := 0.55 * math.Abs(math.Log(
			float64(amount) / math.Max(float64(average), 1),
		))
		metric := -math.Log(quality) + balanceCost +
			float64(fee)/candidateRiskPrice

		if r.failures > 0 && amount >= average {
			metric += 0.08
		}

		choices = append(choices, candidatePlanChoice{
			amount:  amount,
			route:   rt,
			quality: quality,
			metric:  metric,
		})
	}

	sort.Slice(choices, func(i, j int) bool {
		return choices[i].metric < choices[j].metric
	})

	for _, choice := range choices {
		nextVirtual := candidateCloneReservations(virtual)
		r.addVirtualReservation(nextVirtual, choice.route)

		rest, ok := r.planSearch(
			remaining-choice.amount, parts-1,
			nextVirtual,
			plannedFees+r.routeFee(choice.route),
			nodes,
		)
		if !ok {
			continue
		}

		plan := make([]*route.Route, 1, len(rest)+1)
		plan[0] = choice.route
		plan = append(plan, rest...)
		return plan, true
	}

	return nil, false
}

func (r *candidateRouter) tryPlan(amount lnwire.MilliSatoshi,
	parts int) ([]*route.Route, bool) {

	if parts < 1 ||
		(parts > 1 &&
			amount < candidateMinShard*lnwire.MilliSatoshi(parts)) {

		return nil, false
	}

	nodes := 0
	return r.planSearch(
		amount, parts,
		make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		0, &nodes,
	)
}

func (r *candidateRouter) makePlan(amount lnwire.MilliSatoshi,
	slots uint32) ([]*route.Route, error) {

	if slots == 0 {
		return nil, errors.New("maximum parts already in flight")
	}

	full, quality, fullErr := r.findRoute(
		amount, nil, r.budgetLeft(),
	)

	if slots == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	preferred := 1
	switch {
	case fullErr != nil:
		preferred = 2
	case quality < 0.40:
		preferred = 3
	case quality < 0.62 && amount >= 50_000_000:
		preferred = 2
	}

	if r.failures > 0 {
		retryParts := 1 + int(r.failures)
		if retryParts < 2 {
			retryParts = 2
		}
		if retryParts > preferred {
			preferred = retryParts
		}
	}

	if preferred > int(slots) {
		preferred = int(slots)
	}

	if preferred == 1 && fullErr == nil {
		return []*route.Route{full}, nil
	}

	for parts := preferred; parts <= int(slots); parts++ {
		plan, ok := r.tryPlan(amount, parts)
		if ok {
			return plan, nil
		}
	}

	if fullErr == nil {
		return []*route.Route{full}, nil
	}

	shard := amount / lnwire.MilliSatoshi(slots)
	if shard < candidateMinShard {
		shard = candidateMinShard
	}

	for shard >= candidateMinShard {
		rt, _, err := r.findRoute(
			shard, nil, r.budgetLeft(),
		)
		if err == nil {
			return []*route.Route{rt}, nil
		}
		if shard == candidateMinShard {
			break
		}

		shard = shard * 2 / 3
		if shard < candidateMinShard {
			shard = candidateMinShard
		}
	}

	return nil, fullErr
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	for {
		if len(r.plan) == 0 {
			maxParts := r.spec.MaxParts
			if maxParts == 0 {
				maxParts = 1
			}
			if inFlightHtlcs >= maxParts {
				return nil, errors.New("maximum parts already in flight")
			}

			plan, err := r.makePlan(
				amt, maxParts-inFlightHtlcs,
			)
			if err != nil {
				return nil, err
			}
			r.plan = plan
		}

		rt := r.plan[0]
		r.plan = r.plan[1:]

		if r.routeAmount(rt) > amt {
			r.plan = nil
			continue
		}

		fee := r.routeFee(rt)
		budget := r.budgetLeft()
		if budget != lnwire.MaxMilliSatoshi && fee > budget {
			r.plan = nil
			r.failures++
			continue
		}

		r.reserveIssued(rt)
		return rt, nil
	}
}

func (r *candidateRouter) routeFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) routeEdgeAt(rt *route.Route,
	index int) (candidateEdgeKey, lnwire.MilliSatoshi, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, 0, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	amount := rt.TotalAmount
	if index > 0 {
		amount = rt.Hops[index-1].AmtToForward
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, amount, true
}

func (r *candidateRouter) observedLoad(key candidateEdgeKey,
	fallback lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if load := r.reserved[key]; load > 0 {
		return load
	}
	return fallback
}

func (r *candidateRouter) recordLocalFailure(key candidateEdgeKey,
	load lnwire.MilliSatoshi) {

	old := r.failedLoad[key]
	if old == 0 || load < old {
		r.failedLoad[key] = load
	}
	r.failureCount[key]++
	candidateRecordFailure(key, load)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		r.forEachRouteEdge(rt, func(key candidateEdgeKey,
			amount lnwire.MilliSatoshi, _ int) {

			load := r.observedLoad(key, amount)
			candidateRecordSuccess(key, load)

			if failed := r.failedLoad[key];
				failed > 0 && load >= failed {

				delete(r.failedLoad, key)
				delete(r.failureCount, key)
			}
			if r.penalty[key] > 0.25 {
				r.penalty[key] -= 0.25
			} else {
				delete(r.penalty, key)
			}
		})

		r.committedFees = candidateAdd(
			r.committedFees, r.routeFee(rt),
		)
		return nil
	}

	r.failures++
	r.plan = nil
	r.failedRoutes[candidateRouteHash(rt)]++

	failIndex := r.routeFailureIndex(
		rt, result.FailureSource,
	)

	for i := 0; i < failIndex && i < len(rt.Hops); i++ {
		key, amount, ok := r.routeEdgeAt(rt, i)
		if !ok {
			continue
		}

		load := r.observedLoad(key, amount)
		candidateRecordSuccess(key, load)
	}

	code := result.Failure.Code()
	if key, amount, ok := r.routeEdgeAt(rt, failIndex); ok {
		load := r.observedLoad(key, amount)

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			r.recordLocalFailure(key, load)

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.banned[key] = true

		default:
			r.penalty[key] += 0.85
		}
	} else {
		penalty := 0.35
		if code == lnwire.CodeTemporaryChannelFailure {
			penalty = 0.62
		}

		r.forEachRouteEdge(rt, func(key candidateEdgeKey,
			_ lnwire.MilliSatoshi, _ int) {

			r.penalty[key] += penalty
		})
	}

	r.releaseIssued(rt)
	return nil
}
